    def test_setup_is_installed_and_in_system_tools(self):
        self.assertIn('/usr/local/lib/fliperos-setup', ROOTFS)
        self.assertIn('fliperos-setup.desktop', ROOTFS)
        desktop = (ROOT / 'config/fliperos-setup.desktop').read_text()
        self.assertIn('Categories=System;', desktop)
        # Pelo desktop o Setup abre na interface grafica, numa janela do X.
        self.assertIn("sudo /usr/local/bin/fliperos-setup --desktop \"$DISPLAY\"", desktop)
        self.assertIn('Terminal=true', desktop)

    SERVICES_SCREEN = 'sudo -n /usr/local/bin/fliperos-setup --services-screen'

    def tty1(self, installed, setup_codes, requests, *args, splash=False, firstboot=True, terminal='/dev/tty1',
             game=False, services=False):
        """Roda o config/fliperos-tty1 com sudo e fliperos-session falsos.
        setup_codes: status de cada "fliperos-setup --menu"; requests: o
        pedido gravado antes de cada um; splash: o Plymouth do boot no ar;
        terminal: o que o tty responde (o VT do gabinete, ou o pty do SSH).
        Devolve as chamadas, em ordem (o --services-screen so com services)."""
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'bin').mkdir()
            (tmp / 'etc').mkdir()
            if installed:
                (tmp / 'etc/installed').write_text('')
                if firstboot:
                    (tmp / 'etc/firstboot').write_text('')
            if splash:
                (tmp / 'plymouth.pid').write_text('1\n')
            log = tmp / 'calls'
            codes = ' '.join(str(c) for c in setup_codes)
            reqs = ' '.join(requests)
            (tmp / 'bin/sudo').write_text(
                '#!/bin/bash\necho "sudo $*" >> %s\n'
                'if [[ $2 == --menu ]]; then\n'
                '  n=$(grep -c -- --menu %s); codes=(%s); reqs=(%s)\n'
                '  echo "${reqs[n-1]}" > %s/request\n'
                '  exit "${codes[n-1]}"\nfi\n' % (log, log, codes, reqs, tmp))
            (tmp / 'bin/fliperos-session').write_text('#!/bin/bash\necho "session $*" >> %s\n' % log)
            (tmp / 'bin/tty').write_text('#!/bin/bash\necho %s\n' % terminal)
            for f in ('sudo', 'fliperos-session', 'tty'):
                (tmp / 'bin' / f).chmod(0o755)
            if game:
                # O jogo direto no boot, as pastas e um update esperando.
                (tmp / 'etc/session').write_text('game\n')
                (tmp / 'bin/fliperos-roms').write_text('#!/bin/bash\necho roms >> %s\n' % log)
                (tmp / 'bin/fliperos-update').write_text('#!/bin/bash\necho "update $*" >> %s\necho 18\n' % log)
                (tmp / 'bin/nm-online').write_text('#!/bin/bash\nexit 0\n')
                for f in ('fliperos-roms', 'fliperos-update', 'nm-online'):
                    (tmp / 'bin' / f).chmod(0o755)
            env = dict(os.environ, PATH='%s:%s' % (tmp / 'bin', os.environ['PATH']),
                       FLIPEROS_ETC=str(tmp / 'etc'), FLIPEROS_BIN=str(tmp / 'bin'),
                       FLIPEROS_LAUNCH_REQUEST=str(tmp / 'request'),
                       FLIPEROS_PLYMOUTH_PID=str(tmp / 'plymouth.pid'))
            subprocess.run(['bash', str(ROOT / 'config/fliperos-tty1')] + list(args),
                           env=env, check=True, timeout=30)
            calls = [line.strip() for line in log.read_text().splitlines()]
            return calls if services else [c for c in calls if c != self.SERVICES_SCREEN]

    def test_after_boot_services_wait_for_the_first_screen(self):
        # Os servicos em "After boot" sobem depois da primeira tela (o menu,
        # o frontend ou o jogo), uma vez so, e nao mais por um tempo fixo.
        quit = 'sudo -n /usr/bin/plymouth quit'
        calls = self.tty1(True, [0], ['-'], splash=True, firstboot=False, services=True)
        self.assertEqual(calls[1:4], [quit, self.SERVICES_SCREEN, 'session'])
        self.assertEqual(calls.count(self.SERVICES_SCREEN), 1)
        calls = self.tty1(True, [0], ['-'], firstboot=False, game=True, services=True)
        self.assertEqual(calls[1:3], [self.SERVICES_SCREEN, 'session'])
        calls = self.tty1(False, [20, 0], ['lxde', '-'], '--menu', services=True)
        self.assertEqual(calls[0], self.SERVICES_SCREEN)
        self.assertEqual(calls.count(self.SERVICES_SCREEN), 1)
        late = (ROOT / 'config/fliperos-services-late.service').read_text()
        self.assertIn('RemainAfterExit=yes', late)
        screen = (ROOT / 'config/fliperos-services-screen.timer').read_text()
        self.assertIn('OnActiveSec=15s', screen)
        self.assertIn('Unit=fliperos-services-late.service', screen)
        self.assertNotIn('[Install]', screen)
        fallback = (ROOT / 'config/fliperos-services-late.timer').read_text()
        self.assertIn('OnBootSec=3min', fallback)
        self.assertIn('fliperos-services-screen.timer', ROOTFS.split('# ── Servicos')[1].split('for timer')[0])
        # O compartilhamento vai para "After boot" ate a pessoa mudar.
        self.assertIn("echo 'samba=after' >>", ROOTFS)
        self.assertIn('multi-user.target.wants/nmbd.service', ROOTFS)

    def test_tty1_flow_like_groovyarcade(self):
        """No disco: primeiro boot, launcher e depois o menu. Na midia: menu."""
        calls = self.tty1(True, [0], ['-'])
        self.assertEqual(calls, ['sudo setterm --blank 0 --powerdown 0',
                                 'sudo /usr/local/bin/fliperos-setup --first-boot',
                                 'session', 'sudo /usr/local/bin/fliperos-setup --menu'])
        calls = self.tty1(False, [0], ['-'])
        self.assertEqual(calls[1:], ['sudo /usr/local/bin/fliperos-setup --menu'])

    def test_game_at_boot_opens_before_anything_else(self):
        # Modo jogo: nada de esperar a rede pelo update nem varrer pastas
        # antes do jogo; os dois vem depois dele, a caminho do menu.
        calls = self.tty1(True, [0], ['-'], firstboot=False, game=True)
        self.assertEqual(calls, ['sudo setterm --blank 0 --powerdown 0', 'session', 'roms', 'update pending',
                                 'sudo /usr/local/bin/fliperos-setup --update-check',
                                 'sudo /usr/local/bin/fliperos-setup --menu'])
        tty1 = (ROOT / 'config/fliperos-tty1').read_text()
        self.assertIn('FLIPEROS_UPDATE_NET_WAIT=0 update_pending', tty1)
        # O preparo dos frontends (listas, arte) fica de fora no jogo.
        session = (ROOT / 'config/fliperos-session').read_text()
        self.assertIn('fliperos-setup --session-start "$choice"', session)
        entry = (ROOT / 'fliperos-setup/fliperos-setup').read_text()
        start = entry.split('--session-start)')[1].split(';;')[0]
        self.assertLess(start.index('if [[ ${2:-} == game ]]; then\n        latency_session_start\n        return 0'),
                        start.index('media_refolder'))

