class PadKeysTests(unittest.TestCase):
    """Controle como teclado nos menus do setup (config/fliperos-padkeys)."""
    P = padkeys

    def test_buttons(self):
        P = self.P
        m = P.Mapper({})
        self.assertEqual(m.event(P.EV_KEY, 0x130, 1), [(P.KEY_ENTER, 1)])  # A
        self.assertEqual(m.event(P.EV_KEY, 0x131, 0), [(P.KEY_ESC, 0)])    # B solto
        self.assertEqual(m.event(P.EV_KEY, 0x120, 1), [(P.KEY_ENTER, 1)])  # botao 1 do encoder
        self.assertEqual(m.event(P.EV_KEY, 0x121, 1), [(P.KEY_ESC, 1)])    # botao 2
        self.assertEqual(m.event(P.EV_KEY, 0x13b, 1), [(P.KEY_ENTER, 1)])  # Start
        self.assertEqual(m.event(P.EV_KEY, 0x136, 1), [(P.KEY_PAGEUP, 1)])  # L
        self.assertEqual(m.event(P.EV_KEY, 0x221, 1), [(P.KEY_DOWN, 1)])   # direcional
        self.assertEqual(m.event(P.EV_KEY, 0x130, 2), [])  # repeticao do proprio controle
        # Botao 3 e X/Y: Espaco, que marca nas listas de marcar (ui_checklist).
        self.assertEqual(m.event(P.EV_KEY, 0x122, 1), [(P.KEY_SPACE, 1)])
        self.assertEqual(m.event(P.EV_KEY, 0x133, 1), [(P.KEY_SPACE, 1)])
        self.assertEqual(m.event(P.EV_KEY, 0x134, 0), [(P.KEY_SPACE, 0)])
        self.assertEqual(P.KEY_SPACE, 57)
        self.assertEqual(m.event(P.EV_KEY, 0x132, 1), [])  # C: sem tecla

    def test_digital_stick_of_an_arcade_encoder(self):
        # Encoder de fliperama (DragonRise, Xin-Mo): eixo 0..255, repouso 127/128.
        P = self.P
        m = P.Mapper({P.ABS_X: (0, 255), P.ABS_Y: (0, 255)})
        self.assertEqual(m.event(P.EV_ABS, P.ABS_Y, 0), [(P.KEY_UP, 1)])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_Y, 0), [])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_Y, 255), [(P.KEY_UP, 0), (P.KEY_DOWN, 1)])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_Y, 128), [(P.KEY_DOWN, 0)])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_X, 127), [])

    def test_analog_dead_zone_and_hat(self):
        P = self.P
        m = P.Mapper({P.ABS_X: (-32768, 32767)})
        self.assertEqual(m.event(P.EV_ABS, P.ABS_X, 12000), [])  # analogico gasto em repouso
        self.assertEqual(m.event(P.EV_ABS, P.ABS_X, 30000), [(P.KEY_RIGHT, 1)])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_HAT0X, -1), [(P.KEY_LEFT, 1)])
        self.assertEqual(sorted(m.release()), sorted([(P.KEY_RIGHT, 0), (P.KEY_LEFT, 0)]))

    def test_repeat_and_two_sources_on_one_key(self):
        P = self.P
        sent = []
        keys = P.Keys(lambda k, v: sent.append((k, v)))
        keys.apply(P.KEY_DOWN, 1, 0.0)
        keys.apply(P.KEY_DOWN, 1, 0.0)  # hat e analogico juntos
        keys.tick(0.45)
        self.assertEqual(sent, [(P.KEY_DOWN, 1)])
        for t in (0.51, 0.55, 0.64):
            keys.tick(t)
        self.assertEqual(sent, [(P.KEY_DOWN, 1), (P.KEY_DOWN, 2), (P.KEY_DOWN, 2)])
        keys.apply(P.KEY_DOWN, 0, 0.7)
        keys.tick(0.8)
        self.assertEqual(sent[-1], (P.KEY_DOWN, 2))  # o outro ainda segura
        keys.apply(P.KEY_DOWN, 0, 0.8)
        self.assertEqual(sent[-1], (P.KEY_DOWN, 2))  # a soltura espera o repique
        keys.tick(0.8 + P.DEBOUNCE)
        self.assertEqual(sent[-1], (P.KEY_DOWN, 0))
        keys.tick(5)
        # Enter nao repete; soltar o que nao foi apertado nao emite nada.
        keys.apply(P.KEY_ENTER, 1, 6)
        keys.tick(9)
        keys.apply(P.KEY_ESC, 0, 9)
        self.assertEqual(sent[-1], (P.KEY_ENTER, 1))
        keys.release_all()
        self.assertEqual(sent[-1], (P.KEY_ENTER, 0))

    def test_switch_bounce_is_one_press(self):
        # O microswitch repica ao fechar e ao abrir: um toque, um item.
        P = self.P
        sent = []
        keys = P.Keys(lambda k, v: sent.append((k, v)))
        for value, t in ((1, 0.0), (0, 0.004), (1, 0.008), (0, 0.15), (1, 0.153), (0, 0.157)):
            keys.apply(P.KEY_DOWN, value, t)
            keys.tick(t)
        keys.tick(1)
        self.assertEqual(sent, [(P.KEY_DOWN, 1), (P.KEY_DOWN, 0)])
        # Dois toques de verdade, um depois do outro, sao dois itens.
        keys.apply(P.KEY_DOWN, 1, 2.0)
        keys.apply(P.KEY_DOWN, 0, 2.1)
        keys.tick(2.2)
        keys.apply(P.KEY_DOWN, 1, 2.25)
        self.assertEqual(sent[2:], [(P.KEY_DOWN, 1), (P.KEY_DOWN, 0), (P.KEY_DOWN, 1)])
        self.assertLessEqual(keys.timeout(2.25, 0.5), P.REPEAT_DELAY)

    def test_wheel_axes_are_not_arrows(self):
        # Driving Force Pro (2026-11-16): sem mola o volante fica fora do
        # centro e o acelerador solto descansa em 255; as setas seguravam
        # sozinhas e o menu do Setup descia. No volante so o hat anda.
        P = self.P
        self.assertTrue(P.is_wheel(b'Logitech Logitech Driving Force Pro', set()))
        self.assertTrue(P.is_wheel(b'Some Pad', {P.FF_AUTOCENTER}))
        self.assertFalse(P.is_wheel(b'Microsoft X-Box 360 pad', {0x50, 0x51, 0x60}))
        m = P.Mapper({P.ABS_X: (0, 16383), P.ABS_Y: (0, 255)}, wheel=True)
        self.assertEqual(m.event(P.EV_ABS, P.ABS_X, 14860), [])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_Y, 255), [])
        self.assertEqual(m.event(P.EV_ABS, P.ABS_HAT0X, 1), [(P.KEY_RIGHT, 1)])
        self.assertEqual(m.event(P.EV_KEY, 0x120, 1), [(P.KEY_ENTER, 1)])
        # Um joypad continua andando pelo analogico.
        pad = P.Mapper({P.ABS_X: (-32768, 32767)})
        self.assertEqual(pad.event(P.EV_ABS, P.ABS_X, 30000), [(P.KEY_RIGHT, 1)])

    def test_only_controllers_are_read(self):
        P = self.P
        self.assertTrue(P.is_pad(b'Xbox pad', {0x130, 0x131, 0x13b}))
        self.assertTrue(P.is_pad(b'DragonRise Generic USB Joystick', {0x120, 0x121}))
        self.assertFalse(P.is_pad(b'AT keyboard', {1, 28, 30}))
        self.assertFalse(P.is_pad(b'mouse', {0x110, 0x111}))
        self.assertFalse(P.is_pad(b'GunCon2', {0x110, 0x130, 0x13b}))
        self.assertFalse(P.is_pad(P.NAME, {0x130}))

    def test_ioctl_numbers(self):
        # Os valores de linux/uinput.h e linux/input.h no x86_64.
        P = self.P
        self.assertEqual(P.UI_SET_EVBIT, 0x40045564)
        self.assertEqual(P.UI_SET_KEYBIT, 0x40045565)
        self.assertEqual(P.UI_DEV_SETUP, 0x405c5503)
        self.assertEqual(P.UI_DEV_CREATE, 0x5501)
        self.assertEqual(P.eviocgabs(0), 0x80184540)
        self.assertEqual(P.EVENT.size, 24)

    def test_on_only_while_the_setup_menu_is_up(self):
        self.assertIn('multi-user.target.wants/fliperos-padkeys.service', ROOTFS)
        setup = (ROOT / 'fliperos-setup/fliperos-setup').read_text()
        self.assertIn('padkeys_off', setup.split('restore_terminal() {')[1].split('}')[0])
        self.assertLess(setup.index('  ui_init\n'), setup.index('  padkeys_on\n'))

    def test_flag_left_by_a_dead_owner_is_ignored(self):
        # O Setup morto sem o trap (o tty1 reiniciado) deixava o arquivo, e no
        # frontend e nos jogos o botao 2 saia tambem como Esc (fechava o
        # Flycast). Vale so com o dono vivo; sem ele, o arquivo some.
        with tempfile.TemporaryDirectory() as tmp:
            flag = Path(tmp) / 'padkeys'
            old, self.P.FLAG = self.P.FLAG, str(flag)
            try:
                self.assertFalse(self.P.flag_on())
                flag.write_text('%d\n' % os.getpid())
                self.assertTrue(self.P.flag_on())
                dead = subprocess.Popen(['true'])
                dead.wait()
                for text in ('%d\n' % dead.pid, '', 'abc'):
                    flag.write_text(text)
                    self.assertFalse(self.P.flag_on(), text)
                    self.assertFalse(flag.exists(), text)
            finally:
                self.P.FLAG = old
        # O dono que o Setup e o navegador do Downloader gravam.
        lib = (ROOT / 'fliperos-setup/lib/padkeys.sh').read_text()
        self.assertIn('echo "${1:-$$}" > "$PADKEYS_FLAG"', lib)
        self.assertIn('--padkeys on $$', (ROOT / 'config/fliperos-browser').read_text())
        # O endereco que o Setup pede (o cadastro do RetroAchievements) chega
        # ao navegador; sem ele, o padrao do Downloader.
        tty1 = (ROOT / 'config/fliperos-tty1').read_text()
        self.assertIn('url=$(head -n 1 "${FLIPEROS_BROWSER_URL_FILE:-/run/fliperos/browser-url}" 2> /dev/null)', tty1)
        self.assertIn('FLIPEROS_BROWSER_URL=${url:-${FLIPEROS_BROWSER_URL:-}} "$BIN/fliperos-browser"', tty1)
        self.assertIn('url=${FLIPEROS_BROWSER_URL:-https://duckduckgo.com/}', (ROOT / 'config/fliperos-browser').read_text())


class RootfsRunTests(unittest.TestCase):
    """O fliperos-rootfs.sh de verdade numa raiz falsa."""

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory()
        root = Path(cls.tmp.name)
        for d in ('home/fliperos', 'etc/xdg/openbox/LXDE', 'etc/modprobe.d', 'etc/sudoers.d',
                  'etc/profile.d', 'etc/systemd/system'):
            (root / d).mkdir(parents=True)
        (root / 'etc/xdg/openbox/LXDE/rc.xml').write_text(
            '<openbox_config>\n<theme>\n  <name>Clearlooks</name>\n</theme>\n'
            '<applications>\n<!-- exemplos -->\n</applications>\n</openbox_config>\n')
        (root / 'etc/passwd').write_text('fliperos:x:1000:1000::/home/fliperos:/bin/bash\n')
        subprocess.run(['bash', str(ROOT / 'fliperos-rootfs.sh'), str(root)], check=True,
                       capture_output=True, timeout=120)
        cls.root = root

    @classmethod
    def tearDownClass(cls):
        cls.tmp.cleanup()

    def test_openbox_rc_dracula_and_resolution_window(self):
        rc = (self.root / 'home/fliperos/.config/openbox/lxde-rc.xml').read_text()
        self.assertIn('<name>Dracula</name>', rc)
        self.assertIn('<application title="Desktop Resolution"><maximized>yes</maximized></application>\n'
                      '</applications>', rc)

    def test_new_programs_are_installed(self):
        for path in ('usr/local/bin/fliperos-menu', 'opt/fliperos/bin/fliperos-padkeys',
                     'opt/fliperos/bin/fliperos-resolution', 'opt/fliperos/bin/fliperos-tty1'):
            self.assertTrue(os.access(self.root / path, os.X_OK), path)
        self.assertTrue((self.root / 'usr/local/share/applications/fliperos-resolution.desktop').is_file())
        self.assertTrue((self.root / 'usr/local/share/applications/org.gnome.Software.desktop').is_file())
        self.assertTrue(os.access(self.root / 'home/fliperos/Desktop/app-store.desktop', os.X_OK))
        self.assertTrue(os.access(self.root / 'home/fliperos/Desktop/desktop-resolution.desktop', os.X_OK))
        self.assertTrue(os.access(self.root / 'opt/fliperos/bin/fliperos-atom15', os.X_OK))
        self.assertTrue(os.access(self.root / 'opt/fliperos/bin/fliperos-amdgpu-load', os.X_OK))
        self.assertTrue(os.access(self.root / 'etc/initramfs-tools/hooks/fliperos-amdgpu', os.X_OK))
        self.assertIn('install amdgpu ', (self.root / 'etc/modprobe.d/fliperos-amdgpu.conf').read_text())
        self.assertTrue((self.root / 'usr/share/glib-2.0/schemas/90_fliperos-software.gschema.override').is_file())
        self.assertTrue((self.root / 'home/fliperos/.config/alacritty/alacritty.toml').is_file())
        for path in ('opt/fliperos/bin/fliperos-calibrate', 'opt/fliperos/bin/fliperos-roms'):
            self.assertTrue(os.access(self.root / path, os.X_OK), path)
        self.assertEqual(os.readlink(self.root / 'opt/fliperos/roms'), '/home/fliperos/roms')
        self.assertTrue((self.root / 'etc/samba/smb.conf').is_file())
        self.assertTrue((self.root / 'home/fliperos/.config/flycast/emu.cfg').is_file())
        wants = self.root / 'etc/systemd/system/multi-user.target.wants/fliperos-padkeys.service'
        self.assertEqual(os.readlink(wants), '/etc/systemd/system/fliperos-padkeys.service')
        self.assertTrue(os.access(self.root / 'usr/local/bin/fliperos-motd', os.X_OK))
        self.assertFalse((self.root / 'etc/profile.d/fliperos.sh').exists())

    def test_networkmanager_writes_dns_and_manages_ethernet(self):
        # No gabinete o resolv.conf era o do container do build (192.168.65.7)
        # e o cabo de rede ficava sem IP.
        nm = self.root / 'etc/NetworkManager/conf.d'
        dns = (nm / '90-fliperos-dns.conf').read_text()
        self.assertIn('dns=default', dns)
        self.assertIn('rc-manager=file', dns)
        self.assertEqual((nm / '10-globally-managed-devices.conf').read_text(), '')
        squash = MKISO.split('create_squashfs() {')[1].split('mksquashfs')[0]
        self.assertIn('> "$CHROOT_DIR/etc/resolv.conf"', squash)

    def test_clock_is_synced_over_the_network(self):
        # O relogio da BIOS do gabinete estava 2 meses atrasado e o apt
        # recusava os repositorios.
        self.assertRegex(MKISO, r'\bsystemd-timesyncd\b')


class ResolutionAppTests(unittest.TestCase):
    """config/fliperos-resolution com xrandr e switchres falsos."""

    def run_app(self, saved):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'bin').mkdir()
            log = tmp / 'xrandr.log'
            (tmp / 'bin/xrandr').write_text(
                '#!/bin/bash\necho "$*" >> %s\n'
                'if [[ $1 == --query ]]; then\n'
                '  echo "Screen 0: minimum 320 x 200, current 640 x 480, maximum 16384 x 16384"\n'
                '  echo "DVI-D-1 disconnected (normal left inverted right x axis y axis)"\n'
                '  echo "VGA-1 connected primary 640x480+0+0 (normal left inverted right x axis y axis) 0mm x 0mm"\n'
                '  echo "   640x480i     59.99*+"\nfi\n' % log)
            (tmp / 'bin/switchres').write_text(
                '#!/bin/bash\necho "Switchres: Calculating best video mode for $1x$2@$3"\n'
                'echo "Switchres: Modeline \\"640x240_60 15.660000KHz 60.000000Hz\\" '
                '13.013460 640 666 727 831 240 242 245 261   -hsync -vsync"\n')
            for f in ('xrandr', 'switchres'):
                (tmp / 'bin' / f).chmod(0o755)
            (tmp / 'fliperos').mkdir()
            if saved:
                (tmp / 'fliperos/desktop-mode').write_text(saved)
            env = dict(os.environ, PATH='%s:%s' % (tmp / 'bin', os.environ['PATH']),
                       XDG_CONFIG_HOME=str(tmp), FLIPEROS_SETUP_LIB=str(ROOT / 'fliperos-setup/lib'),
                       FLIPEROS_LOG=str(tmp / 'log'))
            subprocess.run(['bash', str(ROOT / 'config/fliperos-resolution'), '--apply-saved'],
                           env=env, check=True, timeout=30)
            return log.read_text().splitlines() if log.exists() else []

    def test_saved_mode_is_calculated_by_switchres_and_set_by_xrandr(self):
        calls = self.run_app('640 240 60\n')
        self.assertEqual(calls[1:], [
            '--newmode fliperos-640x240@60 13.013460 640 666 727 831 240 242 245 261 -hsync -vsync',
            '--addmode VGA-1 fliperos-640x240@60',
            '--output VGA-1 --mode fliperos-640x240@60'])

    def test_nothing_saved_changes_nothing(self):
        self.assertEqual(self.run_app(None), [])

    def test_extra_modes_are_the_ones_the_output_lists_beyond_the_table(self):
        # O 640x480i e 320x240 ja estao na tabela do monitor de 15 kHz; o
        # 800x600 que o EDID lista a mais entra na lista do desktop.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'bin').mkdir()
            (tmp / 'bin/xrandr').write_text(
                '#!/bin/bash\n'
                'echo "VGA-1 connected primary 640x480+0+0 (normal left inverted right x axis y axis)"\n'
                'echo "   640x480i     59.99*+"\necho "   320x240      60.00"\necho "   800x600      60.00"\n')
            (tmp / 'bin/xrandr').chmod(0o755)
            env = dict(os.environ, PATH='%s:%s' % (tmp / 'bin', os.environ['PATH']),
                       FLIPEROS_SETUP_LIB=str(ROOT / 'fliperos-setup/lib'), FLIPEROS_LOG=str(tmp / 'log'))
            script = ('source <(sed "/^if \\[\\[ \\${1:-} == --apply-saved/,\\$d" %s)\n'
                      'video_resolution_choices() { printf "%%s\\n" "320x240S|a" "640x480iS|b"; }\n'
                      'res_extra_modes VGA-1' % (ROOT / 'config/fliperos-resolution'))
            out = subprocess.run(['bash', '-c', script], env=env, check=True, timeout=30,
                                 capture_output=True, text=True).stdout
            self.assertEqual(out.split(), ['800x600'])

    def test_lxde_applies_it_and_the_menu_has_it(self):
        self.assertIn('fliperos-resolution --apply-saved', (ROOT / 'config/fliperos-lxde').read_text())
        entry = (ROOT / 'config/applications/fliperos-resolution.desktop').read_text()
        self.assertIn('Exec=alacritty --title "Desktop Resolution" -e /opt/fliperos/bin/fliperos-resolution', entry)
        self.assertIn('Categories=Settings;', entry)


def apt_list():
    """Os pacotes do apt-get install principal do chroot."""
    block = MKISO.split('apt-get install -y --no-install-recommends \\\n')[1].split('\n\n')[0]
    return block.replace('\\', ' ').split()


class DesktopLogoutTests(unittest.TestCase):
    """O "Back to the menu" do LXDE volta direto ao menu do FliperOS: a
    janela do lxsession-logout era ilegivel numa tela de baixa resolucao."""

    def test_every_logout_path_opens_the_gum_menu(self):
        logout = '/opt/fliperos/bin/fliperos-logout'
        # O quit_manager do lxsession, o item do menu (Logout do lxpanel) e o
        # botao do painel (o lxde-logout.desktop, com o mesmo ID do pacote).
        self.assertIn('quit_manager/command=%s\n' % logout,
                      (ROOT / 'config/lxde/lxsession/LXDE/desktop.conf').read_text())
        self.assertEqual((ROOT / 'config/lxde/lxpanel/LXDE/config').read_text(), '[Command]\nLogout=%s\n' % logout)
        entry = (ROOT / 'config/applications/lxde-logout.desktop').read_text()
        self.assertIn('\nExec=%s\n' % logout, entry)
        self.assertIn('id=lxde-logout.desktop', (ROOT / 'config/lxde/lxpanel/LXDE/panels/panel').read_text())
        self.assertRegex(ROOTFS, r' fliperos-logout[ \w\\\n-]*; do')

    def test_logout_goes_back_to_the_menu(self):
        # Sem perguntar: fecha o lxsession e o fliperos-session volta ao menu
        # (desligar e reiniciar ficam no menu). O botao diz o que faz.
        script = (ROOT / 'config/fliperos-logout').read_text()
        self.assertIn('kill -TERM "${_LXSESSION_PID:-0}"', script)
        self.assertNotIn('gum', script)
        entry = (ROOT / 'config/applications/lxde-logout.desktop').read_text()
        self.assertIn('\nName=Back to the menu\n', entry)
        self.assertNotIn('[pt_BR]', entry)


class DesktopTerminalTests(unittest.TestCase):
    """O lxterminal e o xterm nao desenhavam as bordas do Gum: o terminal do
    desktop e o Alacritty."""

    def test_only_alacritty_in_the_image(self):
        pkgs = apt_list()
        self.assertIn('alacritty', pkgs)
        for old in ('lxterminal', 'xterm', 'lxde'):
            self.assertNotIn(old, pkgs, old)
        # O metapacote lxde depende do lxterminal; os componentes vem a mao, e
        # o cabinet-update.sh protege os mesmos antes de tirar os terminais.
        update = (ROOT / 'tools/cabinet-update.sh').read_text()
        parts = update.split('lxde_parts=(')[1].split(')')[0].split()
        self.assertIn('lxde-core', parts)
        for part in parts:
            self.assertIn(part, pkgs, part)
        self.assertLess(update.index('apt-mark manual'), update.index('apt-get purge -y -q lxterminal xterm'))

    def test_steam_does_not_bring_xterm_back(self):
        # O steam-libs:i386 recomenda "xterm | x-terminal-emulator", e o
        # Alacritty (amd64) nao vale para um pacote i386: o xterm voltou na
        # ISO e virou o x-terminal-emulator. O Steam vem pelo Setup > Games > Extras.
        self.assertIn('STEAM_PACKAGES="steam-installer xterm- xterm:i386-"', EXTRAS)

    def test_ctrl_v_pastes_in_the_terminal(self):
        conf = (ROOT / 'config/lxde/alacritty/alacritty.toml').read_text()
        self.assertIn('[keyboard]', conf)
        self.assertIn('{ key = "V", mods = "Control", action = "Paste" }', conf)

    def test_dracula_palette_of_the_setup(self):
        import tomllib
        conf = tomllib.loads((ROOT / 'config/lxde/alacritty/alacritty.toml').read_text())
        ui = (ROOT / 'fliperos-setup/lib/ui.sh').read_text()
        palette = ui.split('UI_PALETTE=(')[1].split(')')[0].split()
        order = ('black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white')
        colors = [conf['colors']['normal'][c] for c in order] + [conf['colors']['bright'][c] for c in order]
        # O 0 e o preto dos terminais do Dracula; o fundo e o primary.
        self.assertEqual([c.lstrip('#') for c in colors[1:]], palette[1:])
        self.assertEqual(conf['colors']['primary']['background'], '#' + palette[0])
        self.assertEqual(conf['font']['normal']['family'], 'DejaVu Sans Mono')
        self.assertEqual(conf['cursor']['style']['blinking'], 'Never')

    def test_desktop_uses_it(self):
        self.assertIn('id=Alacritty.desktop', (ROOT / 'config/lxde/lxpanel/LXDE/panels/panel').read_text())
        self.assertNotIn('lxterminal', (ROOT / 'config/lxde/lxpanel/LXDE/panels/panel').read_text())
        self.assertIn('terminal_manager/command=alacritty',
                      (ROOT / 'config/lxde/lxsession/LXDE/desktop.conf').read_text())
        session = (ROOT / 'config/fliperos-lxde').read_text()
        self.assertLess(session.index('export WINIT_X11_SCALE_FACTOR=1'), session.index('exec startlxde'))
        self.assertFalse((ROOT / 'config/lxde/lxterminal').exists())


class CalibrateTests(unittest.TestCase):
    """Setup > Joysticks: GunCon 2 e volante/pedais/analogico
    (config/fliperos-calibrate)."""
    C = calibrate

    def test_guncon_range_from_two_targets(self):
        # Tiros a 15% e 85% da tela leram 257 e 638 (faixa real 175..720).
        lo, hi = self.C.guncon_range(257, 638, 0.15, 0.85)
        self.assertAlmostEqual(lo, 175, delta=1)
        self.assertAlmostEqual(hi, 720, delta=1)
        self.assertEqual(self.C.median([300, 900, 310]), 310)

    def test_a_bad_saved_range_does_not_lock_the_next_calibration(self):
        # Gabinete de um usuario (2026-11-14): a faixa salva X 521..589 fazia o
        # driver ver todo tiro como fora da tela, e a calibracao nao lia nada.
        # Os cantos a 15%/85% de 320x240 leram X 231/640 e Y 42/202.
        fx, fy = (47.5 / 320, 271.5 / 320), (35.5 / 240, 203.5 / 240)
        xr = self.C.guncon_range(231, 640, *fx)
        yr = self.C.guncon_range(42, 202, *fy)
        self.assertEqual(xr, (144, 729))
        self.assertEqual(yr, (8, 237))
        self.assertTrue(self.C.plausible_range(xr, yr))
        self.assertFalse(self.C.plausible_range((521, 589), (-30, 304)))
        # Sem luz: x 0/1 do GunCon 2, ou o fora da tela do driver (negativo).
        for x, y in ((0, 5), (1, 5), (-129, -64), (512, -72)):
            self.assertFalse(self.C.gun_sees(x, y))
        self.assertTrue(self.C.gun_sees(430, 115))
        # A faixa aberta deixa o fora da tela do driver negativo (patch 0004).
        lo, hi = self.C.OPEN_X
        self.assertLess(lo - (hi - lo) // 8 - 1, 0)
        lo, hi = self.C.OPEN_Y
        self.assertLess(lo - (hi - lo) // 8 - 1, 0)
        # Abre antes dos alvos, devolve antes de aplicar a faixa nova.
        src = (ROOT / 'config/fliperos-calibrate').read_text()
        body = src[src.index('def calibrate_guncon'):src.index('def wait_enter')]
        self.assertLess(body.index('open_range(path)'), body.index('make_screen()'))
        self.assertLess(body.index('reopen()\n        screen.restore()'), body.index('apply_guncon(path'))

    def test_flash_wait_is_off_while_calibrating(self):
        from unittest import mock
        with tempfile.TemporaryDirectory() as tmp:
            (Path(tmp) / 'flash_ms').write_text('100\n')
            with mock.patch.object(self.C, 'GUNCON_PARAMS', tmp):
                self.assertEqual(self.C.gun_param('flash_ms'), '100')
                self.C.gun_param('flash_ms', 0)
                self.assertEqual(self.C.gun_param('flash_ms'), '0')
                self.assertIsNone(self.C.gun_param('missing'))

    def test_each_gun_has_its_own_conf_by_usb_port(self):
        # Duas GunCon 2 sao iguais no vendor/produto: a porta USB as separa.
        base = '/etc/fliperos/guncon2.conf'
        a = self.C.gun_conf_path(base, 'usb-0000:00:1a.7-2.1/input0')
        b = self.C.gun_conf_path(base, 'usb-0000:00:1a.7-2.2/input0')
        self.assertEqual(a, '/etc/fliperos/guncon2-usb_0000_00_1a_7_2_1_input0.conf')
        self.assertNotEqual(a, b)
        self.assertEqual(self.C.gun_conf_path(base, ''), base)
        # A mesma chave no script do udev (tr + sed), para ele achar o arquivo.
        script = (ROOT / 'config/fliperos-guncon2-calibrate').read_text()
        self.assertIn("tr -c '[:alnum:]' '_'", script)
        self.assertIn('${CONF%.conf}-$key.conf', script)

    def test_centered_axis_is_symmetric_around_rest(self):
        # Volante: repouso fora do meio do curso; os dois lados chegam ao fim.
        self.assertEqual(self.C.axis_calibration(100, 900, 520, 0, 1023), (140, 900, 8))
        # Pedal: repouso numa ponta, faixa vista e sem zona morta.
        self.assertEqual(self.C.axis_calibration(30, 990, 990, 0, 1023), (30, 990, 0))
        # Eixo que nao se mexeu fica como esta.
        self.assertIsNone(self.C.axis_calibration(500, 510, 505, 0, 1023))

    def test_conf_keeps_the_other_controllers(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = str(Path(tmp) / 'calibration.conf')
            self.C.write_axes_conf(path, (0x046d, 0xc24f), 'G29', {0: (140, 900, 8)})
            self.C.write_axes_conf(path, (0x044f, 0xb66e), 'T300', {0: (0, 65535, 300), 2: (10, 1000, 0)})
            self.C.write_axes_conf(path, (0x046d, 0xc24f), 'G29', {0: (120, 910, 8)})
            conf = self.C.read_axes_conf(path)
            self.assertEqual(conf[(0x046d, 0xc24f)], {0: (120, 910, 8)})
            self.assertEqual(conf[(0x044f, 0xb66e)], {0: (0, 65535, 300), 2: (10, 1000, 0)})
            gun = Path(tmp) / 'guncon2.conf'
            self.C.write_guncon_conf(str(gun), (175, 720), (20, 240))
            self.assertIn('X_MIN=175\nX_MAX=720\nY_MIN=20\nY_MAX=240\n', gun.read_text())

    def test_ioctl_numbers(self):
        # linux/input.h no x86_64: EVIOCGID e EVIOCSABS(ABS_X).
        self.assertEqual(self.C.EVIOCGID, 0x80084502)
        self.assertEqual(self.C.eviocsabs(0), 0x401845c0)
        self.assertEqual(self.C.eviocgabs(1), 0x80184541)
        # O force feedback: EVIOCSFF com o struct ff_effect de 48 bytes.
        self.assertEqual(self.C.EVIOCSFF, 0x40304580)
        self.assertEqual(self.C.EVIOCRMFF, 0x40044581)

    def test_wheel_center_is_the_middle_of_travel(self):
        # Gabinete de um usuario (2026-11-16, Driving Force Pro sem mola): o
        # repouso ficou em 1655 e 14860, onde a mao largou o volante. O centro
        # do volante e o meio do curso de batente a batente, sem zona morta.
        self.assertEqual(self.C.axis_calibration(62, 16383, 1655, 0, 16383, wheel=True), (62, 16383, 0))
        self.assertEqual(self.C.axis_calibration(62, 16383, 14860, 0, 16383, wheel=True), (62, 16383, 0))
        # Um eixo de outro controle largado a 30% do curso: o meio, nao uma
        # faixa em volta do repouso que cortava um lado (0..9800).
        self.assertEqual(self.C.axis_calibration(0, 16383, 4900, 0, 16383), (0, 16383, 164))
        # O analogico com mola segue simetrico em volta do repouso.
        self.assertEqual(self.C.axis_calibration(62, 16383, 8196, 0, 16383), (62, 16330, 163))
        self.assertEqual(self.C.axis_kind(0, 0, 16383, 8129, True), 'wheel')
        self.assertEqual(self.C.axis_kind(1, 0, 255, 255, True), 'pedal')
        self.assertEqual(self.C.axis_kind(0, -32768, 32767, 120, False), 'center')
        self.assertEqual(self.C.axis_fraction('pedal', 70, 0, 255, 255), (255 - 70) / 255)
        self.assertEqual(self.C.axis_fraction('wheel', 0, 0, 16383, 0), -1.0)

    def test_arrows_do_not_cancel_the_calibration(self):
        # Girar o volante com o controle como teclado ligado mandava ESC [ D,
        # e o ESC da seta cancelava ("sai do nada"). So um Esc sozinho cancela.
        read = self.C.read_key
        for data in (b'\x1b[D', b'\x1b[B\x1b[C', b'\x1bOA', b'\x1b[1;5C'):
            self.assertEqual(read(data), '', data)
        self.assertEqual(read(b'\x1b'), '\033')
        self.assertEqual(read(b'\r'), '\n')
        self.assertEqual(read(b'\x1b[B\n'), '\n')
        self.assertEqual(read(b'q'), 'q')
        # O Setup desliga o controle como teclado enquanto o calibrador roda.
        screens = (ROOT / 'fliperos-setup/screens/joysticks.sh').read_text()
        body = screens[screens.index('screen_calibrate() {'):]
        body = body[:body.index('\n}\n')]
        self.assertLess(body.index('padkeys_off'), body.index('"$CALIBRATE" axes'))
        self.assertLess(body.index('"$CALIBRATE" axes'), body.index('padkeys_on'))
        self.assertIn('FLIPEROS_CALIBRATE_GUI=$gui', body)
        self.assertIn('gui-background', body)

    def test_force_feedback_effect(self):
        C = self.C
        buf = C.ff_effect(C.FF_CONSTANT, 700, -0x5000)
        self.assertEqual(len(buf), 48)
        kind, eid, direction, _b, _i, length, delay = struct.unpack_from('<HhHHHHH', buf)
        self.assertEqual((kind, eid, direction, length, delay), (C.FF_CONSTANT, -1, 0x4000, 700, 0))
        self.assertEqual(struct.unpack_from('<h', buf, 16)[0], -0x5000)
        sine = C.ff_effect(C.FF_PERIODIC, 900, 0x4000, period=60)
        self.assertEqual(struct.unpack_from('<HHh', sine, 16), (C.FF_SINE, 60, 0x4000))
        rumble = C.ff_effect(C.FF_RUMBLE, 900, strong=0xA000, weak=0x6000)
        self.assertEqual(struct.unpack_from('<HH', rumble, 16), (0xA000, 0x6000))

    def test_button_layout_follows_the_controller(self):
        C = self.C
        dfp = list(range(0x120, 0x12e))
        family, symbols, slots = C.button_layout((0x046d, 0xc298), b'Logitech Logitech Driving Force Pro', dfp, True)
        self.assertEqual((family, symbols), ('wheel', 'ps'))
        self.assertEqual(slots[:4], ['cross', 'square', 'circle', 'triangle'])
        self.assertEqual(slots[-2:], ['gear_up', 'gear_down'])
        # Outro volante: os mesmos lugares, com o numero do botao.
        family, symbols, slots = C.button_layout((0x044f, 0xb66e), b'Thrustmaster T300RS', list(range(0x120, 0x130)), True)
        self.assertEqual((family, symbols, slots[0], slots[-1]), ('wheel', 'numbers', 'cross', None))
        xbox = [0x130, 0x131, 0x133, 0x134, 0x136, 0x137, 0x13a, 0x13b, 0x13c, 0x13d, 0x13e]
        self.assertEqual(C.button_layout((0x045e, 0x028e), b'Microsoft X-Box 360 pad', xbox, False)[:2], ('pad', 'xbox'))
        self.assertEqual(C.button_layout((0x054c, 0x05c4), b'Sony Interactive Entertainment Wireless Controller',
                                         xbox, False)[:2], ('pad', 'ps'))
        self.assertEqual(C.button_layout((0x0079, 0x0006), b'DragonRise Generic USB Joystick',
                                         list(range(0x120, 0x12a)), False), ('grid', 'numbers', [None] * 10))

    def test_axes_session_hold_to_continue_and_button_test(self):
        # Um toque acende o botao (o teste); segurar HOLD segundos avanca.
        import types
        from unittest import mock
        C = self.C
        r, w = os.pipe()
        try:
            events = []
            dev = types.SimpleNamespace(
                name=b'Logitech Logitech Driving Force Pro', path='/dev/input/event6', ident=(0x046d, 0xc298),
                fd=r, abs={0, 1, 5, 0x10, 0x11}, is_wheel=lambda: True, analog_axes=lambda: [0, 1, 5],
                absinfo=lambda a: {0: [8129, 0, 16383, 0, 0, 0], 1: [255, 0, 255, 0, 0, 0],
                                   5: [255, 0, 255, 0, 0, 0]}[a],
                buttons=lambda: list(range(0x120, 0x12e)))

            def feed(*evs):
                events.extend(evs)
                os.write(w, b'x')

            def read_events():
                os.read(r, 64)
                out = events[:]
                events.clear()
                return out
            dev.events = read_events
            with mock.patch.object(C, 'wheel_degrees', return_value=900), mock.patch.object(C, 'HOLD', 0.05):
                s = C.AxesSession(dev)
                self.assertEqual(s.kind, {0: 'wheel', 1: 'pedal', 5: 'pedal'})
                feed((C.EV_ABS, 0, 0), (C.EV_ABS, 0, 16383), (C.EV_ABS, 1, 0), (C.EV_ABS, 1, 255))
                self.assertIsNone(s.pump(0.01))
                feed((C.EV_KEY, 0x122, 1))
                self.assertIsNone(s.pump(0.01))
                feed((C.EV_KEY, 0x122, 0))
                self.assertEqual(s.pump(0.01), 'tap')
                feed((C.EV_KEY, 0x120, 1))
                s.pump(0.01)
                time.sleep(0.06)
                self.assertEqual(s.pump(0.01), 'next')
                # Ainda segurado: nao avanca de novo ate soltar.
                time.sleep(0.06)
                self.assertIsNone(s.pump(0.01))
                feed((C.EV_KEY, 0x120, 0))
                self.assertIsNone(s.pump(0.01))
                state = s.state('buttons')
                self.assertEqual(state['buttons'][0], (False, True))
                self.assertEqual(state['buttons'][2], (False, True))
                self.assertEqual(state['layout']['slots'][0], 'cross')
                self.assertEqual(s.result()[0], (0, 16383, 0))
                self.assertEqual(s.result()[1], (0, 255, 0))
                axes = {a['code']: a for a in state['axes']}
                self.assertEqual(axes[0]['seen'], (-1.0, 1.0))
                self.assertEqual(axes[1]['seen'], (0.0, 1.0))
        finally:
            os.close(r)
            os.close(w)

    def test_text_screen_fits_40_columns(self):
        # O console de 320x240 tem 40x30: as linhas de 60 colunas quebravam.
        C = self.C
        screen = C.Screen.__new__(C.Screen)
        screen.out, screen.cols, screen.rows = io.StringIO(), 40, 30
        axes = [{'code': 0, 'kind': 'wheel', 'label': 'WHEEL', 'frac': -0.5, 'seen': (-0.9, 0.8)},
                {'code': 1, 'kind': 'pedal', 'label': 'PEDAL Y', 'frac': 0.7, 'seen': (0.0, 1.0)}]
        base = {'name': 'Logitech Logitech Driving Force Pro', 'wheel': True, 'degrees': 900, 'hold': 0.5,
                'axes': axes, 'buttons': [(i == 2, i < 4) for i in range(14)], 'hat': (0, 0), 'ff': None,
                'result': [('WHEEL', 0, 16383, 0)], 'text': C.AxesSession.STEPS['move'][0],
                'keys': C.AxesSession.STEPS['move'][2]}
        for step in ('move', 'result', 'buttons'):
            screen.drawn, screen.last_step = 0, None
            screen.out = io.StringIO()
            screen.axes(dict(base, step=step))
            for row, col, text in re.findall(r'\x1b\[(\d+);(\d+)H([^\x1b]*(?:\x1b\[[0-9;]*m[^\x1b]*)*)',
                                             screen.out.getvalue()):
                plain = re.sub(r'\x1b\[[0-9;]*m', '', text)
                self.assertLessEqual(int(col) + len(plain) - 1, 40, (step, row, plain))

    def test_wheel_screen_draws_every_step(self):
        # A tela grafica (gui/wheelscreen.py), deitada e em pe: o volante, os
        # pedais, a tela dos botoes de cada familia e o force feedback.
        try:
            import pygame  # noqa: F401
        except ImportError:
            self.skipTest('pygame')
        script = r'''
import os, sys
os.environ["SDL_VIDEODRIVER"] = "dummy"
sys.path.insert(0, sys.argv[1])
import pygame, wheelscreen, theme as T
pygame.display.init(); pygame.display.set_mode((1, 1))
screen = wheelscreen.WheelScreen(window=False)
screen.fixed_time = 3.0
slots = ["cross", "square", "circle", "triangle", "r1", "l1", "r2", "l2", "select", "start", "r3", "l3",
         "gear_up", "gear_down"]
axes = [{"code": 0, "kind": "wheel", "label": "WHEEL", "frac": -0.5, "seen": (-0.9, 0.8)},
        {"code": 1, "kind": "pedal", "label": "PEDAL Y", "frac": 0.7, "seen": (0.0, 1.0)},
        {"code": 5, "kind": "pedal", "label": "PEDAL RZ", "frac": 0.0, "seen": (0.0, 0.5)}]
layouts = [("wheel", "ps", slots), ("wheel", "numbers", slots + [None]), ("pad", "xbox",
           ["south", "east", "north", "west", "tl", "tr", "select", "start", "mode", "thumbl", "thumbr"]),
           ("grid", "numbers", [None] * 10)]
for family, symbols, sl in layouts:
    for step in ("move", "rest", "result", "nomove", "buttons", "ff"):
        state = {"name": "Logitech Logitech Driving Force Pro", "step": step, "wheel": family == "wheel",
                 "degrees": 900, "text": ["Some text for the step."], "keys": [("HOLD", "NEXT")], "hold": 0.4,
                 "axes": axes, "buttons": [(i == 1, i < 3) for i in range(len(sl))], "hat": (-1, 0),
                 "layout": {"family": family, "symbols": symbols, "slots": sl},
                 "result": [("WHEEL", 0, 16383, 0)],
                 "ff": {"phase": 1, "phases": [("pull", -1), ("pull", 0), ("shake", 0)]}}
        frame = screen.render(state)
        assert frame.get_size() == (T.WIDTH, T.HEIGHT), frame.get_size()
assert wheelscreen.plain_name("Logitech Logitech Driving Force Pro") == "Logitech Driving Force Pro"
print("ok", T.WIDTH, T.HEIGHT)
'''
        for orientation, size in (('horizontal', '320 240'), ('vertical-cw', '240 320')):
            env = dict(os.environ, FLIPEROS_GUI_ORIENTATION=orientation, FLIPEROS_GUI_BG='stars')
            out = subprocess.run([sys.executable, '-c', script, str(ROOT / 'fliperos-setup/gui')],
                                 capture_output=True, text=True, env=env, timeout=120)
            self.assertEqual(out.returncode, 0, out.stderr[-2000:])
            self.assertIn('ok ' + size, out.stdout)

    def test_wired_into_the_setup_and_udev(self):
        rules = (ROOT / 'config/99-fliperos-input.rules').read_text()
        self.assertIn('ENV{ID_INPUT_JOYSTICK}=="1"', rules)
        self.assertIn('/opt/fliperos/bin/fliperos-calibrate apply $env{DEVNAME}', rules)
        menu = (ROOT / 'fliperos-setup/screens/setup-menu.sh').read_text()
        self.assertIn('"joysticks|Joysticks|', menu)
        screens = (ROOT / 'fliperos-setup/screens/joysticks.sh').read_text()
        # A GunCon 2 tem um menu proprio (screen_guncon), com a calibracao nele.
        for item in ('guncon|GunCon 2 (light gun)', 'axes|Calibrate wheel', 'lpt|LPT joysticks',
                     '"calibrate|Calibrate|', 'calibrate) screen_calibrate_guns ;;'):
            self.assertIn(item, screens)
        # Os quirks valem para qualquer USB (discos tambem): em System.
        self.assertIn('"quirks|Quirks (USB device fixes)|', menu)
        self.assertIn('quirks) screen_quirks ;;', menu)


class RomFoldersTests(unittest.TestCase):
    """~/roms com uma pasta por emulador e por core do RetroArch."""

    def test_one_folder_per_emulator_and_core(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            info = tmp / 'info'
            info.mkdir()
            (info / 'snes9x_libretro.info').write_text(
                'display_name = "Nintendo - SNES / SFC (Snes9x - Current)"\n'
                'supported_extensions = "smc|sfc|swc|fig|bs|st"\n')
            (info / 'mpv_libretro.info').write_text('display_name = "Video (MPV)"\n')
            (info / 'mame2010_libretro.info').write_text('display_name = "Arcade (MAME 2010)"\n')
            env = dict(os.environ, FLIPEROS_ROMS=str(tmp / 'roms'), FLIPEROS_CORE_INFO=str(info))
            for _ in range(2):  # a segunda rodada nao muda nada
                subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)
            roms = tmp / 'roms'
            for emu in ('mame', 'ps2', 'namco2x6', 'dreamcast', 'naomi', 'naomi2', 'atomiswave', 'model3', 'dolphin',
                        'openbor/Paks', 'hypseus', 'fightcade', 'fightcade/fbneo', 'fightcade/flycast',
                        'fightcade/snes9x', 'fightcade/fc1'):
                self.assertTrue((roms / emu / '_info.txt').is_file(), emu)
            self.assertEqual((roms / 'retroarch/snes9x/_info.txt').read_text(),
                             'RetroArch, core snes9x: Nintendo - SNES / SFC (Snes9x - Current) '
                             '(.smc .sfc .swc .fig .bs .st)\n')
            self.assertEqual((roms / 'retroarch/mpv/_info.txt').read_text(), 'RetroArch, core mpv: Video (MPV)\n')
            # O MAME 2010 e o "MAME 3D", dos jogos de arcade baseados no PlayStation.
            self.assertIn('Arcade (MAME 2010). This is the MAME 3D: MAME 0.139 sets of the PlayStation-based (PSX)',
                          (roms / 'retroarch/mame2010/_info.txt').read_text())

    def test_old_model2_emulator_leaves(self):
        # O Model 2 Emulator (Wine) saiu: as ROMs de dentro da pasta dele vao
        # para uma ~/roms/model2 comum, e a pasta dele sai (com o link de
        # ~/config). Uma custom folder (Setup > Games > Folders) fica.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            old = tmp / 'opt-model2'
            (old / 'roms/sub').mkdir(parents=True)
            (old / 'emulator_multicpu.exe').write_text('exe')
            (old / 'roms/daytona.zip').write_text('rom')
            (old / 'roms/sub/x.zip').write_text('sub')
            (tmp / 'roms').mkdir()
            (tmp / 'roms/model2').symlink_to(old / 'roms')
            (tmp / 'config').mkdir()
            (tmp / 'config/model2').symlink_to(old)
            env = dict(os.environ, HOME=str(tmp), FLIPEROS_CORE_INFO=str(tmp / 'nada'),
                       FIGHTCADE_DIR=str(tmp / 'nenhum'), FLIPEROS_OLD_MODEL2=str(old))
            for _ in range(2):  # a segunda rodada nao muda nada
                subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)
                model2 = tmp / 'roms/model2'
                self.assertFalse(model2.is_symlink())
                self.assertEqual((model2 / 'daytona.zip').read_text(), 'rom')
                self.assertEqual((model2 / 'sub/x.zip').read_text(), 'sub')
                self.assertTrue((model2 / '_info.txt').is_file())
                self.assertFalse(old.exists())
                self.assertFalse(os.path.lexists(tmp / 'config/model2'))
            # A custom folder de ~/roms/model2 e a pasta antiga com ROMs ficam.
            (old / 'roms').mkdir(parents=True)
            (old / 'roms/srallyc.zip').write_text('rom')
            (tmp / 'disk').mkdir()
            shutil.rmtree(tmp / 'roms/model2')
            (tmp / 'roms/model2').symlink_to(tmp / 'disk')
            subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)
            self.assertEqual(os.readlink(tmp / 'roms/model2'), str(tmp / 'disk'))
            self.assertEqual((old / 'roms/srallyc.zip').read_text(), 'rom')
        self.assertIn('cfglink model2 "$HOME/.config/keisho"', (ROOT / 'config/fliperos-roms').read_text())

    def test_nvram_and_save_folders_take_over_the_old_ones(self):
        # ~/nvram e ~/save existem, e as pastas de antes (do MAME, do RetroArch e
        # do PCSX2) viram links para elas com o que tinham dentro.
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp)
            old = home / 'opt/saves'
            for d, name, text in (('.mame/nvram/sf2', 'sf2.nv', 'nv'), ('.mame/sta/sf2', '1.sta', 'sta'),
                                  ('opt/saves/retroarch/MAME 2010/mame2010/cfg', 'default.cfg', 'cfg'),
                                  ('.config/PCSX2/memcards', 'Mcd001.ps2', 'card')):
                (home / d).mkdir(parents=True)
                (home / d / name).write_text(text)
            env = dict(os.environ, HOME=str(home), FLIPEROS_CORE_INFO=str(home / 'nada'),
                       FLIPEROS_SAVES_OLD=str(old), FIGHTCADE_DIR=str(home / 'nenhum'))
            for _ in range(2):
                subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)
            for d in ('nvram', 'save', 'save/retroarch', 'save/mame', 'save/ps2'):
                self.assertTrue((home / d / '_info.txt').is_file(), d)
            self.assertEqual((home / 'nvram/mame/sf2/sf2.nv').read_text(), 'nv')
            self.assertEqual((home / 'save/mame/sf2/1.sta').read_text(), 'sta')
            self.assertEqual((home / 'save/retroarch/MAME 2010/mame2010/cfg/default.cfg').read_text(), 'cfg')
            self.assertEqual((home / 'save/ps2/Mcd001.ps2').read_text(), 'card')
            # Os caminhos de antes seguem valendo.
            self.assertEqual(os.readlink(home / '.mame/nvram'), str(home / 'nvram/mame'))
            self.assertEqual(os.readlink(home / '.mame/sta'), str(home / 'save/mame'))
            self.assertEqual(os.readlink(old / 'retroarch'), str(home / 'save/retroarch'))
            self.assertEqual(os.readlink(home / '.config/PCSX2/memcards'), str(home / 'save/ps2'))
        ini = (ROOT / 'config/mame.ini').read_text()
        self.assertIn('nvram_directory $HOME/nvram/mame\n', ini)
        self.assertIn('state_directory $HOME/save/mame\n', ini)
        cfg = (ROOT / 'config/retroarch.cfg').read_text()
        self.assertIn('savefile_directory = "/home/fliperos/save/retroarch"', cfg)
        self.assertIn('savestate_directory = "/home/fliperos/save/retroarch"', cfg)

    def nvram_login(self, home):
        env = dict(os.environ, HOME=str(home), FLIPEROS_CORE_INFO=str(home / 'nada'),
                   FLIPEROS_SAVES_OLD=str(home / 'nada'), FIGHTCADE_DIR=str(home / 'nenhum'))
        env.pop('XDG_DATA_HOME', None)
        subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)

    def test_nvram_has_a_folder_per_emulator_and_core(self):
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp)
            # O que cada um ja gravou no caminho dele vai junto.
            for d, name in (('.local/share/flycast', 'kofxi.zip.nvmem'), ('.local/share/keisho/saves', 'daytona.nv'),
                            ('roms/hypseus/ram', 'ace.gz'),
                            ('save/retroarch/MAME 2010/mame2010/nvram', 'tekken3.nv'),
                            ('save/retroarch/FinalBurn Neo/fbneo', 'sf2.fs'),
                            ('save/retroarch/MAME 2003-Plus/mame2003-plus/nvram', 'dino.nv')):
                (home / d).mkdir(parents=True)
                (home / d / name).write_text('mine')
            for _ in range(2):
                self.nvram_login(home)
            for link, target, name in (('.local/share/flycast', 'flycast', 'kofxi.zip.nvmem'),
                                       ('.local/share/keisho/saves', 'model2', 'daytona.nv'),
                                       ('roms/hypseus/ram', 'hypseus', 'ace.gz'),
                                       ('save/retroarch/MAME 2010/mame2010/nvram', 'retroarch/mame2010', 'tekken3.nv'),
                                       ('save/retroarch/FinalBurn Neo/fbneo', 'retroarch/fbneo', 'sf2.fs'),
                                       ('save/retroarch/MAME 2003-Plus/mame2003-plus/nvram', 'retroarch/mame2003_plus',
                                        'dino.nv')):
                self.assertEqual(os.readlink(home / link), str(home / 'nvram' / target), link)
                self.assertEqual((home / 'nvram' / target / name).read_text(), 'mine', link)
                self.assertTrue((home / 'nvram' / target / '_info.txt').is_file(), target)
            self.assertTrue((home / 'nvram/fightcade/flycast/_info.txt').is_file())
            self.assertTrue((home / 'nvram/mame/_info.txt').is_file())

    def test_nvram_of_before_moves_to_the_mame_folder(self):
        # ~/nvram era so do MAME: os conjuntos saem da raiz, e nada se perde.
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp)
            (home / 'nvram/sf2').mkdir(parents=True)
            (home / 'nvram/sf2/sf2.nv').write_text('nv')
            (home / 'nvram/_info.txt').write_text('the MAME nvram')
            (home / 'nvram/old-flycast').mkdir()
            (home / '.mame').mkdir()
            (home / '.mame/nvram').symlink_to(home / 'nvram')
            self.nvram_login(home)
            self.assertEqual((home / 'nvram/mame/sf2/sf2.nv').read_text(), 'nv')
            self.assertFalse((home / 'nvram/sf2').exists())
            # Uma pasta guardada pela custom folder nao e um conjunto: volta ao lugar.
            self.assertFalse((home / 'nvram/mame/old-flycast').exists())
            self.assertTrue((home / 'nvram/flycast').is_dir())
            self.assertNotIn('MAME nvram', (home / 'nvram/_info.txt').read_text())
            self.assertEqual(os.readlink(home / '.mame/nvram'), str(home / 'nvram/mame'))
            # A pasta do MAME apagada a mao nao leva as dos outros junto.
            shutil.rmtree(home / 'nvram/mame')
            (home / 'nvram/flycast/mvsc2.zip.eeprom').write_text('ee')
            self.nvram_login(home)
            self.assertEqual((home / 'nvram/flycast/mvsc2.zip.eeprom').read_text(), 'ee')
            self.assertFalse((home / 'nvram/mame/flycast').exists())

    def test_nvram_of_the_image_comes_once_and_keeps_what_was_played(self):
        # O jogo que ja tinha memoria propria (a de fabrica, gravada ao abrir)
        # recebe a destravada uma vez; a propria fica em .own. Antes ela
        # ficava, e o ngbc jogado antes da imagem trazer a destravada nunca a
        # recebia.
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp) / 'home'
            bundled = Path(tmp) / 'bundled'
            (bundled / 'mame/tekken3').mkdir(parents=True)
            (bundled / 'mame/tekken3/at28c16').write_text('unlocked')
            (bundled / 'mame/sf2').mkdir()
            (bundled / 'mame/sf2/sf2.nv').write_text('unlocked')
            (bundled / 'flycast').mkdir()
            for name in ('kofxi.zip.nvmem', 'kofxi.zip.nvmem2', 'mvsc2.zip.eeprom'):
                (bundled / 'flycast' / name).write_text('unlocked')
            # O MAME 2010 e um <set>.nv por jogo, em retroarch/mame2010.
            (bundled / 'retroarch/mame2010').mkdir(parents=True)
            for name in ('tekken3.nv', 'sfa3.nv'):
                (bundled / 'retroarch/mame2010' / name).write_text('unlocked')
            (home / 'nvram/retroarch/mame2010').mkdir(parents=True)
            (home / 'nvram/retroarch/mame2010/sfa3.nv').write_text('mine')
            # Jogados antes: a propria vai para .own, a destravada entra
            # inteira (sem arquivo de outra origem ao lado).
            (home / 'nvram/mame/sf2').mkdir(parents=True)
            (home / 'nvram/mame/sf2/sf2.nv').write_text('mine')
            (home / 'nvram/flycast').mkdir(parents=True)
            (home / 'nvram/flycast/kofxi.zip.nvmem').write_text('mine')
            (home / 'nvram/flycast/kofxi.zip.eeprom').write_text('mine')
            # Ja igual a da imagem: nada muda. Da regra antiga (.bundled): passa pela nova.
            (home / 'nvram/flycast/mvsc2.zip.eeprom').write_text('unlocked')
            (home / 'nvram/flycast/.bundled').write_text('kofxi.zip\nmvsc2.zip\n')
            env = dict(os.environ, HOME=str(home), FLIPEROS_CORE_INFO=str(home / 'nada'),
                       FLIPEROS_SAVES_OLD=str(home / 'nada'), FIGHTCADE_DIR=str(home / 'nenhum'),
                       FLIPEROS_NVRAM_BUNDLED=str(bundled))
            env.pop('XDG_DATA_HOME', None)
            login = lambda: subprocess.run(['bash', str(ROOT / 'config/fliperos-roms')], env=env, check=True)
            login()
            self.assertEqual((home / 'nvram/mame/tekken3/at28c16').read_text(), 'unlocked')
            self.assertEqual((home / 'nvram/mame/sf2/sf2.nv').read_text(), 'unlocked')
            self.assertEqual((home / 'nvram/mame/.own/sf2/sf2.nv').read_text(), 'mine')
            self.assertEqual((home / 'nvram/flycast/mvsc2.zip.eeprom').read_text(), 'unlocked')
            self.assertFalse((home / 'nvram/flycast/.own/mvsc2.zip.eeprom').exists())
            self.assertEqual((home / 'nvram/flycast/kofxi.zip.nvmem').read_text(), 'unlocked')
            self.assertEqual((home / 'nvram/flycast/kofxi.zip.nvmem2').read_text(), 'unlocked')
            self.assertFalse((home / 'nvram/flycast/kofxi.zip.eeprom').exists())
            self.assertEqual((home / 'nvram/flycast/.own/kofxi.zip.nvmem').read_text(), 'mine')
            self.assertEqual((home / 'nvram/flycast/.own/kofxi.zip.eeprom').read_text(), 'mine')
            # MAME 2010: o jogo sem memoria recebe a destravada; o que ja tinha vai para .own.
            core = home / 'nvram/retroarch/mame2010'
            self.assertEqual((core / 'tekken3.nv').read_text(), 'unlocked')
            self.assertEqual((core / 'sfa3.nv').read_text(), 'unlocked')
            self.assertEqual((core / '.own/sfa3.nv').read_text(), 'mine')
            self.assertFalse((core / '.own/tekken3.nv').exists())
            # O caminho em que o core grava e o link para essa pasta.
            self.assertEqual(os.readlink(home / 'save/retroarch/MAME 2010/mame2010/nvram'), str(core))
            # Jogado de novo depois: o que o jogo gravou fica.
            (home / 'nvram/flycast/kofxi.zip.nvmem').write_text('played')
            (core / 'tekken3.nv').write_text('played')
            login()
            self.assertEqual((home / 'nvram/flycast/kofxi.zip.nvmem').read_text(), 'played')
            self.assertEqual((core / 'tekken3.nv').read_text(), 'played')
            # Apagado para comecar do zero: nao volta.
            shutil.rmtree(home / 'nvram/mame/tekken3')
            (home / 'nvram/flycast/mvsc2.zip.eeprom').unlink()
            (core / 'sfa3.nv').unlink()
            login()
            self.assertFalse((home / 'nvram/mame/tekken3').exists())
            self.assertFalse((home / 'nvram/flycast/mvsc2.zip.eeprom').exists())
            self.assertFalse((core / 'sfa3.nv').exists())
            # Um jogo que uma imagem nova trouxer entra.
            (bundled / 'flycast/ngbc.zip.nvmem').write_text('unlocked')
            login()
            self.assertEqual((home / 'nvram/flycast/ngbc.zip.nvmem').read_text(), 'unlocked')
        # O que vem na imagem: cada arquivo no caminho que o emulador grava.
        nv = ROOT / 'config/nvram'
        self.assertTrue((nv / 'mame/tekken3/at28c16').is_file())
        self.assertTrue((nv / 'mame/mk2/nvram').is_file())
        self.assertTrue((nv / 'flycast/kofxi.zip.nvmem2').is_file())
        self.assertFalse(list(nv.glob('flycast/*.net')))
        self.assertIn('archive.org/details/nvram', (nv / 'SOURCES.md').read_text())

    def test_nvram_of_the_image_for_mame_2010_is_the_same_bytes(self):
        # O MAME 2010 (0.139) junta a memoria de um jogo no <set>.nv. Um jogo
        # so entra se o arquivo dele e byte a byte o do MAME atual: o at28c16
        # (2080 bytes), o eeprom do CPS2 (93C46, 128) e o CMOS do umk3 (49152).
        # O mk2 (16 KB aqui, 32 KB no 0.139, com paginas) e o Naomi (varios
        # arquivos) ficam de fora, e o sfex2u/mvsc2u nao existem no 0.139.
        nv = ROOT / 'config/nvram'
        source = {'sfa3': ('eeprom', 128), 'umk3': ('nvram', 49152)}
        source.update({s: ('at28c16', 2080) for s in (
            'doapp', 'kikaioh', 'rvschool', 'rvschoola', 'sfex', 'sfex2', 'soulclbr', 'souledge',
            'stargld2', 'tekken3', 'tektagt')})
        have = sorted(p.name for p in (nv / 'retroarch/mame2010').iterdir())
        self.assertEqual(have, sorted(s + '.nv' for s in source))
        for game, (name, size) in source.items():
            data = (nv / 'mame' / game / name).read_bytes()
            self.assertEqual(len(data), size, game)
            self.assertEqual((nv / 'retroarch/mame2010' / (game + '.nv')).read_bytes(), data, game)
        self.assertIn('retroarch/mame2010', (nv / 'SOURCES.md').read_text())

