class SimpleArgs:
    def __init__(self, **kw):
        self.__dict__.update(kw)


class QuietLaunchTests(unittest.TestCase):
    """Sem texto na tela ao abrir emuladores; o modo debug mostra tudo."""

    def test_limine_menu_shows_in_debug(self):
        self.assertIn('quiet: yes\n', limine_update.render(['6.18.54-15khz'], 'UUID=abc', '', '3'))
        self.assertIn('quiet: no\n', limine_update.render(['6.18.54-15khz'], 'UUID=abc', '', '3', 'no'))

    def run_kms(self, debug):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'logs').mkdir()
            prog = tmp / 'emu'
            prog.write_text('#!/bin/sh\necho saida-do-emulador\n')
            prog.chmod(0o755)
            flag = tmp / 'debug'
            if debug:
                flag.write_text('')
            env = dict(os.environ, FLIPEROS_LOGS=str(tmp / 'logs'), FLIPEROS_DEBUG_FLAG=str(flag))
            env.pop('DISPLAY', None)
            out = subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), str(prog)],
                                 capture_output=True, text=True, env=env).stdout
            log = tmp / 'logs' / 'emu.log'
            return out, log.read_text() if log.exists() else None

    def test_esde_stretches_a_wide_pixel_mode(self):
        # 640x240 num tubo 4:3: o ES-DE desenha em 320x240 e estica 2x
        # (packaging/patches/emulationstation); 320x240 e 640x480, nao.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'logs').mkdir()
            (tmp / 'debug').write_text('')
            prog = tmp / 'es-de'
            prog.write_text('#!/bin/sh\necho "stretch=$ESDE_STRETCH_X"\n')
            prog.chmod(0o755)
            for size, want in (('640,240', '2'), ('320,240', ''), ('640,480', ''), ('1280,240', '4')):
                (tmp / 'fb').write_text(size + '\n')
                env = dict(os.environ, FLIPEROS_LOGS=str(tmp / 'logs'), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'),
                           FLIPEROS_FB_SIZE=str(tmp / 'fb'))
                env.pop('DISPLAY', None)
                env.pop('ESDE_STRETCH_X', None)
                out = subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), str(prog)],
                                     capture_output=True, text=True, env=env).stdout
                self.assertIn('stretch=%s\n' % want, out, size)
        recipe = (ROOT / 'packaging/packages/fliperos-emulationstation.sh').read_text()
        self.assertIn('patches/emulationstation/*.patch', recipe)
        patch = (ROOT / 'packaging/patches/emulationstation/0001-horizontal-stretch.patch').read_text()
        self.assertIn('getenv("ESDE_STRETCH_X")', patch)

    def test_emulator_output_goes_to_the_log(self):
        out, log = self.run_kms(debug=False)
        self.assertEqual(out, '')
        self.assertEqual(log, 'saida-do-emulador\n')
        out, log = self.run_kms(debug=True)
        self.assertEqual(out, 'saida-do-emulador\n')
        for script in ('config/fliperos-x11-run', 'config/fliperos-session'):
            self.assertIn('/etc/fliperos/debug', (ROOT / script).read_text(), script)

    def test_frontend_reading_the_output_waits_for_the_game(self):
        # O ES-DE abre o jogo com popen("comando 2>&1 &") e o da por fechado
        # no fim do arquivo: com a saida no log, o pipe tem de seguir aberto
        # ate o programa sair.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'logs').mkdir()
            prog = tmp / 'emu'
            prog.write_text('#!/bin/sh\nsleep 1\n: > "%s"\n' % (tmp / 'fim'))
            prog.chmod(0o755)
            env = dict(os.environ, FLIPEROS_LOGS=str(tmp / 'logs'), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'))
            env.pop('DISPLAY', None)
            pipe = subprocess.Popen('bash "%s" "%s" 2>&1 &' % (ROOT / 'config/fliperos-kms-run', prog),
                                    shell=True, stdout=subprocess.PIPE, env=env)
            self.assertEqual(pipe.stdout.read(), b'')
            self.assertTrue((tmp / 'fim').exists())
            pipe.wait()
        for script in ('config/fliperos-kms-run', 'config/fliperos-x11-run'):
            text = (ROOT / script).read_text()
            self.assertLess(text.index('exec 9>&1'), text.index('>> "$log" 2>&1'), script)

    def test_program_opened_in_the_background_reads_the_terminal(self):
        # O "comando &" do ES-DE da /dev/null como entrada; o RetroArch le o
        # teclado do console pela entrada e fechava sem terminal nela. Com um
        # terminal na sessao, ele volta a ser a entrada; sem nenhum (um
        # servico), o programa abre assim mesmo.
        import pty
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'logs').mkdir()
            prog = tmp / 'emu'
            prog.write_text('#!/bin/sh\nif [ -t 0 ]; then echo terminal; else echo sem; fi > "%s"\n' % (tmp / 'entrada'))
            prog.chmod(0o755)
            env = dict(os.environ, FLIPEROS_LOGS=str(tmp / 'logs'), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'))
            env.pop('DISPLAY', None)
            command = 'bash "%s" "%s" 2>&1 & wait' % (ROOT / 'config/fliperos-kms-run', prog)
            pid, fd = pty.fork()
            if pid == 0:
                os.execvpe('sh', ['sh', '-c', command], env)
            try:
                while os.read(fd, 1024):
                    pass
            except OSError:
                pass
            os.waitpid(pid, 0)
            os.close(fd)
            self.assertEqual((tmp / 'entrada').read_text(), 'terminal\n')
            subprocess.run(['setsid', 'sh', '-c', command], env=env, stdin=subprocess.DEVNULL,
                           stdout=subprocess.DEVNULL, check=True)
            self.assertEqual((tmp / 'entrada').read_text(), 'sem\n')

    def test_fbneo_console_set_opens_from_a_system_folder(self):
        # O core do FBNeo so abre um set de console numa pasta com o nome do
        # sistema; solto entre os arcades (a pasta do Fightcade) dava "romset
        # is unknown". O fliperos-fbneo acha o sistema pelos .dat do FBNeo; um
        # nome que existe em dois sistemas e decidido pelos CRCs do .zip.
        import zipfile
        import zlib
        tool = str(ROOT / 'config/fliperos-fbneo')
        dat = '<datafile>\n%s</datafile>\n'
        game = '\t<game name="%s"%s>\n\t\t<rom name="a.bin" size="1" crc="%08x"/>\n\t</game>\n'
        crc = lambda data: zlib.crc32(data) & 0xffffffff
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            dats, roms, cache = tmp / 'dats', tmp / 'roms', tmp / 'cache'
            dats.mkdir()
            (roms / 'megadrive').mkdir(parents=True)
            name = 'FinalBurn Neo (ClrMame Pro XML, %s).dat'
            (dats / (name % 'Arcade only')).write_text(
                dat % (game % ('mslug', '', crc(b'arcade')) + game % ('sonic', '', crc(b'sonic arcade'))))
            (dats / (name % 'Megadrive only')).write_text(
                dat % (game % ('sonic', ' romof="mdbios"', crc(b'sonic md')) +
                       game % ('sonicp', ' cloneof="sonic" romof="sonic"', crc(b'proto'))))
            (dats / (name % 'SNES Games only')).write_text(dat % (game % ('mario', '', crc(b'snes'))))
            (dats / (name % 'NES Games only')).write_text(dat % (game % ('mario', '', crc(b'nes'))))
            (dats / 'FinalBurn Neo (ClrMame Pro XML).dat').write_text(dat % (game % ('tudo', '', 1)))
            for path, data in (('mslug', b'arcade'), ('sonic', b'sonic md'), ('sonicp', b'proto'),
                               ('mario', b'nes'), ('outro', b'x'), ('megadrive/sonic', b'sonic md'),
                               ('mdbios', b'bios')):
                with zipfile.ZipFile(roms / (path + '.zip'), 'w') as z:
                    z.writestr('a.bin', data)
            index = tmp / 'share' / 'fbneo-sets.tsv.xz'
            out = subprocess.run(['python3', tool, 'index', str(dats), str(index)], capture_output=True, text=True,
                                 check=True).stdout
            self.assertEqual(out, 'ok %s (6 sets)\n' % index)
            env = dict(os.environ, FLIPEROS_FBNEO_INDEX=str(index), FLIPEROS_FBNEO_CACHE=str(cache))
            path = lambda rom, e=env: subprocess.run(['python3', tool, 'path', str(roms / rom)], env=e, text=True,
                                                     capture_output=True, check=True).stdout.strip()
            # Arcade, ja numa pasta de sistema ou fora das listas: a propria ROM.
            for rom in ('mslug.zip', 'megadrive/sonic.zip', 'outro.zip', 'nada.zip'):
                self.assertEqual(path(rom), str(roms / rom), rom)
            self.assertEqual(path('sonic.zip'), str(cache / 'megadrive' / 'sonic.zip'))
            self.assertEqual(os.path.realpath(cache / 'megadrive' / 'sonic.zip'), os.path.realpath(roms / 'sonic.zip'))
            self.assertEqual(path('mario.zip'), str(cache / 'nes' / 'mario.zip'))
            self.assertTrue((cache / 'megadrive' / 'mdbios.zip').exists())
            # O clone leva o link do set pai junto, e o da BIOS do pai.
            for link in (cache / 'megadrive').iterdir():
                link.unlink()
            self.assertEqual(path('sonicp.zip'), str(cache / 'megadrive' / 'sonicp.zip'))
            self.assertEqual(sorted(p.name for p in (cache / 'megadrive').iterdir()),
                             ['mdbios.zip', 'sonic.zip', 'sonicp.zip'])
            # Sem o indice, nada muda.
            self.assertEqual(path('sonic.zip', dict(env, FLIPEROS_FBNEO_INDEX=str(tmp / 'falta'))),
                             str(roms / 'sonic.zip'))
            # O fliperos-kms-run troca a ROM so no core do FBNeo.
            (tmp / 'logs').mkdir()
            (tmp / 'bin').mkdir()
            ra = tmp / 'bin' / 'retroarch'
            ra.write_text('#!/bin/sh\nfor a; do last=$a; done\nprintf "%%s\\n" "$last" > "%s"\n' % (tmp / 'rom'))
            ra.chmod(0o755)
            env = dict(env, FLIPEROS_LOGS=str(tmp / 'logs'), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'),
                       FLIPEROS_FBNEO=tool, FLIPEROS_RA_CFG=str(tmp / 'ra.cfg'), FLIPEROS_RA_GL=str(tmp / 'gl.cfg'),
                       FLIPEROS_RA_BUTTONS=str(tmp / 'b.cfg'), FLIPEROS_RA_DOFLINX=str(tmp / 'd.cfg'),
                       FLIPEROS_RA_VERSUS=str(tmp / 'v.cfg'), FLIPEROS_PIXELCADE=str(tmp / 'no-pixelcade'),
                       FLIPEROS_OUTPUTS=str(tmp / 'no-outputs'), FLIPEROS_CONF=str(tmp / 'fliperos.conf'),
                       PATH='%s:%s' % (tmp / 'bin', os.environ['PATH']))
            env.pop('DISPLAY', None)
            for core, expected in (('fbneo_libretro.so', cache / 'megadrive' / 'sonic.zip'),
                                   ('mame2010_libretro.so', roms / 'sonic.zip')):
                subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), 'retroarch', '-L', '/cores/' + core,
                                str(roms / 'sonic.zip')], env=env, check=True, stdin=subprocess.DEVNULL)
                self.assertEqual((tmp / 'rom').read_text().strip(), str(expected), core)
        rootfs = (ROOT / 'fliperos-rootfs.sh').read_text()
        self.assertIn('install -Dm755 "$src/config/fliperos-fbneo" "$root/opt/fliperos/bin/fliperos-fbneo"', rootfs)
        for script in ('fliperos-mkiso.sh', 'tools/cabinet-update.sh'):
            self.assertIn('fliperos-fbneo" fetch' if script.endswith('mkiso.sh') else 'fliperos-fbneo fetch',
                          (ROOT / script).read_text(), script)
            self.assertIn('/usr/local/share/fliperos/fbneo-sets.tsv.xz', (ROOT / script).read_text(), script)


class ControllerMappingTests(unittest.TestCase):
    """fliperos-controllers: completa o mapeamento automatico do SDL2 (botoes
    que ele deixa de fora, direcional digital mandado como eixos)."""
    M = controllers
    # Encoder comum: gamepad de 8 botoes (BTN_A B C X Y Z TL TR) com o
    # direcional em dois eixos de -1 a +1. O SDL so mapeia 6 botoes e poe o
    # direcional no analogico.
    AUTO = 'guid,Encoder,a:b0,b:b1,x:b3,y:b4,leftshoulder:b6,rightshoulder:b7,leftx:a0,lefty:a1,crc:1234,'

    def test_leftover_buttons_and_digital_stick(self):
        base = self.M.parse_mapping(self.AUTO)
        self.assertNotIn('crc', base)
        out = self.M.complete(base, 8, 2, 0, {0, 1}, scratch=False)
        self.assertEqual((out['lefttrigger'], out['righttrigger']), ('b2', 'b5'))
        self.assertEqual([out[k] for k in ('dpleft', 'dpright', 'dpup', 'dpdown')], ['-a0', '+a0', '-a1', '+a1'])
        self.assertNotIn('leftx', out)
        self.assertEqual(sorted(v for v in out.values() if v.startswith('b')), ['b%d' % i for i in range(8)])

    def test_real_analog_stick_and_complete_pads_stay(self):
        base = self.M.parse_mapping(self.AUTO)
        out = self.M.complete(base, 8, 2, 0, set(), scratch=False)
        self.assertEqual((out['leftx'], out['lefty']), ('a0', 'a1'))
        full = self.M.parse_mapping('g,Pad,a:b0,b:b1,x:b2,y:b3,dpup:h0.1,leftx:a0,lefty:a1,')
        self.assertEqual(self.M.complete(full, 4, 2, 1, set(), scratch=False), full)

    def test_controllers_without_any_mapping(self):
        out = self.M.complete({}, 10, 2, 0, {0, 1}, scratch=True)
        self.assertEqual((out['a'], out['b'], out['x'], out['start']), ('b0', 'b1', 'b2', 'b9'))
        self.assertEqual(out['dpup'], '-a1')
        hat = self.M.complete({}, 4, 0, 1, set(), scratch=True)
        self.assertEqual((hat['dpup'], hat['dpleft']), ('h0.1', 'h0.8'))

    def test_db_line_and_merge(self):
        self.assertEqual(self.M.mapping_line('abc', 'Pad, X', {'b': 'b1', 'a': 'b0'}),
                         'abc,Pad  X,a:b0,b:b1,platform:Linux,')
        self.assertEqual(self.M.merge_db(['# gerado', 'abc,old', 'def,keep'], {'abc': 'abc,new'}),
                         ['def,keep', 'abc,new'])

    def test_flycast_files_follow_its_convention(self):
        # O Flycast nao entende direcional em meio eixo: o arquivo dele vem
        # pronto, na convencao do DefaultInputMapping (padrao e arcade).
        binds = self.M.complete(self.M.parse_mapping(self.AUTO), 8, 2, 0, {0, 1}, scratch=False)
        std = self.M.flycast_cfg('Encoder', binds, arcade=False)
        for bind in ('0-:btn_dpad1_left', '1+:btn_dpad1_down', '0:btn_a', '3:btn_x', '6:btn_z', '7:btn_c',
                     '2:btn_trigger_left', '5:btn_trigger_right'):
            self.assertIn(bind + '\n', std, bind)
        arcade = self.M.flycast_cfg('Encoder', binds, arcade=True)
        for bind in ('3:btn_c', '4:btn_x', '7:btn_y', '6:btn_z'):
            self.assertIn(bind + '\n', arcade, bind)
        self.assertIn('version = 4\n', arcade)
        self.assertEqual(self.M.flycast_filename('vusb.wikidot.com/project:x Pad', arcade=True),
                         'SDL_vusb.wikidot.com-project-x Pad_arcade.cfg')

    def test_retroarch_profile_in_panel_order(self):
        # Painel de 8 botoes com o direcional em eixos: 1 2 3 = Y X L,
        # 4 5 6 = B A R, depois Start e Select, na numeracao do udev.
        binds = self.M.complete(self.M.parse_mapping(self.AUTO), 8, 2, 0, {0, 1}, scratch=False)
        self.assertTrue(self.M.is_arcade(binds))
        ra = self.M.retroarch_binds(binds, 8)
        self.assertEqual([ra[k + '_btn'] for k in ('y', 'x', 'l', 'b', 'a', 'r', 'start', 'select')],
                         [str(i) for i in range(8)])
        self.assertEqual([ra[k + '_axis'] for k in ('up', 'down', 'left', 'right')], ['-1', '+1', '-0', '+0'])
        # Encoder de 12 com hat: os extras de painel de 8, Select/Start nos 9 e 10.
        hat = self.M.complete({}, 12, 0, 1, set(), scratch=True)
        ra = self.M.retroarch_binds(hat, 12)
        self.assertEqual([ra[k + '_btn'] for k in ('l2', 'r2', 'select', 'start', 'l3', 'r3')],
                         ['6', '7', '8', '9', '10', '11'])
        self.assertEqual((ra['up_btn'], ra['left_btn']), ('h0up', 'h0left'))
        # Com analogico de verdade nao e painel: fica com o RetroArch.
        analog = self.M.complete(self.M.parse_mapping(self.AUTO), 8, 2, 0, set(), scratch=False)
        self.assertFalse(self.M.is_arcade(analog))
        text = self.M.retroarch_profile('Painel', (5824, 1503), binds, 8)
        for line in ('input_driver = "udev"', 'input_device = "Painel"', 'input_vendor_id = "5824"',
                     'input_product_id = "1503"', 'input_start_btn = "6"', 'input_up_axis = "-1"'):
            self.assertIn(line + '\n', text, line)

    def test_retroarch_linuxraw_profile(self):
        # No joystick do kernel os hats sao eixos, na ordem dos codigos do
        # evdev: X Y (0, 1), HAT0X HAT0Y (2, 3), e um eixo depois deles (4).
        hat = self.M.complete({}, 12, 0, 1, set(), scratch=True)
        js = ({0: 0, 1: 1, 2: 4}, {0: (2, 3)})
        ra = self.M.retroarch_binds(hat, 12, js)
        self.assertEqual([ra[k + '_axis'] for k in ('up', 'down', 'left', 'right')], ['-3', '+3', '-2', '+2'])
        self.assertNotIn('up_btn', ra)
        binds = dict(hat, dpup='-a2', dpdown='+a2', dpleft='-a0', dpright='+a0')
        self.assertEqual(self.M.retroarch_binds(binds, 12, js)['up_axis'], '-4')
        text = self.M.retroarch_profile('Painel', (5824, 1503), hat, 12, 'linuxraw', js)
        self.assertIn('input_driver = "linuxraw"\n', text)
        self.assertEqual(self.M.RA_DRIVERS, ('udev', 'linuxraw'))

    def test_retroarch_profile_only_when_none_matches(self):
        with tempfile.TemporaryDirectory() as tmp:
            self.assertFalse(self.M.retroarch_has_profile(tmp, 'Painel', (5824, 1503)))
            Path(tmp, 'a.cfg').write_text('input_device = "Outro"\ninput_vendor_id = 5824\ninput_product_id = 1503\n')
            self.assertTrue(self.M.retroarch_has_profile(tmp, 'Painel', (5824, 1503)))
            self.assertFalse(self.M.retroarch_has_profile(tmp, 'Painel', (1, 2)))
            Path(tmp, 'b.cfg').write_text('input_driver = "udev"\ninput_device = "Painel"\n')
            self.assertTrue(self.M.retroarch_has_profile(tmp, 'Painel', (0, 0)))

    def test_runs_at_boot_and_on_hotplug(self):
        rules = (ROOT / 'config/99-fliperos-input.rules').read_text()
        self.assertIn('ENV{SYSTEMD_WANTS}+="fliperos-controllers.service"', rules)
        self.assertIn('multi-user.target.wants/fliperos-controllers.service', ROOTFS)
        self.assertIn("echo 'SDL_GAMECONTROLLERCONFIG_FILE=/var/lib/fliperos/gamecontrollerdb.txt'", ROOTFS)
        for script in ('config/fliperos-lxde', 'config/fliperos-kms-run', 'config/fliperos-x11-run'):
            self.assertIn('/var/lib/fliperos/gamecontrollerdb.txt', (ROOT / script).read_text(), script)
        self.assertFalse((ROOT / 'config/gamecontrollerdb.txt').exists())


