    def test_auto_scrape_only_missing(self):
        # O scrape sozinho (2 s parado no jogo, em qualquer modo) so baixa a
        # arte que falta; o Scrape this game do Tab baixa tudo de novo.
        fd = self.fd
        have = {'snap'}

        class Info:
            cache = {}

            def path(self, *a):
                return None

            def arcade(self, *a):
                return {'url_image_ingame': 'http://x/s.png', 'url_image_marquee': 'http://x/m.png',
                        'url_image_flyer': 'http://x/f.png', 'url_video_shortplay': 'http://x/download_file.php?codice=sf2'}, None

        class Lib:
            info = Info()

            def media(self, game, kind):
                return '/m/' + kind if kind in have else None

            def video(self, game):
                return None

        game = {'Name': 'sf2', '_system': {'key': 'mame', 'arcade': True}}
        got = []
        old = fd.download
        try:
            os.environ['FLIPEROS_HOME'] = '/nonexistent'
            fd.PACKS_FILE = '/nonexistent'
            fd.download = lambda url, path: got.append(os.path.basename(path)) or True
            self.assertEqual(fd.missing_art(Lib(), game), ['box', 'marquee', 'logo', 'preview'])
            fd.scrape(Lib(), game, only_missing=True)
            # O marquee, o flyer, o video e o logo (o decal do Arcade Database).
            self.assertEqual(got, ['sf2.png', 'sf2.png', 'sf2.mp4', 'sf2.png'])
            got.clear()
            fd.scrape(Lib(), game)
            self.assertEqual(len(got), 5)
        finally:
            fd.download = old
            os.environ.pop('FLIPEROS_HOME', None)

    def test_auto_scrape_of_every_game(self):
        # O scrape automatico (feharvest.py): conta os jogos sem os dados,
        # busca cada um sem os videos (que vem dos torrents, fliperos-setup
        # --mediapacks auto) e nao tenta de novo o que ja tentou.
        import feharvest
        fd = self.fd
        tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, tmp, True)
        arcade = {'key': 'mame', 'arcade': True}
        console = {'key': 'snes', 'arcade': False}
        have = {('sf2', 'snap'), ('sf2', 'box'), ('sf2', 'marquee'), ('sf2', 'logo'),
                ('mario', 'snap'), ('mario', 'box')}

        class Info:
            cache = {}

            def path(self, key, name, lang):
                return str(tmp / ('%s.json' % name))

            def arcade(self, *a):
                return {'url_image_ingame': 'http://x/s.png', 'url_video_shortplay': 'http://x/v.mp4'}, None

        class Lib:
            info = Info()
            systems = [arcade, console]
            generation = 0

            def media(self, game, kind):
                return '/m' if (game['Name'], kind) in have else None

            def video(self, game):
                return None

            def games(self, system):
                names = {'mame': ['sf2', 'kof98'], 'snes': ['mario', 'zelda']}[system['key']]
                return [{'Name': n, '_system': system} for n in names]

        (tmp / 'sf2.json').write_text('{}')
        fe = type('Fe', (), {})()
        fe.fd, fe.lib, fe.scraping = fd, Lib(), None
        os.environ['FLIPEROS_HOME'] = str(tmp)
        got = []
        old = fd.download, fd.PACKS_FILE
        try:
            fd.download = lambda url, path: got.append(url) or True
            fd.PACKS_FILE = '/nonexistent'
            h = feharvest.Harvester(fe)
            todo = h.scan()
            self.assertEqual((h.total, h.left), (4, 2))
            self.assertEqual([g['Name'] for g in todo], ['kof98', 'zelda'])
            fd.scrape(fe.lib, todo[0], only_missing=True, bulk=True)
            self.assertIn('http://x/s.png', got)
            self.assertNotIn('http://x/v.mp4', got)
            h.state['tried'] = {'mame/kof98': int(time.time())}
            self.assertEqual([g['Name'] for g in h.scan()], ['zelda'])
        finally:
            fd.download, fd.PACKS_FILE = old
            os.environ.pop('FLIPEROS_HOME', None)
        setup = (ROOT / 'fliperos-setup/fliperos-setup').read_text()
        self.assertIn('auto) mediapacks_auto ;;', setup)
        self.assertIn('mediapacks_auto() {', (ROOT / 'fliperos-setup/lib/mediapacks.sh').read_text())

    def test_logo_and_video_from_art_packs(self):
        # O logo e o video que o Arcade Database nao tem saem dos pacotes do
        # archive.org da lista do Setup, um arquivo so: solto, ou de dentro
        # do .zip da letra.
        fd = self.fd
        tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, tmp, True)
        packs = tmp / 'packs'
        packs.write_text('wheels\tlogo\tmame,@arcade-cores\thttps://archive.org/download/wheels/w.torrent\tLogos\n'
                         'videos\tpreview\t@arcade\thttps://archive.org/download/videos/v.torrent\tVideos\n'
                         'naomi\tlogo\tnaomi\thttps://archive.org/download/naomi/n.torrent\tNaomi\n')
        pages = {'metadata/wheels/files': json.dumps({'result': [{'name': 'sf2.png'}, {'name': 'sf2_thumb.jpg'}]}),
                 'metadata/videos/files': json.dumps({'result': [{'name': 'S.zip'}, {'name': '#.zip'}]}),
                 'download/videos/S.zip/': '<a href="//archive.org/download/videos/S.zip/S%2Fsf2.mp4">x</a>'}
        old = fd.PACKS_FILE, fd.fetch_text, fd.download
        got = []
        try:
            os.environ['FLIPEROS_HOME'] = str(tmp)
            fd.PACKS_FILE = str(packs)
            fd.fetch_text = lambda url, name: pages.get(url.split('archive.org/', 1)[1])
            fd.download = lambda url, path: got.append((url, os.path.relpath(path, tmp))) or True
            mame = {'key': 'mame', 'arcade': True}
            self.assertEqual(fd.art_packs(mame, 'logo'), ['wheels'])
            self.assertEqual(fd.art_packs({'key': 'retroarch/fbneo', 'arcade': True}, 'logo'), ['wheels'])
            self.assertEqual(fd.art_packs({'key': 'naomi', 'arcade': True}, 'preview'), ['videos'])
            self.assertEqual(fd.art_packs({'key': 'snes', 'arcade': False}, 'logo'), [])
            game = {'Name': 'sf2ce', 'CloneOf': 'sf2', '_system': mame}
            self.assertEqual(fd.pack_art(None, game, ['logo', 'preview']), 2)
            self.assertEqual(got, [('https://archive.org/download/wheels/sf2.png', 'media/logo/mame/sf2ce.png'),
                                   ('https://archive.org/download/videos/S.zip/S%2Fsf2.mp4',
                                    'media/preview/mame/sf2ce.mp4')])
        finally:
            fd.PACKS_FILE, fd.fetch_text, fd.download = old
            os.environ.pop('FLIPEROS_HOME', None)

    def test_delete_game(self):
        # Apagar um jogo (Tab > Delete this game): a ROM e, no arcade, a
        # pasta dos CHDs de mesmo nome; a arte fica.
        fd = self.fd
        tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, tmp, True)
        (tmp / 'kinst.zip').write_bytes(b'x')
        (tmp / 'kinst').mkdir()
        (tmp / 'kinst' / 'kinst.chd').write_bytes(b'x')
        (tmp / 'sf2.zip').write_bytes(b'x')
        lib = fd.Library.__new__(fd.Library)
        lib.lock = threading.Lock()
        lib.cache, lib.epoch = {'x': []}, 0
        system = {'key': 'mame', 'arcade': True, 'folder': str(tmp)}
        game = {'Name': 'kinst', 'file': 'kinst.zip', '_system': system}
        self.assertEqual(len(lib.rom_files(game)), 2)
        self.assertEqual(lib.delete(game), 2)
        self.assertEqual(sorted(p.name for p in tmp.iterdir()), ['sf2.zip'])
        self.assertEqual(lib.cache, {})
        # O clone sem arquivo proprio (dentro do zip do pai) nao tem o que apagar.
        self.assertEqual(lib.rom_files({'Name': 'sf2ce', '_system': system}), [])

    def test_game_counts_cached_and_lists_read_ahead(self):
        # A tira dos sistemas mostra o numero de jogos de cada romlist ja ao
        # passar por ela (o da ultima vez, em ~/.cache/fliperos), e as listas
        # das outras sao lidas em segundo plano: escolher um sistema abre na
        # hora. O "Arcade" junta as listas das pastas (cada uma lida uma vez).
        fd = self.fd
        tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, tmp, True)
        os.environ['FLIPEROS_HOME'] = str(tmp)
        self.addCleanup(os.environ.pop, 'FLIPEROS_HOME', None)
        reads = []

        def games(system, favs=frozenset()):
            reads.append(system['key'])
            return [{'Name': '%s%d' % (system['key'], i), 'Title': '%s %d' % (system['key'], i)} for i in range(3)]
        old = fd.web.games, fd.PRELOAD_REST
        fd.web.games, fd.PRELOAD_REST = games, 0
        self.addCleanup(lambda: setattr(fd.web, 'games', old[0]) or setattr(fd, 'PRELOAD_REST', old[1]))
        # A arte de cada sistema (a pasta de cada tipo) e listada na pre-carga, nao no primeiro quadro.
        listed = []
        old_names = fd.web.media_names
        fd.web.media_names = lambda base: listed.append(base) or frozenset()
        self.addCleanup(setattr, fd.web, 'media_names', old_names)
        lib = fd.Library.__new__(fd.Library)
        lib.lock, lib.count_lock = threading.Lock(), threading.Lock()
        lib.cache, lib.epoch, lib.counts = {}, 0, fd.load_counts()
        lib.preload_job, lib.preloading = None, False
        lib.edits = lambda system, name: {}
        lib.favourites = lambda: set()
        self.assertEqual(lib.counts, {})
        mame, fbneo = {'key': 'mame', 'name': 'MAME'}, {'key': 'fbneo', 'name': 'FBNeo'}
        arcade = {'key': '@arcade', 'name': 'Arcade', 'parts': [mame, fbneo]}
        lib.preload([mame, arcade, fbneo], lambda cat: len(lib.games(cat)))
        deadline = time.monotonic() + 5
        while lib.preloading and time.monotonic() < deadline:
            time.sleep(0.01)
        self.assertFalse(lib.preloading)
        self.assertEqual(sorted(reads), ['fbneo', 'mame'])
        self.assertEqual(sorted(os.path.relpath(p, str(tmp)) for p in listed if p.endswith('/mame')),
                         sorted('media/%s/mame' % k for k in fd.MEDIA_KINDS))
        self.assertEqual([g['Name'] for g in lib.cache['@arcade']][:2], ['fbneo0', 'fbneo1'])
        self.assertIs(lib.cache['@arcade'][3], lib.cache['mame'][0])
        # Gravado no cache: o frontend aberto de novo ja tem os numeros.
        self.assertEqual(fd.load_counts(), {'mame': 3, '@arcade': 6, 'fbneo': 3})
        lib.set_count('mame', 2)
        self.assertEqual(fd.load_counts()['mame'], 2)
        # Uma lista lida antes de o cache esvaziar (releitura) nao entra nele.
        epoch = lib.epoch
        lib.forget()
        lib.keep('mame', [], epoch)
        self.assertEqual(lib.cache, {})
        lib.keep('mame', [], lib.epoch)
        self.assertEqual(lib.cache, {'mame': []})
        # A tira: o numero do sistema no meio vem do cache, tambem antes de
        # abrir a lista dele.
        view = (ROOT / 'fliperos-setup/gui/feview.py').read_text()
        ribbon = view.split('def draw_ribbon(')[1].split('\ndef ')[0]
        self.assertIn('shown = counts.get(c["key"])', ribbon)
        frontend = (ROOT / 'fliperos-setup/gui/fliperos-frontend').read_text()
        self.assertIn('self.lib.set_count(cat["key"], self.count_of(games))', frontend)
        self.assertIn('self.lib.preload([self.cats[i] for i in order], self.list_count)', frontend)

