    def test_ribbon_tiles_get_the_system_logo_once(self):
        # Os azulejos da tira de romlists: o logotipo escrito do sistema
        # (fliperos-syslogo png NOME ARQUIVO 48 f8f8f2) e feito uma vez e fica em
        # ~/.cache; sem logotipo (status 1), None e o azulejo fica com o icone.
        try:
            import pygame
        except ImportError:
            self.skipTest('pygame')
        os.environ.setdefault('SDL_VIDEODRIVER', 'dummy')
        pygame.init()
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        try:
            import feview
        finally:
            sys.path.remove(str(ROOT / 'fliperos-setup/gui'))
        with tempfile.TemporaryDirectory() as tmp:
            tool, seen = Path(tmp) / 'syslogo', Path(tmp) / 'seen'
            tool.write_text('#!/bin/sh\necho "$@" >> %s\n[ "$2" = "Naomi 2" ] || exit 1\nprintf png > "$3"\n' % seen)
            tool.chmod(0o755)
            old = feview.SYSLOGO, feview.SYSLOGO_CACHE
            feview.SYSLOGO, feview.SYSLOGO_CACHE = str(tool), str(Path(tmp) / 'cache')
            try:
                path = feview.logo_file('Naomi 2')
                self.assertEqual(path, str(Path(tmp) / 'cache/Naomi_2-48.png'))
                self.assertEqual(Path(path).read_bytes(), b'png')
                self.assertEqual(feview.logo_file('Naomi 2'), path)
                self.assertIsNone(feview.logo_file('Super Nintendo'))
                # O temporario termina em .png (o Pillow do fliperos-syslogo escolhe o formato por ela).
                self.assertEqual(seen.read_text().splitlines(),
                                 ['png Naomi 2 %s/cache/Naomi_2-48.tmp.png 48 f8f8f2' % tmp,
                                  'png Super Nintendo %s/cache/Super_Nintendo-48.tmp.png 48 f8f8f2' % tmp])
            finally:
                feview.SYSLOGO, feview.SYSLOGO_CACHE = old
        src = (ROOT / 'fliperos-setup/gui/feview.py').read_text()
        # O logotipo ocupa 80% do azulejo fluido, o icone fica na borda do canto
        # e o nome escrito so aparece sem logotipo.
        self.assertIn('system_logo(c["name"], round(wf * 0.8), round(sf * 0.8))', src)
        self.assertIn('x + w - round(badge.get_width() * 0.65)', src)
        self.assertIn('if logo_source(c["name"]) is None:', src)
        # E no topo, ao lado do nome da romlist.
        self.assertIn('title_logo(ui, cat["name"])', src)

    def test_idle_frontend_starts_the_marquee_screensaver_and_a_press_stops_it(self):
        import types
        fm = self.frontend_module()
        with tempfile.TemporaryDirectory() as tmp:
            tool, seen = Path(tmp) / 'pixelcade', Path(tmp) / 'seen'
            tool.write_text('#!/bin/sh\necho "$@" >> %s\n' % seen)
            tool.chmod(0o755)
            fm.PIXELCADE_TOOL = str(tool)
            self.assertEqual(fm.IDLE_SECONDS, 30.0)
            fe = types.SimpleNamespace(shot=None, last_input=100.0, idle=False, category=lambda: None)
            fe.marquee_logo = lambda *a: fm.Frontend.marquee_logo(fe, *a)
            idle = lambda now, active=False: fm.Frontend.marquee_idle(fe, now, active)

            def calls(wait=0.0):
                deadline = time.time() + wait
                while not seen.exists() and time.time() < deadline:
                    time.sleep(0.05)
                return seen.read_text().splitlines() if seen.exists() else []
            # Antes dos 30 s, nada; um botao reinicia a conta.
            idle(129.0)
            idle(150.0, True)
            idle(179.0)
            self.assertEqual(calls(0.3), [])
            # Passados os 30 s: o protetor de tela comeca, uma vez so.
            idle(180.5)
            self.assertEqual(calls(5), ['bg screensaver start'])
            idle(200.0)
            time.sleep(0.3)
            self.assertEqual(calls(), ['bg screensaver start'])
            # O primeiro toque sem sistema (sem listas): o stop, em segundo plano.
            idle(210.0, True)
            deadline = time.time() + 5
            while len(calls()) < 2 and time.time() < deadline:
                time.sleep(0.05)
            self.assertEqual(calls(), ['bg screensaver start', 'bg screensaver stop'])
            idle(212.0)
            self.assertEqual(len(calls()), 2)
            # Com o sistema de agora: o toque manda o logotipo dele (que tambem
            # tira o protetor de tela), sem depender do que estava gravado.
            fe.category = lambda: {'name': 'Naomi'}
            idle(250.0)
            idle(260.0, True)
            deadline = time.time() + 5
            while len(calls()) < 4 and time.time() < deadline:
                time.sleep(0.05)
            self.assertEqual(calls()[2:], ['bg screensaver start', 'bg logo Naomi  1'])
            self.assertEqual(fe.announced, 'Naomi')
            fe.category = lambda: None
            # Desligado (0) ou nos prints (--shot), nao manda nada; sem o programa, sem erro.
            fm.IDLE_SECONDS = 0.0
            idle(1000.0)
            fe.shot = 'x'
            fm.IDLE_SECONDS = 30.0
            idle(2000.0)
            fe.shot = None
            fe.idle = False
            fm.PIXELCADE_TOOL = str(Path(tmp) / 'nenhum')
            idle(3000.0)
            self.assertEqual(len(calls()), 4)

    def test_exit_key_table_and_panel_keys(self):
        import types
        fm = self.frontend_module()
        names = ['K_ESCAPE', 'K_BACKSPACE', 'K_TAB', 'K_RETURN', 'K_SPACE', 'K_PAUSE', 'K_HOME', 'K_END', 'K_INSERT',
                 'K_DELETE', 'K_PAGEUP', 'K_PAGEDOWN', 'K_0'] + ['K_F%d' % n for n in range(1, 13)] + \
            ['K_' + c for c in 'qwertyuiopasdfghjklzxcvbnm'] + ['K_%d' % n for n in range(1, 10)]
        pg = types.SimpleNamespace(**{n: i for i, n in enumerate(names)})
        table = fm.evdev_keys(pg)
        self.assertEqual(table[pg.K_ESCAPE], ('ESC', 1))
        self.assertEqual(table[pg.K_F12], ('F12', 88))
        self.assertEqual(table[pg.K_p], ('P', 25))
        self.assertEqual(table[pg.K_5], ('5', 6))
        # A tecla de um encoder do painel (k:5 e a ficha) nao fecha o jogo.
        self.assertEqual(fm.panel_keys([('coin', 0, 'k:5'), ('b1', 0, 'k:LCONTROL'), ('b2', 0, 'b1')]), {'5', 'CTRL'})
        self.assertEqual(fm.combo_names(['b2', 'start', 'coin']), ['2', 'START', 'COIN'])

