    def test_switch_bounce_is_one_move(self):
        # O repique do microswitch: apertar pulava dois, soltar mais um.
        fi = self.fi
        inp = object.__new__(fi.Input)
        inp.down, inp.sources, inp.loose = {}, {}, {}
        clock = [10.0]
        real = fi.time.monotonic
        fi.time.monotonic = lambda: clock[0]
        try:
            out = []
            for pressed, t in ((1, 0.0), (0, 0.004), (1, 0.008), (0, 0.2), (1, 0.203), (0, 0.207)):
                clock[0] = 10.0 + t
                inp.settle()
                if pressed:
                    inp.press('up', 'hat', out)
                else:
                    inp.release('up', 'hat')
            clock[0] = 10.5
            inp.settle()
            self.assertEqual(out, ['up'])
            self.assertIsNone(inp.held('up'))
            # Dois toques de verdade sao dois.
            inp.press('up', 'hat', out)
            inp.release('up', 'hat')
            clock[0] = 10.7
            inp.settle()
            inp.press('up', 'hat', out)
            self.assertEqual(out, ['up', 'up', 'up'])
        finally:
            fi.time.monotonic = real

    def test_a_pad_plugged_in_with_the_frontend_open_works(self):
        # Um controle ligado com o frontend aberto avisava e nao andava nos
        # menus: o mapa era lido so ao abrir, e um controle fora dele nao tinha
        # comando nenhum. Agora o que o mapa nao tem anda como um controle comum
        # (so direcional digital e botoes num que nao e game controller: o eixo
        # de um volante ou pedal), e o mapa reescrito (o Bluetooth que chega,
        # fliperos-buttons save) e lido de novo.
        fi = self.fi
        mapped = [('up', 0, 'h0.1'), ('b1', 0, 'b0')]
        rows = fi.unmapped_rows(mapped, {0: True, 1: True, 2: False})
        self.assertFalse([r for r in rows if r[1] == 0])
        self.assertIn(('b1', 1, 'b0'), rows)
        self.assertIn(('up', 1, '-a1'), rows)
        self.assertIn(('down', 2, 'h0.4'), rows)
        self.assertFalse([r for r in rows if r[1] == 2 and 'a' in r[2]])
        self.assertEqual(fi.unmapped_rows([], {1: True}), [])                    # sem mapa: DEFAULT para todos
        self.assertEqual(fi.unmapped_rows([('b1', -1, 'b0')], {1: True}), [])    # o mapa vale para qualquer um
        self.assertIn(('b1', 0, 'b0'), fi.unmapped_rows([('b1', -1, 'k:LCONTROL')], {0: True}))
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'buttons.map'
            path.write_text('1 up 0 h0.1 Panel\n1 b1 0 b0 Panel\n')
            real = fi.MAP
            fi.MAP = str(path)
            try:
                inp = object.__new__(fi.Input)
                inp.pg, inp.pads, inp.player_down = self.fake_pygame(), {0: True, 1: True}, {}
                inp.load_map()
                self.assertEqual(inp.match('b0', 1), ['b1'])
                path.write_text('1 up 0 h0.1 Panel\n1 b1 0 b0 Panel\n2 b1 1 b3 Pad\n2 up 1 h0.1 Pad\n')
                inp.check_map()                     # antes do MAP_POLL: ainda o controle comum
                self.assertEqual(inp.match('b3', 1), ['b4'])
                inp.map_checked = 0.0
                inp.check_map()
                self.assertEqual(inp.match('b3', 1), ['b1'])
                self.assertEqual(inp.match('b0', 1), [])
            finally:
                fi.MAP = real
        source = (ROOT / 'fliperos-setup/gui/feinput.py').read_text()
        self.assertIn('self.check_map()\n        for ev in pg.event.get():', source)

    @staticmethod
    def fake_pygame():
        import types
        names = ['K_UP', 'K_DOWN', 'K_LEFT', 'K_RIGHT', 'K_RETURN', 'K_ESCAPE', 'K_PAGEUP', 'K_PAGEDOWN', 'K_f',
                 'K_v', 'K_TAB', 'K_q']
        pg = types.SimpleNamespace(**{n: 100 + i for i, n in enumerate(names)})
        codes = {'left ctrl': 1, 'left alt': 2, 'space': 3, 'left shift': 4, 'z': 5, 'x': 6, '1': 7, '5': 8, 'a': 9}

        def key_code(name):
            if name not in codes:
                raise ValueError(name)
            return codes[name]
        pg.key = types.SimpleNamespace(key_code=key_code, name=lambda k: {pg.K_q: 'q', 1: 'left ctrl'}.get(k, ''))
        return pg

    def test_frontend_controls_map(self):
        # Tab > Frontend options > Frontend controls: cada funcao com um
        # comando do painel e uma tecla. Sem nada gravado, o de sempre.
        fi, pg = self.fi, self.fake_pygame()
        binds = fi.default_binds(pg)
        self.assertEqual(binds['b1'], {'pad': 'b1', 'joy': 'accept', 'key': pg.K_RETURN})
        self.assertEqual(binds['tab'], {'pad': None, 'joy': 'select', 'key': pg.K_TAB})
        self.assertEqual(binds['b5'], {'pad': 'b5', 'joy': 'west', 'key': None})
        self.assertEqual(list(binds), list(fi.FUNCTIONS))
        self.assertNotIn('coin', fi.PAD)
        # Gravado: por cima do padrao; o que nao vale fica de fora, e um
        # comando em duas funcoes fica so na primeira.
        saved = {'tab': {'pad': 'b5'}, 'b5': {'pad': None, 'key': pg.K_q}, 'b4': {'pad': 'coin', 'key': 'x'},
                 'b6': {'key': True}, 'b3': {'pad': 'b1'}, 'nada': {'pad': 'b2'}}
        binds = fi.load_binds(pg, saved)
        self.assertEqual(binds['tab'], {'pad': 'b5', 'joy': 'select', 'key': pg.K_TAB})
        self.assertEqual(binds['b5'], {'pad': None, 'joy': 'west', 'key': pg.K_q})
        self.assertEqual(binds['b4'], {'pad': 'b4', 'joy': 'north', 'key': pg.K_f})
        self.assertEqual(binds['b6']['key'], pg.K_PAGEDOWN)
        # A coluna JOYPAD: o papel gravado vale (um que nao existe nao), e o
        # mesmo papel em duas funcoes fica so na primeira.
        joyed = fi.load_binds(pg, {'b2': {'joy': 'l2'}, 'b3': {'joy': 'nada'}, 'b6': {'joy': 'accept'}})
        self.assertEqual((joyed['b2']['joy'], joyed['b3']['joy'], joyed['b6']['joy']), ('l2', 'l1', None))
        self.assertEqual([fi.joy_name(r) for r in ('accept', 'cancel', 'north', 'l1', None)],
                         ['ACCEPT', 'BACK', 'NORTH', 'L1', None])
        self.assertEqual((binds['b1']['pad'], binds['b3']['pad']), ('b1', None))
        self.assertEqual(fi.load_binds(pg, 'x'), fi.default_binds(pg))
        # Dar a uma funcao o botao de outra troca os dois; o mesmo de novo, ou
        # None, deixa a funcao sem nada (pode, e o guia nao desenha o botao).
        binds = fi.default_binds(pg)
        self.assertEqual(fi.assign(binds, 'tab', 'pad', 'b5'), ('b5', 'b5'))
        self.assertEqual((binds['tab']['pad'], binds['b5']['pad']), ('b5', None))
        self.assertEqual(fi.assign(binds, 'b4', 'pad', 'b1'), ('b1', 'b1'))
        self.assertEqual((binds['b4']['pad'], binds['b1']['pad']), ('b1', 'b4'))
        self.assertEqual(fi.assign(binds, 'b4', 'pad', 'b1'), (None, None))
        self.assertIsNone(binds['b4']['pad'])
        self.assertEqual(fi.assign(binds, 'b2', 'key', None), (None, None))
        self.assertIsNone(binds['b2']['key'])
        self.assertEqual(fi.assign(binds, 'start', 'key', pg.K_TAB), (pg.K_TAB, 'tab'))
        self.assertEqual((binds['start']['key'], binds['tab']['key']), (pg.K_TAB, pg.K_v))
        self.assertEqual([fi.pad_name(c) for c in ('b3', 'start', 'up', None)], ['BUTTON 3', 'START', 'UP', None])
        self.assertEqual(fi.key_name(pg, pg.K_q), 'Q')

    def test_panel_and_keys_become_the_mapped_functions(self):
        # O comando do painel faz a funcao que o mapa deu a ele; a ficha e
        # sempre a ficha; o estado dos comandos (os botoes do atalho que fecha
        # o jogo) e o do painel, nao o das funcoes.
        fi, pg = self.fi, self.fake_pygame()
        inp = object.__new__(fi.Input)
        inp.down, inp.sources, inp.loose = {}, {}, {}
        inp.capture_pad = False
        binds = fi.default_binds(pg)
        fi.assign(binds, 'tab', 'pad', 'b5')
        inp.bind(binds)
        out = []
        inp.pad_press('b5', ('b', 0, 4), out)
        inp.pad_press('coin', ('b', 0, 6), out)
        inp.pad_press('b1', ('b', 0, 0), out)
        self.assertEqual(out, ['tab', 'coin', 'b1'])
        self.assertEqual(inp.pad_held(), {'b5', 'coin', 'b1'})
        self.assertIsNotNone(inp.held('tab'))
        self.assertIsNone(inp.held('b5'))
        # Escolhendo o comando de uma funcao: "pad:COMANDO", sem a funcao.
        inp.capture_pad = True
        out = []
        inp.pad_press('b6', ('b', 0, 5), out)
        self.assertEqual(out, ['pad:b6'])
        self.assertIsNone(inp.held('b6'))
        # Um comando sem funcao nao faz nada.
        inp.capture_pad = False
        fi.assign(binds, 'b3', 'pad', None)
        inp.bind(binds)
        out = []
        inp.pad_press('b3', ('b', 0, 2), out)
        self.assertEqual(out, [])
        # As teclas do encoder: os k: do mapa; sem nenhum, as do MAME.
        self.assertEqual(fi.panel_keyboard(pg, [('b1', 0, 'k:A'), ('up', 0, 'h0.1')]), {9: 'b1'})
        mame = fi.panel_keyboard(pg, [('b1', 0, 'b0')])
        self.assertEqual(mame, {1: 'b1', 2: 'b2', 3: 'b3', 4: 'b4', 5: 'b5', 6: 'b6', 7: 'start', 8: 'coin'})

    def test_frontend_controls_screen_and_guide(self):
        # A area Frontend controls no Tab, e o guia desenhado pelo mapa: o
        # botao sem funcao sai do guia.
        src = (ROOT / 'fliperos-setup/gui/fliperos-frontend').read_text()
        self.assertIn('elif sel == OPT_CONTROLS and a == "b1":', src)
        self.assertIn('"controls": self.input.binds, "panel_layout": self.panel_layout', src)
        self.assertIn('held = frozenset(self.input.players_held())', src)
        # A primeira abertura comeca no Frontend controls; ao sair dele, o guia.
        self.assertIn('self.controls_seen = cfg.get("controls_seen") is True', src)
        self.assertIn('self.overlay, self.ov = "controls", {"sel": CONTROLS_FIRST, "col": 0, "wait": None}', src)
        self.assertIn('"controls_seen": self.controls_seen', src)
        # O SAVE no fim, ao lado do RESET: grava e sai, como o back.
        self.assertIn('elif a == "b1" and sel == reset_row and ov["col"] == 1:', src)
        self.assertIn('(("RESET", reset_icon, T.ORANGE), ("SAVE", save_icon, T.GREEN))',
                      (ROOT / 'fliperos-setup/gui/feview.py').read_text())
        view = (ROOT / 'fliperos-setup/gui/feview.py').read_text()
        self.assertIn('("controls", "FRONTEND CONTROLS")', view)
        # O atalho que fecha o jogo fica dentro do Frontend controls, nao no Tab.
        self.assertNotIn('"EXIT KEY")', view)
        self.assertIn('y = label(exit_row, "EXIT GAME", exit_icon, T.RED)', view)
        self.assertIn('elif a == "b1" and sel in rows and ov["col"] < 2:', src)
        self.assertNotIn('OPT_EXIT', src)
        try:
            import pygame
        except ImportError:
            self.skipTest('pygame')
        import types
        os.environ.setdefault('SDL_VIDEODRIVER', 'dummy')
        pygame.init()
        import feview
        fi = self.fi
        binds = fi.default_binds(pygame)
        fe = types.SimpleNamespace(pg=pygame, input=types.SimpleNamespace(binds=binds),
                                   fd=types.SimpleNamespace(web=types.SimpleNamespace(button_layout=lambda n: [1, 2, 3, 4, 5, 6])),
                                   ov={'sel': 0, 'col': 0, 'wait': None}, exit_combo=['b1', 'start'],
                                   exit_key=['F12', 88])
        pad = feview.guide_map(fe)
        self.assertEqual((pad['b4'], 'tab' in pad.values()), ('b4', False))
        fi.assign(binds, 'tab', 'pad', 'b5')
        fi.assign(binds, 'b6', 'pad', None)
        pad = feview.guide_map(fe)
        self.assertEqual((pad['b5'], 'b6' in pad), ('tab', False))
        # O direcional e os botoes no meio da janela: os dois blocos, com os
        # nomes, centrados (o par lado a lado, com 24 pixels entre eles).
        parts, hold, (sl, st, sr, sb) = feview.stick_parts(pad)
        self.assertTrue(hold)
        self.assertEqual((sl, sr), (-max(35, 19 + 35), max(42, 19 + 35)))
        bparts, (bl, bt, br, bb) = feview.button_parts('6', [1, 2, 3, 4, 5, 6], pad,
                                                       ['b1', 'b2', 'b3', 'b4', 'b5'])
        self.assertEqual(len(bparts), 5)
        self.assertLess(bl, -30)
        view = (ROOT / 'fliperos-setup/gui/feview.py').read_text()
        guide = view.split('def draw_guide(')[1].split('\ndef ')[0]
        self.assertIn('x = WW // 2 - (ws + wb + (gap if split else 0)) // 2', guide)
        self.assertNotIn('START: ', guide)
        ui = pygame.Surface((feview.WW, feview.HH), pygame.SRCALPHA)
        feview.draw_guide(fe, ui)
        feview.draw_controls(fe, ui, 1.0)
        fe.ov['wait'] = 'pad'
        feview.draw_controls(fe, ui, 1.0)
        # Sem direcao nenhuma no painel, o direcional nem aparece.
        for d in ('up', 'down', 'left', 'right'):
            fi.assign(binds, d, 'pad', None)
        feview.draw_guide(fe, ui)
        # O formato do painel: um MVS (4 em linha) nao tem o botao 5, entao a
        # funcao dele vale so pela tecla.
        fe.input.binds = fi.default_binds(pygame)
        fe.panel_layout = '4'
        pad = feview.guide_map(fe)
        self.assertNotIn('b5', pad)
        self.assertNotIn('b6', pad)
        slots = feview.panel_slots('4', [1, 2, 3, 4, 5, 6], ['b1', 'b2', 'b3', 'b4'], 30)
        self.assertEqual([slots['b%d' % n][0] for n in range(1, 5)], [-45, -15, 15, 45])
        self.assertEqual([slots['b%d' % n][3] for n in range(1, 5)], ['up', 'down', 'up', 'down'])
        self.assertEqual(feview.panel_slots('2v', [], ['b1', 'b2'], 30), {'b1': (0, 0, 0, 'up', 0),
                                                                          'b2': (0, 32, 0, 'down', 0)})
        # No de 6, a posicao do Buttons layout.
        self.assertEqual(feview.panel_slots('6', [4, 5, 6, 1, 2, 3], ['b1'], 30)['b1'][:2], (-30, 32))
        for layout, _ in feview.PANEL_LAYOUTS:
            fe.panel_layout = layout
            feview.draw_guide(fe, ui)
        # O guia e o formato antes das funcoes; depois delas o atalho que
        # fecha o jogo e o RESET/SAVE (todas as linhas, nas tres colunas).
        self.assertIn('CONTROLS_FIRST = 2', src)
        self.assertIn('guide_row, layout_row, first = 0, 1, 2', view)
        fe.menu_combo, fe.menu_key = ['1:start', '2:start'], ['F11', 87]
        fe.osd_combo, fe.osd_key = ['start', 'down'], ['PAUSE', 119]
        for row in range(len(fi.FUNCTIONS) + 6):
            for col in range(3):
                fe.ov = {'sel': row, 'col': col, 'wait': None}
                feview.draw_controls(fe, ui, 1.0)
        # Tudo cabe nos 240 de altura: o RESET/SAVE e as dicas embaixo.
        self.assertGreaterEqual(feview.HH, 40 + (len(fi.FUNCTIONS) + 6) * 9 + feview.BUTTONS_GAP + 19)
        self.assertIn('y = label(osd_row, "OSD MENU", osd_icon, T.CYAN)', view)
        self.assertIn('SHORTCUTS = ("exit", "menu", "osd")', src)
        # A escolha dos botoes, de um jogador ou de dois.
        for which in ('exit', 'menu', 'osd'):
            fe.overlay, fe.ov = 'exitpad', {'since': 0.0, 'held': frozenset({(1, 'start'), (2, 'start')}),
                                             'which': which}
            feview.draw_capture(fe, ui, 1.0)
        fm = self.frontend_module()
        names = ['K_ESCAPE', 'K_BACKSPACE', 'K_TAB', 'K_RETURN', 'K_SPACE', 'K_PAUSE', 'K_HOME', 'K_END', 'K_INSERT',
                 'K_DELETE', 'K_PAGEUP', 'K_PAGEDOWN', 'K_0'] + ['K_F%d' % n for n in range(1, 13)] + \
            ['K_' + c for c in 'qwertyuiopasdfghjklzxcvbnm'] + ['K_%d' % n for n in range(1, 10)]
        osd = types.SimpleNamespace(fi=fi, keytable=fm.evdev_keys(types.SimpleNamespace(
            **{n: i for i, n in enumerate(names)})))
        self.assertEqual(fm.Frontend.osd_shortcut(osd, {}), (['PAUSE', 119], ['start', 'down']))
        self.assertEqual(fm.Frontend.osd_shortcut(osd, {'osd_key': '164,88', 'osd_combo': '1:start+2:start'}),
                         (['F12', 88], ['1:start', '2:start']))
        self.assertEqual(fm.Frontend.osd_shortcut(osd, {'osd_key': '0', 'osd_combo': ''}), (None, []))
        calls = []
        import fedata as fedata_mod
        real_setup = fedata_mod.setup
        fedata_mod.setup = lambda *a, **k: calls.append(a)
        try:
            osd.osd_combo, osd.osd_key = ['start', 'down'], ['PAUSE', 119]
            fm.Frontend.set_shortcut(osd, 'osd', combo=['coin', 'b2'])
            fm.Frontend.set_shortcut(osd, 'osd', key=['F12', 88])
            fm.Frontend.set_shortcut(osd, 'osd', key=None)
            deadline = time.time() + 5
            while len(calls) < 3 and time.time() < deadline:
                time.sleep(0.05)
        finally:
            fedata_mod.setup = real_setup
        self.assertEqual(sorted(calls), sorted([('--setting', 'osd_combo', 'coin+b2'),
                                                ('--setting', 'osd_key', '88,164,201,207'),
                                                ('--setting', 'osd_key', '164,201,207')]))
        self.assertEqual(fi.combo_from({(1, 'coin'), (1, 'start')}), ['start', 'coin'])
        self.assertEqual(fi.combo_from({(2, 'start'), (1, 'start')}), ['1:start', '2:start'])
        self.assertEqual(fi.combo_names(['1:start', '2:b3', 'coin']), ['P1 START', 'P2 3', 'COIN'])
        self.assertTrue(fi.combo_item_ok('2:hotkey'))
        self.assertFalse(fi.combo_item_ok('x:start'))
        self.assertFalse(fi.combo_item_ok('select'))
        fe.panel_layout = 'x'
        self.assertEqual(feview.panel_layout(fe), '6')
        # O guia em joypad: a cruz e os botoes do videogame, cada funcao da
        # coluna JOYPAD no botao dela (o aceitar no de sul sem o Button
        # mapping); os ombros e o Select em texto embaixo.
        import fepads
        fe.input.binds = fi.default_binds(pygame)
        fe.guide_kind = 'joypad'
        joy = feview.joy_map(fe)
        self.assertEqual((joy['south'], joy['east'], joy['l1'], joy['select']), ('b1', 'b2', 'b3', 'tab'))
        for value, _, _ in fepads.PADS:
            fe.joypad_layout = value
            surf, c, labels, lines, (bl, bt, br, bb) = feview.joypad_parts(fe, joy)
            self.assertTrue(labels, value)
            feview.draw_guide(fe, ui)
        fe.joypad_layout = 'playstation'
        surf, c, labels, lines, _ = feview.joypad_parts(fe, joy)
        self.assertEqual(sorted(t[0] for t in labels), ['BACK', 'FAVOURITE', 'FILTER', 'SELECT'])
        roles = [[(r, f) for r, f, _ in words] for words, _ in lines]
        # O rodape so com as opcoes do jogo e o modo (sem paginar, favorito, filtro).
        self.assertEqual(sum(roles, []), [('SELECT', 'GAME OPTIONS'), ('START', 'VIEW MODE')])
        fe.joypad_layout = 'nes'
        _, _, _, lines, _ = feview.joypad_parts(fe, joy)
        self.assertNotIn('FILTER', [f for words, _ in lines for _, f, _ in words])
        # No Mega Drive os ombros sao o X e o Z: saem do texto.
        fe.joypad_layout = 'megadrive'
        surf, c, labels, lines, _ = feview.joypad_parts(fe, joy)
        self.assertIn('PAGE UP', [t[0] for t in labels])
        self.assertNotIn('L1', [r for words, _ in lines for r, _, _ in words])
        # Apertado ao lado do direcional, os nomes sobem ou descem para caber.
        for value, _, _ in fepads.PADS:
            fe.joypad_layout = value
            _, _, labels, _, (bl, bt, br, bb) = feview.joypad_parts(fe, joy, 150)
            free = feview.joypad_parts(fe, joy)
            # (o GameCube nao encolhe tanto: os feijoes ja sao largos)
            self.assertLessEqual(br - bl, min(160, free[4][2] - free[4][0]), value)
            self.assertEqual(len(labels), len(free[2]), value)

    def test_list_mode_icons_in_one_row_and_the_synopsis(self):
        # O modo lista: os icones numa fileira so e, fora do modo comercial, a
        # sinopse rolando (o que o scrape salvou em ~/media/info, sem rede).
        view = (ROOT / 'fliperos-setup/gui/feview.py').read_text()
        draw = view.split('def draw_list(')[1].split('\ndef ')[0]
        self.assertIn('strip = icon_strip(fe, s, game, px, y, SX + SW)', draw)
        self.assertIn('draw_synopsis(fe, s, game, (px, y, pw, HH - 6 - y), now)', draw)
        self.assertLess(draw.index('if fe.commercial:\n            coin_box'), draw.index('draw_synopsis('))
        # O contador desce com o vao dos jogos de outro gabinete (no alto): sem
        # ele, ficava em cima da ultima linha.
        self.assertIn('y0 + rows * 14 + 1 + sep, right=True', draw)
        self.assertIn('y0 + rows * 14 + 2 + sep)', draw)
        src = (ROOT / 'fliperos-setup/gui/fliperos-frontend').read_text()
        self.assertIn('self.media.pop(("desc", folder, name), None)', src)
        try:
            import pygame
        except ImportError:
            self.skipTest('pygame')
        import json
        import types
        os.environ.setdefault('SDL_VIDEODRIVER', 'dummy')
        pygame.init()
        import feview
        lines = feview.wrap_tiny('Ação "rápida"; [x]\n\nsegundo paragrafo com palavras', 40)
        self.assertEqual(lines[0], "Acao")
        self.assertIn("'rapida', (x)", ' '.join(lines))
        self.assertIn('', lines)
        self.assertTrue(all(feview.tiny.width(l) <= 40 for l in lines))
        with tempfile.TemporaryDirectory() as tmp:
            (Path(tmp) / 'mame').mkdir()
            hist = 'Street Fighter II (c) 1991 Capcom.\n\nThe World Warrior.\n\n- TECHNICAL -\n\nCPS-1.\n'
            (Path(tmp) / 'mame/sf2.en.json').write_text(json.dumps({'saved': 1, 'info': {'history': hist}}))
            system = {'key': 'mame', 'arcade': True}
            fe = types.SimpleNamespace(media={}, fd=self.fd, lib=types.SimpleNamespace(
                info=self.fd.web.GameInfo(root=tmp)))
            self.assertEqual(feview.game_description(fe, {'Name': 'sf2', '_system': system}), 'The World Warrior.')
            # O clone sem a sua usa a do pai; o console nao tem.
            self.assertEqual(feview.game_description(fe, {'Name': 'sf2ua', 'CloneOf': 'sf2', '_system': system}),
                             'The World Warrior.')
            self.assertEqual(feview.game_description(fe, {'Name': 'mario', '_system': {'key': 'nes'}}), '')
            ui = pygame.Surface((320, 240), pygame.SRCALPHA)
            game = {'Name': 'sf2', '_system': system, 'Players': '2', 'Category': 'Fighter / Versus'}
            for t in (0.0, 30.0):
                feview.draw_synopsis(fe, ui, game, (200, 160, 100, 30), t)
            # Cabe na altura maior; num lugar estreito, encolhe.
            self.assertEqual(feview.icon_strip(fe, ui, game, 200, 140, 304), 16)
            self.assertLess(feview.icon_strip(fe, ui, game, 200, 140, 236), 16)
            self.assertEqual(feview.icon_strip(fe, ui, {'Name': 'x', '_system': system}, 200, 140, 304), 0)
        mask = feview.fade_mask(10, 30, 0)
        self.assertEqual((mask.get_at((0, 0)).a, mask.get_at((0, 29)).a, mask.get_at((0, 15)).a), (255, 0, 255))

