    def test_custom_windows_games_get_the_32_bit_layer_by_flag(self):
        # O executor dos jogos custom (o .exe esta no cfg, nao no comando):
        # o --wine do fliperos-x11-run leva a camada de 32 bits; o --wine nao
        # chega ao programa.
        out = EmulatorModeTests.run_x11(EmulatorModeTests(), ['--mode', '640x240@60', '--app', 'custom_pc_pang', '--wine',
                                                              'myprog', 'run', 'x.cfg']).stdout
        self.assertIn('WINE=1', out)
        self.assertIn('APP=custom_pc_pang', out)
        self.assertIn('fliperos-x11-client myprog run x.cfg --', out)
        self.assertIn('WINE=\n', EmulatorModeTests.run_x11(EmulatorModeTests(), ['--app', 'custom_x', 'myprog']).stdout)
        launch, picom = self.client_launch(['fliperos-customgame', 'run', 'x.cfg'], extra={'FLIPEROS_USES_WINE': '1'})
        self.assertIn('LD_PRELOAD=l64.so:l32.so ', launch)
        self.assertFalse(picom)
        launch, picom = self.client_launch(['fliperos-customgame', 'run', 'x.cfg'], lib32=False,
                                           extra={'FLIPEROS_USES_WINE': '1'})
        self.assertNotIn('LD_PRELOAD', launch)
        self.assertTrue(picom)
        self.assertIn('LD_PRELOAD=l64.so ', self.client_launch(['fliperos-customgame', 'run', 'x.cfg'])[0])
        # Cada jogo custom com o log dele.
        run = (ROOT / 'config/fliperos-x11-run').read_text()
        self.assertIn('[[ $app == custom_* ]] && log_name=$app', run)
        # O executor e o ajudante entram na imagem.
        self.assertIn('install -Dm755 "$src/config/fliperos-customgame" "$root/opt/fliperos/bin/fliperos-customgame"',
                      ROOTFS)

    def test_portproton_custom_games_get_the_picom_filter(self):
        # O container do PortProton (pressure-vessel) troca o LD_PRELOAD: a camada
        # nunca chega ao jogo (visto no gabinete com o MARVEL Cosmic Invasion em
        # 854x480i: o wineserver com LD_PRELOAD vazio, sem filtro). Um jogo custom
        # do Windows com o runner padrao (ou portproton) fica no picom; o Wine do
        # sistema e o Staging seguem com a camada, e o que nao e do Windows tambem.
        wine = {'FLIPEROS_USES_WINE': '1'}
        with tempfile.TemporaryDirectory() as tmp:
            cfg = Path(tmp) / 'Game with spaces.cfg'

            def launch_of(text, extra=wine):
                cfg.write_text(text)
                return self.client_launch(['fliperos-customgame', 'run', str(cfg)], extra=extra)

            for text in ('platform=windows\nexe=Game.exe\n', 'platform=windows\nrunner=portproton\nexe=g.exe\n',
                         'platform=windows\nrunner=portproton'):
                launch, picom = launch_of(text)
                self.assertTrue(picom, text)
                self.assertNotIn('LD_PRELOAD', launch, text)
            for text in ('platform=windows\nrunner=wine\n', 'platform=windows\nrunner=wine-staging\n',
                         'platform=native\ncommand=./game\n', 'platform=command\ncommand=wine a.exe\n', ''):
                launch, picom = launch_of(text)
                self.assertFalse(picom, text)
                self.assertIn('LD_PRELOAD=l64.so:l32.so ', launch, text)
            # Sem o --wine (FLIPEROS_USES_WINE) o cfg nem e lido.
            self.assertFalse(launch_of('platform=windows\n', extra={})[1])
        # O nome do jogo vai ao filtro do picom (deflicker_NOME= do fliperos.conf).
        client = (ROOT / 'config/fliperos-x11-client').read_text()
        self.assertIn('--app "${FLIPEROS_DEFLICKER_APP:-$(basename -- "$1")}" --watch', client)

    def run_x11(self, args, conf, lib=True, flycast_rend=None):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'lib.so').write_text('')
            if flycast_rend is not None:
                (tmp / '.config/flycast').mkdir(parents=True)
                (tmp / '.config/flycast/emu.cfg').write_text('[config]\npvr.rend = %d\n' % flycast_rend)
            extra = {'FLIPEROS_DEFLICKER_LIB': str(tmp / ('lib.so' if lib else 'missing.so')),
                     'FLIPEROS_PCSX2_INI': str(ROOT / 'config/pcsx2.ini'),
                     'FLIPEROS_INI_SET': str(ROOT / 'config/fliperos-ini-set')}
            out = EmulatorModeTests.run_x11(EmulatorModeTests(), args, home=tmp, extra=extra, conf=conf).stdout
            ini = tmp / '.config/PCSX2/inis/PCSX2.ini'
            return out, ini.read_text() if ini.exists() else ''

    def test_vulkan_stays_in_480i_with_the_filter_on(self):
        # A camada do Vulkan (config/fliperos-vkfps.c) filtra: nada de trocar o
        # renderizador do emulador por causa do filtro.
        hd = ['--mode', '640x480@59.94']
