    def test_live_capture_problem_in_words(self):
        # O erro da captura (fliperos-stream status) vira a resposta da
        # oferta: sem VA-API o painel pede para instalar de novo.
        web = load_script('fliperos_web_capture', 'config/fliperos-web')
        problem = web.capture_problem
        mmap = {'copy': 'mmap', 'error': '[AVHWFramesContext @ 0x1] Failed to map DRM object 4 to memory: 1.',
                'error_at': 100}
        self.assertEqual(problem(mmap, 90)['code'], 'no_vaapi')
        self.assertIn('mesa-va-drivers', problem(mmap)['error'])
        # Um erro de antes da tentativa nao conta; sem erro, nada.
        self.assertIsNone(problem(mmap, 101))
        self.assertIsNone(problem({'copy': 'mmap'}))
        other = dict(mmap, copy='vaapi', error='Failed to open DRM device.')
        self.assertEqual(problem(other), {'error': 'the cabinet could not capture the screen: Failed to open DRM device.',
                                          'code': 'capture'})

    def test_live_screen_link_from_the_default_route(self):
        # A pagina recomenda o cabo quando a rota padrao sai pelo Wi-Fi; com
        # os dois, vale a de menor metrica.
        web = load_script('fliperos_web_link', 'config/fliperos-web')
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'proc/net').mkdir(parents=True)
            (tmp / 'sys/class/net/wlx1/wireless').mkdir(parents=True)
            (tmp / 'sys/class/net/ens1').mkdir(parents=True)
            web.PROC, web.SYS = str(tmp / 'proc'), str(tmp / 'sys')
            head = 'Iface\tDestination\tGateway\tFlags\tRefCnt\tUse\tMetric\tMask\tMTU\tWindow\tIRTT\n'
            route = tmp / 'proc/net/route'
            wifi = 'wlx1\t00000000\t0101A8C0\t0003\t0\t0\t600\t00000000\t0\t0\t0\n'
            lan = 'wlx1\t0001A8C0\t00000000\t0001\t0\t0\t600\t00FFFFFF\t0\t0\t0\n'
            wired = 'ens1\t00000000\t0101A8C0\t0003\t0\t0\t100\t00000000\t0\t0\t0\n'
            self.assertIsNone(web.stream_link())
            route.write_text(head + lan)
            self.assertIsNone(web.stream_link())
            route.write_text(head + wifi + lan)
            self.assertEqual(web.stream_link(), 'wifi')
            route.write_text(head + wifi + wired)
            self.assertEqual(web.stream_link(), 'wired')
        index = (ROOT / 'config/web/index.html').read_text()
        self.assertIn('id="live-net"', index)
        self.assertIn('id="live-net-tip"', index)
        app = (ROOT / 'config/web/text.js').read_text()
        self.assertIn('live_net_tip_wifi: "O gabinete está no Wi-Fi.', app)

    def test_live_screen_offer_goes_to_go2rtc(self):
        cookie = self.login()
        status = json.loads(self.request('GET', '/api/stream', cookie=cookie)[2])
        self.assertEqual(status, {'installed': True, 'active': True, 'encoder': 'x264', 'audio': False,
                                  'rates': [15, 30, 60], 'link': status['link'], 'quality': 'normal',
                                  'copy': None, 'error': None,
                                  'error_at': None})
        self.assertIn(status['link'], ('wifi', 'wired', None))
        offer = 'v=0\r\no=- 1 2 IN IP4 127.0.0.1\r\n'
        for bad in ({'fps': 25, 'sdp': offer}, {'fps': 30, 'sdp': 'hello'}, {'fps': '30', 'sdp': offer}):
            self.assertEqual(self.request('POST', '/api/stream/offer', bad, cookie=cookie)[0], 400, bad)
        status, _, data = self.request('POST', '/api/stream/offer', {'fps': 60, 'sdp': offer}, cookie=cookie)
        self.assertEqual((status, json.loads(data)), (200, {'sdp': 'v=0\r\no=- answer\r\n'}))
        # A oferta vai como esta, no WHEP do go2rtc, no stream da taxa pedida.
        self.assertEqual(self.webrtc[-1], ('/api/webrtc?src=cabinet60', 'application/sdp', offer))
        # O OBS (/overlay/live): a mesma oferta, pela chave do endereco, sem login.
        live = json.loads(self.request('GET', '/api/overlay', cookie=cookie)[2])['live']
        self.assertTrue(live.startswith('/overlay/live?key='))
        key = live.split('key=')[1]
        self.assertEqual(self.request('POST', '/api/overlay/offer?key=wrong', {'fps': 30, 'sdp': offer})[0], 403)
        status, _, data = self.request('POST', '/api/overlay/offer?key=' + key, {'fps': 30, 'sdp': offer})
        self.assertEqual((status, json.loads(data)), (200, {'sdp': 'v=0\r\no=- answer\r\n'}))
        self.assertEqual(self.webrtc[-1][0], '/api/webrtc?src=cabinet30')
        status, _, page = self.request('GET', live)
        self.assertEqual((status, b'live.js' in page), (200, True))
        # Instalar: o Setup > Games > Extras > Live screen, como tarefa.
        status, _, data = self.request('POST', '/api/stream/install', {}, cookie=cookie)
        self.assertEqual(status, 200, data)
        log = Path(self.tmp.name) / 'extras.log'
        for _ in range(50):
            if log.exists():
                break
            time.sleep(0.1)
        self.assertEqual(log.read_text(), 'install stream --progress\n')

    def test_obs_marquee_needs_the_key(self):
        cookie = self.login()
        tmp = Path(self.tmp.name)
        info = json.loads(self.request('GET', '/api/overlay', cookie=cookie)[2])
        self.assertTrue(info['enabled'])
        self.assertTrue(info['path'].startswith('/overlay/marquee?key='))
        key = info['path'].split('key=')[1]
        self.assertEqual(oct((tmp / 'overlay.key').stat().st_mode & 0o777), '0o600')
        # A pagina e publica (e pode ir num iframe do proprio painel); os dados
        # pedem a chave, sem login.
        status, _, page = self.request('GET', '/overlay/marquee?key=x')
        self.assertEqual(status, 200)
        self.assertIn(b'overlay.js', page)
        self.assertEqual(self.last_headers['X-Frame-Options'], 'SAMEORIGIN')
        self.assertEqual(self.request('GET', '/')[0], 200)
        self.assertEqual(self.last_headers['X-Frame-Options'], 'DENY')
        for query in ('', '?key=', '?key=wrong'):
            self.assertEqual(self.request('GET', '/api/overlay/state' + query)[0], 403, query)
        status, _, data = self.request('GET', '/api/overlay/state?key=' + key)
        state = json.loads(data)
        self.assertEqual(state['state']['title'], 'Street Fighter II')
        self.assertEqual(state['state']['event'], 'game')
        self.assertTrue(state['art'].startswith('/api/overlay/art?key='))
        status, _, data = self.request('GET', state['art'])
        self.assertEqual((status, data, self.last_headers['Content-Type']), (200, b'\x89PNG fake', 'image/png'))
        self.assertEqual(self.request('GET', '/api/overlay/art?key=%s&id=nope' % key)[0], 404)
        # Um endereco novo invalida o antigo.
        new = json.loads(self.request('POST', '/api/overlay', {'action': 'newkey'}, cookie=cookie)[2])['path']
        self.assertNotEqual(new, info['path'])
        self.assertEqual(self.request('GET', '/api/overlay/state?key=' + key)[0], 403)
        self.assertEqual(self.request('GET', '/api/overlay/state?key=' + new.split('key=')[1])[0], 200)

    def test_system_logo_for_the_preview_and_the_obs_page(self):
        # A troca de sistema do frontend: o painel (com login) e a pagina do OBS
        # (pela chave) pedem o logotipo do sistema, em PNG; sem logotipo, 404.
        cookie = self.login()
        key = json.loads(self.request('GET', '/api/overlay', cookie=cookie)[2])['path'].split('key=')[1]
        status, _, data = self.request('GET', '/api/marquee/logo?name=Naomi', cookie=cookie)
        self.assertEqual((status, data, self.last_headers['Content-Type']), (200, b'\x89PNG logo', 'image/png'))
        self.assertEqual(self.request('GET', '/api/marquee/logo?name=Naomi')[0], 401)
        self.assertEqual(self.request('GET', '/api/marquee/logo?name=Nada', cookie=cookie)[0], 404)
        self.assertEqual(self.request('GET', '/api/marquee/logo', cookie=cookie)[0], 404)
        status, _, data = self.request('GET', '/api/overlay/logo?key=%s&name=Naomi' % key)
        self.assertEqual((status, data), (200, b'\x89PNG logo'))
        self.assertEqual(self.request('GET', '/api/overlay/logo?key=wrong&name=Naomi')[0], 403)
        self.assertEqual(self.request('GET', '/api/overlay/logo?key=%s&name=Nada' % key)[0], 404)
        # As duas paginas sabem desenha-lo.
        for name, url in (('overlay.js', '/api/overlay/logo?key='), ('marqueeview.js', '/api/marquee/logo?name=')):
            self.assertIn(url, (ROOT / 'config/web' / name).read_text(), name)

    def test_idle_animation_for_the_preview_and_the_obs_page(self):
        # O ZeDMD parado (o evento attract) toca a animacao do logo: o painel (com
        # login) e a pagina do OBS (pela chave) pedem o GIF de 128x32.
        cookie = self.login()
        key = json.loads(self.request('GET', '/api/overlay', cookie=cookie)[2])['path'].split('key=')[1]
        gif = (ROOT / 'config/zedmd-fliperos.gif').read_bytes()
        status, _, data = self.request('GET', '/api/marquee/idle', cookie=cookie)
        self.assertEqual((status, data, self.last_headers['Content-Type']), (200, gif, 'image/gif'))
        self.assertEqual(data[:6], b'GIF89a')
        self.assertEqual(self.request('GET', '/api/marquee/idle')[0], 401)
        status, _, data = self.request('GET', '/api/overlay/idle?key=' + key)
        self.assertEqual((status, data), (200, gif))
        self.assertEqual(self.request('GET', '/api/overlay/idle?key=wrong')[0], 403)
        self.assertEqual(self.request('GET', '/api/overlay/idle')[0], 403)
        # As duas paginas desenham o evento attract com ele (a previa, no modo
        # Pixelcade e no ZeDMD: os dois tocam a animacao).
        web = ROOT / 'config/web'
        view, obs = (web / 'marqueeview.js').read_text(), (web / 'overlay.js').read_text()
        self.assertIn('if (s.event === "attract") return "/api/marquee/idle";', view)
        # O nome que nao cabe numa linha roda sem parar (antes ficava cortado):
        # na previa, no letreiro do desenho do gabinete e na pagina do OBS.
        # Mede depois de a letra de pixel carregar (antes dela o nome parece caber).
        self.assertIn('document.fonts.ready.then(() => requestAnimationFrame(() => mqRun(name)));', view)
        self.assertIn('.mq-led .mq-name b.run span', (web / 'stream.css').read_text())
        self.assertIn('document.fonts.ready.then(() => requestAnimationFrame(() => cabRun(box)));',
                      (web / 'cabinet.js').read_text())
        self.assertIn('.marquee-art.run span', (web / 'cabinet.css').read_text())
        self.assertIn('document.fonts.ready.then(() => requestAnimationFrame(() => runTitle(title)));', obs)
        self.assertIn('.title.run span', (web / 'overlay.css').read_text())
        # Sem jogo e sem evento que desenhe (o jogo acabou de fechar), fica o
        # ultimo logotipo de sistema, e nao o nome FliperOS.
        self.assertIn('const hold = !open && !!mqLastSys && !["system", "attract", "versus", "menu"].includes(s.event);',
                      view)
        # O padrao sem jogo (antes o nome FliperOS em texto): o logotipo animado,
        # servido como arquivo do painel (sem login, como o resto da pagina).
        self.assertIn('urls.push({ url: "marquee-fliperos.gif", logo: false })', view)
        from PIL import Image
        # E o menu do FliperOS (evento menu): a animacao de cada um dos 5 itens.
        self.assertIn('return "marquee-menu-" + s.item + ".gif";', view)
        self.assertIn('return "/marquee-menu-" + s.item + ".gif?";', obs)
        for name in ['marquee-fliperos'] + ['marquee-menu-' + i for i in ('frontend', 'setup', 'desktop', 'shell', 'power')]:
            status, _, data = self.request('GET', '/%s.gif' % name)
            self.assertEqual((status, self.last_headers['Content-Type']), (200, 'image/gif'), name)
            self.assertEqual(data, (web / (name + '.gif')).read_bytes(), name)
            with Image.open(web / (name + '.gif')) as img:
                self.assertEqual((img.size, img.n_frames > 30), ((128, 32), True), name)
        self.assertIn('/api/overlay/idle?key=', obs)
        self.assertIn('const idle = data.enabled && (s.event === "attract" || s.event === "menu");', obs)
        self.assertIn('id="idle"', (web / 'overlay.html').read_text())
        self.assertIn('.mq-led.ani', (web / 'stream.css').read_text())

    def test_obs_controls_page_and_its_css(self):
        import http.client
        cookie = self.login()
        tmp = Path(self.tmp.name)
        info = json.loads(self.request('GET', '/api/overlay', cookie=cookie)[2])
        self.assertTrue(info['input'].startswith('/overlay/input?key='))
        key = info['input'].split('key=')[1]
        status, _, page = self.request('GET', '/overlay/input?key=x')
        self.assertEqual(status, 200)
        self.assertIn(b'/input.js', page)
        self.assertEqual(self.last_headers['X-Frame-Options'], 'SAMEORIGIN')
        # Os dados pedem a chave.
        for path in ('/api/overlay/input/css', '/api/overlay/input/events'):
            self.assertEqual(self.request('GET', path + '?key=wrong')[0], 403, path)
        default = (ROOT / 'config/web/input.css').read_text()
        status, _, css = self.request('GET', '/api/overlay/input/css?key=' + key)
        self.assertEqual((status, css.decode(), self.last_headers['Content-Type']),
                         (200, default, 'text/css; charset=utf-8'))
        # O CSS do usuario: gravado, servido no lugar do de fabrica e apagado
        # pelo reset; sem login nao muda, e um corpo sem "css" nao apaga nada.
        self.assertEqual(self.request('POST', '/api/overlay/input/style', {'css': 'x'})[0], 401)
        self.assertEqual(self.request('POST', '/api/overlay/input/style', {}, cookie=cookie)[0], 400)
        self.assertEqual(self.request('POST', '/api/overlay/input/style', {'css': 'x' * 40000}, cookie=cookie)[0], 400)
        status, _, data = self.request('POST', '/api/overlay/input/style', {'css': '.pad { opacity: .5; }'}, cookie=cookie)
        self.assertEqual((status, json.loads(data)['custom']), (200, True))
        self.assertEqual((tmp / 'etc/input-overlay.css').read_text(), '.pad { opacity: .5; }')
        self.assertEqual(self.request('GET', '/api/overlay/input/css?key=' + key)[2], b'.pad { opacity: .5; }')
        style = json.loads(self.request('GET', '/api/overlay/input/style', cookie=cookie)[2])
        self.assertEqual((style['css'], style['custom'], style['default']), ('.pad { opacity: .5; }', True, default))
        status, _, data = self.request('POST', '/api/overlay/input/style', {'reset': True}, cookie=cookie)
        self.assertEqual(json.loads(data), {'css': default, 'custom': False})
        self.assertFalse((tmp / 'etc/input-overlay.css').exists())
        # Os comandos apertados: Server-Sent Events do fliperos-buttons watch,
        # com o mapa do Button mapping.
        conn = http.client.HTTPConnection('127.0.0.1', self.port, timeout=10)
        conn.request('GET', '/api/overlay/input/events?key=' + key)
        res = conn.getresponse()
        self.assertEqual((res.status, res.getheader('Content-Type')), (200, 'text/event-stream'))
        # O primeiro evento pode ser o "{}" de antes do watch ler.
        event = {}
        while event == {}:
            line = res.fp.readline()
            self.assertTrue(line)
            if line.startswith(b'data: '):
                event = json.loads(line[len(b'data: '):])
        self.assertEqual(event, {'1': ['up', 'b1'], '2': []})
        # O CSS ao vivo: salvo no painel, a pagina aberta recebe "event: css"
        # e o pede de novo, sem atualizar a fonte no OBS.
        self.assertEqual(self.request('POST', '/api/overlay/input/style', {'css': '.pad { opacity: 1; }'},
                                      cookie=cookie)[0], 200)
        line = b''
        while line != b'event: css\n':
            line = res.fp.readline()
            self.assertTrue(line)
        self.assertTrue(res.fp.readline().startswith(b'data: '))
        self.request('POST', '/api/overlay/input/style', {'reset': True}, cookie=cookie)
        conn.close()
        self.assertEqual((tmp / 'buttons.log').read_text(), 'watch /etc/fliperos/buttons.map\n')

