    def test_favourites_are_fliperos_own_copied_from_the_frontend(self):
        cookie = self.login()
        tag = Path(self.tmp.name) / '.attract/romlists/Naomi.tag'
        own = Path(self.tmp.name) / '.config/fliperos/favourites'
        before = tag.read_text()
        try:
            status, _, data = self.request('POST', '/api/favourite', {'system': 'naomi', 'game': 'Ikaruga', 'on': True},
                                           cookie=cookie)
            self.assertEqual((status, json.loads(data)), (200, {'game': 'Ikaruga', 'favourite': True}))
            # O de antes veio do Attract-Mode na primeira vez.
            self.assertEqual(own.read_text(), 'naomi\tIkaruga\nnaomi\tvf4\n')
            status, _, data = self.request('POST', '/api/favourite', {'system': 'naomi', 'game': 'vf4.zip', 'on': False},
                                           cookie=cookie)
            self.assertEqual((status, json.loads(data)), (200, {'game': 'vf4', 'favourite': False}))
            self.assertEqual(own.read_text(), 'naomi\tIkaruga\n')
            # O arquivo do frontend nao muda, e o que muda nele nao volta.
            self.assertEqual(tag.read_text(), before)
            tag.write_text('vf4;Naomi\nIkaruga;Naomi\n')
            games = json.loads(self.request('GET', '/api/games?system=naomi', cookie=cookie)[2])['games']
            self.assertEqual([g['Name'] for g in games if g.get('Favourite')], ['Ikaruga'])
            for body in ({'system': 'naomi', 'game': 'kofxi', 'on': True}, {'system': 'naomi', 'game': 'vf4'},
                         {'system': 'naomi', 'game': '../other/evil', 'on': True}):
                self.assertEqual(self.request('POST', '/api/favourite', body, cookie=cookie)[0], 400, body)
        finally:
            tag.write_text(before)
            own.unlink()

    def test_game_info_from_the_arcade_database_and_libretro(self):
        cookie = self.login()
        status, _, data = self.request('GET', '/api/gameinfo?system=naomi&game=vf4', cookie=cookie)
        self.assertEqual(status, 200, data)
        info = json.loads(data)
        self.assertEqual(info['source'], 'Arcade Database')
        # So os campos conhecidos; a segunda vez vem do cache do servidor.
        self.assertEqual(info['info']['title'], 'Virtua Fighter 4 (GDS-0012)')
        self.assertNotIn('unknown', info['info'])
        self.request('GET', '/api/gameinfo?system=naomi&game=vf4', cookie=cookie)
        self.assertEqual(len([q for q in self.adb_queries if 'game_name=vf4&' in q]), 1)
        # Fica salvo no gabinete, junto da midia: ~/media/info/<pasta>/<set>.<idioma>.json.
        tmp = Path(self.tmp.name)
        saved = json.loads((tmp / 'media/info/naomi/vf4.en.json').read_text())
        self.assertEqual((saved['info']['title'], saved['lang'], saved['source']),
                         ('Virtua Fighter 4 (GDS-0012)', 'en', 'Arcade Database'))
        self.assertEqual(info['saved'], saved['saved'])
        self.assertIsNone(json.loads(self.request('GET', '/api/gameinfo?system=naomi&game=newgame', cookie=cookie)[2])
                          ['info'])
        self.assertIsNone(json.loads((tmp / 'media/info/naomi/newgame.en.json').read_text())['info'])
        # Salvo, ele vale mesmo para um servidor novo (o cache em memoria vazio).
        web = SourceFileLoader('fliperos_web', str(ROOT / 'config/fliperos-web')).load_module()
        gi = web.GameInfo(str(tmp / 'media/info'))
        self.assertEqual(gi.arcade('naomi', 'vf4', 'en')[0]['title'], 'Virtua Fighter 4 (GDS-0012)')
        self.assertEqual(len([q for q in self.adb_queries if 'game_name=vf4&' in q]), 1)
        self.assertIsNone(gi.path('naomi', '../..', 'en'))
        self.assertEqual(gi.path('../retroarch/fbneo', 'sf2', 'pt'), str(tmp / 'media/info/retroarch/fbneo/sf2.pt.json'))
        self.assertEqual(self.request('GET', '/api/gameinfo?system=naomi&game=kofxi', cookie=cookie)[0], 404)
        # Console: as imagens do libretro-thumbnails pelo nome do arquivo.
        thumbs = json.loads(self.request('GET', '/api/gameinfo?system=shell&game=Ikaruga.zip', cookie=cookie)[2])
        self.assertEqual(thumbs['images'][0], {'kind': 'boxart', 'url': 'https://thumbnails.libretro.com/'
                                               'Nintendo%20-%20Super%20Nintendo%20Entertainment%20System/'
                                               'Named_Boxarts/Ikaruga.png'})
        # A pagina pode mostrar as imagens dessas fontes, e so delas.
        csp = self.last_headers['Content-Security-Policy']
        self.assertIn("img-src 'self' data: blob: https://adb.arcadeitalia.net https://thumbnails.libretro.com;", csp)

    def test_launch_asks_the_tty1_and_closes_what_is_on_screen(self):
        import shutil as sh
        cookie = self.login()
        # Um "jogo" aberto (um processo chamado flycast): sai antes do novo.
        fake = Path(self.tmp.name) / 'flycast'
        sh.copy('/bin/sleep', fake)
        game = subprocess.Popen([str(fake), '60'])
        try:
            status, _, data = self.request('POST', '/api/launch', {'system': 'naomi', 'game': 'vf4.zip'}, cookie=cookie)
            self.assertEqual(status, 200, data)
            self.assertEqual(json.loads(data), {'back': 'menu', 'via': 'tty1'})
            self.assertIsNotNone(game.wait(timeout=10))
        finally:
            game.kill()
        request = (self.runtime / 'fliperos-web-launch').read_text().splitlines()
        self.assertEqual(request, ['return=menu', '/opt/fliperos/bin/fliperos-x11-run', 'flycast',
                                   str(self.roms / 'vf4.zip')])
        # Fora da pasta, um arquivo que nao e jogo, ou um comando que nao e um
        # dos lancadores do FliperOS: nada.
        for body in ({'system': 'naomi', 'game': '../other/evil.zip'}, {'system': 'naomi', 'game': 'notes.txt'},
                     {'system': 'shell', 'game': 'vf4.zip'}, {'system': 'naomi'}):
            self.assertEqual(self.request('POST', '/api/launch', body, cookie=cookie)[0], 400, body)

