    def test_files_browse_upload_download_and_delete(self):
        cookie = self.login()
        listing = json.loads(self.request('GET', '/api/files?root=roms&path=', cookie=cookie)[2])
        self.assertEqual(listing['roots'], ['roms', 'bios', 'media', 'nvram', 'save', 'splashscreen', 'home'])
        # A pasta pessoal inteira (~): sem os ocultos e sem sair dela.
        home = json.loads(self.request('GET', '/api/files?root=home&path=', cookie=cookie)[2])
        self.assertIn('roms', [e['name'] for e in home['entries']])
        self.assertNotIn('.attract', [e['name'] for e in home['entries']])
        self.assertEqual(self.request('GET', '/api/files?root=home&path=..', cookie=cookie)[0], 404)
        self.assertEqual([(e['name'], e['dir']) for e in listing['entries']], [('naomi', True), ('other', True)])
        naomi = json.loads(self.request('GET', '/api/files?root=roms&path=naomi', cookie=cookie)[2])['entries']
        # Pastas primeiro; os ocultos ficam de fora.
        self.assertEqual([e['name'] for e in naomi],
                         ['vf4', 'Ikaruga.zip', 'kofxi.zip', 'naomi.zip', 'newgame.7z', 'notes.txt', 'vf4.zip'])
        for query in ('root=roms&path=../', 'root=roms&path=naomi/../..', 'root=etc&path=', 'root=roms&path=/etc'):
            self.assertEqual(self.request('GET', '/api/files?' + query, cookie=cookie)[0], 404, query)
        # Enviar: o corpo e o arquivo; o que ja existe so com overwrite.
        up = '/api/upload?root=roms&path=naomi&name=new%20game.zip'
        self.assertEqual(self.request('POST', up, b'first', cookie=cookie)[0], 200)
        self.assertEqual(self.request('POST', up, b'second', cookie=cookie)[0], 409)
        self.assertEqual(self.request('POST', up + '&overwrite=1', b'second', cookie=cookie)[0], 200)
        self.assertEqual((self.roms / 'new game.zip').read_bytes(), b'second')
        self.assertFalse(list(self.roms.glob('.*part*')))
        for bad in ('name=..%2Fevil.zip', 'name=a%2Fb.zip', 'name=..', 'name='):
            self.assertEqual(self.request('POST', '/api/upload?root=roms&path=naomi&' + bad, b'x', cookie=cookie)[0],
                             400, bad)
        self.assertFalse((self.roms.parent / 'evil.zip').exists())
        # Sem o cabecalho X-FliperOS, nada.
        self.assertEqual(self.request('POST', up + '&overwrite=1', b'third', cookie=cookie, header=False)[0], 403)
        status, _, data = self.request('GET', '/api/download?root=roms&path=naomi/new%20game.zip', cookie=cookie)
        self.assertEqual((status, data), (200, b'second'))
        self.assertIn("filename*=UTF-8''new%20game.zip", self.last_headers['Content-Disposition'])
        self.assertEqual(self.request('GET', '/api/download?root=roms&path=naomi', cookie=cookie)[0], 404)
        # Pasta nova, apagar arquivo, pasta com coisa dentro nao, a de cima nunca.
        mk = {'root': 'roms', 'path': 'naomi', 'name': 'saves'}
        self.assertEqual(self.request('POST', '/api/mkdir', mk, cookie=cookie)[0], 200)
        self.assertEqual(self.request('POST', '/api/mkdir', mk, cookie=cookie)[0], 409)
        self.assertEqual(self.request('POST', '/api/mkdir', dict(mk, name='../x'), cookie=cookie)[0], 400)
        delete = lambda path: self.request('POST', '/api/delete', {'root': 'roms', 'path': path}, cookie=cookie)[0]
        self.assertEqual(delete('naomi/new game.zip'), 200)
        self.assertFalse((self.roms / 'new game.zip').exists())
        self.assertEqual(delete('naomi/saves'), 200)
        self.assertEqual(delete('naomi'), 409)
        self.assertEqual(delete(''), 400)
        self.assertEqual(delete('../roms'), 400)
        self.assertEqual(delete('naomi/missing.zip'), 404)

    def test_screenshot_from_the_layer(self):
        import struct
        import threading
        import zlib
        cookie = self.login()
        request, ppm = self.runtime / 'fliperos-shot-request', self.runtime / 'fliperos-shot.ppm'

        def layer():
            # O papel da camada: ve o pedido, grava o quadro (2x2) e o apaga.
            for _ in range(100):
                if request.exists():
                    ppm.write_bytes(b'P6\n2 2\n255\n' + bytes([255, 0, 0, 0, 255, 0, 0, 0, 255, 255, 255, 255]))
                    request.unlink()
                    return
                time.sleep(0.05)
        thread = threading.Thread(target=layer)
        thread.start()
        status, _, data = self.request('GET', '/api/screenshot', cookie=cookie)
        thread.join()
        self.assertEqual(status, 200)
        self.assertEqual(self.last_headers['Content-Type'], 'image/png')
        self.assertEqual(self.last_headers['X-Shot-Source'], 'opengl')
        self.assertEqual(data[:8], b'\x89PNG\r\n\x1a\n')
        self.assertEqual(struct.unpack('>II', data[16:24]), (2, 2))
        idat = data[data.index(b'IDAT') + 4:data.index(b'IEND') - 8]
        self.assertEqual(zlib.decompress(idat), b'\0' + bytes([255, 0, 0, 0, 255, 0]) + b'\0' + bytes([0, 0, 255, 255, 255, 255]))
        # Ninguem responde (o console de texto) e sem X: 503, e o pedido sai.
        status, _, data = self.request('GET', '/api/screenshot', cookie=cookie)
        self.assertEqual(status, 503, data)
        self.assertFalse(request.exists())

    def test_terminal_over_websocket(self):
        import base64
        import socket
        import struct
        cookie = self.login()

        def handshake(origin):
            sock = socket.create_connection(('127.0.0.1', self.port), timeout=10)
            key = base64.b64encode(os.urandom(16)).decode()
            sock.sendall(('GET /api/terminal HTTP/1.1\r\nHost: 127.0.0.1:%d\r\nUpgrade: websocket\r\n'
                          'Connection: Upgrade\r\nSec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n'
                          'Origin: %s\r\nCookie: %s\r\n\r\n' % (self.port, key, origin, cookie)).encode())
            head = b''
            while b'\r\n\r\n' not in head:
                head += sock.recv(1)
            return sock, head.decode()

        def frame(opcode, data):
            mask = os.urandom(4)
            return (bytes([0x80 | opcode, 0x80 | len(data)]) + mask
                    + bytes(c ^ mask[i % 4] for i, c in enumerate(data)))

        # Outro site (o cookie iria junto no navegador): recusado.
        sock, head = handshake('http://evil.example')
        sock.close()
        self.assertIn(' 403 ', head.splitlines()[0])
        sock, head = handshake('http://127.0.0.1:%d' % self.port)
        try:
            # HTTP/1.1: o Chrome recusa o 101 em HTTP/1.0.
            self.assertTrue(head.startswith('HTTP/1.1 101 '), head)
            sock.sendall(frame(1, json.dumps({'resize': [100, 30]}).encode()))
            sock.sendall(frame(2, b'stty size; echo hello-$((40+2))\n'))
            out, end = b'', time.time() + 10
            while b'hello-42' not in out and time.time() < end:
                b0, b1 = sock.recv(1)[0], sock.recv(1)[0]
                size = b1 & 0x7F
                if size == 126:
                    size = struct.unpack('>H', sock.recv(2))[0]
                data = b''
                while len(data) < size:
                    data += sock.recv(size - len(data))
                out += data
            self.assertIn(b'hello-42', out)
            # O tamanho pedido chegou ao pty.
            self.assertIn(b'30 100', out)
            sock.sendall(frame(8, struct.pack('>H', 1000)))
        finally:
            sock.close()

    def test_trackball_events(self):
        # O mouse virtual num arquivo comum no lugar do /dev/uinput (sem os
        # ioctl): os eventos que ele grava.
        web = SourceFileLoader('fliperos_web', str(ROOT / 'config/fliperos-web')).load_module()
        import struct
        with tempfile.TemporaryDirectory() as tmp:
            dev = Path(tmp) / 'uinput'
            dev.write_bytes(b'')
            mouse = web.VirtualMouse(str(dev))
            mouse.fd = os.open(str(dev), os.O_WRONLY)

            class FakeWs:
                def __init__(self, msgs):
                    self.msgs = list(msgs)

                def receive(self):
                    if not self.msgs:
                        raise EOFError
                    return 1, json.dumps(self.msgs.pop(0)).encode()
            # Um movimento, a roda, o botao 1 apertado e a conexao que cai:
            # o botao solta sozinho. Lixo e ignorado.
            web.trackball(FakeWs([{'m': [5, -3]}, {'m': [0, 0], 'w': 1}, {'b': ['left', 1]}, {'b': ['reboot', 1]},
                                  {'m': ['x', 1]}, 'nonsense']), mouse)
            os.close(mouse.fd)
            data = dev.read_bytes()
        events = [struct.unpack('llHHi', data[i:i + 24])[2:] for i in range(0, len(data), 24)]
        self.assertEqual(events, [(2, 0, 5), (2, 1, -3), (0, 0, 0), (2, 8, 1), (0, 0, 0),
                                  (1, 0x110, 1), (0, 0, 0), (1, 0x110, 0), (0, 0, 0)])
        # A abertura do dispositivo de verdade: o nome e os eixos do uinput.
        source = (ROOT / 'config/fliperos-web').read_text()
        self.assertIn('b"FliperOS web trackball"', source)
        # Desligado por enquanto: o servidor recusa e a pagina esconde o cartao.
        cookie = self.login()
        self.assertEqual(self.request('GET', '/api/trackball', cookie=cookie)[0], 404)
        self.assertIn('<section class="card wide" data-off aria-labelledby="h-ball">',
                      (ROOT / 'config/web/index.html').read_text())

    def test_settings(self):
        cookie = self.login()
        rows = json.loads(self.request('GET', '/api/settings', cookie=cookie)[2])['settings']
        self.assertEqual(rows[0], {'key': 'debug', 'group': 'System', 'label': 'Debug mode', 'type': 'choice', 'value': 'off',
                                   'help': 'Shows all text.', 'options': [{'value': 'off', 'label': 'Off'},
                                                                          {'value': 'on', 'label': 'On (show all text)'}]})
        self.assertEqual((rows[1]['type'], rows[1]['min'], rows[1]['max'], rows[1]['step']), ('number', 50, 200, 5))
        status, _, data = self.request('POST', '/api/settings', {'key': 'color.gamma', 'value': '-5'}, cookie=cookie)
        self.assertEqual(status, 200, data)
        self.assertIn('--setting color.gamma -5\n', self.volume_log.read_text())
        self.assertEqual(json.loads(data)['setting']['key'], 'color.gamma')
        # Nada que nao seja chave e valor simples chega ao Setup.
        for body in ({'key': 'debug', 'value': 'on; reboot'}, {'key': '../x', 'value': 'on'}, {'key': '', 'value': 'on'}):
            self.assertEqual(self.request('POST', '/api/settings', body, cookie=cookie)[0], 400, body)
        self.assertEqual(self.request('POST', '/api/settings', {'key': 'nope', 'value': 'x'}, cookie=cookie)[0], 400)
        status, _, data = self.request('POST', '/api/settings', {'key': 'broken', 'value': 'x'}, cookie=cookie)
        self.assertEqual((status, json.loads(data)['error']), (500, 'boom'))
        # A latencia do MAME anda de meio em meio; a orientacao refaz o boot:
        # uma tarefa, com o andamento na gaveta.
        latency, orientation = rows[2], rows[3]
        self.assertEqual((latency['min'], latency['max'], latency['step']), (0, 50, 0.5))
        self.assertTrue(orientation['task'])
        self.assertNotIn('task', latency)
        status, _, data = self.request('POST', '/api/settings', {'key': 'orientation', 'value': 'vertical-cw'},
                                       cookie=cookie)
        self.assertEqual(status, 200, data)
        self.assertEqual(json.loads(data)['task']['kind'], 'settings')

    def test_wifi_password_and_whatsnew(self):
        # Setup > Network, a senha e o What's new: pelo Setup, com as senhas
        # so pela entrada (nunca na linha de comando, que o ps mostra).
        cookie = self.login()
        secret = Path(self.tmp.name) / 'secret.log'
        info = json.loads(self.request('GET', '/api/wifi', cookie=cookie)[2])
        self.assertEqual(info, {'devices': [{'device': 'wlan0', 'type': 'wifi', 'state': 'connected',
                                             'connection': 'Casa', 'ip': '192.168.1.9'}]})
        info = json.loads(self.request('GET', '/api/wifi?scan=1', cookie=cookie)[2])
        self.assertEqual(info['networks'], [{'device': 'wlan0', 'ssid': 'Casa', 'signal': '80', 'security': 'WPA2'}])
        body = {'device': 'wlan0', 'ssid': 'Casa', 'password': 'segredo wifi'}
        self.assertEqual(self.request('POST', '/api/wifi', body, cookie=cookie)[0], 200)
        self.assertIn('--wifi connect wlan0 Casa\n', self.volume_log.read_text())
        self.assertIn('wifi segredo wifi\n', secret.read_text())
        for bad in ({'device': 'wlan0; reboot', 'ssid': 'Casa'}, {'device': 'wlan0', 'ssid': ''},
                    {'device': 'wlan0', 'ssid': 'Casa', 'password': 'a\nb'}):
            self.assertEqual(self.request('POST', '/api/wifi', bad, cookie=cookie)[0], 400, bad)
        # A senha do gabinete: so com a de agora.
        wrong = {'current': 'nope', 'password': 'nova senha'}
        self.assertEqual(self.request('POST', '/api/password', wrong, cookie=cookie)[0], 403)
        self.assertEqual(self.request('POST', '/api/password', {'current': 'arcade', 'password': 'abc'},
                                      cookie=cookie)[0], 400)
        self.assertEqual(self.request('POST', '/api/password', {'current': 'arcade', 'password': 'nova senha'},
                                      cookie=cookie)[0], 200)
        self.assertIn('password nova senha\n', secret.read_text())
        self.assertNotIn('nova senha', self.volume_log.read_text())
        text = json.loads(self.request('GET', '/api/whatsnew', cookie=cookie)[2])['text']
        self.assertIn('update 85', text)

    def test_version_list_and_change(self):
        # Setup > System > FliperOS version pelo painel: a lista e o goto como
        # tarefa (uma troca por vez); so numero ou "latest".
        cookie = self.login()
        info = json.loads(self.request('GET', '/api/versions', cookie=cookie)[2])
        self.assertEqual((info['level'], info['base'], info['latest'], info['hold'], info['reboot']),
                         (63, 60, 63, None, False))
        self.assertEqual(info['updates'][2], {'n': 61, 'state': 'older', 'reboot': True, 'title': 'Scanlines'})
        status, _, data = self.request('POST', '/api/versions', {'update': 61}, cookie=cookie)
        self.assertEqual(status, 200, data)
        task = json.loads(data)
        self.assertEqual(task['name'], 'FliperOS version: update 61')
        for _ in range(50):
            if not json.loads(self.request('GET', '/api/task?id=%d' % task['id'], cookie=cookie)[2])['running']:
                break
            time.sleep(0.1)
        self.assertIn('goto 61 --progress\n', (Path(self.tmp.name) / 'update.log').read_text())
        for bad in ({'update': '61; reboot'}, {'update': True}, {'update': 0}, {}):
            self.assertEqual(self.request('POST', '/api/versions', bad, cookie=cookie)[0], 400, bad)
        status, _, data = self.request('POST', '/api/versions', {'update': 'latest'}, cookie=cookie)
        self.assertEqual(json.loads(data)['name'], 'FliperOS version: the newest update')
        js = (ROOT / 'config/web/setup.js').read_text()
        self.assertIn('const SETUP_PAGES = { custom: (box) => customGamesPage(box), version: versionPage, whatsnew: whatsnewPage };', js)
        text = (ROOT / 'config/web/text.js').read_text()
        self.assertEqual(text.count('group_Version:'), 2)

    def test_downloader_and_tasks(self):
        cookie = self.login()
        status = json.loads(self.request('GET', '/api/downloader', cookie=cookie)[2])
        self.assertEqual((status['pct'], status['roms_name'], status['filter']), ('40', 'MAME 0.289', 'Arcade, GroovyMAME'))
        # Aplicar o filtro: uma tarefa, com os eventos de progresso do Setup.
        status, _, data = self.request('POST', '/api/downloader', {'action': 'start'}, cookie=cookie)
        self.assertEqual(status, 200, data)
        task = json.loads(data)
        for _ in range(50):
            info = json.loads(self.request('GET', '/api/task?id=%d' % task['id'], cookie=cookie)[2])
            if not info['running']:
                break
            time.sleep(0.1)
        self.assertEqual((info['rc'], info['pct'], info['step'], info['last']), (0, 55, 'almost', 'plain line'))
        self.assertIn('@step 10 Reading the list', info['log'])
        self.assertIn('--downloader start\n', self.volume_log.read_text())
        # Sem link colado, o que vem na imagem; um que nao e magnet, nao.
        status, _, data = self.request('POST', '/api/downloader', {'action': 'add', 'kind': 'chds'}, cookie=cookie)
        self.assertEqual(status, 200, data)
        adding = json.loads(data)
        for _ in range(50):
            if '--downloader add' in self.volume_log.read_text():
                break
            time.sleep(0.1)
        self.assertIn('--downloader add chds magnet:?xt=urn:btih:chds\n', self.volume_log.read_text())
        # Um de cada vez: com o add rodando, outro pedido do Downloader espera.
        self.assertEqual(self.request('POST', '/api/downloader', {'action': 'start'}, cookie=cookie)[0], 409)
        self.assertEqual(self.request('POST', '/api/downloader', {'action': 'add', 'kind': 'roms', 'magnet': 'http://x'},
                                      cookie=cookie)[0], 400)
        # Cancelar.
        info = json.loads(self.request('POST', '/api/task/cancel', {'id': adding['id']}, cookie=cookie)[2])
        for _ in range(50):
            info = json.loads(self.request('GET', '/api/task?id=%d' % adding['id'], cookie=cookie)[2])
            if not info['running']:
                break
            time.sleep(0.1)
        self.assertFalse(info['running'])
        tasks = json.loads(self.request('GET', '/api/tasks', cookie=cookie)[2])['tasks']
        self.assertEqual([t['id'] for t in tasks][:2], [adding['id'], task['id']])
        self.assertIn('downloader_cli "${@:2}"', (ROOT / 'fliperos-setup/fliperos-setup').read_text())
        # O que roda sozinho (com jogo aberto ou nao) vem em background: o
        # Downloader e o scrape automatico (o scrape-status.json do servico).
        status_file = Path(self.tmp.name) / '.local/share/fliperos/scrape-status.json'
        status_file.parent.mkdir(parents=True, exist_ok=True)
        status_file.write_text(json.dumps({'total': 200, 'left': 50, 'scanned': True, 'current': 'Metal Slug',
                                           'torrent': [30, 'downloading'], 'pid': os.getpid(),
                                           'packs': {'mame-videos': ['downloading', 30], 'mame-logos': ['done', 100]}}))
        self.addCleanup(status_file.unlink)
        bg = json.loads(self.request('GET', '/api/tasks', cookie=cookie)[2])['background']
        self.assertEqual([(b['kind'], b['pct']) for b in bg], [('download', 40), ('scrape', 75)])
        self.assertEqual((bg[1]['done'], bg[1]['current'], bg[1]['packs_pct'], bg[1]['busy']), (150, 'Metal Slug', 30, True))
        auto = json.loads(self.request('GET', '/api/scraper?packs=1', cookie=cookie)[2])['auto']
        self.assertEqual((auto['on'], auto['left']), (True, 50))
        # Com o servico fora do ar (o pid nao existe), o scrape sai da lista.
        status_file.write_text(json.dumps({'total': 200, 'left': 50, 'scanned': True, 'pid': 2 ** 22 + 1}))
        bg = json.loads(self.request('GET', '/api/tasks', cookie=cookie)[2])['background']
        self.assertEqual([b['kind'] for b in bg], ['download'])
        # Pausar e na hora; continuar e uma tarefa (sobe o servico).
        status, _, data = self.request('POST', '/api/downloader', {'action': 'pause'}, cookie=cookie)
        self.assertEqual(status, 200, data)
        self.assertIn('--downloader pause\n', self.volume_log.read_text())
        status, _, data = self.request('POST', '/api/downloader', {'action': 'resume'}, cookie=cookie)
        self.assertEqual(status, 200, data)
        self.assertEqual(self.wait_task(cookie, data)['rc'], 0)
        self.assertIn('--downloader resume\n', self.volume_log.read_text())
        # O botao de pausar na pagina e na gaveta das tarefas.
        web = ROOT / 'config/web'
        self.assertIn('id="dl-pause"', (web / 'index.html').read_text())
        self.assertIn('action: goOn ? "resume" : "pause"', (web / 'tasks.js').read_text())

    def wait_task(self, cookie, data):
        task = json.loads(data)
        for _ in range(50):
            info = json.loads(self.request('GET', '/api/task?id=%d' % task['id'], cookie=cookie)[2])
            if not info['running']:
                return info
            time.sleep(0.1)
        self.fail('task still running: %s' % info)

    def test_scraper_page_through_the_setup(self):
        # Setup > Games > Scraper no painel: a fonte, a conta (pela entrada
        # padrao, nunca na linha de comando), os tipos de midia e as raspagens.
        cookie, tmp = self.login(), Path(self.tmp.name)
        status, _, data = self.request('GET', '/api/scraper', cookie=cookie)
        self.assertEqual(status, 200, data)
        info = json.loads(data)
        self.assertEqual((info['source'], info['user'], info['media'], info['pending'], info['skyscraper']),
                         ('screenscraper', 'joe', ['snap', 'logo'], ['mame'], True))
        self.assertEqual(info['systems'], [{'key': 'mame', 'platform': 'arcade', 'count': 12, 'arcade': True},
                                           {'key': 'retroarch/snes9x', 'platform': 'snes', 'count': 3, 'arcade': False}])
        self.assertEqual(info['sources'][1], {'key': 'mobygames', 'name': 'MobyGames', 'kind': 'key',
                                              'note': 'needs your API key'})
        packs = {'pct': '30', 'state': 'downloading', 'line': 'Logos 3 of 10'}
        self.assertEqual(info['packs'], packs)
        self.assertEqual(json.loads(self.request('GET', '/api/scraper?packs=1', cookie=cookie)[2]), {'packs': packs, 'auto': {'on': False}})
        account = {'action': 'account', 'source': 'screenscraper', 'user': 'joe', 'password': 's3cret'}
        self.assertEqual(self.request('POST', '/api/scraper', account, cookie=cookie)[0], 200)
        self.assertEqual((tmp / 'account.in').read_text(), 'joe:s3cret\n')
        self.assertNotIn('s3cret', self.volume_log.read_text())
        self.assertEqual(self.request('POST', '/api/scraper', {'action': 'account', 'source': 'igdb', 'id': 'a', 'secret': 'b'},
                                      cookie=cookie)[0], 200)
        self.assertEqual((tmp / 'account.in').read_text(), 'a:b\n')
        self.assertEqual(self.request('POST', '/api/scraper', {'action': 'account', 'source': 'screenscraper', 'remove': True},
                                      cookie=cookie)[0], 200)
        self.assertEqual((tmp / 'account.in').read_text(), '\n')
        for body in ({'action': 'account', 'source': 'screenscraper', 'user': 'joe'},
                     {'action': 'account', 'source': 'mobygames', 'key': 'a b'},
                     {'action': 'account', 'source': 'mobygames'},
                     {'action': 'source', 'source': 'nope'}, {'action': 'source', 'source': '../x'},
                     {'action': 'site', 'systems': ['../etc']}, {'action': 'scrape', 'systems': 'mame'},
                     {'action': 'media', 'media': ['snap;rm']}, {'action': 'nope'}):
            self.assertEqual(self.request('POST', '/api/scraper', body, cookie=cookie)[0], 400, body)
        self.assertEqual(self.request('POST', '/api/scraper', {'action': 'media', 'media': ['snap', 'preview']},
                                      cookie=cookie)[0], 200)
        self.assertIn('--scraper media snap,preview\n', self.volume_log.read_text())
        status, _, data = self.request('POST', '/api/scraper', {'action': 'site', 'systems': ['mame', 'retroarch/snes9x'],
                                                                'clones': True}, cookie=cookie)
        self.assertEqual(status, 200, data)
        self.assertEqual(self.wait_task(cookie, data)['rc'], 0)
        self.assertIn('--scraper site --clones mame retroarch/snes9x\n', self.volume_log.read_text())
        for body, line in (({'action': 'scrape', 'systems': []}, '--scraper scrape\n'),
                           ({'action': 'resume'}, '--scraper resume\n'), ({'action': 'packs'}, '--mediapacks auto\n')):
            status, _, data = self.request('POST', '/api/scraper', body, cookie=cookie)
            self.assertEqual(status, 200, data)
            self.wait_task(cookie, data)
            self.assertIn(line, self.volume_log.read_text())
        main = (ROOT / 'fliperos-setup/fliperos-setup').read_text()
        self.assertIn('scraper_cli "${@:2}"', main)
        self.assertIn('bios_cli "${@:2}"', main)

