class GuiWaitingTests(unittest.TestCase):
    """A espera do Entrar com o Google (ui_wait, widgets.Waiting): os segundos
    sao so o intervalo em que o Setup pergunta o estado, entao a tela nao
    mostra contagem regressiva (ela recomecava 3, 2, 1 a cada volta durante a
    primeira sincronizacao); o tempo desde o comeco dela so sobe."""
    GUI = ROOT / "fliperos-setup/gui"

    @unittest.skipUnless(importlib.util.find_spec("pygame"), "sem o pygame")
    def test_no_countdown_and_timeout_after_the_interval(self):
        os.environ["SDL_VIDEODRIVER"] = "dummy"
        os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "1"
        sys.path.insert(0, str(self.GUI))
        self.addCleanup(sys.path.remove, str(self.GUI))
        import pygame
        import widgets
        pygame.font.init()
        drawn = []
        original = widgets.centered
        widgets.centered = lambda surf, s, *a, **k: drawn.append(s)
        self.addCleanup(setattr, widgets, "centered", original)
        screen = widgets.Waiting("Sign in with Google", [("First sync running for 0:03.", None)], 3)
        screen.draw(pygame.Surface((320, 240), pygame.SRCALPHA), {"status": "", "version": ""})
        self.assertTrue(any(s.startswith("WAITING") for s in drawn))
        self.assertFalse([s for s in drawn if re.fullmatch(r"\d+ s", s)])
        self.assertNotEqual(screen.tick(), ("timeout", None))
        self.assertIsNone(screen.key("enter"))
        self.assertEqual(screen.key("esc"), ("back", None))
        screen.deadline -= 3
        self.assertEqual(screen.tick(), ("timeout", None))

    @unittest.skipUnless(importlib.util.find_spec("pygame"), "sem o pygame")
    def test_the_first_sync_wait_draws_a_progress_bar(self):
        # A primeira sincronizacao com a nuvem: uma barra em blocos (a mesma da tela de progresso) com a
        # porcentagem, que anda com o rclone; sem "@bar", a espera e a de antes.
        os.environ["SDL_VIDEODRIVER"] = "dummy"
        os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "1"
        sys.path.insert(0, str(self.GUI))
        self.addCleanup(sys.path.remove, str(self.GUI))
        import pygame
        import widgets
        pygame.font.init()
        drawn = []
        original = widgets.centered
        widgets.centered = lambda surf, s, *a, **k: drawn.append(s)
        self.addCleanup(setattr, widgets, "centered", original)
        ctx = {"status": "", "version": ""}
        surf = pygame.Surface((320, 240), pygame.SRCALPHA)
        widgets.Waiting("Sign in with Google", [("First sync running for 0:03.", None)], 3, 42).draw(surf, ctx)
        self.assertIn("42%", drawn)
        self.assertTrue(any(s.startswith("WAITING") for s in drawn))
        # A barra pinta blocos (42% de 24 = 10 acesos); sem a porcentagem, nenhum "%".
        drawn.clear()
        widgets.Waiting("Sign in with Google", [("x", None)], 3).draw(surf, ctx)
        self.assertFalse([s for s in drawn if s.endswith("%")])
        # O Setup manda "@bar PCT" e o serve.py o tira das linhas.
        serve = (self.GUI / "serve.py").read_text()
        self.assertIn('re.fullmatch(r"@bar (\\d{1,3})", arg)', serve)
        self.assertIn("W.Waiting(plain(a[0]), self.lines(rest), int(a[1]), pct)", serve)

    def test_the_first_sync_screen_has_a_bar_in_the_gui_and_in_text(self):
        menu = (ROOT / "fliperos-setup/screens/setup-menu.sh").read_text()
        body = menu[menu.index("screen_cloud_google() {"):]
        body = body[:body.index("\n}\n")]
        self.assertIn('"First sync running for $(printf \'%d:%02d\' $((elapsed / 60)) $((elapsed % 60)))." "@bar $pct"', body)
        self.assertIn("[[ $pct =~ ^[0-9]{1,3}$ ]] || pct=0", body)
        # Sem a interface grafica, a barra de texto.
        out = subprocess.run(['bash', '-c', 'source "$1"/lib/ui.sh; ui_text_bar 42; echo; ui_text_bar 100 4; echo; ui_text_bar 250 4; echo',
                              'x', str(ROOT / 'fliperos-setup')], capture_output=True, text=True).stdout.splitlines()
        self.assertEqual(out, ['[' + '█' * 10 + '░' * 14 + ']  42%', '[████] 100%', '[████] 100%'])
        # O painel web tambem desenha a barra desde o comeco (em 0 ate o primeiro numero).
        js = (ROOT / "config/web/system.js").read_text()
        self.assertIn('Number(s.pct)) : 0;', js)
        self.assertIn('stMeter(pct, ""));', js)

    def test_google_sign_in_uses_the_wait_without_a_countdown(self):
        menu = (ROOT / "fliperos-setup/screens/setup-menu.sh").read_text()
        body = menu[menu.index("screen_cloud_google() {"):]
        body = body[:body.index("\n}\n")]
        self.assertNotIn("ui_timed_confirm", body)
        self.assertIn("First sync running for", body)
        ui = (ROOT / "fliperos-setup/lib/ui.sh").read_text()
        qr = ui[ui.index("ui_qr_wait() {"):]
        self.assertNotIn("ui_timed_confirm", qr[:qr.index("\n}\n")])
        self.assertIn('if cmd == "wait":', (self.GUI / "serve.py").read_text())


class GuiNotSupportedTests(unittest.TestCase):
    """Um item "(not supported)" de um menu do Setup grafico: a dica traz o
    motivo e o Menu desenha um X vermelho no icone (gui/serve.py, widgets.py)."""
    GUI = ROOT / "fliperos-setup/gui"

    def serve(self):
        sys.path.insert(0, str(self.GUI))
        try:
            import serve
        finally:
            sys.path.remove(str(self.GUI))
        return serve

    def test_the_label_notes_become_the_hint_and_the_blocked_flag(self):
        serve = self.serve()
        gs = serve.GS
        reason = "Needs OpenGL 3.3 or OpenGL ES 3.0, and this video card gives OpenGL ES 2.0"
        entries = serve.Server.entries(None, [
            "emulationstation" + gs + "EmulationStation (not installed) (" + reason + ") (not supported)" + gs,
            "pegasus" + gs + "Pegasus (not installed)" + gs,
            "retroarch" + gs + "RetroArch (installed)" + gs,
        ])
        self.assertEqual(entries[0], ("emulationstation", "EmulationStation",
                                      "Not installed. " + reason + ". Not supported", False, True))
        self.assertEqual(entries[1], ("pegasus", "Pegasus", "Not installed", False, False))
        self.assertEqual(entries[2][3:], (True, False))

    @unittest.skipUnless(importlib.util.find_spec("pygame"), "sem o pygame")
    def test_the_menu_draws_a_red_cross_over_a_blocked_item(self):
        os.environ["SDL_VIDEODRIVER"] = "dummy"
        os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "1"
        sys.path.insert(0, str(self.GUI))
        try:
            import pygame
            import theme
            import widgets
        finally:
            sys.path.remove(str(self.GUI))
        pygame.init()
        surf = pygame.Surface((64, 64))
        surf.fill((0, 0, 0))
        widgets.cross(surf, 0, 0, 64)
        reds = sum(1 for x in range(64) for y in range(64) if surf.get_at((x, y))[:3] == theme.RED)
        self.assertGreater(reds, 100)
        menu = widgets.Menu("Frontend", [("emulationstation", "ES", "hint", False, True), ("pegasus", "P", "", False, False)])
        self.assertEqual(menu.blocked, {"emulationstation"})


class GuiInputKeyboardTests(unittest.TestCase):
    """Todo campo de texto do Setup grafico tem o teclado na tela, para o
    controle: aberto num campo sem botoes, e pelo Enter no campo num com
    botoes (o Esc o fecha e os botoes voltam)."""
    GUI = ROOT / "fliperos-setup/gui"

    @unittest.skipUnless(importlib.util.find_spec("pygame"), "sem o pygame")
    def test_every_field_gets_the_keyboard(self):
        os.environ["SDL_VIDEODRIVER"] = "dummy"
        os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "1"
        sys.path.insert(0, str(self.GUI))
        # O frame importa o tiny na hora de desenhar.
        self.addCleanup(sys.path.remove, str(self.GUI))
        import pygame
        import widgets
        pygame.font.init()
        surf = pygame.Surface((320, 240), pygame.SRCALPHA)
        ctx = {"status": "", "version": ""}
        # Sem botoes: o teclado ja aberto; a tecla escolhida e digitada.
        plain = widgets.Input("Name", ["Cabinet name:"], "ab", keyboard=True)
        self.assertTrue(plain.keyboard)
        plain.draw(surf, ctx)
        self.assertIsNone(plain.key("enter"))
        self.assertEqual(plain.value, "abq")
        for k in ("down", "down", "down", "left"):     # a fileira de baixo, no OK
            plain.key(k)
        self.assertEqual(plain.key("enter"), ("select", "abq"))
        # Com botoes: o Enter no campo abre o teclado, o Esc o fecha.
        link = widgets.Input("ROM set link", ["Magnet:"], "", action=[("torrent", "TORRENT", "a .torrent")],
                             keyboard=True)
        self.assertFalse(link.keyboard)
        self.assertIsNone(link.key("enter"))
        self.assertTrue(link.keyboard)
        link.draw(surf, ctx)
        link.key("enter")
        self.assertEqual(link.value, "q")
        self.assertIsNone(link.key("esc"))
        self.assertFalse(link.keyboard)
        link.draw(surf, ctx)
        self.assertEqual(link.key("down"), None)
        self.assertEqual(link.key("enter"), ("select", "torrent"))
        # Quem digita num teclado de verdade confirma com o Enter.
        typed = widgets.Input("ROM set link", ["Magnet:"], "", action=[("torrent", "TORRENT", "")], keyboard=True)
        typed.key("m")
        self.assertEqual(typed.key("enter"), ("select", "m"))
        self.assertIn("keyboard=True)", (self.GUI / "serve.py").read_text())


class DrmMasterTests(unittest.TestCase):
    """gui/drmmaster.py: na Intel o Mesa deixa o master da tela depois do
    display.quit() do pygame, e o jogo seguinte nao abria."""
    GUI = ROOT / 'fliperos-setup/gui'

    def module(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location('drmmaster', self.GUI / 'drmmaster.py')
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    def test_drop_releases_only_the_dri_card_descriptors(self):
        from unittest import mock
        mod = self.module()
        links = {'3': '/dev/dri/card0', '4': '/dev/dri/renderD128', '5': '/tmp/x', '6': '/dev/dri/card1'}
        with mock.patch.object(mod.os, 'listdir', return_value=list(links)), \
                mock.patch.object(mod.os, 'readlink', side_effect=lambda p: links[p.rsplit('/', 1)[1]]), \
                mock.patch.object(mod.fcntl, 'ioctl') as ioctl:
            self.assertEqual(mod.drop(), 2)
        self.assertEqual([c.args for c in ioctl.call_args_list],
                         [(3, mod.DRM_IOCTL_DROP_MASTER), (6, mod.DRM_IOCTL_DROP_MASTER)])
        self.assertEqual(mod.DRM_IOCTL_DROP_MASTER, 0x641F)

    def test_a_descriptor_that_is_not_the_master_is_skipped(self):
        from unittest import mock
        mod = self.module()
        with mock.patch.object(mod.os, 'listdir', return_value=['3']), \
                mock.patch.object(mod.os, 'readlink', return_value='/dev/dri/card0'), \
                mock.patch.object(mod.fcntl, 'ioctl', side_effect=PermissionError):
            self.assertEqual(mod.drop(), 0)

    def test_both_pygame_programs_drop_it_after_closing_the_display(self):
        for name in ('fliperos-frontend', 'fliperos-gui'):
            text = (self.GUI / name).read_text()
            self.assertRegex(text, r'display\.quit\(\)[^\n]*\n(?:[^\n]*\n)*?[^\n]*drmmaster\.drop\(\)', name)


class OnDemandFrontendTests(unittest.TestCase):
    """O ES-DE e o Pegasus nao vem na imagem: o Setup os compila no gabinete
    (config/fliperos-frontend-build) com a receita e os patches do packaging/."""
    SCRIPT = ROOT / 'config/fliperos-frontend-build'
    ON_DEMAND = ('fliperos-emulationstation', 'fliperos-pegasus')

    def list_recipes(self, flag):
        run = subprocess.run(['bash', str(ROOT / 'packaging/build-deb.sh'), flag], capture_output=True, text=True)
        self.assertEqual(run.returncode, 0, run.stderr)
        return run.stdout.split()

    def test_the_iso_repository_keeps_only_the_recipes_that_are_not_on_demand(self):
        iso = ('fliperos-attractplus', 'fliperos-dolphin', 'fliperos-flycast', 'fliperos-groovymame', 'fliperos-gum',
               'fliperos-keisho', 'fliperos-openbor', 'fliperos-pcsx2', 'fliperos-rahasher', 'fliperos-retroarch',
               'fliperos-sdl2-kms')
        self.assertEqual(self.list_recipes('--list-iso'), list(iso))
        self.assertEqual(sorted(self.list_recipes('--list')), sorted(iso + self.ON_DEMAND))
        self.assertIn('build-deb.sh --list-iso', (ROOT / '.github/workflows/release.yml').read_text())

    def test_the_session_table_fetches_them_instead_of_installing_a_package(self):
        table = (ROOT / 'config/fliperos-sessions.conf').read_text()
        self.assertIn('emulationstation|kms|emulationstation|fetch:fliperos-emulationstation|', table)
        self.assertIn('pegasus|kms|pegasus-fe|fetch:fliperos-pegasus|', table)

    def test_the_image_carries_the_installer_the_recipes_and_the_patches(self):
        rootfs = (ROOT / 'fliperos-rootfs.sh').read_text()
        for name in self.ON_DEMAND:
            self.assertIn('"$root/opt/fliperos/bin/%s"' % name, rootfs)
            self.assertIn(name, rootfs)
        self.assertIn('config/fliperos-frontend-build', rootfs)
        self.assertIn('packaging/patches/{emulationstation,retroarch,dolphin,flycast,keisho}/*.patch', rootfs)
        self.assertIn('COPY packaging/', (ROOT / 'Dockerfile.fliperos').read_text())
        self.assertIn('config packaging', (ROOT / 'tools/cabinet-push.sh').read_text())

    def test_about_warns_that_it_is_built_here(self):
        for name, label in (('fliperos-emulationstation', 'EmulationStation-DE'), ('fliperos-pegasus', 'Pegasus')):
            run = subprocess.run(['bash', str(self.SCRIPT), 'about'], capture_output=True, text=True,
                                 env=dict(os.environ, FLIPEROS_FRONTEND_PKG=name))
            self.assertEqual(run.returncode, 0, run.stderr)
            self.assertIn(label + ' does not come with FliperOS', run.stdout)
            self.assertIn('built on this machine', run.stdout)

    def build(self, tmp, name='fliperos-emulationstation', fail=False, eglinfo=''):
        """Roda o fetch com um build-deb.sh e um apt de mentira; devolve o
        resultado e o que o apt recebeu."""
        packaging, bin_dir, out = tmp / 'packaging', tmp / 'bin', tmp / 'work'
        (packaging / 'packages').mkdir(parents=True)
        bin_dir.mkdir()
        out.mkdir()
        (packaging / 'packages' / (name + '.sh')).write_text('PKG_BUILD_DEPS="aaa \\\nbbb"\n')
        (packaging / 'build-deb.sh').write_text(
            '#!/bin/bash\n'
            'echo "Installing build dependencies"\n'
            'echo "Compiling (this can take a while)"\n'
            'echo "[ 50%%] Building CXX object x.o"\n'
            'echo "Computing Depends with dpkg-shlibdeps"\n'
            '%s'
            'touch "$2/%s_1-1_amd64.deb"\n' % ('exit 1\n' if fail else '', name))
        (bin_dir / 'apt-get').write_text('#!/bin/sh\necho "$@" >> "$APT_LOG"\n')
        # "aaa" nao estava instalada (sai no fim); "bbb" ja estava.
        (bin_dir / 'dpkg').write_text('#!/bin/sh\n[ "$1 $2" = "-s aaa" ] && exit 1\nexit 0\n')
        for tool in ('apt-get', 'dpkg'):
            (bin_dir / tool).chmod(0o755)
        if eglinfo:
            (tmp / 'eglinfo').write_text('#!/bin/sh\ncat <<\'EOF\'\n%s\nEOF\n' % eglinfo)
            (tmp / 'eglinfo').chmod(0o755)
        env = dict(os.environ, PATH='%s:%s' % (bin_dir, os.environ['PATH']), APT_LOG=str(tmp / 'apt.log'),
                   FLIPEROS_FRONTEND_PKG=name, FLIPEROS_PACKAGING=str(packaging), FLIPEROS_BUILD_DIR=str(out),
                   FLIPEROS_BUILD_LOG=str(tmp / 'build.log'), FLIPEROS_BUILD_MIN_MB='1',
                   FLIPEROS_EGLINFO=str(tmp / 'eglinfo') if eglinfo else str(tmp / 'sem-eglinfo'))
        run = subprocess.run(['bash', str(self.SCRIPT), 'fetch', '--progress'], capture_output=True, text=True,
                             env=env, timeout=60)
        apt = (tmp / 'apt.log').read_text().splitlines() if (tmp / 'apt.log').exists() else []
        return run, apt, out

    @unittest.skipUnless(hasattr(os, 'geteuid') and os.geteuid() == 0, 'o instalador exige root')
    def test_fetch_builds_installs_and_removes_only_the_tools_it_brought(self):
        with tempfile.TemporaryDirectory() as tmp:
            run, apt, out = self.build(Path(tmp))
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
            steps = [line for line in run.stdout.splitlines() if line.startswith('@step')]
            self.assertEqual(steps[0], '@step 1 Updating the package lists')
            self.assertIn('@step 3 Installing the build tools', steps)
            self.assertIn('@step 12 Compiling EmulationStation-DE (30 or more minutes)', steps)
            # O cmake conta 50%: 12 + 50 * 75 / 100.
            self.assertIn('@step 49 Compiling EmulationStation-DE (30 or more minutes)', steps)
            self.assertEqual(steps[-1], '@step 100 EmulationStation-DE installed')
            self.assertTrue(apt[0].endswith('update -qq'), apt)
            self.assertTrue(any(line.startswith('-y') and ' install ' in line and line.endswith('_1-1_amd64.deb')
                                for line in apt), apt)
            # So a que faltava sai do sistema; a que ja estava fica.
            self.assertEqual(apt[-1], '-y -o DPkg::Lock::Timeout=120 purge aaa')
            self.assertEqual(list(out.iterdir()), [], 'a pasta de trabalho do build ficou para tras')

    @unittest.skipUnless(hasattr(os, 'geteuid') and os.geteuid() == 0, 'o instalador exige root')
    def test_a_failed_build_reports_the_log_and_installs_nothing(self):
        with tempfile.TemporaryDirectory() as tmp:
            run, apt, out = self.build(Path(tmp), 'fliperos-pegasus', fail=True)
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail Pegasus|the build failed (details in %s/build.log)' % tmp, run.stdout)
            self.assertFalse(any(' install ' in line for line in apt), apt)
            self.assertIn('Compiling', (Path(tmp) / 'build.log').read_text())
            self.assertEqual(list(out.iterdir()), [])

    IRONLAKE = ('EGL client APIs: OpenGL OpenGL_ES \n'
                'OpenGL compatibility profile version: 2.1 Mesa 25.2.8\n'
                'OpenGL ES profile version: OpenGL ES 2.0 Mesa 25.2.8')
    MODERN = ('EGL client APIs: OpenGL OpenGL_ES \n'
              'OpenGL core profile version: 4.6 (Core Profile) Mesa 25.2.8\n'
              'OpenGL ES profile version: OpenGL ES 3.2 Mesa 25.2.8')

    @unittest.skipUnless(hasattr(os, 'geteuid') and os.geteuid() == 0, 'o instalador exige root')
    def test_esde_is_not_built_on_a_card_without_opengl_3_3_or_es_3_0(self):
        # O ES-DE 3.x pede OpenGL 3.3 core ou ES 3.0: na Intel Ironlake (2.1 e
        # ES 2.0) ele nao abre, e a compilacao seria em vao.
        with tempfile.TemporaryDirectory() as tmp:
            run, apt, out = self.build(Path(tmp), eglinfo=self.IRONLAKE)
            self.assertEqual(run.returncode, 1, run.stdout)
            self.assertIn('@fail EmulationStation-DE|EmulationStation-DE needs OpenGL 3.3 or OpenGL ES 3.0, '
                          'and this video card gives OpenGL ES 2.0.', run.stdout)
            self.assertEqual(apt, [], 'nem o apt update devia rodar')
        with tempfile.TemporaryDirectory() as tmp:
            run, apt, out = self.build(Path(tmp), eglinfo=self.MODERN)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
        # O Pegasus (Qt, OpenGL ES 2.0) nao tem essa exigencia.
        with tempfile.TemporaryDirectory() as tmp:
            run, apt, out = self.build(Path(tmp), 'fliperos-pegasus', eglinfo=self.IRONLAKE)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)

    def test_about_warns_when_the_card_cannot_run_esde(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            (tmp / 'eglinfo').write_text('#!/bin/sh\ncat <<\'EOF\'\n%s\nEOF\n' % self.IRONLAKE)
            (tmp / 'eglinfo').chmod(0o755)
            env = dict(os.environ, FLIPEROS_EGLINFO=str(tmp / 'eglinfo'))
            run = subprocess.run(['bash', str(self.SCRIPT), 'about'], capture_output=True, text=True,
                                 env=dict(env, FLIPEROS_FRONTEND_PKG='fliperos-emulationstation'))
            self.assertIn('WARNING: EmulationStation-DE needs OpenGL 3.3 or OpenGL ES 3.0', run.stdout)
            run = subprocess.run(['bash', str(self.SCRIPT), 'about'], capture_output=True, text=True,
                                 env=dict(env, FLIPEROS_FRONTEND_PKG='fliperos-pegasus'))
            self.assertNotIn('WARNING', run.stdout)
            # Sem eglinfo (ou sem resposta) nao da para saber: sem aviso.
            run = subprocess.run(['bash', str(self.SCRIPT), 'about'], capture_output=True, text=True,
                                 env=dict(env, FLIPEROS_EGLINFO=str(tmp / 'nada'),
                                          FLIPEROS_FRONTEND_PKG='fliperos-emulationstation'))
            self.assertNotIn('WARNING', run.stdout)

    def test_an_unknown_program_name_is_refused(self):
        run = subprocess.run(['bash', str(self.SCRIPT), 'about'], capture_output=True, text=True,
                             env=dict(os.environ, FLIPEROS_FRONTEND_PKG='outro'))
        self.assertEqual(run.returncode, 2)


class PackagingTests(unittest.TestCase):
    RECIPES = ROOT / 'packaging/packages'

    def recipe_files(self):
        return sorted(self.RECIPES.glob('*.sh'))

    def test_recipes_declare_the_full_contract(self):
        self.assertTrue(self.recipe_files())
        for recipe in self.recipe_files():
            text = recipe.read_text()
            for field in ('PKG_NAME=', 'PKG_VERSION=', 'PKG_SUMMARY=',
                          'PKG_BUILD_DEPS=', 'PKG_SHLIB_TARGETS=', 'pkg_build()'):
                self.assertIn(field, text, '%s sem %s' % (recipe.name, field))

    def test_the_iso_takes_the_published_debs_and_builds_only_what_is_missing(self):
        # Os .deb do release "packages" (os da updates/packages.list, pelo
        # sha256) entram na ISO prontos: o GroovyMAME levaria horas na CI, e a
        # ISO fica com os mesmos binarios dos updates.
        release = (ROOT / '.github/workflows/release.yml').read_text()
        step = release.split('- name: Repositorio dos frontends')[1].split('- name: ISO')[0]
        self.assertIn('GH_TOKEN: ${{ github.token }}', step)
        self.assertIn("grep -v '^#' updates/packages.list | while read -r name version sum when; do", step)
        self.assertIn('gh release download packages -R "$GITHUB_REPOSITORY" -p "$deb"', step)
        self.assertIn('sha256sum -c --quiet - || rm -f "$OUT/packages/$deb"', step)
        self.assertIn('bash packaging/build-deb.sh --skip-existing $recipes', step)
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp, 'out')
            out.mkdir()
            recipes = Path(tmp, 'packaging/packages')
            recipes.mkdir(parents=True)
            shutil.copy(ROOT / 'packaging/build-deb.sh', Path(tmp, 'packaging/build-deb.sh'))
            (recipes / 'fliperos-x.sh').write_text('PKG_NAME="fliperos-x"\nPKG_VERSION="1.0"\nPKG_REVISION="1fliperos3"\n'
                                                   'pkg_build() { touch "$SRC/built"; return 1; }\n')
            Path(out, 'fliperos-x_1.0-1fliperos3_amd64.deb').write_bytes(b'published')
            if os.geteuid():
                self.skipTest('build-deb.sh runs as root (the test container)')
            run = subprocess.run(['bash', str(Path(tmp, 'packaging/build-deb.sh')), '--output', str(out),
                                  '--skip-existing', 'fliperos-x'], capture_output=True, text=True)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
            self.assertIn('already built', run.stdout)
            self.assertEqual(Path(out, 'fliperos-x_1.0-1fliperos3_amd64.deb').read_bytes(), b'published')

    def test_recipe_filename_matches_package_name(self):
        for recipe in self.recipe_files():
            declared = re.search(r'^PKG_NAME="([^"]+)"', recipe.read_text(), flags=re.M).group(1)
            self.assertEqual(declared, recipe.stem)

    def test_every_recipe_is_a_launcher_an_emulator_or_its_library(self):
        # Os frontends, os emuladores que vinham compilados na ISO (os updates
        # os levam como pacote), o SDL do GroovyMAME, o gum do Setup e o
        # RAHasher do selo das conquistas (gui/fecheevos.py).
        table = (ROOT / 'config/fliperos-sessions.conf').read_text()
        emulators = {line.split('|')[0] for line in
                     (ROOT / 'config/fliperos-emulators').read_text().split('table() {')[1].split('\nEOF')[0].splitlines()
                     if '|' in line}
        for recipe in self.recipe_files():
            name = recipe.stem[len('fliperos-'):]
            self.assertTrue(recipe.stem in table or name in emulators
                            or recipe.stem in ('fliperos-sdl2-kms', 'fliperos-gum', 'fliperos-rahasher'), recipe.stem)

    def test_attractplus_patches_apply_on_linux_and_keep_the_kernel_joystick_order(self):
        # patch -p1 no container: um patch em CRLF nao se aplica.
        patches = sorted((ROOT / 'packaging/patches/attractplus').glob('*.patch'))
        for patch in patches:
            self.assertNotIn(b'\r', patch.read_bytes(), patch.name)
        self.assertIn('packaging/patches/** -text', (ROOT / '.gitattributes').read_text())
        recipe = (self.RECIPES / 'fliperos-attractplus.sh').read_text()
        self.assertIn('for patch in "$here"/../patches/attractplus/*.patch', recipe)
        self.assertIn('patch -d "$SRC/attractplus" -p1 < "$patch" || return 1', recipe)
        # O SFML listava os joysticks pelo caminho do sysfs como texto
        # (input10 antes de input9): o Joy0 era o jogador 2.
        order = (ROOT / 'packaging/patches/attractplus/0001-sfml-joysticks-in-kernel-order.patch').read_text()
        self.assertIn('+++ b/extlibs/SFML/src/SFML/Window/Unix/JoystickImpl.cpp', order)
        self.assertIn('joystickNumber(left.deviceNode) < joystickNumber(right.deviceNode)', order)
        # Intel Ironlake recusa o framebuffer ARGB8888 do SFML (tela preta e
        # "Failed to create fb"): so depois das duas tentativas, XRGB8888.
        xrgb = (ROOT / 'packaging/patches/attractplus/0002-sfml-drm-xrgb-fallback-for-ironlake.patch').read_text()
        self.assertIn('+++ b/extlibs/SFML/src/SFML/Window/DRM/DRMContext.cpp', xrgb)
        self.assertIn('if (result && format == GBM_FORMAT_ARGB8888)', xrgb)
        self.assertIn('+                               GBM_FORMAT_XRGB8888,', xrgb)
        # O Mesa da Ironlake deixa o master da tela para tras: o SFML o solta
        # antes de fechar o descritor, senao o emulador nao abre.
        master = (ROOT / 'packaging/patches/attractplus/0003-sfml-drm-drop-master-on-cleanup.patch').read_text()
        self.assertIn('+    drmDropMaster(drmNode.fileDescriptor);', master)


class DocsTests(unittest.TestCase):
    """O README e o resumo; o detalhe fica nas paginas de docs/wiki, que o
    tools/wiki-publish.sh publica na wiki do GitHub."""
    WIKI = ROOT / 'docs/wiki'
    URL = 'https://github.com/juniorterin/fliperOS/wiki'
    PAGE = r'[A-Za-z0-9_-]+'

    def pages(self):
        return {p.stem for p in self.WIKI.glob('*.md')} - {'Home', '_Sidebar'}

    def test_links_between_pages_exist(self):
        for page in self.WIKI.glob('*.md'):
            text = page.read_text()
            for target in re.findall(r'\]\(([^)]+)\)', text):
                if target.startswith(('https://', 'http://', '#')):
                    continue
                # Fora isso, so outra pagina da wiki: la nao ha os arquivos do repositorio.
                match = re.fullmatch(r'(%s)\.md(#.*)?' % self.PAGE, target)
                self.assertTrue(match, '%s: link %s' % (page.name, target))
                self.assertIn(match.group(1), self.pages() | {'Home'}, '%s: link %s' % (page.name, target))
            # As referencias "secao N" eram do README de uma pagina so.
            self.assertNotRegex(text, r'(se[cç][aã]o|[Ss]ection) \d', page.name)

    def top_pages(self):
        # As paginas de topo: as do _Sidebar sem recuo (as subpaginas vem
        # recuadas debaixo delas).
        return set(re.findall(r'^- \[[^\]]+\]\((%s)\.md\)' % self.PAGE,
                              (self.WIKI / '_Sidebar.md').read_text(), re.M))

    @staticmethod
    def anchors(text):
        """As ancoras que o GitHub da a uma pagina: uma por titulo (minusculas,
        sem pontuacao, cada espaco um hifen; repetido ganha -1, -2) e os <a id>."""
        found, seen = set(re.findall(r'<a (?:id|name)="([^"]+)"', text)), {}
        for heading in re.findall(r'^#{1,6} +(.+?)\s*$', re.sub(r'```.*?```', '', text, flags=re.S), re.M):
            heading = re.sub(r'\[([^\]]*)\]\([^)]*\)', r'\1', heading)
            heading = re.sub(r'<[^>]+>|[`*]', '', heading)
            slug = re.sub(r'[^\w\- ]', '', heading.strip().lower()).replace(' ', '-')
            found.add('%s-%d' % (slug, seen[slug]) if slug in seen else slug)
            seen[slug] = seen.get(slug, 0) + 1
        return found

    def test_every_page_is_in_the_index_and_in_the_sidebar(self):
        self.assertGreaterEqual(len(self.pages()), 10)
        for index in ('Home.md', '_Sidebar.md'):
            listed = set(re.findall(r'\]\((%s)\.md\)' % self.PAGE, (self.WIKI / index).read_text())) - {'Home'}
            self.assertEqual(listed, self.pages(), index)
        self.assertGreaterEqual(len(self.top_pages()), 10)

    def test_anchors_lead_to_a_heading(self):
        # Um link "Pagina#secao" (entre paginas, no README, no painel web ou no
        # site) cai num titulo que existe: dividir uma pagina nao pode deixar
        # um link de fora no topo da pagina errada.
        anchors = {p.stem: self.anchors(p.read_text(encoding='utf-8')) for p in self.WIKI.glob('*.md')}
        sources = [(p.name, p.stem) for p in self.WIKI.glob('*.md')]
        sources += [(path, None) for path in ('README.md', 'README.pt-BR.md', 'config/web/index.html',
                                              'config/web/library.js')]
        sources += [(str(p.relative_to(ROOT)), None) for p in (ROOT / 'website/src').rglob('*.ts*')]
        for name, own in sources:
            text = (self.WIKI / name if own else ROOT / name).read_text(encoding='utf-8')
            links = re.findall(r'\]\((%s)\.md#([^)\s]+)\)' % self.PAGE, text)
            links += re.findall(re.escape(self.URL) + r'/(%s)#([\w-]+)' % self.PAGE, text)
            links += re.findall(r'docs/wiki/(%s)\.md#([\w-]+)' % self.PAGE, text)
            links += re.findall(r'\$\{LINKS\.docs\}/(%s)#([\w-]+)' % self.PAGE, text)
            links += re.findall(r"docs: '(%s)#([\w-]+)'" % self.PAGE, text)
            if own:
                links += [(own, anchor) for anchor in re.findall(r'\]\(#([^)\s]+)\)', text)]
            for page, anchor in links:
                self.assertIn(anchor, anchors.get(page, set()), '%s: %s#%s' % (name, page, anchor))

    def test_readmes_guide_from_install_to_play_in_both_languages(self):
        english = (ROOT / 'README.md').read_text(encoding='utf-8')
        portuguese = (ROOT / 'README.pt-BR.md').read_text(encoding='utf-8')
        # Um leva ao outro, logo no topo (link Markdown ou HTML do cabecalho centralizado).
        self.assertRegex(english.split('\n## ')[0], r'\(README\.pt-BR\.md\)|href="README\.pt-BR\.md"')
        self.assertRegex(portuguese.split('\n## ')[0], r'\(README\.md\)|href="README\.md"')
        for readme in (english, portuguese):
            # Leva a cada pagina de topo da wiki (as subpaginas estao nelas), e so
            # a paginas que existem.
            linked = set(re.findall(re.escape(self.URL) + r'/(%s)' % self.PAGE, readme))
            self.assertLessEqual(self.top_pages(), linked)
            self.assertLessEqual(linked, self.pages())
            for needed in ('dd if=fliperos-0.26.iso', 'fliperos-mkiso.sh', 'tests/test_setup.py',
                           'tools/wiki-publish.sh', 'openbor/Paks', 'Video Setup'):
                self.assertIn(needed, readme)
        # O passo a passo tem os mesmos passos numerados nas duas linguas.
        steps = [re.findall(r'^### (\d+)\.', r, re.M) for r in (english, portuguese)]
        self.assertEqual(steps[0], steps[1])
        self.assertGreaterEqual(len(steps[0]), 10)

    def test_site_links_each_language_to_its_readme(self):
        site = (ROOT / 'website/src/lib/site.ts').read_text()
        self.assertIn('README.pt-BR.md', site)
        for page in ('sections/OpenSource.tsx', 'sections/Footer.tsx', 'components/Header.tsx'):
            text = (ROOT / 'website/src' / page).read_text()
            self.assertIn('readmeUrl(locale)', text, page)
            self.assertNotIn('LINKS.github', text, page)
        # O CTA do hero baixa a ISO do release mais recente, nao a pagina do release.
        hero = (ROOT / 'website/src/sections/Hero.tsx').read_text()
        page = (ROOT / 'website/src/app/[lang]/page.tsx').read_text()
        github = (ROOT / 'website/src/lib/github.ts').read_text()
        self.assertIn('downloadUrl', hero)
        self.assertIn('stats?.release?.iso ?? latestIsoUrl()', page)
        self.assertIn("name.endsWith('.iso')", github)
        self.assertIn('releases/latest/download/fliperos-', site)

    def test_site_has_a_wiki_button_in_the_hero_and_above_github_in_the_sidebar(self):
        # A wiki do projeto: na primeira pagina, ao lado de "Explore features", e na barra lateral (e no menu do
        # celular), logo acima do botao do GitHub.
        src = ROOT / 'website/src'
        site = (src / 'lib/site.ts').read_text()
        self.assertIn('docs: `${REPO_URL}/wiki`', site)
        hero = (src / 'sections/Hero.tsx').read_text()
        self.assertLess(hero.index('{h.ctaFeatures}'), hero.index('href={LINKS.docs}'))
        self.assertIn('{h.ctaWiki}', hero)
        header = (src / 'components/Header.tsx').read_text()
        side = header.split('<aside')[1].split('</aside>')[0]
        self.assertLess(side.index('href={LINKS.docs}'), side.index('href={readmeUrl(locale)}'))
        self.assertLess(side.index('{t.nav.wiki}'), side.index('{t.nav.viewOnGithub}'))
        mobile = header.split('id="mobile-nav"')[1]
        self.assertLess(mobile.index('href={LINKS.docs}'), mobile.index('href={readmeUrl(locale)}'))
        for lang in ('en-US', 'pt-BR'):
            text = (src / 'i18n' / (lang + '.ts')).read_text(encoding='utf-8')
            self.assertRegex(text, r"\n    wiki: '[^']+',\n    viewOnGithub:")
            self.assertRegex(text, r"\n    ctaWiki: '[^']+',")

    def test_site_support_section_has_no_secrets_and_no_mailto(self):
        src = ROOT / 'website/src'
        for path in src.rglob('*.ts*'):
            text = path.read_text(encoding='utf-8')
            # Chave secreta (sk_) ou restrita (rk_) do Stripe nunca vai para o site.
            self.assertNotRegex(text, r'\b(sk|rk)_(live|test)_', path.name)
            self.assertNotIn('mailto:', text, path.name)
        support = (src / 'sections/Support.tsx').read_text(encoding='utf-8')
        self.assertIn('https://donate.stripe.com/', (src / 'lib/site.ts').read_text(encoding='utf-8'))
        self.assertIn("locale.startsWith('pt')", support)
        self.assertIn('<Support />', (src / 'app/[lang]/page.tsx').read_text(encoding='utf-8'))

    def test_publish_writes_wiki_links(self):
        # Aqui os links levam o .md (funcionam no repositorio); na wiki, nao.
        with tempfile.TemporaryDirectory() as tmp:
            subprocess.run(['bash', str(ROOT / 'tools/wiki-publish.sh'), '--to', tmp], check=True,
                           capture_output=True, timeout=60)
            out = Path(tmp)
            self.assertEqual({p.name for p in out.iterdir()}, {p.name for p in self.WIKI.glob('*.md')})
            home = (out / 'Home.md').read_text()
            self.assertIn('[Emulators](Emulators)', home)
            self.assertIn('[Fightcade 2](Fightcade-2)', (out / '_Sidebar.md').read_text())
            for page in out.iterdir():
                self.assertNotRegex(page.read_text(), r'\]\(%s\.md' % self.PAGE, page.name)
            # Os enderecos de fora ficam como estao.
            self.assertIn('(https://github.com/charmbracelet/gum)', home)
            self.assertIn('tree/main/docs/wiki)', home)

    def test_wikipedia_draft_is_wikitext_and_cites_existing_pages(self):
        text = (ROOT / 'docs/wikipedia/FliperOS.wiki').read_text()
        # Wikitexto, nao Markdown (o link "[x](y)"), e com tudo o que abre fechado.
        self.assertNotIn('](', text)
        for opened, closed in (('{{', '}}'), ('[[', ']]')):
            self.assertEqual(text.count(opened), text.count(closed), opened)
        self.assertEqual(len(re.findall(r'<ref[ >]', text)), text.count('</ref>') + len(re.findall(r'<ref [^>]*/>', text)))
        # Cada nome de referencia e definido uma vez so.
        named = re.findall(r'<ref name="([^"]+)">', text)
        self.assertEqual(len(named), len(set(named)))
        for used in re.findall(r'<ref name="([^"]+)" />', text):
            self.assertIn(used, named)
        # As referencias sao as paginas daqui: uma renomeada quebraria o artigo.
        cited = re.findall(r'fliperOS/blob/main/([^ |}]+)', text)
        self.assertGreaterEqual(len(cited), 10)
        for path in cited:
            self.assertTrue((ROOT / path).is_file(), path)

    def test_html_reference_is_built_from_both(self):
        script = (ROOT / 'tools/render-docs.py').read_text()
        self.assertIn("root / 'README.md'", script)
        self.assertIn("'_Sidebar.md'", script)
        html = (ROOT / 'fliperos-doc.html').read_text()
        for title in ('Fightcade 2', 'Installed system', 'Build and tests'):
            self.assertIn('>%s</h1>' % title, html)
        # Os links entre paginas viram links dentro do arquivo.
        self.assertIn('href="#Fightcade-2"', html)
        for page in self.pages():
            self.assertNotIn('href="%s.md' % page, html)
            self.assertNotIn('href="%s/%s"' % (self.URL, page), html)


class StyleguideTests(unittest.TestCase):
    """tools/styleguide.py: a pagina do styleguide so para quem desenvolve
    (docs/styleguide/index.html), lida do CSS do painel, do tema do Setup e dos icones."""

    @classmethod
    def setUpClass(cls):
        cls.sg = SourceFileLoader('fliperos_styleguide', str(ROOT / 'tools/styleguide.py')).load_module()

    def test_the_page_shows_every_token_colour_icon_and_the_real_stylesheets(self):
        page = self.sg.build()
        css = (ROOT / 'config/web/style.css').read_text()
        for name, value in self.sg.root_tokens(css):
            self.assertIn(name, page)
            if value.strip().startswith('#'):
                self.assertIn(value.strip(), page)
        theme = self.sg.theme_colors((ROOT / 'fliperos-setup/gui/theme.py').read_text())
        for name in ('PINK', 'PURPLE', 'CYAN', 'GREEN', 'BG_DEEP', 'COMMENT'):
            self.assertIn(name, theme)
            self.assertIn('>%s<' % name, page)
        sprite = (ROOT / 'config/web/icons.svg').read_text()
        for icon in re.findall(r'<symbol id="((?:px|g)-[\w-]+)"', sprite):
            self.assertIn('icons.svg#%s"' % icon, page)
        # Os CSS que ele mostra sao os do painel, por caminho relativo (o arquivo abre no navegador).
        for sheet in re.findall(r'href="\.\./\.\./(config/web/[\w.]+)"', page):
            self.assertTrue((ROOT / sheet).is_file(), sheet)
        for title in ('Buttons', 'Setting rows', 'Meter', 'Audit', 'Rules', 'Two languages', 'Every menu item has an icon'):
            self.assertIn(title, page)
        # Os componentes de amostra usam classes que existem nos .css.
        sheets = ''.join((ROOT / 'config/web' / f).read_text() for f in self.sg.CSS_FILES if (ROOT / 'config/web' / f).is_file())
        for cls in ('btn', 'tag', 'st-chip', 'st-meter', 'srow', 'slist', 'st-card', 'toast', 'sel', 'fld'):
            self.assertIn('.' + cls, sheets, cls)

    def test_the_audit_finds_what_is_not_the_standard(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root / 'config/web').mkdir(parents=True)
            (root / 'fliperos-setup/gui').mkdir(parents=True)
            (root / 'config/web/style.css').write_text(
                ':root {\n  --a: #112233;\n  --b: #112233;\n  --pink: #ff79c6;\n  --r: 16px;\n}\n'
                '.x { color: #abcdef; font-size: 13px; border-radius: 7px; }\n'
                '.y { color: var(--a); font-size: 17px; border-radius: 8px; }\n')
            (root / 'config/web/icons.svg').write_text('<svg><symbol id="px-games"></symbol><symbol id="g-play"></symbol></svg>')
            (root / 'fliperos-setup/gui/theme.py').write_text('PINK = (0xFF, 0x79, 0xC7)\nBG_DEEP = (0x19, 0x1A, 0x21)\n')
            page = self.sg.build(str(root))
            self.assertIn('<code>--a</code> and <code>--b</code> are both <code>#112233</code>', page)
            self.assertIn('<td>style.css</td><td>1</td><td>1</td><td>17</td><td>7</td>', page)     # cor solta, token, letra e raio fora
            self.assertIn('<code>--pink</code> #ff79c6 &ne; <code>PINK</code> #ff79c7', page)         # a mesma cor, valores diferentes
            self.assertIn('1 pixel icons, 1 glyphs', page)

    def test_the_page_is_in_the_repo_and_linked_from_the_wiki(self):
        page = ROOT / 'docs/styleguide/index.html'
        self.assertTrue(page.is_file())
        self.assertIn('FliperOS style guide', page.read_text())
        dev = (ROOT / 'docs/wiki/Development.md').read_text()
        self.assertIn('tools/styleguide.py', dev)
        self.assertIn('docs/styleguide/index.html', dev)


class ReleaseTests(unittest.TestCase):
    """Toda ISO nova vai para os Releases do GitHub com o changelog da versao,
    no formato dos releases do GroovyArcade (tools/release-publish.sh)."""

    def test_audit_expects_the_boot_menu_timer_of_the_template(self):
        # A 0.14 baixou o timer do menu da ISO de 30 para 10 s e a auditoria
        # seguiu esperando 30: o build inteiro nao foi publicado.
        audit = (ROOT / 'tools/verify-iso.sh').read_text()
        self.assertNotIn("timeout: 30$", audit)
        self.assertIn("sed -n 's/^timeout: \\([0-9]*\\)$/\\1/p' \"$src/config/limine.conf\"", audit)
        self.assertRegex((ROOT / 'config/limine.conf').read_text(), r'(?m)^timeout: \d+$')
    SCRIPT = ROOT / 'tools/release-publish.sh'
    VERSION = re.search(r'^FLIPEROS_VERSION="(.*)"$', MKISO, re.M).group(1)

    def notes(self, version):
        return subprocess.run(['bash', str(self.SCRIPT), '--notes', version], capture_output=True, text=True, timeout=60)

    def test_changelog_has_the_version_of_the_build(self):
        # Subir o FLIPEROS_VERSION sem escrever o que mudou quebra aqui.
        changelog = (ROOT / 'CHANGELOG.md').read_text()
        versions = re.findall(r'^## (\S+)$', changelog, re.M)
        self.assertEqual(versions[0], self.VERSION)
        self.assertEqual(len(versions), len(set(versions)))
        self.assertEqual(len(versions), len(re.findall(r'^## ', changelog, re.M)))

    def test_release_text_is_the_section_of_the_version(self):
        result = self.notes(self.VERSION)
        self.assertEqual(result.returncode, 0, result.stderr)
        # As secoes do GroovyArcade: OS, Packages, gasetup, gatools.
        for heading in ('**System changes:**', '**Package changes:**',
                        '**fliperos-setup changes:**', '**Tool changes:**'):
            self.assertIn(heading + '\n\n- ', result.stdout)
        self.assertNotIn('\n## ', '\n' + result.stdout)
        self.assertNotIn('# Changelog', result.stdout)
        self.assertNotEqual(result.stdout[0], '\n')

    def test_version_without_section_is_not_published(self):
        result = self.notes('99.9')
        self.assertNotEqual(result.returncode, 0)
        self.assertIn('CHANGELOG.md', result.stderr)
        self.assertEqual(result.stdout, '')

    def test_only_the_audited_iso_without_wifi_goes_public(self):
        script = self.SCRIPT.read_text()
        audit = script.index('tools/verify-iso.sh" "$iso"')
        wifi = script.index('NetworkManager/system-connections/')
        self.assertLess(audit, wifi)
        self.assertLess(wifi, script.index('gh release create'))
        # O verify-iso extrai onde o release-publish vai ler.
        self.assertIn('FLIPEROS_VERIFY_DIR=$audit', script)
        self.assertIn('work=${FLIPEROS_VERIFY_DIR:-', (ROOT / 'tools/verify-iso.sh').read_text())
        # A senha do --wifi-psk vai em texto para a imagem.
        self.assertIn('/etc/NetworkManager/system-connections', MKISO)

    def test_iso_over_the_github_limit_goes_in_parts(self):
        script = self.SCRIPT.read_text()
        self.assertIn('limit=2147483648 part=1900M', script)
        self.assertIn('split -b "$part" -a 3 --numeric-suffixes=1', script)
        self.assertIn('copy /b', script)
        # O release e do commit de que a ISO saiu, e nao troca um que ja existe sem pedir.
        self.assertIn('--target "$commit"', script)
        self.assertRegex(script, r'\(\(replace\)\) \|\| die')

    def test_release_tools_are_in_the_vmtest_image(self):
        dockerfile = (ROOT / 'tools/Dockerfile.vmtest').read_text()
        for package in ('gh', 'git', 'ca-certificates', 'xorriso', 'squashfs-tools'):
            self.assertRegex(dockerfile, r'\s%s\s' % re.escape(package))


class TelegramTests(unittest.TestCase):
    """Cada release e postado no grupo do Telegram, com fotos e a explicacao de
    como funcionam as novidades (tools/telegram-post.py, docs/telegram)."""
    SCRIPT = ROOT / 'tools/telegram-post.py'
    GROUP = 'https://t.me/fliperos15khz'
    VERSION = ReleaseTests.VERSION

    @classmethod
    def setUpClass(cls):
        loader = SourceFileLoader('telegram_post', str(cls.SCRIPT))
        spec = importlib.util.spec_from_loader('telegram_post', loader)
        cls.post = importlib.util.module_from_spec(spec)
        loader.exec_module(cls.post)

    def test_every_version_has_its_text_for_the_group(self):
        # Subir o FLIPEROS_VERSION sem escrever o que contar ao grupo quebra aqui
        # (e o workflow Release recusa a tag).
        text = (ROOT / ('docs/telegram/%s.md' % self.VERSION)).read_text(encoding='utf-8')
        messages = self.post.parse(text)
        self.assertGreaterEqual(len(messages), 3)
        self.assertTrue(any(m['images'] for m in messages), 'photos are the point of the post')
        self.assertIn('/releases/tag/%s' % self.VERSION, text)
        # Em portugues e em ingles, cada mensagem (o parse recusa sem os dois).
        self.assertTrue(all(self.post.EN in m['text'] and self.post.PT in m['text'] for m in messages if m['text']))

    def test_the_text_of_the_version_passes_the_dry_run(self):
        try:
            import PIL  # noqa: F401
        except ImportError:
            self.skipTest('Pillow is not installed')
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--dry-run', self.VERSION],
                                capture_output=True, text=True, timeout=120)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn('messages ok', result.stdout)

    def test_version_without_text_is_refused_and_nothing_goes_out(self):
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--dry-run', '99.9'],
                                capture_output=True, text=True, timeout=60)
        self.assertEqual(result.returncode, 1)
        self.assertIn('CHANGELOG.md has no "## 99.9"', result.stderr)

    def test_without_a_text_of_its_own_the_group_gets_the_changelog_section(self):
        for version in self.post.changelog_versions():
            messages = self.post.messages_for(version, True)
            self.assertTrue(messages, version)
            self.assertIn('**FliperOS', messages[0]['text'].replace('<b>', '**').replace('</b>', '**'))
            self.assertIn('/releases/tag/%s' % version, messages[0]['text'])
            self.assertTrue(self.post.bilingual(messages[0]['text']), version)
            for message in messages:
                self.assertLessEqual(self.post.visible(message['text']), self.post.TEXT_MAX, version)
                self.assertEqual(message['images'], [])
        # O texto com fotos vale no lugar do changelog, se existir.
        self.assertTrue(self.post.messages_for(self.VERSION, False)[1]['images'] or
                        any(m['images'] for m in self.post.messages_for(self.VERSION, False)))

    def test_backfill_posts_the_oldest_version_first(self):
        versions = self.post.changelog_versions()
        self.assertEqual(versions[0], self.VERSION)
        self.assertEqual(versions[-1], '0.7')
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--backfill', '--dry-run'],
                                capture_output=True, text=True, timeout=300)
        try:
            import PIL  # noqa: F401
        except ImportError:
            self.skipTest('Pillow is not installed')
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertRegex(result.stdout, r'\d+ messages ok')

    def test_every_published_update_has_a_text_for_the_group(self):
        # O push do updates/index posta o update (workflow Telegram): cada um
        # tem de caber, com o titulo do index e o changelog dele.
        numbers = [int(line.split('\t')[0]) for line in (ROOT / 'updates/index').read_text().splitlines()
                   if line[:1].isdigit()]
        self.assertTrue(numbers)
        for number in numbers[-5:]:
            messages = self.post.update_messages(number)
            self.assertIn('Atualização %d do FliperOS' % number, messages[0]['text'])
            # Em portugues e em ingles: juntas, ou uma mensagem de cada.
            self.assertIn('FliperOS update %d:' % number, messages[-1]['text'])
            self.assertTrue(self.post.bilingual('\n'.join(m['text'] for m in messages)), number)
            for message in messages:
                self.assertLessEqual(self.post.visible(message['text']), self.post.TEXT_MAX, number)
        with self.assertRaises(self.post.PostError):
            self.post.update_messages(99999)
        # O 34 nao cabe numa mensagem com os dois idiomas: vai uma de cada.
        self.assertEqual(len(self.post.update_messages(34)), 2)
        self.assertEqual(len(self.post.update_messages(37)), 1)
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--dry-run', '--update', str(numbers[-1])],
                                capture_output=True, text=True, timeout=60)
        self.assertEqual(result.returncode, 0, result.stderr)

    def test_the_push_of_the_update_index_posts_the_new_updates(self):
        workflow = (ROOT / '.github/workflows/telegram.yml').read_text()
        self.assertIn('paths: [updates/index]', workflow)
        self.assertIn('--update "$n"', workflow)
        # Chamado pelo Release (o evento e o push da tag), posta a versao.
        self.assertIn("if: inputs.version == ''", workflow)
        self.assertIn("if: inputs.version != ''", workflow)
        script = (ROOT / 'tools/make-update.sh').read_text()
        self.assertIn('telegram-post.py --dry-run --update', script)
        # Sem o Telegram: o commit do index leva [skip ci], que o GitHub respeita.
        self.assertIn('--no-telegram) telegram=no', script)
        self.assertIn('[skip ci]', script)

    def test_markdown_becomes_telegram_html(self):
        html = self.post.markup('**Bold** and `a<b` & [site](https://x.org/?a=1&b=2)\n- item\n- `**no**`')
        self.assertEqual(html, '<b>Bold</b> and <code>a&lt;b</code> &amp; '
                               '<a href="https://x.org/?a=1&amp;b=2">site</a>\n• item\n• <code>**no**</code>')

    def test_messages_split_on_a_line_with_only_dashes(self):
        messages = self.post.parse('🇧🇷 um\n🇺🇸 one\n\n---\n\n![](README.md)\n🇧🇷 dois\n\n🇺🇸 two\n\n---\n\n')
        self.assertEqual([m['text'] for m in messages], ['🇧🇷 um\n🇺🇸 one', '🇧🇷 dois\n\n🇺🇸 two'])
        self.assertEqual([len(m['images']) for m in messages], [0, 1])

    def test_a_message_in_one_language_is_refused(self):
        for text in ('só português', '🇧🇷 só português', '🇺🇸 English only', 'a 🇧🇷 mid-line\n🇺🇸 one'):
            with self.assertRaises(self.post.PostError, msg=text):
                self.post.parse(text)
        # Uma mensagem so de imagem nao tem texto para traduzir.
