class TelegramCustomGameTests(unittest.TestCase):
    """O robo dos pacotes de jogo custom: alguem manda um GAME.fliperos-customgame.zip ao grupo, e ele posta no
    topico Files um album (imagem, logotipo, video), os dados em portugues e ingles, a descricao e o arquivo
    (tools/telegram-customgame.py, o Worker e o workflow Telegram custom game)."""
    SCRIPT = ROOT / 'tools/telegram-customgame.py'

    @classmethod
    def setUpClass(cls):
        loader = SourceFileLoader('telegram_customgame', str(cls.SCRIPT))
        spec = importlib.util.spec_from_loader('telegram_customgame', loader)
        cls.bot = importlib.util.module_from_spec(spec)
        loader.exec_module(cls.bot)
        cls.tool = cls.bot.load_tool()

    @staticmethod
    def png(width=8, height=6):
        import zlib
        raw = b''.join(b'\0' + bytes([40, 120, 220]) * width for _ in range(height))

        def chunk(kind, data):
            return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xFFFFFFFF)

        return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 2, 0, 0, 0))
                + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b''))

    def make_zip(self, path, name='Street Fighter 4', game=b'MZ' + b'x' * 2000, cfg=None, art=True):
        cfg = cfg if cfg is not None else ('name=%s\nplatform=windows\nexe=SF4.exe\nmode=480i\ncategory=Fighter / Versus\n'
                                           'controls=joy8\nbuttons=6\nplayers=2\nyear=2008\ndeveloper=Capcom\n' % name)
        with zipfile.ZipFile(path, 'w', zipfile.ZIP_STORED) as zf:
            zf.writestr(name + '.cfg', cfg)
            if art:
                zf.writestr(name + '.png', self.png())
                zf.writestr(name + '.logo.png', self.png(16, 4))
                zf.writestr(name + '.mp4', b'\0\0\0\x18ftypmp42' + b'v' * 500)
                zf.writestr(name + '.txt', 'Street fighters from around the world meet again.\nPick a fighter.\n')
                zf.writestr(name + '.key', 'p1_b1=Z\np1_start=ENTER\n')
                zf.writestr(name + '.ppdb', 'export PW_X=1\n')
            zf.writestr('%s/SF4.exe' % name, game)
        return Path(path)

    class Fake:
        """O Telegram de mentira: guarda cada chamada."""

        def __init__(self, data=b''):
            self.data, self.calls = data, []

        def download(self, file_id):
            self.calls.append(('download', file_id))
            return self.data

        def message(self, chat, text, thread=None, reply=None):
            self.calls.append(('message', chat, text, thread, reply))

        def album(self, chat, items, caption, thread=None, reply=None):
            self.calls.append(('album', chat, items, caption, thread, reply))

        def document(self, chat, file_id, caption, thread=None):
            self.calls.append(('document', chat, file_id, caption, thread))

    def payload(self, **over):
        base = {'chat_id': -1001234, 'chat_username': 'fliperos15khz', 'message_id': 55, 'thread_id': 0, 'file_id': 'FILE1',
                'file_name': 'Street Fighter 4.fliperos-customgame.zip', 'file_size': 4000, 'from': 'Ana Souza', 'username': 'ana'}
        return dict(base, **over)

    def test_a_package_becomes_an_album_a_bilingual_post_and_the_file_in_the_files_topic(self):
        with tempfile.TemporaryDirectory() as tmp:
            zip_ = self.make_zip(Path(tmp) / 'sf4.zip')
            tg = self.Fake(zip_.read_bytes())
            out = []
            result = self.bot.post_package(tg, self.payload(), {'TELEGRAM_FILES_TOPIC': '578'}, self.tool, out=out.append)
        self.assertEqual(result, 'posted: Street Fighter 4')
        kinds = [c[0] for c in tg.calls]
        self.assertEqual(kinds, ['download', 'album', 'message', 'document', 'message'])
        album, details, document, notice = tg.calls[1], tg.calls[2], tg.calls[3], tg.calls[4]
        # O album: a imagem, o logotipo e o video, no topico Files, com o nome e uma linha por idioma.
        self.assertEqual([i[0] for i in album[2]], ['photo', 'photo', 'video'])
        self.assertEqual(album[4:], (578, None))
        for part in ('Street Fighter 4', '\U0001F1E7\U0001F1F7', '\U0001F1FA\U0001F1F8', 'Ana Souza (@ana)', 'Fighter / Versus', 'Capcom'):
            self.assertIn(part, album[3])
        self.assertLessEqual(len(album[3]), 1024)
        # Os dados: todos, nos dois idiomas, mais a descricao.
        text = details[2]
        self.assertEqual(details[3:], (578, None))
        self.assertLess(text.index('\U0001F1E7\U0001F1F7'), text.index('\U0001F1FA\U0001F1F8'))
        for part in ('Modo de vídeo: 480i', 'Video mode: 480i', 'Jogadores: 2', 'Players: 2', 'Botões: 6', 'Buttons: 6', 'joy8',
                     '2008', 'Capcom', 'sim, 2 teclas', 'yes, 2 keys', 'PortProton (.ppdb): sim', 'PortProton (.ppdb): yes',
                     'Street fighters from around the world meet again.', 'Pick a fighter.', 'Descrição / Description',
                     'painel web > Jogos custom', 'web panel > Custom games'):
            self.assertIn(part, text)
        self.assertLessEqual(len(text), 4096)
        # O arquivo vai por file_id para o topico Files; onde o zip foi mandado, um aviso curto e a resposta a ele.
        self.assertEqual(document[1:3], ('-1001234', 'FILE1'))
        self.assertEqual(document[4], 578)
        self.assertIn('Street Fighter 4.fliperos-customgame.zip', document[3])
        self.assertEqual(notice[3:], (None, 55))
        self.assertIn('Os dados e o arquivo estão no tópico Arquivos', notice[2])
        self.assertIn('The details and the file are in the Files topic', notice[2])

    def test_a_zip_sent_in_the_files_topic_gets_the_details_as_a_reply_without_repeating_the_file(self):
        with tempfile.TemporaryDirectory() as tmp:
            tg = self.Fake(self.make_zip(Path(tmp) / 'sf4.zip').read_bytes())
            self.bot.post_package(tg, self.payload(thread_id=578), {}, self.tool, out=lambda *_: None)
        self.assertEqual([c[0] for c in tg.calls], ['download', 'album', 'message'])
        self.assertEqual(tg.calls[1][4:], (578, 55))        # no topico Files, respondendo ao zip
        self.assertEqual(tg.calls[2][3:], (578, 55))
        # Sem arte: so o texto, com a legenda e os dados juntos.
        with tempfile.TemporaryDirectory() as tmp:
            tg = self.Fake(self.make_zip(Path(tmp) / 'sf4.zip', art=False).read_bytes())
            self.bot.post_package(tg, self.payload(thread_id=578), {}, self.tool, out=lambda *_: None)
        self.assertEqual([c[0] for c in tg.calls], ['download', 'message'])
        self.assertIn('Modo de vídeo: 480i', tg.calls[1][2])
        self.assertIn('Street Fighter 4', tg.calls[1][2])

    def test_a_file_that_is_not_a_good_package_is_refused_with_its_problems_where_it_was_sent(self):
        with tempfile.TemporaryDirectory() as tmp:
            bad = Path(tmp) / 'bad.zip'
            with zipfile.ZipFile(bad, 'w') as zf:
                zf.writestr('Street Fighter 4/SF4.exe', b'MZ')
            tg = self.Fake(bad.read_bytes())
            result = self.bot.post_package(tg, self.payload(thread_id=12), {}, self.tool, out=lambda *_: None)
        self.assertTrue(result.startswith('refused'))
        self.assertEqual([c[0] for c in tg.calls], ['download', 'message'])
        self.assertEqual(tg.calls[1][3:], (12, 55))
        self.assertIn('Street Fighter 4.cfg is missing', tg.calls[1][2])
        self.assertIn('\U0001F1E7\U0001F1F7', tg.calls[1][2])
        # Outro nome, ou outro grupo: o robo nem olha.
        for payload, env in ((self.payload(file_name='notes.zip'), {}), (self.payload(), {'TELEGRAM_CHAT_ID': '-100999'})):
            tg = self.Fake()
            self.assertTrue(self.bot.post_package(tg, payload, env, self.tool).startswith('skipped'))
            self.assertEqual(tg.calls, [])

    def test_a_big_package_is_read_by_pieces_without_downloading_the_game(self):
        # Acima de 20 MB a Bot API nao entrega o arquivo: pelo MTProto o robo le o fim do zip (a lista de arquivos) e
        # os arquivos pequenos do pacote, nunca a pasta do jogo (aqui 12 MB que nao se comprimem).
        with tempfile.TemporaryDirectory() as tmp:
            data = self.make_zip(Path(tmp) / 'big.zip', game=os.urandom(12 << 20)).read_bytes()
        asked = []

        class Source:
            size = len(data)

            def fetch(self, offset, length):
                asked.append((offset, length))
                return data[offset:offset + length]

            def close(self):
                self.closed = True

        source = Source()
        tg = self.Fake()
        out = []
        env = {}
        result = self.bot.post_package(tg, self.payload(file_size=600 << 20), env, self.tool,
                                       mtproto=lambda e, chat, message, *rest: (asked.append(('open', chat, message)), source)[1],
                                       out=out.append)
        self.assertEqual(result, 'posted: Street Fighter 4')
        self.assertEqual(asked[0], ('open', '@fliperos15khz', 55))
        fetched = sum(length for offset, length in asked[1:])
        self.assertLess(fetched, len(data) // 4, 'the game folder must not be downloaded')
        self.assertTrue(all(offset % self.bot.BLOCK == 0 for offset, _ in asked[1:]))
        self.assertTrue(source.closed)
        self.assertEqual([c[0] for c in tg.calls], ['album', 'message', 'document', 'message'])    # nada baixado pela Bot API
        self.assertIn('Street Fighter 4', tg.calls[0][3])
        self.assertIn('%d of %d bytes fetched' % (fetched, len(data)), out[0])
        # Sem as chaves do MTProto: o arquivo vai assim mesmo, com o aviso de que os detalhes nao deu para ler.
        tg = self.Fake()
        result = self.bot.post_package(tg, self.payload(file_size=600 << 20), {}, self.tool, mtproto=lambda *a: None, out=lambda *_: None)
        self.assertEqual(result, 'posted: Street Fighter 4.fliperos-customgame.zip (details unreadable)')
        self.assertEqual([c[0] for c in tg.calls], ['message', 'document', 'message'])
        self.assertIn('Não deu para ler os detalhes', tg.calls[0][2])
        self.assertIn('could not be read', tg.calls[0][2])
        self.assertEqual(tg.calls[1][2], 'FILE1')
        # Um erro do MTProto (rede, chaves) tambem nao perde o arquivo.

        def broken(env, chat, message, *rest):
            raise RuntimeError('bad api hash')
        tg = self.Fake()
        self.bot.post_package(tg, self.payload(file_size=600 << 20), {}, self.tool, mtproto=broken, out=lambda *_: None)
        self.assertEqual([c[0] for c in tg.calls], ['message', 'document', 'message'])

    def test_the_range_file_reads_like_the_zip_it_stands_for(self):
        data = os.urandom((3 << 20) + 123)
        fetches = []
        ranged = self.bot.RangeFile(len(data), lambda offset, length: (fetches.append(offset), data[offset:offset + length])[1])
        ranged.seek(self.bot.BLOCK - 10)
        self.assertEqual(ranged.read(100), data[self.bot.BLOCK - 10:self.bot.BLOCK + 90])      # atravessa dois pedacos
        ranged.seek(-50, 2)
        self.assertEqual(ranged.read(), data[-50:])
        ranged.seek(0)
        self.assertEqual(ranged.read(10), data[:10])
        self.assertEqual(ranged.tell(), 10)
        self.assertEqual(ranged.read(1 << 30), data[10:])                                         # o resto, sem passar do fim
        self.assertEqual(ranged.read(5), b'')
        # Cada pedaco vem uma vez so (fica guardado).
        self.assertEqual(sorted(fetches), sorted(set(fetches)))

    def test_the_telethon_source_works_with_the_way_telethon_really_behaves(self):
        # O Telethon de verdade: start() e disconnect() rodam o laco sozinhos quando ele nao esta rodando e devolvem o
        # resultado (nao uma corrotina; o primeiro teste real falhou aqui com "An asyncio.Future, a coroutine or an
        # awaitable is required"); get_messages e uma corrotina e iter_download um iterador assincrono.
        import asyncio
        import types
        with tempfile.TemporaryDirectory() as tmp:
            data = self.make_zip(Path(tmp) / 'big.zip', game=os.urandom(3 << 20)).read_bytes()
        seen = {}

        class Doc:
            size = len(data)

        class Message:
            document = Doc()

        class Client:
            def __init__(self, session, api_id, api_hash, loop=None):
                self.loop = loop
                seen.update(api_id=api_id, api_hash=api_hash)

            def start(self, bot_token=None):
                self.loop.run_until_complete(asyncio.sleep(0))
                seen['token'] = bot_token
                return self                                  # o cliente, nao uma corrotina

            async def get_messages(self, chat, ids=None):
                seen.update(chat=chat, ids=ids)
                return None if seen.get('hide_message') else Message()

            def iter_download(self, document, offset=0, request_size=0, limit=None, file_size=None):
                seen['file_size'] = file_size
                async def chunks():
                    yield data[offset:offset + request_size]
                seen.setdefault('offsets', []).append(offset)
                return chunks()

            def disconnect(self):
                seen['closed'] = True                        # tambem sincrono

        telethon = types.ModuleType('telethon')
        telethon.TelegramClient = Client
        sessions = types.ModuleType('telethon.sessions')
        sessions.StringSession = type('StringSession', (), {})
        utils = types.ModuleType('telethon.utils')

        def resolve_bot_file_id(file_id):
            seen['resolved'] = file_id
            return Doc()                                     # como o Telethon: um Document com size=0

        utils.resolve_bot_file_id = resolve_bot_file_id
        Doc.size = len(data)
        telethon.utils = utils
        saved = {k: sys.modules.get(k) for k in ('telethon', 'telethon.sessions', 'telethon.utils')}
        sys.modules.update({'telethon': telethon, 'telethon.sessions': sessions, 'telethon.utils': utils})
        env = {'TELEGRAM_BOT_TOKEN': '1:tok', 'TELEGRAM_API_ID': '123', 'TELEGRAM_API_HASH': 'abc'}
        small = self.bot.BOT_DOWNLOAD_MAX
        try:
            tg = self.Fake()
            result = self.bot.post_package(tg, self.payload(file_size=600 << 20), env, self.tool, out=lambda *_: None)
            first = dict(seen)
            # Um bot nem sempre acha a mensagem por id (o teste real): o arquivo vem do file_id, e o tamanho, do pedido.
            seen.clear()
            seen['hide_message'] = True
            self.bot.BOT_DOWNLOAD_MAX = 1 << 20              # o zip de mentira tem 3 MB: grande para o robo
            tg2 = self.Fake()
            result2 = self.bot.post_package(tg2, self.payload(file_size=len(data)), env, self.tool, out=lambda *_: None)
        finally:
            self.bot.BOT_DOWNLOAD_MAX = small
            for key, module in saved.items():
                if module is None:
                    sys.modules.pop(key, None)
                else:
                    sys.modules[key] = module
        self.assertEqual(result, 'posted: Street Fighter 4')
        self.assertEqual((first['token'], first['api_id'], first['api_hash'], first['chat'], first['ids']), ('1:tok', 123, 'abc', '@fliperos15khz', 55))
        self.assertTrue(first['closed'])
        self.assertNotIn('resolved', first)                  # a mensagem bastou
        self.assertTrue(all(o % self.bot.BLOCK == 0 for o in first['offsets']))
        self.assertLess(len(first['offsets']) * self.bot.BLOCK, len(data))          # nao leu o zip inteiro
        self.assertEqual([c[0] for c in tg.calls], ['album', 'message', 'document', 'message'])
        self.assertEqual(result2, 'posted: Street Fighter 4')
        self.assertEqual(seen['resolved'], 'FILE1')
        self.assertEqual(seen['file_size'], len(data))
        self.assertEqual([c[0] for c in tg2.calls], ['album', 'message', 'document', 'message'])

    def test_no_post_reads_the_package_but_sends_nothing_to_the_group(self):
        posted = []
        fake = self.bot.PrintOnly('1:tok')
        fake.call = lambda *a, **k: posted.append(a)          # qualquer chamada de rede apareceria aqui
        import contextlib
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            fake.message('-100', 'dados', 578, 55)
            fake.album('-100', [('photo', 'snap.png', b'x' * 10)], 'legenda', 578)
            fake.document('-100', 'BQACAgEAAyEFAAMBBVUx', 'arquivo', 578)
        self.assertEqual(posted, [])
        shown = buffer.getvalue()
        for part in ('[mensagem] topico=578 resposta=55', 'dados', '[album]', 'photo snap.png (10 bytes)', '[arquivo] topico=578', 'BQACAgEAAyEF...'):
            self.assertIn(part, shown)
        workflow = (ROOT / '.github/workflows/telegram-customgame.yml').read_text(encoding='utf-8')
        self.assertIn('no_post:', workflow)
        self.assertIn('[[ $NO_POST == true ]] && args+=(--no-post)', workflow)

    def test_the_preview_prints_the_post_and_saves_the_art(self):
        with tempfile.TemporaryDirectory() as tmp:
            zip_ = self.make_zip(Path(tmp) / 'Street Fighter 4.fliperos-customgame.zip')
            result = subprocess.run([sys.executable, str(self.SCRIPT), '--zip', str(zip_), '--out', str(Path(tmp) / 'art')],
                                    capture_output=True, text=True, timeout=60)
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertIn('Modo de vídeo: 480i', result.stdout)
            self.assertIn('Video mode: 480i', result.stdout)
            self.assertEqual(sorted(p.name for p in (Path(tmp) / 'art').iterdir()), ['logo.png', 'preview.mp4', 'snap.png'])

    def test_the_worker_hands_the_zip_to_github_and_the_workflow_posts_it(self):
        worker = (ROOT / 'tools/telegram-translate/worker.js').read_text(encoding='utf-8')
        self.assertIn("/\\.fliperos-customgame\\.zip$/i", worker)
        self.assertIn("event_type: 'customgame-zip'", worker)
        self.assertIn("'https://api.github.com/repos/' + env.GITHUB_REPO + '/dispatches'", worker)
        self.assertIn('if (await dispatchPackage(env, msg)) return;', worker)
        for field in ('chat_id', 'chat_username', 'message_id', 'thread_id', 'file_id', 'file_name', 'file_size', 'from', 'username'):
            self.assertIn(field, worker[worker.index('client_payload'):worker.index('if (!r.ok)')])
        # O repository_dispatch aceita ate 10 campos no client_payload.
        self.assertLessEqual(len(re.findall(r'^\s+(\w+)(?::|,\n)', worker[worker.index('client_payload'):worker.index('if (!r.ok)')], re.M)), 10)
        self.assertIn('GITHUB_REPO = "juniorterin/fliperOS"', (ROOT / 'tools/telegram-translate/wrangler.toml').read_text())
        workflow = (ROOT / '.github/workflows/telegram-customgame.yml').read_text(encoding='utf-8')
        self.assertIn('types: [customgame-zip]', workflow)
        self.assertIn('toJson(github.event.client_payload)', workflow)
        # O pedido vai por variavel de ambiente, nunca interpolado no script.
        run = workflow[workflow.index('run: |\n          args='):]
        self.assertNotIn('${{', run)
        self.assertIn('python3 tools/telegram-customgame.py "${args[@]}"', run)
        for secret in ('TELEGRAM_BOT_TOKEN', 'TELEGRAM_API_ID', 'TELEGRAM_API_HASH'):
            self.assertIn('%s: ${{ secrets.%s }}' % (secret, secret), workflow)
        self.assertIn('group: telegram-customgame', workflow)
        # O Files e o topico 578 (o mesmo que o tradutor deixa sem traducao).
        self.assertEqual(self.bot.FILES_TOPIC, 578)
        self.assertIn('SKIP_TOPICS = "578"', (ROOT / 'tools/telegram-translate/wrangler.toml').read_text())
        # Sem token ou em dry run, o pedido so e conferido.
        payload = json.dumps(self.payload())
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--payload-env', 'PAYLOAD', '--dry-run'],
                                capture_output=True, text=True, timeout=60, env=dict(os.environ, PAYLOAD=payload))
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn('dry run: would post Street Fighter 4.fliperos-customgame.zip', result.stdout)
        result = subprocess.run([sys.executable, str(self.SCRIPT), '--payload-env', 'PAYLOAD'], capture_output=True, text=True,
                                timeout=60, env=dict({k: v for k, v in os.environ.items() if k != 'TELEGRAM_BOT_TOKEN'}, PAYLOAD='{oops'))
        self.assertEqual(result.returncode, 1)


class SplashTests(unittest.TestCase):
    THEMES = ROOT / 'config/splashscreen'

    def test_bundled_themes_are_complete(self):
        # Cada pasta e um tema: NOME/NOME.plymouth apontando para a pasta de
        # mesmo nome no Plymouth, com o script e as imagens que ele abre.
        names = sorted(p.name for p in self.THEMES.iterdir() if p.is_dir())
        self.assertEqual(names, ['cogwheel', 'fliperos', 'fliperos-text', 'into-it', 'windoze95'])
        for name in names:
            plymouth = (self.THEMES / name / ('%s.plymouth' % name)).read_text()
            self.assertIn('ModuleName=script\n', plymouth)
            self.assertIn('ImageDir=/usr/share/plymouth/themes/%s\n' % name, plymouth)
            self.assertIn('ScriptFile=/usr/share/plymouth/themes/%s/%s.script\n' % (name, name), plymouth)
            self.assertRegex(plymouth, r'\nDescription=\w')
            script = (self.THEMES / name / ('%s.script' % name)).read_text(encoding='utf-8')
            code = re.sub(r'//[^\n]*', '', re.sub(r'/\*.*?\*/', '', script, flags=re.S))
            for image in re.findall(r'Image\("([^"]+)"\)', code):
                self.assertTrue((self.THEMES / name / image).is_file(), '%s: %s' % (name, image))
        # Os de terceiros escalam para a janela: 320x240 e 640x240 no CRT.
        self.assertIn('FlImage("SPINNER.PNG")', (self.THEMES / 'cogwheel/cogwheel.script').read_text(encoding='utf-8'))
        self.assertIn('scaleFactor * fl_py', (self.THEMES / 'into-it/into-it.script').read_text())
        self.assertIn('Image("w95_boot.png").Scale(Window.GetWidth(), Window.GetHeight())',
                      (self.THEMES / 'windoze95/windoze95.script').read_text())
        script = (self.THEMES / 'fliperos/fliperos.script').read_text()
        for frame in range(33):
            self.assertTrue((self.THEMES / ('fliperos/throbber-0%d.png' % frame)).is_file())
        # A arte de 640x480 escala para a janela (640x240 e 320x240 no CRT).
        self.assertIn('Image("logo.png").Scale(screen_width, screen_height)', script)
        self.assertEqual((self.THEMES / 'fliperos/logo.png').read_bytes()[:8], b'\x89PNG\r\n\x1a\n')

    def test_png_files_are_binary_in_git(self):
        # A regra "config/** text eol=lf" corromperia as imagens dos temas.
        attributes = (ROOT / '.gitattributes').read_text()
        self.assertGreater(attributes.index('*.png binary'), attributes.index('config/** text eol=lf'))

    def test_themes_are_installed(self):
        self.assertIn('cp -r "$src/config/splashscreen" "$root/usr/share/fliperos/splashscreen"', ROOTFS)
        self.assertIn('cp -r "$src/config/splashscreen/$theme" "$root/usr/share/plymouth/themes/$theme"', ROOTFS)
        self.assertIn('SPLASH_THEME="fliperos-text"\n', MKISO)
        self.assertIn('set_default_plymouth_theme "$SPLASH_THEME"\n', MKISO)
        roms = (ROOT / 'config/fliperos-roms').read_text()
        self.assertIn('splash=${FLIPEROS_SPLASH:-$HOME/splashscreen}', roms)

    def test_cabinet_update_rebuilds_initramfs_for_a_new_splash(self):
        script = (ROOT / 'tools/cabinet-update.sh').read_text()
        before = script.index('splash_before=$(splash_sum)')
        self.assertLess(before, script.index('bash "$src/fliperos-rootfs.sh" /'))
        self.assertIn('if [[ $(splash_sum) != "$splash_before" ]]; then', script)

    def test_text_theme_uses_only_verified_api(self):
        text = (self.THEMES / 'fliperos-text/fliperos-text.script').read_text(encoding='utf-8')
        code = re.sub(r'//[^\n]*', '', text)
        for call in ('Window.SetBackgroundTopColor', 'Window.GetWidth', 'Image.Text', 'Math.Int',
                     'Plymouth.SetBootProgressFunction', 'Plymouth.SetUpdateStatusFunction',
                     'Plymouth.SetRefreshFunction'):
            self.assertIn(call, code)
        self.assertNotRegex(code, r'(?<![\w.])Image\(')
        # O Plymouth nao tem continue; os textos nao-ASCII (blocos, spinner)
        # sao fatiados por byte, entao so aparecem inteiros nas strings.
        self.assertNotRegex(code, r'\bcontinue\b')
        self.assertNotIn('@U', code)

    def test_themes_do_not_trust_plymouth_random(self):
        # O Math.Random do Plymouth 24.004 devolve sempre ~0 ("AliperOS"): so
        # serve de semente para um gerador do proprio tema.
        for script in self.THEMES.glob('*/*.script'):
            code = re.sub(r'//[^\n]*', '', script.read_text(encoding='utf-8', errors='replace'))
            for line in code.splitlines():
                if 'Math.Random' in line:
                    self.assertRegex(line, r'^\w*seed\w* = ', '%s: %s' % (script.name, line.strip()))
        text = (self.THEMES / 'fliperos-text/fliperos-text.script').read_text(encoding='utf-8')
        self.assertIn('fun Rnd()', text)
        self.assertIn('% 2147483647', text)

    def test_text_theme_font_goes_into_the_initramfs(self):
        fonts = ROOT / 'config/fonts/jetbrains-mono'
        for weight in ('Regular', 'Bold', 'ExtraBold'):
            self.assertEqual((fonts / ('JetBrainsMono-%s.ttf' % weight)).read_bytes()[:4], b'\x00\x01\x00\x00')
        self.assertTrue((fonts / 'OFL.txt').is_file())
        self.assertIn('FONT = "JetBrains Mono";', (self.THEMES / 'fliperos-text/fliperos-text.script').read_text(encoding='utf-8'))
        self.assertIn('"$root/usr/share/fonts/truetype/fliperos"', ROOTFS)
        self.assertIn('install -Dm755 "$src/config/fliperos-initramfs-fonts" '
                      '"$root/etc/initramfs-tools/hooks/fliperos-fonts"', ROOTFS)
        hook = (ROOT / 'config/fliperos-initramfs-fonts').read_text()
        self.assertIn('cp -a /usr/share/fonts/truetype/fliperos "${DESTDIR}/usr/share/fonts/truetype/"', hook)
        self.assertIn('/usr/share/fonts/truetype/fliperos', (ROOT / 'tools/cabinet-update.sh').read_text())
        self.assertIn('*.ttf binary', (ROOT / '.gitattributes').read_text())

    def test_initramfs_goes_without_nouveau_and_the_nvidia_firmware(self):
        self.assertIn('install -Dm755 "$src/config/fliperos-initramfs-nvidia" '
                      '"$root/etc/initramfs-tools/hooks/fliperos-nvidia"', ROOTFS)
        with tempfile.TemporaryDirectory() as tmp:
            dest = Path(tmp)
            drm = dest / 'usr/lib/modules/6.18.54-15khz/kernel/drivers/gpu/drm'
            keep = [drm / 'radeon/radeon.ko', drm / 'amd/amdgpu/amdgpu.ko', dest / 'usr/lib/firmware/edid/arcade_15.bin',
                    dest / 'usr/lib/firmware/amdgpu/x.bin.zst', dest / 'usr/lib/firmware/radeon/y.bin.zst']
            gone = [drm / 'nouveau/nouveau.ko', dest / 'usr/lib/firmware/nvidia/ga102/gsp/gsp-570.144.bin.zst']
            for path in keep + gone:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(b'x')
            # O usrmerge do initramfs: /lib e um link para usr/lib.
            (dest / 'lib').symlink_to('usr/lib')
            hook = ROOT / 'config/fliperos-initramfs-nvidia'
            self.assertEqual(subprocess.run(['sh', str(hook), 'prereqs'], capture_output=True, text=True).stdout, '\n')
            r = subprocess.run(['sh', str(hook)], env=dict(os.environ, DESTDIR=tmp), capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, r.stderr)
            for path in keep:
                self.assertTrue(path.exists(), path)
            for path in gone:
                self.assertFalse(path.exists(), path)
            self.assertFalse((drm / 'nouveau').exists())
            self.assertTrue((dest / 'lib').is_symlink())
        # O firmware continua no sistema, e a ISO e conferida sem ele no initramfs.
        verify = (ROOT / 'tools/verify-iso.sh').read_text()
        self.assertIn("grep -q 'squashfs-root/usr/lib/firmware/nvidia/'", verify)
        self.assertIn("grep -qE 'firmware/nvidia/|drm/nouveau/' \"$work/initrd.txt\" && fail", verify)

    def test_update_6_moves_the_old_default_to_the_text_theme(self):
        script = (ROOT / 'updates/0006.sh').read_text()
        self.assertIn('== "$themes/fliperos/fliperos.plymouth" ]] || exit 0', script)
        self.assertIn("grep -q '^splash=' /etc/fliperos/fliperos.conf", script)
        self.assertIn('update-alternatives --set default.plymouth "$file"', script)
        # A mesma soma do .bundled do fliperos-roms.
        roms = (ROOT / 'config/fliperos-roms').read_text()
        line = 'splash_sum() { (cd "$1" && find . -type f ! -name .bundled -exec cksum {} + | sort | cksum); }'
        self.assertIn(line, script)
        self.assertIn(line, roms)

    def test_splash_is_generated_for_the_boot_mode(self):
        geometry = MKISO.split('splash_mode_geometry()')[1].split('}')[0]
        self.assertIn('640x480', geometry)


class AmdgpuLoadTests(unittest.TestCase):
    """config/fliperos-amdgpu-load: o dc=0 das Tonga (R9 380) desde a midia."""

    SCRIPT = ROOT / 'config/fliperos-amdgpu-load'

    def load(self, devices, cmdline='boot=live quiet', args=()):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            for n, (vendor, device) in enumerate(devices):
                dev = tmp / 'pci' / ('0000:0%d:00.0' % n)
                dev.mkdir(parents=True)
                (dev / 'vendor').write_text(vendor + '\n')
                (dev / 'device').write_text(device + '\n')
            (tmp / 'pci').mkdir(exist_ok=True)
            (tmp / 'cmdline').write_text(cmdline + '\n')
            modprobe = tmp / 'modprobe'
            modprobe.write_text('#!/bin/sh\necho "$@"\n')
            modprobe.chmod(0o755)
            # sh: no initramfs e no udev o install do modprobe.d roda no sh.
            r = subprocess.run(['sh', str(self.SCRIPT), *args], capture_output=True, text=True,
                               env=dict(os.environ, PCI_SYSFS=str(tmp / 'pci'), PROC_CMDLINE=str(tmp / 'cmdline'),
                                        MODPROBE=str(modprobe)))
            self.assertEqual(r.returncode, 0, r.stderr)
            return r.stdout.split()

    def test_a_tonga_loads_with_dc_off(self):
        self.assertEqual(self.load([('0x8086', '0x0042'), ('0x1002', '0x6939')], args=['si_support=0']),
                         ['--ignore-install', 'amdgpu', 'si_support=0', 'dc=0'])
        self.assertEqual(self.load([('0x1002', '0x6938')]), ['--ignore-install', 'amdgpu', 'dc=0'])

    def test_other_cards_and_the_kernel_line_keep_the_default(self):
        # Polaris (RX 580) e Vega nao tem saida analogica; Vega e as mais
        # novas nem tem video sem o DC.
        self.assertEqual(self.load([('0x1002', '0x67df')]), ['--ignore-install', 'amdgpu'])
        self.assertEqual(self.load([('0x10de', '0x6939')]), ['--ignore-install', 'amdgpu'])
        self.assertEqual(self.load([('0x1002', '0x6939')], cmdline='quiet amdgpu.dc=1'),
                         ['--ignore-install', 'amdgpu'])
        self.assertEqual(self.load([]), ['--ignore-install', 'amdgpu'])

    def test_ids_match_the_setup(self):
        setup = (ROOT / 'fliperos-setup/lib/bootloader.sh').read_text()
        ids = re.search(r'AMDGPU_NO_DC_IDS="([^"]*)"', setup).group(1).split()
        script = self.SCRIPT.read_text()
        listed = re.search(r'^\s*(0x6920 \|[^)]*)\)', script, re.M).group(1).replace('|', ' ').split()
        self.assertEqual(['1002:' + i[2:] for i in listed], ids)

    def test_the_modprobe_rule_falls_back_to_a_plain_load(self):
        conf = ROOTFS.split('fliperos-amdgpu.conf" <<')[1].split('\nEOF')[0]
        self.assertIn('install amdgpu /bin/sh /opt/fliperos/bin/fliperos-amdgpu-load $CMDLINE_OPTS'
                      ' || /sbin/modprobe --ignore-install amdgpu $CMDLINE_OPTS', conf)

    def test_the_hook_puts_the_script_in_the_initramfs(self):
        hook = ROOT / 'config/fliperos-initramfs-amdgpu'
        self.assertEqual(subprocess.run(['sh', str(hook), 'prereqs'], capture_output=True, text=True).stdout, '\n')
        self.assertIn('script=/opt/fliperos/bin/fliperos-amdgpu-load\n', hook.read_text())
        verify = (ROOT / 'tools/verify-iso.sh').read_text()
        self.assertIn("grep -q 'opt/fliperos/bin/fliperos-amdgpu-load$' \"$work/initrd.txt\"", verify)


