class RetroArchConfigTests(unittest.TestCase):
    """config/retroarch.cfg e config de sistema: o fliperos-kms-run a passa
    com --appendconfig, por cima da do usuario."""

    CFG = ROOT / 'config/retroarch.cfg'

    def values(self):
        found = {}
        for line in self.CFG.read_text().splitlines():
            if not line.strip() or line.startswith('#'):
                continue
            match = re.match(r'^([a-z0-9_]+) = "([^"]*)"$', line)
            self.assertIsNotNone(match, 'linha fora do formato do RetroArch: ' + line)
            self.assertNotIn(match.group(1), found, 'chave repetida: ' + match.group(1))
            found[match.group(1)] = match.group(2)
        return found

    def test_crt_switchres_uses_the_system_switchres_ini(self):
        self.assertEqual(self.values()['crt_switch_resolution'], '4')

    def test_video_driver_can_modeswitch_in_kms(self):
        # glcore e gl usam o contexto KMS; o vulkan (khr_display) so troca
        # com o patch, e entra por cima no amdgpu (teste do Vulkan abaixo).
        self.assertEqual(self.values()['video_driver'], 'glcore')
        gl = [line for line in (ROOT / 'config/retroarch-gl.cfg').read_text().splitlines()
              if line and not line.startswith('#')]
        self.assertEqual(gl, ['video_driver = "gl"'])
        self.assertIn('install -Dm644 "$src/config/retroarch-gl.cfg" "$root/etc/fliperos/retroarch/retroarch-gl.cfg"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())

    def test_initial_mode_is_the_active_one(self):
        values = self.values()
        self.assertEqual((values['video_fullscreen_x'], values['video_fullscreen_y']), ('0', '0'))

    def test_audio_is_sdl2_over_alsa(self):
        # Sem servidor de som: o SDL do RetroArch sai direto no ALSA.
        self.assertEqual(self.values()['audio_driver'], 'sdl2')
        self.assertIn('export SDL_AUDIODRIVER="${SDL_AUDIODRIVER:-alsa}"',
                      (ROOT / 'config/fliperos-kms-run').read_text())

    def test_one_esc_quits(self):
        # Sem as notificacoes na tela, o "press again to quit" nao aparece.
        values = self.values()
        self.assertEqual(values['confirm_quit'], 'false')
        self.assertEqual(values['video_font_enable'], 'false')

    def test_standard_latency_values(self):
        values = self.values()
        self.assertEqual(values['video_max_swapchain_images'], '2')
        self.assertEqual(values['video_threaded'], 'false')
        self.assertEqual(values['input_poll_type_behavior'], '2')
        # Os do modo de baixa latencia ficam desligados no arquivo da ISO.
        self.assertEqual(values['video_frame_delay_auto'], 'false')
        self.assertEqual(values['preemptive_frames_enable'], 'false')
        self.assertEqual(values['run_ahead_enabled'], 'false')

    def test_online_updater_can_write(self):
        # Pastas do usuario: o Core Downloader e as atualizacoes do menu
        # gravam sem root. Nada disso em /etc.
        values = self.values()
        self.assertEqual(values['libretro_directory'], '/opt/fliperos/retroarch/cores')
        self.assertEqual(values['libretro_info_path'], '/opt/fliperos/retroarch/info')
        self.assertEqual(values['joypad_autoconfig_dir'], '/opt/fliperos/retroarch/autoconfig')
        body = MKISO.split("<< 'RASCRIPT'")[1].split('\nRASCRIPT\n')[0]
        self.assertIn('RA_DIR=/opt/fliperos/retroarch', body)
        self.assertIn('chown -R fliperos:fliperos "$RA_DIR"', body)
        self.assertIn('libretro/libretro-core-info __RA_CORE_INFO_COMMIT__', body)
        self.assertNotIn('/etc/fliperos/retroarch/cores', MKISO)
        for name in ('RA_CORE_INFO_COMMIT', 'RA_AUTOCONFIG_COMMIT'):
            self.assertRegex(MKISO, name + r'="[0-9a-f]{40}"')

    def test_input_and_joypad_drivers_are_linuxraw(self):
        values = self.values()
        self.assertEqual(values['input_driver'], 'linuxraw')
        self.assertEqual(values['input_joypad_driver'], 'linuxraw')
        body = MKISO.split("<< 'RASCRIPT'")[1].split('\nRASCRIPT\n')[0]
        # Os perfis de fabrica dos dois drivers.
        self.assertIn('cp -a /tmp/ra-autoconfig/udev /tmp/ra-autoconfig/linuxraw "$RA_DIR/autoconfig/"', body)
        recipe = (ROOT / 'packaging/packages/fliperos-retroarch.sh').read_text()
        self.assertIn('libsdl2-dev', recipe)
        self.assertIn('--enable-sdl2', recipe)
        self.assertNotIn('--disable-sdl2', recipe)

    def test_emulators_built_with_vulkan(self):
        # Para o driver amdgpu (Setup > Video Setup > Video driver).
        ra = (ROOT / 'packaging/packages/fliperos-retroarch.sh').read_text()
        self.assertIn('libvulkan-dev', ra)
        self.assertIn('--enable-vulkan', ra)
        fc = (ROOT / 'packaging/packages/fliperos-flycast.sh').read_text()
        self.assertIn('-DUSE_VULKAN=ON', fc)
        self.assertNotIn('USE_VULKAN=OFF', fc)
        dol = (ROOT / 'packaging/packages/fliperos-dolphin.sh').read_text()
        self.assertIn('-DENABLE_VULKAN=ON', dol)
        # O padrao do arquivo segue o glcore; o Vulkan entra por cima so no
        # amdgpu, pelo fliperos-kms-run.
        self.assertEqual(self.values()['video_driver'], 'glcore')

    def test_no_onscreen_notifications(self):
        values = self.values()
        self.assertEqual(values['video_font_enable'], 'false')
        self.assertEqual(values['menu_enable_widgets'], 'false')

    def test_mame2010_is_built_without_fortify(self):
        # O gcc do Ubuntu liga o _FORTIFY_SOURCE sozinho, e com ele a glibc
        # aborta o MAME 0.139 ao iniciar uma CPU H8/3002 (Namco System 12).
        body = MKISO.split("<< 'RASCRIPT'")[1].split('\nRASCRIPT\n')[0]
        self.assertIn('make -C "$dir" -f "$mk" -j"$(nproc)" "$@"', body)
        self.assertIn('\nbuild_core libretro/mame2010-libretro ARCHOPTS=-U_FORTIFY_SOURCE\n', body)
        # O FBNeo (o placar versus pelo RetroArch): o makefile do core fica
        # numa subpasta, e o .so vai sem os simbolos.
        self.assertIn('elif [[ -f "$dir/src/burner/libretro/Makefile" ]]; then', body)
        self.assertIn('\nbuild_core libretro/FBNeo\nstrip --strip-unneeded "$RA_DIR/cores/fbneo_libretro.so"\n', body)
        self.assertIn('[[ $symbols != *__strcat_chk* ]]', (ROOT / 'tools/verify-iso.sh').read_text())

    def test_retroarch_gets_the_system_config(self):
        # E, se o Setup gravou, os botoes de cada jogador por cima.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            prog = tmp / 'retroarch'
            prog.write_text('#!/bin/sh\nprintf "%s\\n" "$@"\n')
            prog.chmod(0o755)
            buttons = tmp / 'buttons.cfg'
            (tmp / 'debug').write_text('')  # modo debug: a saida na tela, nao no log
            env = dict(os.environ, FLIPEROS_RA_BUTTONS=str(buttons), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'),
                       PATH='%s:%s' % (tmp, os.environ['PATH']))
            env.pop('DISPLAY', None)
            run = lambda: subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), 'retroarch', '-L', 'x'],
                                         capture_output=True, text=True, env=env).stdout.split('\n')
            self.assertEqual(run()[:3], ['--appendconfig', '/etc/fliperos/retroarch/retroarch.cfg', '-L'])
            buttons.write_text('')
            self.assertEqual(run()[:2], ['--appendconfig', '/etc/fliperos/retroarch/retroarch.cfg|%s' % buttons])
            # Uma pistola de luz (GunCon 2, tambem mouse) no js0: o linuxraw conta
            # os jsN, o Button mapping o indice do SDL (sem a pistola). Cada
            # jogador vai para o jsN do seu controle.
            devices = tmp / 'devices'
            env.update(FLIPEROS_INPUT_DEVICES=str(devices), XDG_RUNTIME_DIR=str(tmp))
            dev = 'N: Name="%s"\nH: Handlers=%s \n\n'
            devices.write_text(dev % ('Pad', 'event3 js0') + dev % ('Pad', 'event4 js1'))
            self.assertEqual(run()[1].split('|')[-1], str(buttons))  # sem pistola, nada muda
            devices.write_text(dev % ('Namco GunCon 2', 'mouse1 event6 js0') + dev % ('Pad', 'event14 js1')
                               + dev % ('Pad', 'event15 js2'))
            buttons.write_text('input_player1_joypad_index = "0"\ninput_player2_joypad_index = "1"\n')
            out = run()[1].split('|')
            self.assertEqual(out[-2:], [str(buttons), str(tmp / 'fliperos-retroarch-joypads.cfg')])
            lines = Path(out[-1]).read_text()
            for player, js in ((1, 1), (2, 2), (3, 3), (4, 4), (8, 8)):
                self.assertIn('input_player%d_joypad_index = "%d"\n' % (player, js), lines)
            # Jogadores trocados no Button mapping continuam trocados.
            buttons.write_text('input_player1_joypad_index = "1"\ninput_player2_joypad_index = "0"\n')
            lines = Path(run()[1].split('|')[-1]).read_text()
            self.assertIn('input_player1_joypad_index = "2"\n', lines)
            self.assertIn('input_player2_joypad_index = "1"\n', lines)

    def test_glcore_falls_back_to_gl_without_opengl_3_2_core(self):
        # O glcore nao abre em placa que so tem OpenGL 2.x: o fliperos-kms-run
        # pergunta ao Mesa (eglinfo) e passa o "gl" por cima. Sem resposta
        # (sem eglinfo, EGL que nao abre), vale o glcore do arquivo.
        head = 'GBM platform:\nEGL API version: 1.5\nEGL client APIs: OpenGL OpenGL_ES \n'
        core = 'OpenGL core profile version: %s (Core Profile) Mesa 25.2.8\n'
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            prog = tmp / 'retroarch'
            prog.write_text('#!/bin/sh\nprintf "%s\\n" "$@"\n')
            prog.chmod(0o755)
            cfg = tmp / 'retroarch.cfg'
            gl = ROOT / 'config/retroarch-gl.cfg'
            (tmp / 'debug').write_text('')
            env = dict(os.environ, FLIPEROS_RA_CFG=str(cfg), FLIPEROS_RA_GL=str(gl),
                       FLIPEROS_RA_BUTTONS=str(tmp / 'buttons.cfg'), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'),
                       PATH='%s:%s' % (tmp, os.environ['PATH']))
            env.pop('DISPLAY', None)

            def appended(driver, eglinfo):
                cfg.write_text('video_driver = "%s"\n' % driver)
                fake = tmp / 'eglinfo'
                if eglinfo is None:
                    fake.unlink(missing_ok=True)
                else:
                    (tmp / 'eglinfo.txt').write_text(eglinfo)
                    fake.write_text('#!/bin/sh\necho "$*" > "%s/eglinfo.args"\ncat "%s/eglinfo.txt"\n' % (tmp, tmp))
                    fake.chmod(0o755)
                out = subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), 'retroarch', '-L', 'x'],
                                     capture_output=True, text=True, env=env).stdout.split('\n')
                self.assertEqual((out[0], out[2]), ('--appendconfig', '-L'))
                return out[1].split('|')[1:]

            self.assertEqual(appended('glcore', head), [str(gl)])  # so OpenGL 2.x: sem perfil core
            self.assertEqual((tmp / 'eglinfo.args').read_text().split(), ['-B', '-p', 'gbm', '-a', 'glcore'])
            self.assertEqual(appended('glcore', head + core % '3.1'), [str(gl)])
            for version in ('3.2', '3.3', '4.5', '10.0'):
                self.assertEqual(appended('glcore', head + core % version), [], version)
            self.assertEqual(appended('glcore', 'GBM platform:\neglinfo: eglInitialize failed\n'), [])
            self.assertEqual(appended('glcore', None), [])
            # Quem trocou o driver no arquivo do sistema fica com o dele.
            self.assertEqual(appended('vulkan', head), [])

    def test_vulkan_on_amdgpu_with_the_khr_display_patch(self):
        # O khr_display do patch troca o modo do CRT: no amdgpu o RetroArch
        # abre em Vulkan. Em outro driver, outra placa ou sem o patch (sem a
        # marca do build), o glcore. Nada fica gravado: vale a placa de agora.
        # O RetroArch e o pacote fliperos-retroarch: o patch entra sempre (o
        # commit e fixo) e a marca vem no pacote.
        recipe = (ROOT / 'packaging/packages/fliperos-retroarch.sh').read_text()
        self.assertIn('touch "$STAGING/usr/local/share/fliperos/retroarch-vulkan-crt"', recipe)
        self.assertLess(recipe.index('git -C "$dir" apply "$patch" || return 1'), recipe.index('./configure'))
        self.assertTrue((ROOT / 'packaging/patches/retroarch/0001-khr-display-crt-modeswitch.patch').is_file())
        self.assertFalse((ROOT / 'config/retroarch-patches').exists())
        self.assertIn('install -Dm644 "$src/config/retroarch-vulkan.cfg" "$root/etc/fliperos/retroarch/retroarch-vulkan.cfg"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())
        vulkan = ROOT / 'config/retroarch-vulkan.cfg'
        self.assertEqual([line for line in vulkan.read_text().splitlines() if line and not line.startswith('#')],
                         ['video_driver = "vulkan"'])
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            prog = tmp / 'retroarch'
            prog.write_text('#!/bin/sh\nprintf "%s\\n" "$@"\n')
            prog.chmod(0o755)
            # eglinfo que responde OpenGL 4.6: o "gl" nao entra.
            (tmp / 'eglinfo').write_text('#!/bin/sh\nprintf "EGL client APIs: OpenGL\\n'
                                         'OpenGL core profile version: 4.6\\n"\n')
            (tmp / 'eglinfo').chmod(0o755)
            sysfs = tmp / 'drm'
            marker = tmp / 'retroarch-vulkan-crt'
            (tmp / 'debug').write_text('')
            env = dict(os.environ, FLIPEROS_RA_CFG=str(ROOT / 'config/retroarch.cfg'),
                       FLIPEROS_RA_VULKAN=str(vulkan), FLIPEROS_RA_VULKAN_CRT=str(marker),
                       FLIPEROS_DRM_SYSFS=str(sysfs), FLIPEROS_RA_BUTTONS=str(tmp / 'buttons.cfg'),
                       FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'), PATH='%s:%s' % (tmp, os.environ['PATH']))
            env.pop('DISPLAY', None)

            def cards(*outputs):
                # (placa, driver, conector, status)
                shutil.rmtree(sysfs, ignore_errors=True)
                for card, driver, connector, status in outputs:
                    (tmp / 'drivers' / driver).mkdir(parents=True, exist_ok=True)
                    (sysfs / card / 'device').mkdir(parents=True, exist_ok=True)
                    link = sysfs / card / 'device/driver'
                    if not link.is_symlink():
                        link.symlink_to(tmp / 'drivers' / driver)
                    (sysfs / ('%s-%s' % (card, connector))).mkdir()
                    (sysfs / ('%s-%s' % (card, connector)) / 'status').write_text(status + '\n')

            def appended():
                out = subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), 'retroarch', '-L', 'x'],
                                     capture_output=True, text=True, env=env).stdout.split('\n')
                self.assertEqual(out[0], '--appendconfig')
                return out[1].split('|')[1:]

            cards(('card0', 'amdgpu', 'VGA-1', 'connected'))
            self.assertEqual(appended(), [])  # RetroArch sem o patch
            marker.write_text('')
            self.assertEqual(appended(), [str(vulkan)])
            cards(('card0', 'radeon', 'VGA-1', 'connected'))
            self.assertEqual(appended(), [])
            # Outra placa: vale a do conector ligado.
            cards(('card0', 'i915', 'HDMI-A-1', 'disconnected'), ('card1', 'amdgpu', 'DVI-I-1', 'connected'))
            self.assertEqual(appended(), [str(vulkan)])
            cards(('card0', 'i915', 'VGA-1', 'connected'), ('card1', 'amdgpu', 'DVI-I-1', 'disconnected'))
            self.assertEqual(appended(), [])


class RetroArchMameRemapTests(unittest.TestCase):
    """Os cores de MAME do RetroArch leem Button 1-6 do RetroPad numa ordem
    propria: o remap leva o painel (Y X L / B A R) ao botao de mesmo numero."""

    IDS = {'b': 0, 'y': 1, 'a': 8, 'x': 9, 'l': 10, 'r': 11}
    PANEL = ['y', 'x', 'l', 'b', 'a', 'r']   # botoes 1 a 6 do painel no RetroPad
    CORES = {'MAME': ['b', 'a', 'y', 'x', 'l', 'r'],          # input_retro.cpp
             'MAME 2010': ['a', 'b', 'x', 'y', 'l', 'r']}     # retromain.c

    def test_panel_button_n_is_game_button_n(self):
        for core, order in self.CORES.items():
            text = (ROOT / 'config/retroarch-remaps' / (core + '.rmp')).read_text()
            self.assertTrue(text.startswith('# FliperOS'), core)
            for player in range(1, 5):
                for n, pad in enumerate(self.PANEL):
                    self.assertIn('input_player%d_btn_%s = "%d"\n' % (player, pad, self.IDS[order[n]]), text,
                                  (core, player, n + 1))

    def test_installed_without_overwriting_a_user_remap(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for d in ('home/fliperos', 'etc/fliperos/mame', 'etc/modprobe.d', 'etc/sudoers.d', 'etc/profile.d',
                      'etc/systemd/system'):
                (root / d).mkdir(parents=True)
            (root / 'etc/passwd').write_text('fliperos:x:1000:1000::/home/fliperos:/bin/bash\n')
            remaps = root / 'home/fliperos/.config/retroarch/config/remaps'
            (remaps / 'MAME 2010').mkdir(parents=True)
            (remaps / 'MAME 2010' / 'MAME 2010.rmp').write_text('input_player1_btn_b = "0"\n')
            subprocess.run(['bash', str(ROOT / 'fliperos-rootfs.sh'), str(root)], check=True,
                           capture_output=True, timeout=120)
            self.assertEqual((remaps / 'MAME' / 'MAME.rmp').read_text(),
                             (ROOT / 'config/retroarch-remaps/MAME.rmp').read_text())
            self.assertEqual((remaps / 'MAME 2010' / 'MAME 2010.rmp').read_text(), 'input_player1_btn_b = "0"\n')

    def test_mame2010_buttons_only_from_the_retropad(self):
        # O core le o teclado direto: com as teclas padrao do MAME (as do
        # painel) cada botao chegava duas vezes. Cada botao de cada jogador
        # so no Joy do mesmo numero, nenhuma tecla.
        text = (ROOT / 'config/mame2010-default.cfg').read_text()
        self.assertNotIn('KEYCODE', text)
        for player in range(1, 5):
            for n in range(1, 7):
                self.assertRegex(text, r'<port type="P%d_BUTTON%d">\s*<newseq type="standard">\s*'
                                       r'JOYCODE_%d_BUTTON%d\s*</newseq>' % (player, n, player, n))
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for d in ('home/fliperos', 'etc/fliperos/mame', 'etc/modprobe.d', 'etc/sudoers.d', 'etc/profile.d',
                      'etc/systemd/system'):
                (root / d).mkdir(parents=True)
            (root / 'etc/passwd').write_text('fliperos:x:1000:1000::/home/fliperos:/bin/bash\n')
            cfg = root / 'opt/fliperos/saves/retroarch/MAME 2010/mame2010/cfg/default.cfg'
            cfg.parent.mkdir(parents=True)
            # O que o menu do MAME gravou no gabinete: o botao 2 junto do 5.
            cfg.write_text('<port type="P1_BUTTON2"><newseq type="standard">JOYCODE_1_BUTTON2 JOYCODE_1_BUTTON5'
                           '</newseq></port>\n')
            subprocess.run(['bash', str(ROOT / 'fliperos-rootfs.sh'), str(root)], check=True,
                           capture_output=True, timeout=120)
            self.assertEqual(cfg.read_text(), text)
            # O nosso (mesmo reescrito pelo MAME, sem o comentario) fica.
            cfg.write_text(text.replace('FliperOS', 'x'))
            subprocess.run(['bash', str(ROOT / 'fliperos-rootfs.sh'), str(root)], check=True,
                           capture_output=True, timeout=120)
            self.assertIn('<!-- x', cfg.read_text())


class RetroArchCoreSwitchresTests(unittest.TestCase):
    """config/retroarch-switchres: o switchres.ini que o CRT SwitchRes do
    RetroArch le so para um core (config/<Core>/<Core>.switchres.ini)."""

    INI = ROOT / 'config/retroarch-switchres/MAME 2010.switchres.ini'

    def test_mame2010_never_interlaces(self):
        # Um jogo de 480 linhas sai em 240p (640x240 a 15 kHz), nao em 480i.
        lines = self.INI.read_text().splitlines()
        self.assertTrue(lines[0].startswith('# FliperOS'))
        self.assertEqual([line for line in lines if not line.startswith('#')], ['interlace 0'])

    def test_installed_without_overwriting_a_user_file(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            for d in ('home/fliperos', 'etc/fliperos/mame', 'etc/modprobe.d', 'etc/sudoers.d', 'etc/profile.d',
                      'etc/systemd/system'):
                (root / d).mkdir(parents=True)
            (root / 'etc/passwd').write_text('fliperos:x:1000:1000::/home/fliperos:/bin/bash\n')
            target = root / 'home/fliperos/.config/retroarch/config/MAME 2010/MAME 2010.switchres.ini'
            run = lambda: subprocess.run(['bash', str(ROOT / 'fliperos-rootfs.sh'), str(root)], check=True,
                                         capture_output=True, timeout=120)
            run()
            self.assertEqual(target.read_text(), self.INI.read_text())
            # Sem o cabecalho o arquivo e da pessoa.
            target.write_text('interlace 1\n')
            run()
            self.assertEqual(target.read_text(), 'interlace 1\n')


class EmulatorsMenuTests(unittest.TestCase):
    """Setup > Games > Emulators & Games: o estado de cada emulador e a instalacao dos que nao vem na imagem."""

    def run_cmd(self, script, *args, env=None):
        return subprocess.run(['bash', str(ROOT / 'config' / script), *args], capture_output=True, text=True,
                              env=dict(os.environ, **(env or {})), timeout=120)

    def edge_rig(self, tmp, patch_fits=True):
        """Um Flycast de pacote num root falso, a receita com PKG_UPSTREAM num
        repositorio local, e o dpkg-divert/dpkg-query/apt-get de mentira (o
        divert move os arquivos dentro do root falso)."""
        root, recipes, bin_dir = tmp / 'root', tmp / 'recipes', tmp / 'bin'
        for d in (root / 'usr/local/bin', recipes, bin_dir):
            d.mkdir(parents=True)
        (root / 'usr/local/bin/flycast').write_text('package\n')
        upstream = tmp / 'upstream'
        git = ['git', '-c', 'user.name=t', '-c', 'user.email=t@t']
        subprocess.run([*git, 'init', '-q', str(upstream)], check=True)
        subprocess.run([*git, '-C', str(upstream), 'commit', '-q', '--allow-empty', '-m', 'a'], check=True)
        head = subprocess.run(['git', '-C', str(upstream), 'rev-parse', 'HEAD'], capture_output=True,
                              text=True).stdout.strip()
        body = ('echo "error: patch failed: core/x.cpp:1" >&2; return 1' if not patch_fits else
                'mkdir -p "$STAGING/usr/local/bin" && echo "edge $FLYCAST_COMMIT" > "$STAGING/usr/local/bin/flycast"'
                ' && chmod 755 "$STAGING/usr/local/bin/flycast"')
        (recipes / 'fliperos-flycast.sh').write_text(
            'PKG_UPSTREAM="%s"\nPKG_COMMIT_VAR="FLYCAST_COMMIT"\nFLYCAST_COMMIT="0"\nPKG_BUILD_DEPS="cmake"\n'
            'pkg_build() {\n  %s\n}\n' % (upstream, body))
        (recipes / 'fliperos-retroarch.sh').write_text('PKG_NAME="fliperos-retroarch"\n')
        divert = tmp / 'diverts'
        stubs = {
            'apt-get': 'exit 0',
            'dpkg-query': '[ "$1" = -S ] && [ "$2" = /usr/local/bin/flycast ] && exit 0; exit 1',
            'dpkg-divert': (
                'R=%s; D=%s; touch "$D"\n'
                'case " $* " in\n'
                '  *" --list "*) grep -x -- "${@: -1}" "$D" ;;\n'
                '  *" --add "*) p=${@: -1}; mv "$R$p" "$R$p.fliperos-package"; echo "$p" >> "$D" ;;\n'
                '  *" --remove "*) p=${@: -1}; mv "$R$p.fliperos-package" "$R$p"; grep -vx -- "$p" "$D" > "$D.n"; mv "$D.n" "$D" ;;\n'
                'esac\nexit 0\n') % (root, divert),
        }
        for name, text in stubs.items():
            (bin_dir / name).write_text('#!/bin/bash\n' + text + '\n')
            (bin_dir / name).chmod(0o755)
        env = {'FLIPEROS_EMULATORS_ROOT': str(root), 'FLIPEROS_HOME': str(tmp / 'home'),
               'FLIPEROS_RECIPES': str(recipes), 'FLIPEROS_EDGE_STATE': str(tmp / 'state'),
               'FLIPEROS_EDGE_WORK': str(tmp / 'work'), 'PATH': '%s:%s' % (bin_dir, os.environ['PATH'])}
        return root, env, head

    def test_the_newest_flycast_is_built_over_the_package_and_goes_back(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            root, env, head = self.edge_rig(tmp)
            self.assertEqual(self.run_cmd('fliperos-emulators', 'edge-available', 'flycast', env=env).returncode, 0)
            # Sem PKG_UPSTREAM na receita (o RetroArch), so o pacote.
            self.assertNotEqual(self.run_cmd('fliperos-emulators', 'edge-available', 'retroarch', env=env).returncode, 0)
            run = self.run_cmd('fliperos-emulators', 'edge', 'flycast', '--progress', env=env)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
            self.assertIn('@step 100 Flycast (Dreamcast, Naomi, Atomiswave) %s installed' % head[:7], run.stdout)
            # O build no lugar; o binario do pacote guardado ao lado.
            self.assertEqual((root / 'usr/local/bin/flycast').read_text(), 'edge %s\n' % head)
            self.assertEqual((root / 'usr/local/bin/flycast.fliperos-package').read_text(), 'package\n')
            self.assertEqual(self.run_cmd('fliperos-emulators', 'edge-status', 'flycast', env=env).stdout.strip(), head)
            # Compilar de novo nao perde o do pacote.
            self.assertEqual(self.run_cmd('fliperos-emulators', 'edge', 'flycast', env=env).returncode, 0)
            self.assertEqual((root / 'usr/local/bin/flycast.fliperos-package').read_text(), 'package\n')
            # De volta ao pacote.
            self.assertEqual(self.run_cmd('fliperos-emulators', 'edge-off', 'flycast', env=env).returncode, 0)
            self.assertEqual((root / 'usr/local/bin/flycast').read_text(), 'package\n')
            self.assertFalse((root / 'usr/local/bin/flycast.fliperos-package').exists())
            self.assertEqual(self.run_cmd('fliperos-emulators', 'edge-status', 'flycast', env=env).stdout.strip(), '')

