    def test_list_marks_what_is_installed(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            env = {'FLIPEROS_EMULATORS_ROOT': str(tmp / 'root'), 'FLIPEROS_HOME': str(tmp / 'home')}
            for path in ('root/usr/local/bin/retroarch', 'root/usr/local/bin/keisho'):
                (tmp / path).parent.mkdir(parents=True, exist_ok=True)
                (tmp / path).write_text('')
                (tmp / path).chmod(0o755)
            rows = [r.split('|') for r in self.run_cmd('fliperos-emulators', 'list', env=env).stdout.splitlines()]
            # Os do menu do desktop (config/applications), na ordem dele, e o KOF.
            self.assertEqual([r[0] for r in rows], ['retroarch', 'groovymame', 'flycast', 'pcsx2', 'pcsx2x6',
                                                    'dolphin', 'openbor', 'keisho', 'fightcade',
                                                    'duckstation', 'kof'])
            state = {r[0]: (r[1], r[2]) for r in rows}
            self.assertEqual(state['retroarch'], ('1', 'image'))
            self.assertEqual(state['flycast'], ('0', 'image'))
            self.assertEqual(state['keisho'], ('1', 'image'))
            self.assertEqual(state['fightcade'], ('0', 'fetch'))
            self.assertEqual(state['duckstation'], ('0', 'fetch'))
            self.assertEqual(state['kof'], ('0', 'source'))
            self.assertEqual(self.run_cmd('fliperos-emulators', 'installed', 'keisho', env=env).returncode, 0)
            self.assertEqual(self.run_cmd('fliperos-emulators', 'installed', 'kof', env=env).returncode, 1)
        # O arquivo que diz "instalado" e o TryExec do atalho do desktop.
        script = (ROOT / 'config/fliperos-emulators').read_text()
        for name in ('retroarch', 'groovymame', 'flycast', 'pcsx2', 'dolphin', 'openbor', 'fightcade',
                     'duckstation'):
            tryexec = re.search(r'(?m)^TryExec=(.+)$',
                                (ROOT / 'config/applications' / ('fliperos-%s.desktop' % name)).read_text()).group(1)
            self.assertIn('|$root%s|' % tryexec, script, name)
        for name in ('model2', 'model3'):
            self.assertIn('TryExec=/usr/local/bin/keisho\n',
                          (ROOT / 'config/applications' / ('fliperos-%s.desktop' % name)).read_text())
        self.assertIn('keisho|image|$root/usr/local/bin/keisho|', script)

    def test_versions_and_what_the_update_brings(self):
        # A versao instalada sai de arquivos, sem abrir o emulador; a do update
        # vem do fliperos-mkiso.sh do repositorio (as da imagem) ou do git.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            root, home = tmp / 'root', tmp / 'home'
            for path in ('usr/local/bin/retroarch', 'usr/local/bin/groovymame', 'usr/local/bin/pcsx2',
                         'usr/local/bin/duckstation', 'opt/fliperos/fightcade/fightcade'):
                (root / path).parent.mkdir(parents=True, exist_ok=True)
                (root / path).write_text('')
                (root / path).chmod(0o755)
            share = root / 'usr/local/share/fliperos'
            share.mkdir(parents=True)
            (share / 'emulator-versions').write_text('retroarch=2026-10-12 55c2026\nflycast=2026-10-01 1111111\n')
            # O RetroArch do pacote grava a sua, que vale antes da do arquivo da imagem.
            (share / 'emulator-versions.d').mkdir()
            (share / 'emulator-versions.d/retroarch').write_text('2026-11-05 7d2e953\n')
            (tmp / 'packaging/packages').mkdir(parents=True)
            (tmp / 'packaging/packages/fliperos-retroarch.sh').write_text(
                'RA_COMMIT="8e3f00aa8e3f00aa8e3f00aa8e3f00aa8e3f00aa"\n')
            (root / 'usr/local/libexec').mkdir(parents=True)
            (root / 'usr/local/libexec/groovymame').write_bytes(b'\0x 0.976 (\0Lua 5.4\0' b'0.289 (unknown)\0')
            for app, version in (('pcsx2', 'v2.8.2'), ('duckstation', '0.1-12083-g00e299795')):
                (root / 'opt' / app / 'usr/share/metainfo').mkdir(parents=True)
                (root / 'opt' / app / 'usr/share/metainfo/a.xml').write_text(
                    '<releases>\n  <release version="%s" date="2026-10-01"/>\n</releases>\n' % version)
            (root / 'opt/fliperos/fightcade/VERSION.txt').write_text('2.1.45\n')
            # O Keisho: o pacote grava a versao; o update traz o commit da receita.
            (root / 'usr/local/bin/keisho').write_text('')
            (root / 'usr/local/bin/keisho').chmod(0o755)
            (root / 'usr/local/share/fliperos/emulator-versions.d').mkdir(parents=True, exist_ok=True)
            (root / 'usr/local/share/fliperos/emulator-versions.d/keisho').write_text('2026-11-16 d7c7dd8\n')
            (tmp / 'packaging/packages/fliperos-keisho.sh').write_text('KEISHO_COMMIT="%s"\n' % ('e' * 40))
            mkiso = tmp / 'fliperos-mkiso.sh'
            mkiso.write_text('')
            (tmp / 'packaging/packages/fliperos-pcsx2.sh').write_text('PKG_VERSION="2.8.2"\n')
            # O GroovyMAME que o update traz: a tag da receita do pacote.
            (tmp / 'packaging/packages/fliperos-groovymame.sh').write_text('GROOVYMAME_TAG="gm0290sr222g"\n')
            env = {'FLIPEROS_EMULATORS_ROOT': str(root), 'FLIPEROS_HOME': str(home),
                   'FLIPEROS_MKISO_URL': mkiso.as_uri()}
            got = dict(r.split('|') for r in self.run_cmd('fliperos-emulators', 'versions', env=env).stdout.splitlines())
            self.assertEqual(got['retroarch'], '2026-11-05 7d2e953')
            self.assertEqual(got['groovymame'], '0.289')
            self.assertEqual(got['pcsx2'], '2.8.2')
            self.assertEqual(got['duckstation'], '0.1-12083-g00e299795')
            self.assertEqual(got['fightcade'], '2.1.45')
            self.assertEqual(got['keisho'], '2026-11-16 d7c7dd8')
            # Nao instalado: sem versao.
            self.assertEqual(got['flycast'], '')

            def latest(name):
                return self.run_cmd('fliperos-emulators', 'latest', name, env=env).stdout.strip()
            self.assertEqual(latest('pcsx2'), '2.8.2|2.8.2|same')
            # O commit fixado na receita do pacote: o que o proximo update leva.
            self.assertEqual(latest('retroarch'), '2026-11-05 7d2e953|8e3f00a|new')
            self.assertEqual(latest('groovymame'), '0.289|0.290|new')
            self.assertEqual(latest('keisho'), '2026-11-16 d7c7dd8|eeeeeee|new')
            # Sem como saber a nova (o Fightcade nao diz a versao antes de baixar).
            self.assertEqual(latest('fightcade'), '2.1.45||unknown')
        # O build da imagem grava a versao de cada emulador dela.
        mk = (ROOT / 'fliperos-mkiso.sh').read_text()
        self.assertIn('echo "${PCSX2_TAG#v}" > "$STAGING/usr/local/share/fliperos/emulator-versions.d/pcsx2"',
                      (ROOT / 'packaging/packages/fliperos-pcsx2.sh').read_text())
        self.assertIn('echo "$PKG_VERSION" > "$STAGING/usr/local/share/fliperos/emulator-versions.d/dolphin"',
                      (ROOT / 'packaging/packages/fliperos-dolphin.sh').read_text())
        self.assertIn('echo "0.${GROOVYMAME_TAG:3:3}" > "$STAGING/usr/local/share/fliperos/emulator-versions.d/groovymame"',
                      (ROOT / 'packaging/packages/fliperos-groovymame.sh').read_text())
        self.assertIn("git -C \"$dir\" log -1 --format='%h' > \"$STAGING/usr/local/share/fliperos/emulator-versions.d/openbor\"",
                      (ROOT / 'packaging/packages/fliperos-openbor.sh').read_text())
        # Os que vem em pacote gravam a versao em emulator-versions.d.
        for name in ('retroarch', 'flycast', 'keisho'):
            self.assertIn("git -C \"$dir\" log -1 --format='%%cs %%h' > "
                          "\"$STAGING/usr/local/share/fliperos/emulator-versions.d/%s\"" % name,
                          (ROOT / ('packaging/packages/fliperos-%s.sh' % name)).read_text())

    def test_install_calls_the_installer_of_each_kind(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            calls = tmp / 'calls'
            for name in ('fightcade', 'duckstation', 'kof'):
                (tmp / name).write_text('#!/bin/sh\necho "%s $* HOME=$HOME" >> "%s"\n' % (name, calls))
                (tmp / name).chmod(0o755)
            env = {'FLIPEROS_FIGHTCADE': str(tmp / 'fightcade'),
                   'FLIPEROS_DUCKSTATION': str(tmp / 'duckstation'),
                   'FLIPEROS_KOF': str(tmp / 'kof'), 'FLIPEROS_HOME': str(tmp / 'home'),
                   'FLIPEROS_USER': 'root', 'FLIPEROS_EMULATORS_ROOT': str(tmp / 'root')}
            run = self.run_cmd('fliperos-emulators', 'install', 'fightcade', '--progress', env=env)
            self.assertEqual(run.returncode, 0, run.stderr)
            self.run_cmd('fliperos-emulators', 'install', 'duckstation', '--progress', env=env)
            self.run_cmd('fliperos-emulators', 'install', 'kof', '--progress', '--source', '/media/usb/KOF', env=env)
            # Sem a pasta, o KOF baixa o jogo do itch.io.
            self.run_cmd('fliperos-emulators', 'install', 'kof', '--progress', env=env)
            self.assertEqual(calls.read_text().splitlines(),
                             ['fightcade fetch --progress HOME=%s' % os.environ.get('HOME', ''),
                              'duckstation fetch --progress HOME=%s' % os.environ.get('HOME', ''),
                              'kof install /media/usb/KOF --progress HOME=%s' % (tmp / 'home'),
                              'kof install --progress HOME=%s' % (tmp / 'home')])
            # O que vem compilado na imagem nao se instala daqui.
            run = self.run_cmd('fliperos-emulators', 'install', 'flycast', '--progress', env=env)
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail Flycast (Dreamcast, Naomi, Atomiswave)|it comes compiled in the FliperOS image',
                          run.stdout)

    def test_update_removes_supermodel_only_after_keisho(self):
        # O Model 3 passou ao Keisho: o update tira o Supermodel so depois que
        # o pacote do Keisho chegou (sem ele, o gabinete ficaria sem Model 3).
        update = (ROOT / 'tools/cabinet-update.sh').read_text()
        step = update.split('echo "== Model 2 and 3 in Keisho (Supermodel removed)"')[1].split('\nfi\n')[0]
        self.assertIn('if dpkg -s fliperos-keisho > /dev/null 2>&1; then', step)
        self.assertIn('purge -y -q fliperos-supermodel', step)
        self.assertIn('fliperos-sm2emu --migrate', step)
        self.assertIn('sed -i "s/^${key}_supermodel=/${key}_fliperos-model3=/"', step)
        self.assertLess(update.index('packages-sync.sh'), update.index('purge -y -q fliperos-supermodel'))
        listed = {l.split('\t')[0]: l.split('\t')[3] for l in (ROOT / 'updates/packages.list').read_text().splitlines()
                  if l and not l.startswith('#')}
        self.assertEqual(listed.get('fliperos-keisho'), 'always')
        self.assertNotIn('fliperos-supermodel', listed)
        self.assertFalse((ROOT / 'packaging/packages/fliperos-supermodel.sh').exists())
        self.assertIn('frontends_supermodel_gone\n  frontends_configure', update)

    def test_sm2emu_folders_move_to_keisho(self):
        # O SM2-Emu virou Keisho (keisho, ~/.config/keisho/keisho.ini,
        # ~/.local/share/keisho): o fonte, a configuracao e os dados vao para
        # as pastas novas, e o fonte passa a puxar do repositorio novo. Com so
        # o binario velho, o update recompila.
        with tempfile.TemporaryDirectory() as tmp:
            home = Path(tmp)
            old = home / '.local/src/sm2-emu'
            subprocess.run(['git', 'init', '-q', str(old)], check=True)
            subprocess.run(['git', '-C', str(old), 'remote', 'add', 'origin',
                            'https://github.com/dmanlfc/sm2-emu.git'], check=True)
            (old / 'build/bin').mkdir(parents=True)
            (old / 'build/bin/sm2-emu').write_text('')
            (old / 'build/bin/sm2-emu').chmod(0o755)
            (home / '.config/sm2-emu').mkdir(parents=True)
            (home / '.config/sm2-emu/sm2-emu.ini').write_text('vsync = false\n')
            (home / '.config/sm2-emu/.fliperos-vsync').write_text('')
            (home / '.local/share/sm2-emu/screenshots').mkdir(parents=True)
            env = {'HOME': str(home), 'XDG_CONFIG_HOME': '', 'XDG_DATA_HOME': '',
                   'FLIPEROS_SM2_SRC': '', 'FLIPEROS_SM2_PATCHES': str(home / 'none')}
            self.assertEqual(self.run_cmd('fliperos-sm2emu', '--migrate', env=env).returncode, 0)
            new = home / '.local/src/keisho'
            self.assertFalse(old.exists())
            self.assertTrue((new / 'build/bin/sm2-emu').exists())
            self.assertEqual(subprocess.run(['git', '-C', str(new), 'remote', 'get-url', 'origin'],
                                            capture_output=True, text=True).stdout.strip(),
                             'https://github.com/Keisho-Emu/Keisho.git')
            self.assertEqual((home / '.config/keisho/keisho.ini').read_text(), 'vsync = false\n')
            self.assertTrue((home / '.config/keisho/.fliperos-vsync').exists())
            self.assertFalse((home / '.config/sm2-emu').exists())
            self.assertTrue((home / '.local/share/keisho/screenshots').is_dir())
            # Uma segunda vez nao mexe em nada.
            self.assertEqual(self.run_cmd('fliperos-sm2emu', '--migrate', env=env).returncode, 0)
            self.assertEqual((home / '.config/keisho/keisho.ini').read_text(), 'vsync = false\n')
        x11 = (ROOT / 'config/fliperos-x11-run').read_text()
        self.assertLess(x11.index('"$sm2emu" --migrate'), x11.index('cfg=${XDG_CONFIG_HOME:-$HOME/.config}/keisho'))

    def test_duckstation_fetch_extracts_the_appimage(self):
        # A licenca do DuckStation nao deixa redistribuir: o AppImage oficial
        # vem do GitHub dele na instalacao e e extraido (sem FUSE).
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            image = tmp / 'DuckStation-x64.AppImage'
            image.write_text('#!/bin/sh\n[ "$1" = --appimage-extract ] || exit 1\nmkdir -p squashfs-root\n'
                             'printf "#!/bin/sh\\n" > squashfs-root/AppRun\nchmod 755 squashfs-root/AppRun\n'
                             'echo png > squashfs-root/org.duckstation.DuckStation.png\n')
            folders = tmp / 'roms.sh'
            folders.write_text('#!/bin/sh\necho ran > "%s/roms.ran"\n' % tmp)
            folders.chmod(0o755)
            env = {'DUCKSTATION_DIR': str(tmp / 'opt/duckstation'), 'DUCKSTATION_BIN': str(tmp / 'bin/duckstation'),
                   'DUCKSTATION_ICON': str(tmp / 'pixmaps/duckstation.png'), 'DUCKSTATION_URL': image.as_uri(),
                   'FLIPEROS_ROMS_SCRIPT': str(folders), 'FLIPEROS_USER': 'root'}
            run = self.run_cmd('fliperos-duckstation', 'fetch', '--progress', env=env)
            self.assertEqual(run.returncode, 0, run.stderr)
            self.assertIn('@step 100 DuckStation installed', run.stdout)
            self.assertTrue(os.access(tmp / 'opt/duckstation/AppRun', os.X_OK))
            self.assertEqual((tmp / 'bin/duckstation').read_text(),
                             '#!/bin/sh\nexec %s/AppRun "$@"\n' % (tmp / 'opt/duckstation'))
            self.assertEqual((tmp / 'pixmaps/duckstation.png').read_text(), 'png\n')
            self.assertTrue((tmp / 'roms.ran').exists())
            # Outro arquivo no lugar do AppImage: falha, e o instalado fica.
            image.write_text('#!/bin/sh\nexit 1\n')
            run = self.run_cmd('fliperos-duckstation', 'fetch', '--progress', env=env)
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail DuckStation|the downloaded file is not the DuckStation AppImage', run.stdout)
            self.assertTrue((tmp / 'opt/duckstation/AppRun').exists())
        # Os atalhos: o menu do desktop, o fliperos-launch e o modo do X.
        desktop = (ROOT / 'config/applications/fliperos-duckstation.desktop').read_text()
        self.assertIn('Exec=/opt/fliperos/bin/fliperos-launch duckstation\n', desktop)
        launch = (ROOT / 'config/fliperos-launch').read_text()
        self.assertIn('  duckstation) label=DuckStation run=("$x11" duckstation) ;;', launch)
        self.assertRegex((ROOT / 'config/fliperos-emulator-modes.conf').read_text(),
                         r'(?m)^duckstation +640x240@60 +640x480@60$')
        self.assertIn('install -Dm755 "$src/config/fliperos-duckstation" '
                      '"$root/opt/fliperos/bin/fliperos-duckstation"', ROOTFS)

    def kof_repo(self, tmp, converter):
        repo = tmp / 'patch-repo'
        repo.mkdir()
        (repo / 'converter-ikemen.sh').write_text(converter)
        git = ['git', '-C', str(repo), '-c', 'user.name=t', '-c', 'user.email=t@t']
        subprocess.run(['git', 'init', '-q', str(repo)], check=True, capture_output=True)
        subprocess.run(git + ['add', '.'], check=True, capture_output=True)
        subprocess.run(git + ['commit', '-qm', 'x'], check=True, capture_output=True)
        return repo

    @unittest.skipUnless(shutil.which('git'), 'sem git')
    def test_kof_install_converts_a_copy_and_leaves_the_game_alone(self):
        # O conversor do patch (aqui um de mentira) roda de dentro de "Patch
        # 4x3" na pasta do jogo e escreve a copia em -Out.
        converter = ('#!/bin/bash\n[ -f "$(dirname "$0")/../Final Attack.exe" ] || exit 3\n'
                     'while [ $# -gt 0 ]; do [ "$1" = -Out ] && out=$2; shift; done\n'
                     '[ -n "$FAIL" ] && exit 1\nmkdir -p "$out" && echo "$KIND" > "$out/Ikemen_GO_Linux"\n')
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            game = tmp / 'usb' / 'KOF' / 'Final Attack'
            game.mkdir(parents=True)
            (game / 'Final Attack.exe').write_text('x')
            dest = tmp / 'home' / 'roms' / 'ikemen' / 'kof-final-attack'
            env = {'HOME': str(tmp / 'home'), 'FLIPEROS_KOF_REPO': str(self.kof_repo(tmp, converter)),
                   'FLIPEROS_KOF_DIR': str(dest), 'FLIPEROS_KOF_CACHE': str(tmp / 'cache'), 'KIND': 'first',
                   'GIT_CONFIG_GLOBAL': '/dev/null'}
            self.assertEqual(self.run_cmd('fliperos-kof', 'installed', env=env).returncode, 1)
            # A pasta escolhida pode ser a de cima.
            self.assertEqual(self.run_cmd('fliperos-kof', 'find', str(tmp / 'usb'), env=env).stdout.strip(), str(game))
            self.assertEqual(self.run_cmd('fliperos-kof', 'find', str(tmp / 'home'), env=env).returncode, 1)
            run = self.run_cmd('fliperos-kof', 'install', str(tmp / 'usb'), '--progress', env=env)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
            self.assertIn('@step 100 KOF Final Attack installed', run.stdout)
            self.assertEqual((dest / 'Ikemen_GO_Linux').read_text(), 'first\n')
            self.assertTrue(os.access(dest / 'Ikemen_GO_Linux', os.X_OK))
            self.assertEqual(self.run_cmd('fliperos-kof', 'installed', env=env).returncode, 0)
            # A pasta original fica como estava.
            self.assertEqual(sorted(p.name for p in game.iterdir()), ['Final Attack.exe'])
            # De novo com falha: a instalacao anterior volta.
            run = self.run_cmd('fliperos-kof', 'install', str(game), '--progress', env=dict(env, FAIL='1'))
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail KOF Final Attack|the conversion failed', run.stdout)
            self.assertEqual((dest / 'Ikemen_GO_Linux').read_text(), 'first\n')
            run = self.run_cmd('fliperos-kof', 'install', str(game), env=dict(env, KIND='second'))
            self.assertEqual(run.returncode, 0, run.stderr)
            self.assertEqual((dest / 'Ikemen_GO_Linux').read_text(), 'second\n')
            self.assertFalse(Path(str(dest) + '.old').exists())
            # Sem o jogo na pasta: nada a fazer.
            run = self.run_cmd('fliperos-kof', 'install', str(tmp / 'home'), '--progress', env=env)
            self.assertIn('@fail KOF Final Attack|no "Final Attack.exe"', run.stdout)

    @unittest.skipUnless(shutil.which('git'), 'sem git')
    def test_kof_install_downloads_the_game_when_no_folder_is_given(self):
        # Sem pasta, o zip do jogo (o do itch.io; aqui um file://) e baixado,
        # aberto, convertido e apagado.
        converter = ('#!/bin/bash\n[ -f "$(dirname "$0")/../Final Attack.exe" ] || exit 3\n'
                     'while [ $# -gt 0 ]; do [ "$1" = -Out ] && out=$2; shift; done\n'
                     'mkdir -p "$out" && echo ok > "$out/Ikemen_GO_Linux"\n')
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            archive = tmp / 'the-king-of-fighters-final-attack-win.zip'
            with zipfile.ZipFile(archive, 'w') as z:
                z.writestr('Final Attack.exe', 'x')
                z.writestr('data/mugen.cfg', '')
            dest = tmp / 'home' / 'roms' / 'ikemen' / 'kof-final-attack'
            download = tmp / 'home' / 'kof-game'
            env = {'HOME': str(tmp / 'home'), 'FLIPEROS_KOF_REPO': str(self.kof_repo(tmp, converter)),
                   'FLIPEROS_KOF_DIR': str(dest), 'FLIPEROS_KOF_CACHE': str(tmp / 'cache'),
                   'FLIPEROS_KOF_ZIP': archive.as_uri(), 'FLIPEROS_KOF_DOWNLOAD': str(download),
                   'FLIPEROS_KOF_DOWNLOAD_KB': '1', 'GIT_CONFIG_GLOBAL': '/dev/null'}
            run = self.run_cmd('fliperos-kof', 'install', '--progress', env=env)
            self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
            steps = [int(line.split()[1]) for line in run.stdout.splitlines() if line.startswith('@step ')]
            self.assertEqual(steps, sorted(steps))
            self.assertIn('@step 0 Downloading the game from itch.io', run.stdout)
            self.assertIn('@step 100 KOF Final Attack installed', run.stdout)
            self.assertEqual((dest / 'Ikemen_GO_Linux').read_text(), 'ok\n')
            self.assertFalse(download.exists())
            self.assertFalse(Path(str(download) + '.zip').exists())
            # Outro arquivo no lugar do zip: falha, e o instalado fica.
            archive.write_text('not a zip')
            run = self.run_cmd('fliperos-kof', 'install', '--progress', env=env)
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail KOF Final Attack|the downloaded file is not a zip of the game', run.stdout)
            self.assertEqual((dest / 'Ikemen_GO_Linux').read_text(), 'ok\n')
            self.assertFalse(download.exists())
            # Com outra instalacao rodando (o lock preso), esta nao comeca.
            lock = download.parent / 'kof-install.lock'
            with subprocess.Popen(['flock', str(lock), 'sleep', '30']) as held:
                try:
                    for _ in range(50):
                        if subprocess.run(['flock', '-n', str(lock), 'true']).returncode:
                            break
                        time.sleep(0.1)
                    run = self.run_cmd('fliperos-kof', 'install', '--progress', env=env)
                finally:
                    held.kill()
            self.assertEqual(run.returncode, 1)
            self.assertIn('@fail KOF Final Attack|KOF Final Attack is already being installed', run.stdout)
            self.assertNotIn('Downloading', run.stdout)

    def test_kof_opens_at_320x240_from_the_desktop_and_the_console(self):
        modes = (ROOT / 'config/fliperos-emulator-modes.conf').read_text()
