class OsdTests(unittest.TestCase):
    """A OSD (config/fliperos-osd): o menu por cima do jogo, as contas da
    geometria e o arquivo que as camadas leem. O desenho nas camadas e testado por
    tools/deflicker-test.sh e tools/vkfps-test.sh."""

    SWITCHRES = (
        'Switchres: Monitor range 15625.00-15750.00,49.50-65.00,2.000,4.700,8.000,0.064,0.192,1.024,0,0,192,288,448,576\n'
        'Switchres: Calculating best video mode for 640x480@60.000000 orientation: normal\n'
        'Switchres: Modeline "640x480_60i 15.690000KHz 60.000000Hz" 13.336500 640 665 727 850 480 487 493 523 interlace  -hsync -vsync\n'
        'Adjusted geometry (0.900:5:-2) H: 1.875, 4.649, 9.223 V: 0.446, 0.382, 1.211\n')

    def setUp(self):
        import importlib.machinery
        import importlib.util
        loader = importlib.machinery.SourceFileLoader('fliperos_osd', str(ROOT / 'config/fliperos-osd'))
        spec = importlib.util.spec_from_loader('fliperos_osd', loader)
        self.osd = importlib.util.module_from_spec(spec)
        loader.exec_module(self.osd)
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.conf = Path(self.tmp.name) / 'fliperos.conf'
        self.conf.write_text('monitor=generic_15\n')
        self.osd.CONF = str(self.conf)
        self.calls = []
        self.osd.run = self.fake_run
        self.osd.process_env = lambda pid: {}
        self.osd.X11Modes.counter = itertools.count(1)
        # Sem GunCon 2, a nao ser no teste dela (o /sys da maquina nao entra).
        self.osd.SYS_INPUT = str(Path(self.tmp.name) / 'input')
        # Os perfis da OSD num arquivo do teste.
        self.osd.PROFILES = str(Path(self.tmp.name) / 'osd-profiles.conf')

    MODE = {'clock': 13038, 'h': [640, 666, 727, 831], 'v': [480, 483, 489, 523], 'interlace': True}

    def fake_run(self, args, timeout=30, env=None):
        self.calls.append(args)
        out, code = '', 0
        if args[0] == self.osd.XRANDR and args[1:] == ['--current']:
            out = ('Screen 0: minimum 320 x 200, current 640 x 480\nVGA-1 connected 640x480+0+0 (normal) 0mm x 0mm\n'
                   '   SR-1_640x480@60.00i  60.00*\n   640x240  60.00 +\nHDMI-A-1 disconnected (normal)\n')
        if args[1:] == ['--volume', 'state']:
            out = '80 on\n'
        elif args[1:] == ['--settings']:
            out = ('color.brightness|Colour|Brightness|number|0|-50..50:1|h\ncolor.gamma|Colour|Gamma|number|100|50..200:5|h\n'
                   'color.range|Colour|RGB range|choice|default|default=Card default;full=Full|h\n'
                   'color.reset|Colour|Back|action|||h\nlatency|System|Latency|choice|low|low=Low|h\n'
                   'gun_flash|GunCon 2|Screen flash|choice|pulse|pulse=Pulse;hold=Hold;off=Off|h\n'
                   'gun.flash_level|GunCon 2|Flash brightness (%)|number|100|10..100:10|h\n'
                   'gun.edge_pct|GunCon 2|Edge band (%)|number|12|0..30:1|h\n'
                   'gun_offscreen_reload|GunCon 2|Off-screen reload button|choice|on|on=On;off=Off|h\n'
                   'gun.reset|GunCon 2|Back to the defaults|action|||h\n'
                   + getattr(self, 'settings_extra', ''))
        elif args[1:] == ['mode']:
            out = '13038 640 666 727 831 480 483 489 523 1\n'
        elif args[0] == self.osd.SWITCHRES:
            out = self.SWITCHRES
        return subprocess.CompletedProcess(args, code, out, '')

    def menu(self, screen=None, mode=None):
        worker = self.osd.Worker()
        return self.osd.Menu(screen or {'program': 'pcsx2', 'core': ''}, mode or self.MODE, worker), worker

    def labels(self, menu):
        return [row.label for row in menu.page['rows']]

    def test_shortcut_keys_include_the_media_keys_of_a_wireless_remote(self):
        service = object.__new__(self.osd.Service)
        command = service.hotkey_command()
        keys = [command[i + 1] for i, word in enumerate(command) if word == '--key']
        self.assertEqual(keys, ['119', '164', '201', '207'])
        self.assertEqual(command[command.index('--combo') + 1], 'start+down')
        self.conf.write_text('osd_key=88, 0\nosd_combo=\n')
        self.assertEqual(service.hotkey_command(), [self.osd.BUTTONS, 'hotkey', '--key', '88'])
        # O fliperos-buttons aceita a opcao repetida, e o frontend continua com uma.
        source = (ROOT / 'config/fliperos-buttons').read_text()
        self.assertIn("p.add_argument('--key', type=int, action='append', default=[])", source)
        self.assertIn('any(code in keys for code in args.key)', source)

    def test_parse_switchres_gives_the_mode_and_the_final_range(self):
        result = self.osd.parse_switchres(self.SWITCHRES)
        self.assertEqual(result['mode'], {'clock': 13336, 'h': [640, 665, 727, 850], 'v': [480, 487, 493, 523], 'interlace': True,
                                          'sync': ['-HSync', '-VSync']})
        self.assertEqual(result['geometry'], (0.9, 5, -2))
        # As faixas do monitor ficam; so os seis tempos mudam (o geometry.py do Switchres).
        self.assertEqual(result['range'],
                         '15625.00-15750.00,49.50-65.00,1.875,4.649,9.223,0.446,0.382,1.211,0,0,192,288,448,576')
        self.assertIsNone(self.osd.parse_switchres('Switchres: nothing here\n'))

    def test_parse_mode_and_refresh_of_an_interlaced_mode(self):
        mode = self.osd.parse_mode('13038 640 666 727 831 480 483 489 523 1\n')
        self.assertEqual(mode, self.MODE)
        self.assertAlmostEqual(self.osd.mode_refresh(mode), 60.0, places=0)
        self.assertIsNone(self.osd.parse_mode('no mode\n'))

    def test_filter_level_is_the_one_the_layer_uses(self):
        conf = {'deflicker': 'light', 'deflicker_pcsx2': 'strong', 'deflicker_mame2010': 'off'}
        self.assertEqual(self.osd.filter_level(conf, 'pcsx2', ''), 'strong')
        self.assertEqual(self.osd.filter_level(conf, 'retroarch', 'mame2010'), 'off')
        self.assertEqual(self.osd.filter_level(conf, 'other', ''), 'light')
        self.assertEqual(self.osd.filter_level({}, 'other', ''), 'medium')

    def test_rows_stop_at_the_limits(self):
        changes = []
        row = self.osd.Row('number', 'x', 95, 0, 100, 5, change=changes.append)
        self.assertTrue(row.move(1))
        self.assertFalse(row.move(1))
        self.assertEqual((row.value, changes), (100, [100]))
        choice = self.osd.Row('choice', 'y', 'off', options=[('off', 'Off'), ('on', 'On')])
        self.assertFalse(choice.move(-1))
        self.assertTrue(choice.move(1))
        self.assertEqual(choice.text(), 'On')

    def config(self, screen=None, mode=None):
        """O menu ja na pagina Configuration."""
        menu, worker = self.menu(screen, mode)
        menu.open_page('config')
        return menu, worker

    def test_main_page_shows_the_filter_only_in_an_interlaced_mode(self):
        menu, _ = self.config()
        self.assertEqual(self.labels(menu), ['Save profile as', 'Delete profile', 'Interlaced filter', 'Geometry',
                                             'Colour', 'Save|Back'])
        menu, _ = self.config(mode=dict(self.MODE, interlace=False))
        self.assertEqual(self.labels(menu), ['Save profile as', 'Delete profile', 'Geometry', 'Colour', 'Save|Back'])
        # Num LCD nao ha geometria para ajustar.
        self.conf.write_text('monitor=lcd\n')
        menu, _ = self.config(mode=dict(self.MODE, interlace=False))
        self.assertEqual(self.labels(menu), ['Save profile as', 'Delete profile', 'Colour', 'Save|Back'])

    def test_custom_game_controller_configuration(self):
        # Um jogo custom (custom_GRUPO_NOME) com o mapa do controle rodando:
        # Controller configuration no lugar do Emulator menu. O teclado na
        # tela: Enter numa tecla pede o botao (o servico pergunta ao
        # gamekeys), o mesmo botao de novo limpa, Save grava o .key e manda
        # o gamekeys reler; Back sai sem gravar.
        osd = self.osd
        buttons = load_script('fliperos_buttons_osd', 'config/fliperos-buttons')
        calls = []
        buttons.gamekeys_call = lambda folder, command, timeout=2.0: calls.append((folder, command)) or 'ok'
        keyfile = Path(self.tmp.name) / 'Pang.key'
        keyfile.write_text('p1_b1=Z\n')
        gamekeys = {'folder': '/run/user/1000/fliperos-gamekeys', 'keyfile': str(keyfile), 'buttons': buttons}
        screen = {'program': 'custom_pc_games_pang', 'core': ''}
        menu = osd.Menu(screen, self.MODE, osd.Worker(), None, gamekeys)
        self.assertEqual(self.labels(menu), ['Configuration', 'Controller configuration', 'Close', 'Quit'])
        self.assertEqual(menu.page['rows'][1].icon, ('pad', 'CYAN'))
        # Sobre o frontend, nao; sem o gamekeys, nao.
        self.assertNotIn('Controller configuration',
                         self.labels(osd.Menu({'program': 'python3'}, self.MODE, osd.Worker(), None, gamekeys)))
        self.assertNotIn('Controller configuration', self.labels(osd.Menu(screen, self.MODE, osd.Worker())))
        menu.page['cursor'] = 1
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.title(), 'CONTROLLER')
        self.assertEqual(menu.osk_current(), '1')
        self.assertEqual(menu.osk_bound('Z'), [(1, 'b1')])
        # Ate o X (linha do Z, uma a direita).
        for key in (osd.KEY_DOWN, osd.KEY_DOWN, osd.KEY_DOWN):
            menu.key(key)
        self.assertEqual(menu.osk_current(), 'Z')
        menu.key(osd.KEY_RIGHT)
        self.assertEqual(menu.osk_current(), 'X')
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.capture_request, 'X')
        menu.key(osd.KEY_RIGHT)                     # esperando o botao: as teclas nao andam
        self.assertEqual(menu.osk_current(), 'X')
        menu.capture_done('p1_b2')
        self.assertEqual(menu.osk['map'], {(1, 'b1'): 'Z', (1, 'b2'): 'X'})
        menu.key(osd.KEY_ENTER)
        menu.capture_done('p1_b1')                  # o botao 1 sai do Z e vai para o X
        self.assertEqual(menu.osk['map'], {(1, 'b1'): 'X', (1, 'b2'): 'X'})
        menu.key(osd.KEY_ENTER)
        menu.capture_done('p1_b1')                  # de novo na mesma tecla: limpa
        self.assertEqual(menu.osk['map'], {(1, 'b2'): 'X'})
        menu.key(osd.KEY_ENTER)
        menu.capture_done('none')
        self.assertEqual(menu.status, 'NO BUTTON')
        menu.key(osd.KEY_ENTER)
        menu.capture_done(None)
        self.assertEqual(menu.status, 'NO CONTROLLER MAPPER')
        # Save, na linha de baixo (descendo do X chega no Clear all).
        for _ in range(5):
            menu.key(osd.KEY_DOWN)
        self.assertEqual(menu.osk_current(), 'clear')
        menu.key(osd.KEY_RIGHT)
        self.assertEqual(menu.osk_current(), 'save')
        menu.key(osd.KEY_ENTER)
        self.assertEqual([l for l in keyfile.read_text().splitlines() if not l.startswith('#')], ['p1_b2=X'])
        self.assertEqual(calls, [('/run/user/1000/fliperos-gamekeys', 'reload')])
        self.assertEqual(menu.status, 'SAVED')
        self.assertEqual(menu.osk['notice'], '')     # tinha mapa e ficou com mapa: nada muda
        # Clear all e Back: sai sem gravar.
        menu.key(osd.KEY_LEFT)
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.osk['map'], {})
        # Zerar e salvar muda o que o jogo ve: a OSD avisa que ele pode precisar reabrir.
        menu.key(osd.KEY_RIGHT)
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.osk['notice'], osd.KEYS_RESTART_NOTICE)
        self.assertNotIn('p1_b2', keyfile.read_text())
        keyfile.write_text('p1_b2=X\n')
        menu.key(osd.KEY_LEFT)
        menu.key(osd.KEY_ESC)
        self.assertEqual(menu.title(), 'FliperOS')
        self.assertIn('p1_b2=X', keyfile.read_text())
        # O servico acha o gamekeys pelo uid da camada e o arquivo current.
        service = object.__new__(osd.Service)
        service.buttons = buttons
        run_user = Path(self.tmp.name) / 'run'
        (run_user / '1000' / 'fliperos-gamekeys').mkdir(parents=True)
        (run_user / '1000' / 'fliperos-gamekeys' / 'current').write_text('%s\n99\n' % keyfile)
        old = osd.RUN_USER
        osd.RUN_USER = str(run_user)
        try:
            found = service.gamekeys({'program': 'custom_pc_games_pang', 'uid': 1000})
            self.assertEqual(found['keyfile'], str(keyfile))
            self.assertIsNone(service.gamekeys({'program': 'retroarch', 'uid': 1000}))
            self.assertIsNone(service.gamekeys({'program': 'custom_x', 'uid': 1001}))
        finally:
            osd.RUN_USER = old
        # A OSD nao toma o teclado virtual do gamekeys.
        self.assertIn('GAME_KEYS_NAME) and self.is_keyboard(keys)', (ROOT / 'config/fliperos-osd').read_text())

    def test_a_custom_game_without_keys_opens_the_controller_configuration(self):
        # O .key quase nunca vem pronto (a pessoa o faz pela OSD): um jogo
        # custom sem ele abre a OSD sozinha no Controller configuration, uma
        # vez por jogo aberto, depois de AUTO_KEYS_DELAY s na tela.
        osd = self.osd
        buttons = load_script('fliperos_buttons_osd_auto', 'config/fliperos-buttons')
        keyfile = Path(self.tmp.name) / 'New.key'
        service = object.__new__(osd.Service)
        service.keys_since = service.keys_asked = None
        service.gamekeys = lambda screen: {'folder': '/run/user/1000/fliperos-gamekeys', 'keyfile': str(keyfile),
                                           'buttons': buttons}
        allowed = [True]
        service.allowed = lambda screen: allowed[0]
        clock = [100.0]
        saved = osd.time.monotonic
        osd.time.monotonic = lambda: clock[0]
        try:
            screen = {'program': 'custom_pc_games_new', 'pid': 42, 'core': ''}
            self.assertFalse(service.auto_keys(screen))           # acabou de aparecer
            clock[0] += osd.AUTO_KEYS_DELAY / 2
            self.assertFalse(service.auto_keys(screen))
            clock[0] += osd.AUTO_KEYS_DELAY
            self.assertTrue(service.auto_keys(screen))
            self.assertFalse(service.auto_keys(screen))           # uma vez por jogo aberto
            # Aberto de novo (outro pid), ja com o .key (um Save, mesmo vazio): nao.
            keyfile.write_text(buttons.gamekeys_text({}))
            again = dict(screen, pid=43)
            service.auto_keys(again)
            clock[0] += osd.AUTO_KEYS_DELAY + 1
            self.assertFalse(service.auto_keys(again))
            keyfile.unlink()
            # Um emulador, o frontend, ou a OSD desligada (modo comercial...): nao.
            for other in ({'program': 'retroarch', 'pid': 50}, {'program': 'python3', 'pid': 51}):
                service.auto_keys(other)
                clock[0] += osd.AUTO_KEYS_DELAY + 1
                self.assertFalse(service.auto_keys(other), other)
            allowed[0] = False
            service.auto_keys(dict(screen, pid=60))
            clock[0] += osd.AUTO_KEYS_DELAY + 1
            self.assertFalse(service.auto_keys(dict(screen, pid=60)))
        finally:
            osd.time.monotonic = saved
        # O menu aberto direto no teclado: Back fecha (nao volta ao principal).
        gamekeys = service.gamekeys(screen)
        menu = osd.Menu(screen, self.MODE, osd.Worker(), None, gamekeys)
        menu.open_keys()
        menu.direct = True
        self.assertEqual(menu.title(), 'CONTROLLER')
        menu.key(osd.KEY_ESC)
        self.assertTrue(menu.closing)
        source = (ROOT / 'config/fliperos-osd').read_text()
        self.assertIn('elif self.auto_keys(screen):\n                self.open_menu(page="keys")', source)
        self.assertIn('if page == "keys" and menu.gamekeys:\n            menu.open_keys()\n            menu.direct = True', source)

    def test_controller_configuration_fits_any_frame(self):
        # O teclado e desenhado no quadro do jogo, como o menu: cabe em todos,
        # deitado e em pe, e a tecla esperando o botao fica amarela.
        painter = self.painter()
        t = painter.theme
        osd = self.osd
        buttons = load_script('fliperos_buttons_osd2', 'config/fliperos-buttons')
        keyfile = Path(self.tmp.name) / 'Pang.key'
        keyfile.write_text('p1_b1=Z\np1_up=UP\n')
        try:
            for orient, frame in (('', (320, 240)), ('', (256, 224)), ('', (384, 224)), ('', (640, 480)),
                                  ('', (160, 144)), ('vertical-cw', (256, 224)), ('vertical-cw', (640, 480))):
                t.set_orientation(orient)
                mode = {'clock': 6700, 'h': [frame[0], 0, 0, frame[0] + 64], 'v': [frame[1], 0, 0, frame[1] + 20],
                        'interlace': False}
                menu = osd.Menu({'program': 'custom_pc_games_pang', 'core': '', 'fps': 60.0}, mode, osd.Worker(),
                                None, {'folder': '/x', 'keyfile': str(keyfile), 'buttons': buttons})
                menu.open_keys()
                menu.capture_request = 'Z'
                canvas = painter.fit(lambda: painter.panel(menu), mode)
                self.assertEqual(canvas.get_size(), (320, 240))
                w, h = min(320, frame[0]), min(240, frame[1])
                painter.size = ((h, w) if orient else (w, h)) if (w, h) != (320, 240) else None
                try:
                    W, H = painter.area()
                    drawn = painter.panel(menu)
                finally:
                    painter.size = None
                self.assertEqual(drawn.get_size(), (W, H))
                # A caixa inteira dentro do quadro (o canto de cima tem a borda).
                box = drawn.get_bounding_rect()
                self.assertGreaterEqual(box.top, 0, (orient, frame))
                self.assertLessEqual(box.bottom, H, (orient, frame))
                self.assertGreater(box.height, 60, (orient, frame))
        finally:
            t.set_orientation('')

    def test_main_page_is_configuration_and_the_items(self):
        # A Configuration (os ajustes e o Save) e os itens com icone: Emulator
        # menu (so num emulador com menu proprio), Close e Quit (so num jogo:
        # sobre o frontend, nem um nem outro). O volume nao: e das teclas de
        # volume.
        osd = self.osd
        menu, _ = self.menu()
        self.assertEqual(self.labels(menu), ['Configuration', 'Close', 'Quit'])
        menu = osd.Menu({'program': 'retroarch', 'core': 'fbneo'}, self.MODE, osd.Worker(), emulator_key=59)
        self.assertEqual(self.labels(menu), ['Configuration', 'Emulator menu', 'Close', 'Quit'])
        self.assertEqual([getattr(r, 'icon', None) for r in menu.page['rows']],
                         [None, ('menu', 'CYAN'), ('close', 'RED'), ('quit', 'ORANGE')])
        self.assertEqual({r.kind for r in menu.page['rows'][1:]}, {'action'})
        menu = osd.Menu({'program': 'python3', 'core': ''}, self.MODE, osd.Worker(), emulator_key=59)
        self.assertEqual(self.labels(menu), ['Configuration', 'Close'])
        self.assertFalse([c for c in self.calls if '--volume' in c])
        # Configuration abre a pagina; o Back dela volta.
        menu, _ = self.menu()
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.title(), 'CONFIGURATION')
        menu.page['cursor'] = len(menu.page['rows']) - 1
        menu.key(osd.KEY_RIGHT)
        menu.key(osd.KEY_ENTER)
        self.assertEqual(menu.title(), 'FliperOS')
        # Emulator menu e Quit fecham a OSD e dizem ao servico o que fazer.
        for cursor, after in ((1, 'emulator'), (2, None), (3, 'quit')):
            menu = osd.Menu({'program': 'flycast', 'core': ''}, self.MODE, osd.Worker(), emulator_key=15)
            menu.page['cursor'] = cursor
            menu.key(osd.KEY_ENTER)
            self.assertEqual((menu.closing, menu.after), (True, after))
        # Os icones na frente dos itens, desenhados na cor deles.
        if importlib.util.find_spec('pygame'):
            os.environ['SDL_VIDEODRIVER'] = 'dummy'
            osd.GUI = str(ROOT / 'fliperos-setup/gui')
            painter = osd.Painter()
            menu = osd.Menu({'program': 'flycast', 'core': ''}, self.MODE, osd.Worker(), emulator_key=15)
            surface = painter.panel(menu)
            colours = {tuple(surface.get_at((x, y))[:3]) for x in range(surface.get_width())
                       for y in range(surface.get_height())}
            for name in ('CYAN', 'RED', 'ORANGE'):
                self.assertIn(getattr(painter.theme, name), colours)

    def test_service_presses_the_emulator_key_or_quits_the_game(self):
        # O servico: a tecla do menu de cada emulador pelo fliperos-buttons; o
        # Quit e o SIGTERM no jogo, e o SIGKILL se ele nao sair.
        import signal
        import types
        osd = self.osd
        service = object.__new__(osd.Service)
        service.buttons = load_script('buttons_osd', 'config/fliperos-buttons')
        pressed = []
        service.keys = types.SimpleNamespace(press=pressed.append)
        uid = os.getuid()
        self.assertEqual(service.emulator_key({'program': 'retroarch', 'uid': uid}), 59)
        self.assertEqual(service.emulator_key({'program': 'groovymame', 'uid': uid}), 15)
        self.assertIsNone(service.emulator_key({'program': 'supermodel', 'uid': uid}))
        self.assertIsNone(service.emulator_key({'program': 'python3', 'uid': uid}))
        sleep = osd.time.sleep
        osd.time.sleep = lambda s: None
        try:
            service.press_emulator_key(59)
        finally:
            osd.time.sleep = sleep
        self.assertEqual(pressed, [59])
        child = subprocess.Popen(['sleep', '30'])
        osd.QUIT_KILL = 0.5
        service.quit_game({'pid': child.pid})
        self.assertEqual(child.wait(5), -signal.SIGTERM)
        source = (ROOT / 'config/fliperos-osd').read_text()
        self.assertIn('name not in (self.pk.NAME, EMULATOR_KEYS, GAME_KEYS_NAME)', source)

    def test_scanlines_page_on_a_31_khz_monitor(self):
        # So com frequency=31k, como no Video Setup: a pagina Scanlines, com
        # ligar e cada ajuste (o escuro, a espessura, a altura, o brilho), pelo
        # --setting do Setup; as camadas releem o fliperos.conf com o jogo aberto.
        self.settings_extra = ('scanlines|Scanlines|Scanlines|choice|on|off=Off;on=On|h\n'
                               'scanline.strength|Scanlines|Darkness|number|50|5..100:5|h\n'
                               'scanline.thickness|Scanlines|Thickness|number|50|10..90:10|h\n'
                               'scanline.height|Scanlines|Line height|number|0|0..8:1|h\n'
                               'scanline.brightness|Scanlines|Brightness boost|number|115|100..200:5|h\n'
                               'scanline.reset|Scanlines|Back to the defaults|action|||h\n')
        self.conf.write_text('monitor=arcade_15_25_31\nfrequency=31k\nscanlines=on\n')
        menu, worker = self.config(mode=dict(self.MODE, interlace=False))
        labels = self.labels(menu)
        self.assertEqual(labels, ['Save profile as', 'Delete profile', 'Scanlines', 'Geometry', 'Colour', 'Save|Back'])
        menu.page['cursor'] = labels.index('Scanlines')
        menu.key(self.osd.KEY_ENTER)
        self.assertEqual(menu.title(), 'SCANLINES')
        self.assertEqual(self.labels(menu), ['Scanlines', 'Darkness', 'Thickness', 'Line height', 'Brightness boost',
                                             'Back to the defaults', 'Back'])
        self.assertEqual([r.text() for r in menu.page['rows'][:5]], ['On', '50%', '50%', 'Auto', '115%'])
        menu.key(self.osd.KEY_LEFT)                 # desligar
        menu.key(self.osd.KEY_DOWN)
        menu.key(self.osd.KEY_RIGHT)                # o escuro: 50 -> 55
        worker.wait()
        self.assertIn([self.osd.SETUP, '--setting', 'scanlines', 'off'], self.calls)
        self.assertIn([self.osd.SETUP, '--setting', 'scanline.strength', '55'], self.calls)
        menu.page['cursor'] = 5
        menu.key(self.osd.KEY_ENTER)
        worker.wait()
        self.assertIn([self.osd.SETUP, '--setting', 'scanline.reset', '1'], self.calls)
        self.conf.write_text('monitor=generic_15\nfrequency=15k\nscanlines=on\n')
        menu, _ = self.config(mode=dict(self.MODE, interlace=False))
        self.assertNotIn('Scanlines', self.labels(menu))

