def atom_load():
    return load_script('fliperos_atom15', 'config/fliperos-atom15')


def atom_rom(device=0x6613, size=0x10000, legacy=0xe000, efi=False, fill_blank=False):
    """Uma BIOS ATOM de mentira, com o que o patch le: a entrada, o INT 10h, a
    tabela de modos padrao, os timings VESA 640x480 e 1024x768."""
    rom = bytearray(size)
    rom[0:3] = bytes((0x55, 0xaa, legacy // 512))
    rom[3] = 0xe9
    struct.pack_into('<H', rom, 4, 0x100 - 6)
    rom[0x100:0x103] = bytes((0xa3, 0x1a, 0x02))
    struct.pack_into('<H', rom, 0x48, 0x200)
    rom[0x204:0x208] = b'ATOM'
    struct.pack_into('<H', rom, 0x200 + 18, 0x300)
    struct.pack_into('<H', rom, 0x200 + 28, 0x400)
    struct.pack_into('<H', rom, 0x200 + 32, 0x500)
    rom[0x400:0x404] = b'PCIR'
    struct.pack_into('<HH', rom, 0x404, 0x1002, device)
    struct.pack_into('<H', rom, 0x500 + 10, 0x600)
    struct.pack_into('<H', rom, 0x500 + 30, 0x800)
    # INT 10h: o desvio VESA e os dois call do original.
    rom[0x300:0x303] = bytes((0x80, 0xfc, 0x4f))
    rom[0x305] = 0xe8
    struct.pack_into('<H', rom, 0x306, 0x350 - 0x308)
    rom[0x30a] = 0xe8
    struct.pack_into('<H', rom, 0x30b, 0x360 - 0x30d)
    # Timings (DTD): 640x480 e 1024x768.
    struct.pack_into('<H', rom, 0x600, 4 + 2 * 28)
    for i, (number, w, h) in enumerate(((18, 640, 480), (20, 1024, 768))):
        struct.pack_into('<11HBBHBB', rom, 0x604 + i * 28, 2517, w, 160, h, 45, 16, 96, 10, 2, 0, 0, 0, 0, 0, number, 60)
    # A tabela VESA -> interno: 640x480 e 1024x768 em 8 bits.
    struct.pack_into('<H', rom, 0x800, 4 + 2 * 4)
    struct.pack_into('<HH', rom, 0x804, 0x101, 18 << 8 | 2)
    struct.pack_into('<HH', rom, 0x808, 0x105, 20 << 8 | 2)
    # A Video Parameter Table, do formato novo: so os modos 1, 3 e 12h.
    vpt = 0x1000
    for i, columns in ((1, 40), (3, 80), (27, 80)):
        rom[vpt + i * 64] = columns
    rom[vpt:vpt + 4] = bytes((0x28, 0x18, 0x08, 0x00))
    if efi:
        rom[legacy] = 0x55
        rom[legacy + 1] = 0xaa
        rom[legacy + 2] = (size - legacy) // 512
        rom[legacy + 28:legacy + 32] = b'PCIR'
    if fill_blank:
        rom[0xe000:0xffff] = b'\x5a' * (0xffff - 0xe000)
    rom[0x50] = (-sum(rom[:rom[2] * 512])) & 0xff
    return bytes(rom)


class AtomPatchTests(unittest.TestCase):
    """O ATOM-15 traduzido (config/fliperos-atom15). A comparacao com uma BIOS
    feita pelo atom-15.exe e o tools/atom15-check.py: a BIOS nao vem no repositorio."""

    def setUp(self):
        self.atom = atom_load()

    def test_hook_is_the_size_of_the_original(self):
        self.assertEqual(len(self.atom.HOOK), 532)
        self.assertEqual(self.atom.HOOK_LABELS['hook_end'], 532)
        self.assertEqual(self.atom.HOOK_LABELS['vesa_modes'] - self.atom.HOOK_LABELS['standard_modes'], 20)
        self.assertIn(self.atom.HOOK_MARK, self.atom.HOOK)

    def test_hook_matches_its_source(self):
        if not shutil.which('nasm'):
            self.skipTest('no nasm in this image')
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp) / 'hook.bin'
            subprocess.run(['nasm', '-f', 'bin', '-o', str(out), str(ROOT / 'tools/atom15-hook.asm')], check=True)
            self.assertEqual(out.read_bytes(), self.atom.HOOK)

    def test_registers_by_card(self):
        # R7 240 (Oland): DCE6, o mesmo caminho do DCE4. HD 5450, HD 4670 e R9 290.
        for device, kind in ((0x6613, 'dce4'), (0x68f9, 'dce4'), (0x9498, 'avivo'), (0x67b0, 'dce8'), (0x6938, 'dce8')):
            self.assertEqual(self.atom.pci_class(device), kind, hex(device))
        self.assertIsNone(self.atom.pci_class(0x1234))

    def test_modes_at_15_khz_as_the_real_tool(self):
        out, log = self.atom.patch(atom_rom(), {15})
        b = self.atom.Bios(out)
        # 640x480: os valores da BIOS feita pelo atom-15.exe do gabinete.
        ml = self.atom.timing_read(b, 0x604)
        self.assertEqual((ml['pclock'], ml['htotal'], ml['hbegin'], ml['hend'], ml['vtotal'], ml['vbegin'], ml['vend']),
                         (1300, 832, 664, 728, 521, 483, 489))
        self.assertEqual(ml['interlace'], 1)
        self.assertEqual(ml['number'], 18)
        # 1024x768 nao cabe em 15 kHz: sai do timing e da lista VESA.
        self.assertEqual(out[0x604 + 28 + 26], 0)
        self.assertEqual(struct.unpack_from('<H', out, 0x800)[0], 4 + 4)
        self.assertEqual(struct.unpack_from('<HH', out, 0x804), (0x101, 18 << 8 | 2))
        self.assertEqual(struct.unpack_from('<HH', out, 0x808), (0xffff, 0xffff))
        self.assertTrue(any('640x480' in line for line in log))

    def test_31_khz_keeps_480_progressive(self):
        out, _ = self.atom.patch(atom_rom(), {15, 31})
        ml = self.atom.timing_read(self.atom.Bios(out), 0x604)
        self.assertEqual(ml['interlace'], 0)

    def test_hook_is_wired_and_the_sum_is_kept(self):
        rom = atom_rom()
        out, _ = self.atom.patch(rom, {15})
        label = self.atom.HOOK_LABELS
        at = out.find(self.atom.HOOK_MARK) - (label['vesa_bios_service_mod'] + 2)
        self.assertGreaterEqual(at, 0xe000)
        self.assertEqual(self.atom.checksum(out), self.atom.checksum(rom))
        self.assertEqual(self.atom.checksum(out) & 0xff, 0)

        def call(where):
            return (struct.unpack_from('<H', out, where + 1)[0] + where + 3) & 0xffff

        # Os dois call da BIOS entram no hook, e o hook chama os de antes.
        self.assertEqual(call(0x30a), at + label['standard_bios_hook'])
        self.assertEqual(call(0x305), at + label['vesa_bios_hook'])
        self.assertEqual(call(at + label['standard_bios_service']), 0x360)
        self.assertEqual(call(at + label['vesa_bios_service']), 0x350)
        self.assertEqual(call(at + label['call_crtc3']), at + label['crtc_program_registers'])
        self.assertEqual(struct.unpack_from('<H', out, at + label['get_pci_bus'] + 3)[0], 0x21a)
        self.assertEqual(struct.unpack_from('<H', out, at + label['crtc1_enable_interlace'] + 1)[0], 0xc00)
        self.assertEqual(struct.unpack_from('<H', out, at + label['crtc_interlace_control_reg'] + 2)[0], 0x6e78)
        # 640x480 (o modo 101h) entrelacado; 1024x768 fora.
        table = at + label['vesa_modes']
        self.assertEqual(out[table + 1] & 1, 1)
        self.assertEqual(out[table + 5] & 1, 0)

    def test_composite_sync(self):
        out, _ = self.atom.patch(atom_rom(), {15}, csync=True)
        label = self.atom.HOOK_LABELS
        at = out.find(self.atom.HOOK_MARK) - (label['vesa_bios_service_mod'] + 2)
        self.assertEqual(out[at + label['crtc_enable_composite_sync']:at + label['crtc_enable_composite_sync'] + 2], b'\x90\x90')

    def test_refuses(self):
        rom = atom_rom()
        patched, _ = self.atom.patch(rom, {15})
        bad_sum = bytearray(rom)
        bad_sum[0x51] ^= 1
        no_entry = bytearray(rom)
        no_entry[3] = 0xeb
        no_entry[0x50] = (no_entry[0x50] + 0xe9 - 0xeb) & 0xff
        for image, text in ((patched, 'already has the ATOM-15 hook'),
                            (b'\0' * 4096, 'no 55 AA'),
                            (bytes(bad_sum), 'checksum'),
                            (bytes(no_entry), 'entry point'),
                            (atom_rom(device=0x1234), 'not in the ATOM-15 list'),
                            (atom_rom(fill_blank=True), 'No room for the hook')):
            with self.assertRaises(self.atom.Atom15Error) as e:
                self.atom.patch(image, {15})
            self.assertIn(text, str(e.exception))
        with self.assertRaises(self.atom.Atom15Error):
            self.atom.patch(rom, {20})

    def test_hook_never_lands_on_the_efi_part(self):
        # O branco so existe depois do fim da parte legada: dentro do EFI.
        rom = bytearray(atom_rom(legacy=0xd000, efi=True))
        with self.assertRaises(self.atom.Atom15Error) as e:
            self.atom.patch(bytes(rom), {15})
        self.assertIn('EFI part', str(e.exception))

    def test_efi_part_moves_when_it_can(self):
        # Parte legada ate 0xE200 sem branco; o GOP logo depois e empurrado.
        rom = bytearray(0x20000)
        base = atom_rom(legacy=0xe200, size=0x20000, efi=True, fill_blank=False)
        rom[:] = base
        rom[0xe000:0xe1f0] = b'\x5a' * 0x1f0
        rom[0xe200 + 32:0xffff] = b'\x5a' * (0xffff - (0xe200 + 32))
        rom[0xe1f0:0xe200] = bytes(16)
        rom[0xe200 + 2] = 16    # o GOP com 8 KB
        interior = bytearray(rom)
        rom[0xe203:0xe21c] = b'\x5a' * 25
        rom[0x50] = 0
        rom[0x50] = (-sum(rom[:rom[2] * 512])) & 0xff
        block = bytes(rom[0xe200:0xe200 + 16 * 512])
        # O maior branco de dentro do GOP: nao da para por o hook ali.
        interior[0x50] = 0
        interior[0x50] = (-sum(interior[:interior[2] * 512])) & 0xff
        with self.assertRaises(self.atom.Atom15Error) as e:
            self.atom.patch(bytes(interior), {15})
        self.assertIn('EFI part', str(e.exception))
        out, _ = self.atom.patch(bytes(rom), {15})
        b = self.atom.Bios(out)
        self.assertGreater(b.data[2] * 512, 0xe200)
        self.assertEqual(out[b.data[2] * 512 + 28:b.data[2] * 512 + 32], b'PCIR')
        self.assertEqual(out[b.data[2] * 512:b.data[2] * 512 + len(block)], block)

    def run_tool(self, *args, stdin=None):
        return subprocess.run(['python3', '-B', str(ROOT / 'config/fliperos-atom15'), *args], input=stdin,
                              capture_output=True, text=True)

    def test_command_line(self):
        with tempfile.TemporaryDirectory() as tmp:
            rom, out, log = Path(tmp) / 'a.rom', Path(tmp) / 'b.rom', Path(tmp) / 'b.log'
            rom.write_bytes(atom_rom())
            r = self.run_tool('info', str(rom))
            self.assertIn('device=6613\n', r.stdout)
            self.assertIn('class=dce4\n', r.stdout)
            self.assertIn('patched=0\n', r.stdout)
            r = self.run_tool('patch', str(rom), str(out), '--ranges', '15', '--log', str(log))
            self.assertEqual(r.returncode, 0, r.stderr)
            self.assertEqual(len(out.read_bytes()), 0x10000)
            self.assertIn('640x480', log.read_text())
            self.assertIn('patched=1\n', self.run_tool('info', str(out)).stdout)
            r = self.run_tool('patch', str(out), str(rom))
            self.assertEqual(r.returncode, 1)
            self.assertIn('already has', r.stderr)

    def test_flash_tool_list(self):
        old = ('adapter bn dn dID       asic           flash      romsize test    bios p/n    \n'
               '======= == == ==== =============== ============== ======= ==== ================\n'
               '   0    01 00 6613 Oland           W25X20          40000 pass  113-C4400100-X04\n'
               '   1    02 00 68F9 Cedar           M25P10/c        20000 fail  113-X\n')
        new = ('adapter seg  bn dn dID       asic           flash      romsize test    bios p/n    \n'
               '======= ==== == == ==== =============== ============== ======= ==== ================\n'
               '   0    0000 0A 00 67DF Polaris10       GD25Q80        100000 pass  113-1E3660E\n')
        self.assertEqual(self.run_tool('adapter', '01', '00', stdin=old).stdout, '0 262144 pass\n')
        self.assertEqual(self.run_tool('adapter', '02', '00', stdin=old).stdout, '1 131072 fail\n')
        self.assertEqual(self.run_tool('adapter', '0a', '00', stdin=new).stdout, '0 1048576 pass\n')
        self.assertEqual(self.run_tool('adapter', '03', '00', stdin=old).returncode, 1)
        self.assertEqual(self.run_tool('adapter', '01', '00', stdin='no adapters\n').returncode, 1)

    def test_installed_and_on_the_iso_check(self):
        self.assertIn('install -Dm755 "$src/config/fliperos-atom15" "$root/opt/fliperos/bin/fliperos-atom15"', ROOTFS)
        self.assertIn('multi-user.target.wants/fliperos-atom15-guard.service', ROOTFS)
        verify = (ROOT / 'tools/verify-iso.sh').read_text()
        self.assertIn('opt/fliperos/bin/fliperos-atom15', verify)
        self.assertIn('etc/systemd/system/fliperos-atom15-guard.service', verify)

    def test_flash_tool_is_never_downloaded_or_shipped(self):
        # A AMD nao publica o amdvbflash: a pessoa traz o arquivo.
        for path in ('fliperos-setup/lib/atom15.sh', 'fliperos-setup/screens/atom15.sh', 'fliperos-rootfs.sh', 'fliperos-mkiso.sh'):
            text = (ROOT / path).read_text()
            self.assertNotIn('github.com/stylesuxx', text, path)
            self.assertNotRegex(text, r'(curl|wget)[^\n]*amdvbflash', path)


class MkisoFunctionsTests(unittest.TestCase):
    """Toda funcao que o fliperos-mkiso.sh chama existe nele, fora dos heredocs."""

    @staticmethod
    def undefined_calls(text):
        # O texto de um heredoc (o script gravado no chroot) nao define nada
        # no mkiso: a install_fbneo_sets ficou dentro do RASCRIPT e o build da
        # 0.9.1 no GitHub parou em "command not found" depois de 1h23.
        outside, end = [], None
        for line in text.split('\n'):
            if end is not None:
                if line.strip() == end:
                    end = None
                continue
            outside.append(line)
            found = re.search(r"<<-?\s*['\"]?([A-Za-z_]\w*)['\"]?", line)
            if found and not line.lstrip().startswith('#'):
                end = found.group(1)
        code = '\n'.join(outside)
        defined = set(re.findall(r'^\s*([A-Za-z_]\w*)\(\)\s*\{', code, re.M))
        called = set(re.findall(r'^\s*([a-z]\w*_\w*)\s*$', code, re.M))
        return sorted(called - defined)

    def test_every_called_function_is_defined(self):
        self.assertEqual(self.undefined_calls(MKISO), [])

    def test_a_function_inside_a_heredoc_is_caught(self):
        script = "build_x() {\n  cat > /tmp/x.sh << 'EOF'\nhelper_y() {\n  :\n}\nEOF\n}\nbuild_x\nhelper_y\n"
        self.assertEqual(self.undefined_calls(script), ['helper_y'])


class PhysicalMediaTests(unittest.TestCase):
    """A midia fisica do frontend (gui/femedia.py): o console de cada disco,
    lido do proprio disco; os comandos que abrem o drive; o rip; e o caminho
    na tela, da fileira PHYSICAL MEDIA ao cartao, a lista dos cores e o boot
    pela midia."""

    @classmethod
    def setUpClass(cls):
        gui = str(ROOT / 'fliperos-setup/gui')
        sys.path.insert(0, gui)
        sys.dont_write_bytecode = True
        import femedia
        cls.fm = femedia

    @staticmethod
    def image(path, sectors):
        """Uma imagem de setores de 2048 bytes ({lba: bytes})."""
        data = bytearray((max(sectors) + 1) * 2048)
        for lba, raw in sectors.items():
            data[lba * 2048:lba * 2048 + len(raw)] = raw
        Path(path).write_bytes(bytes(data))
        return str(path)

    @staticmethod
    def iso(files, system=b'PLAYSTATION', volume=b''):
        """Os setores de um ISO9660: o PVD no 16, a raiz no 18 e cada arquivo
        num setor a partir do 20."""
        pvd = bytearray(2048)
        pvd[0], pvd[1:6] = 1, b'CD001'
        pvd[8:40], pvd[40:72] = system.ljust(32), volume.ljust(32)
        struct.pack_into('<I', pvd, 158, 18)
        struct.pack_into('<I', pvd, 166, 2048)
        root, sectors, p = bytearray(2048), {16: bytes(pvd)}, 0
        for i, (name, content) in enumerate([(b'\0', b''), (b'\1', b'')] + list(files.items())):
            if name not in (b'\0', b'\1'):
                name += b';1'
                sectors[20 + i] = content
            size = 34 + len(name) - (1 if len(name) % 2 else 0)
            rec = bytearray(size)
            rec[0] = size
            struct.pack_into('<I', rec, 2, 20 + i)
            struct.pack_into('<I', rec, 10, len(content))
            rec[32] = len(name)
            rec[33:33 + len(name)] = name
            root[p:p + size] = rec
            p += size
        sectors[18] = bytes(root)
        return sectors

    def test_each_console_is_read_from_the_disc(self):
        fm = self.fm
        saturn = bytearray(b'SEGA SEGASATURN '.ljust(0x100))
        saturn[0x20:0x2A], saturn[0x60:0x70] = b'MK-81009  ', b'NIGHTS INTO DREA'
        segacd = bytearray(b'SEGADISCSYSTEM  '.ljust(0x200))
        segacd[0x150:0x158], segacd[0x180:0x18E] = b'SONIC CD', b'GM MK-4407 -00'
        cases = {
            'ps1': (self.iso({b'SYSTEM.CNF': b'BOOT = cdrom:\\SLUS_000.67;1\r\nTCB = 4\r\n'}, volume=b'SLUS_000.67'),
                    {'console': 'psx', 'serial': 'SLUS-00067', 'title': ''}),
            'ps1-old': (self.iso({b'PSX.EXE': b'x'}, volume=b'RIDGE_RACER'),
                        {'console': 'psx', 'title': 'RIDGE RACER'}),
            'ps2': (self.iso({b'SYSTEM.CNF': b'BOOT2 = cdrom0:\\SCUS_973.28;1\nVER = 1.00\n'}, volume=b'GT4'),
                    {'console': 'ps2', 'serial': 'SCUS-97328', 'title': 'GT4'}),
            'saturn': ({0: bytes(saturn)}, {'console': 'saturn', 'serial': 'MK-81009', 'title': 'NIGHTS INTO DREA'}),
            'segacd': ({0: bytes(segacd)}, {'console': 'segacd', 'serial': 'MK-4407', 'title': 'SONIC CD'}),
            '3do': ({0: b'\x01' + b'\x5a' * 5 + b'\x01\x00'}, {'console': '3do'}),
            'pce': ({1: b'\0' * 0x20 + b'PC Engine CD-ROM SYSTEM'}, {'console': 'pce'}),
            'pcfx': ({0: b'PC-FX:Hu_CD-ROM '}, {'console': 'pcfx'}),
            'neocd': (self.iso({b'IPL.TXT': b'x'}, system=b'', volume=b'KOF96'), {'console': 'neocd'}),
            'dreamcast': ({0: b'SEGA SEGAKATANA SEGA ENTERPRISES'}, {'console': None, 'unsupported': 'DREAMCAST'}),
            'gamecube': ({0: b'\0' * 0x1C + b'\xc2\x33\x9f\x3d'}, {'console': None, 'unsupported': 'GAMECUBE'}),
            'pc': (self.iso({b'SETUP.EXE': b'x'}, system=b'WIN32', volume=b'DATA'), {'console': None}),
        }
        with tempfile.TemporaryDirectory() as tmp:
            for name, (sectors, want) in cases.items():
                sectors.setdefault(17, b'')
                info = fm.identify(self.image(Path(tmp) / name, sectors))
                self.assertEqual({k: info.get(k) for k in want}, want, name)
                self.assertFalse(info['dvd'], name)
            self.assertEqual(fm.identify(str(Path(tmp) / 'ps1'))['name'], 'Sony PlayStation')
            self.assertEqual(fm.identify(str(Path(tmp) / 'nothing'))['console'], None)
        self.assertEqual(fm.file_name({'title': 'Castlevania: SOTN', 'serial': 'SLUS-00067', 'name': 'x'}),
                         'Castlevania SOTN (SLUS-00067)')
        self.assertEqual(fm.file_name({'title': '', 'serial': 'SLUS-00067', 'name': 'Sony PlayStation'}),
                         'Sony PlayStation (SLUS-00067)')

    def test_drives_and_the_command_of_each_emulator(self):
        fm = self.fm
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            block = tmp / 'block'
            for name, sg in (('sr0', 'sg1'), ('sr1', None)):
                dev = block / name / 'device'
                (dev / ('scsi_generic/' + sg if sg else '')).mkdir(parents=True)
                (dev / 'vendor').write_text('ASUS\n')
                (dev / 'model').write_text('BW-16D1HT\n')
            (block / 'sda').mkdir()
            (tmp / 'dev').mkdir()
            (tmp / 'dev' / 'sr0').write_text('')
            bins = tmp / 'bin'
            bins.mkdir()
            for exe in ('duckstation', 'retroarch'):
                (bins / exe).write_text('#!/bin/sh\n')
                (bins / exe).chmod(0o755)
            cores = tmp / 'cores'
            cores.mkdir()
            (cores / 'mednafen_psx_libretro.so').write_text('')
            saved = (fm.SYS_BLOCK, fm.DEV_DIR, fm.RA_CORES, os.environ['PATH'])
            fm.SYS_BLOCK, fm.DEV_DIR, fm.RA_CORES = str(block), str(tmp / 'dev'), str(cores)
            os.environ['PATH'] = str(bins)
            try:
                drives = fm.scan()
                self.assertEqual([(d['key'], d['name'], d['model'], d['sg']) for d in drives],
                                 [('sr0', 'DRIVE 1', 'ASUS BW-16D1HT', 'sg1'), ('sr1', 'DRIVE 2', 'ASUS BW-16D1HT', None)])
                # Um arquivo comum nao responde ao ioctl do drive; o que nao existe tambem nao.
                self.assertEqual([d['state'] for d in drives], ['unknown', 'unknown'])
                options = fm.emulators('psx')
                self.assertEqual([(o['id'], o['folder'], o.get('missing')) for o in options],
                                 [('duckstation', 'ps1', None),
                                  ('retroarch:mednafen_psx_hw', 'retroarch/mednafen_psx_hw', True),
                                  ('retroarch:mednafen_psx', 'retroarch/mednafen_psx', False),
                                  ('retroarch:pcsx_rearmed', 'retroarch/pcsx_rearmed', True)])
                self.assertEqual(fm.pick('psx')['id'], 'duckstation')
                self.assertEqual(fm.pick('psx', 'retroarch:pcsx_rearmed')['id'], 'retroarch:pcsx_rearmed')
                self.assertEqual(fm.pick('psx', 'retroarch:sumiu')['id'], 'duckstation')
                # O Sega CD so tem o RetroArch; o PS2 so o PCSX2 (que nao esta aqui).
                self.assertEqual([o['id'] for o in fm.emulators('segacd')], ['retroarch:genesis_plus_gx'])
                self.assertIsNone(fm.pick('ps2'))
                kms, x11 = fm.BIN + '/fliperos-kms-run', fm.BIN + '/fliperos-x11-run'
                self.assertEqual(fm.command('psx', options[2], drives[0]),
                                 [kms, 'retroarch', '-L', str(cores / 'mednafen_psx_libretro.so'), 'cdrom://drive1.cue'])
                self.assertIsNone(fm.command('psx', options[2], drives[1]))
                self.assertEqual(fm.command('psx', options[0], drives[0]), [x11, 'duckstation', str(tmp / 'dev/sr0')])
                pcsx2 = {'id': 'pcsx2', 'core': None}
                self.assertEqual(fm.command('ps2', pcsx2, drives[0]), [x11, 'pcsx2', '-disc', str(tmp / 'dev/sr0')])
            finally:
                fm.SYS_BLOCK, fm.DEV_DIR, fm.RA_CORES, os.environ['PATH'] = saved

    def rip(self, image, folder, tools):
        """Roda o rip num processo (ele troca o SIGTERM) com as ferramentas
        falsas de tools no PATH; devolve as linhas que ele imprime."""
        code = ('import sys; sys.path.insert(0, %r); import femedia; femedia.DVD_BYTES = int(sys.argv[4]); '
                'sys.exit(femedia.rip(*sys.argv[1:4]))' % str(ROOT / 'fliperos-setup/gui'))
        env = dict(os.environ, PATH='%s:/usr/bin:/bin' % tools, HOME=str(Path(folder).parent))
        return subprocess.run([sys.executable, '-c', code, image, folder, 'Game (SLUS-00067)',
                               str(self.dvd)], capture_output=True, text=True, env=env, timeout=60).stdout

    def test_rip_makes_one_chd_or_keeps_the_cue(self):
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            image = self.image(tmp / 'disc', self.iso({b'SYSTEM.CNF': b'BOOT = cdrom:\\SLUS_000.67;1\n'}))
            tools = tmp / 'tools'
            tools.mkdir()
            scripts = {
                'cdrdao': '#!/bin/sh\nwhile [ $# -gt 1 ]; do [ "$1" = --datafile ] && data=$2; shift; done\n'
                          'printf bin > "$data"; printf toc > "$1"\n',
                'toc2cue': '#!/bin/sh\nprintf cue > "$2"\n',
                'chdman': '#!/bin/sh\nprintf chd > "$5"\n'}
            for name, text in scripts.items():
                (tools / name).write_text(text)
                (tools / name).chmod(0o755)
            self.dvd = 1 << 40
            out = tmp / 'roms' / 'ps1'
            lines = self.rip(image, str(out), tools).splitlines()
            self.assertEqual(lines[-1], '@done %s' % (out / 'Game (SLUS-00067).chd'))
            self.assertEqual(sorted(p.name for p in out.iterdir()), ['Game (SLUS-00067).chd'])
            self.assertTrue(any(line.startswith('@step 85 COMPRESSING') for line in lines))
            # O mesmo nome de novo ganha um (2); sem o chdman, ficam o .cue e o .bin.
            (tools / 'chdman').unlink()
            lines = self.rip(image, str(out), tools).splitlines()
            self.assertEqual(lines[-1], '@done %s' % (out / 'Game (SLUS-00067) (2).cue'))
            self.assertEqual(sorted(p.name for p in out.iterdir()),
                             ['Game (SLUS-00067) (2).bin', 'Game (SLUS-00067) (2).cue', 'Game (SLUS-00067).chd'])
            # O cdrdao que falha nao deixa nada para tras.
            (tools / 'cdrdao').write_text('#!/bin/sh\nexit 1\n')
            fresh = tmp / 'roms' / 'other'
            self.assertEqual(self.rip(image, str(fresh), tools).splitlines()[-1], '@fail could not read the disc')
            self.assertEqual(list(fresh.iterdir()), [])
            # Um DVD vira a imagem .iso, byte a byte.
            self.dvd = 0
            lines = self.rip(image, str(tmp / 'roms' / 'ps2'), tools).splitlines()
            iso = tmp / 'roms' / 'ps2' / 'Game (SLUS-00067).iso'
            self.assertEqual(lines[-1], '@done %s' % iso)
            self.assertEqual(iso.read_bytes(), Path(image).read_bytes())

    def test_strip_card_lists_and_boot_from_media(self):
        import types
        loader = SourceFileLoader('fliperos_frontend_media', str(ROOT / 'fliperos-setup/gui/fliperos-frontend'))
        fmod = types.ModuleType(loader.name)
        fmod.__file__ = loader.path
        loader.exec_module(fmod)
        real = self.fm
        options = {
            'psx': [{'id': 'duckstation', 'label': 'DUCKSTATION', 'icon': 'duckstation', 'folder': 'ps1', 'core': None},
                    {'id': 'retroarch:mednafen_psx_hw', 'label': 'BEETLE PSX HW', 'icon': 'retroarch',
                     'folder': 'retroarch/mednafen_psx_hw', 'core': 'mednafen_psx_hw', 'missing': True},
                    {'id': 'retroarch:mednafen_psx', 'label': 'BEETLE PSX', 'icon': 'retroarch',
                     'folder': 'retroarch/mednafen_psx', 'core': 'mednafen_psx', 'missing': False}],
            'segacd': [{'id': 'retroarch:genesis_plus_gx', 'label': 'GENESIS PLUS GX', 'icon': 'retroarch',
                        'folder': 'retroarch/genesis_plus_gx', 'core': 'genesis_plus_gx', 'missing': False}]}
        discs = {'psx': {'console': 'psx', 'name': 'Sony PlayStation', 'title': '', 'serial': 'SLUS-00067'},
                 'segacd': {'console': 'segacd', 'name': 'Sega CD', 'title': 'SONIC CD', 'serial': 'MK-4407'},
                 'bad': {'console': None, 'unsupported': 'DREAMCAST'}}
        now_disc = ['psx']
        fake = types.SimpleNamespace(
            identify=lambda dev: discs[now_disc[0]], emulators=lambda c: options[c],
            pick=lambda c, saved=None: next((o for o in options[c] if o['id'] == saved), options[c][0]),
            command=real.command, file_name=real.file_name)
        drive = {'key': 'sr0', 'kind': 'cd', 'name': 'DRIVE 1', 'model': 'ASUS', 'dev': '/dev/sr0', 'sg': 'sg1',
                 'state': 'disc', 'label': 'DISC'}
        fe = types.SimpleNamespace(fm=fake, devices=[drive], strip=None, picking=True, overlay=None, ov={},
                                   commercial=False, boot=None, media_emus={}, said=[], launched=[],
                                   view=types.SimpleNamespace(INSERT_TIME=0.8), letter_mode=None)
        fe.say = lambda text, *a: fe.said.append(text)
        fe.remember = lambda: None
        fe.cancel_pick = lambda: setattr(fe, 'picking', False)
        fe.launch = lambda argv, media=False: fe.launched.append((argv, media))
        for name in ('act', 'overlay_act', 'strip_act', 'device', 'media_open', 'media_card', 'media_labels',
                     'media_choose', 'media_list', 'media_act', 'media_play', 'media_tick', 'none_ov', 'boot_leave'):
            setattr(fe, name, types.MethodType(getattr(fmod.Frontend, name), fe))

        def read(disc):
            # O botao 1 no drive: READING, e depois o cartao (ou o aviso).
            now_disc[0] = disc
            fe.act('b1')
            self.assertEqual(fe.overlay, 'mediaload')
            deadline = time.monotonic() + 5
            while fe.ov.get('result') is None and time.monotonic() < deadline:
                time.sleep(0.02)
            fe.media_tick(time.monotonic() + 1)

        # Na tira, para baixo vai a fileira; o 2 fecha tudo.
        fe.act('down')
        self.assertEqual(fe.strip, 0)
        read('psx')
        self.assertEqual(fe.overlay, 'mediacard')
        self.assertEqual((fe.ov['title'], fe.ov['sub'], fe.ov['emu'], fe.ov['dest']),
                         ('Sony PlayStation', 'Sony PlayStation - SLUS-00067 - DRIVE 1', 'DUCKSTATION', 'ROMS/PS1'))
        # EMULATOR > RETROARCH > a lista dos cores > o segundo.
        fe.act('right')
        fe.act('b1')
        self.assertEqual([r['label'] for r in fe.ov['rows']], ['DUCKSTATION', 'RETROARCH'])
        self.assertTrue(fe.ov['rows'][0]['current'])
        fe.act('down')
        fe.act('b1')
        self.assertEqual((fe.ov['level'], [(r['label'], r['tag']) for r in fe.ov['rows']]),
                         ('cores', [('BEETLE PSX HW', 'DOWNLOAD'), ('BEETLE PSX', '')]))
        fe.act('down')
        fe.act('b1')
        self.assertEqual((fe.overlay, fe.ov['emu'], fe.media_emus), ('mediacard', 'RETROARCH - BEETLE PSX',
                                                                     {'psx': 'retroarch:mednafen_psx'}))
        # PLAY: direto do drive, pelo /dev/sg1.
        fe.act('left')
        fe.act('b1')
        self.assertEqual(fe.launched[-1][0][-1], 'cdrom://drive1.cue')
        self.assertTrue(fe.launched[-1][1])
        # O disco saiu com o cartao aberto: volta a fileira.
        drive['state'] = 'empty'
        fe.media_tick(time.monotonic())
        self.assertEqual((fe.overlay, fe.said[-1]), (None, 'DISC REMOVED'))
        fe.act('b1')
        self.assertEqual((fe.overlay, fe.said[-1]), (None, 'NO DISC IN DRIVE 1'))
        # Um core so: o RETROARCH vai direto nele.
        drive['state'] = 'disc'
        read('segacd')
        fe.act('right')
        fe.act('b1')
        self.assertEqual([r['label'] for r in fe.ov['rows']], ['RETROARCH'])
        fe.act('b1')
        self.assertEqual((fe.overlay, fe.said[-1]), ('mediacard', 'ONE CORE: GENESIS PLUS GX'))
        fe.act('b2')
        self.assertEqual(fe.overlay, None)
        read('bad')
        self.assertEqual((fe.overlay, fe.said[-1]), (None, 'DREAMCAST DISCS ARE NOT SUPPORTED'))
        # O 2 na fileira fecha a tira.
        fe.act('b2')
        self.assertEqual((fe.strip, fe.picking), (None, False))

        # O boot pela midia: sem disco, a tela pede; posto, a gaveta e o READING.
        fe.boot, drive['state'] = 'sr0', 'empty'
        fe.overlay, fe.ov = 'medianone', fe.none_ov()
        self.assertEqual(fe.ov['sub'], 'PUT A DISC IN DRIVE 1 TO CONTINUE')
        t = time.monotonic()
        fe.media_tick(t)
        self.assertEqual((fe.overlay, fe.ov['inserted']), ('medianone', None))
        drive['state'] = 'disc'
        now_disc[0] = 'bad'
        fe.media_tick(t)
        self.assertEqual(fe.ov['inserted'], t)
        fe.media_tick(t + 0.5)
        self.assertEqual(fe.overlay, 'medianone')
        fe.media_tick(t + 1.2)
        self.assertEqual(fe.overlay, 'mediaload')
        deadline = time.monotonic() + 5
        while fe.ov.get('result') is None and time.monotonic() < deadline:
            time.sleep(0.02)
        fe.media_tick(time.monotonic() + 1)
        # O disco que nao abre: a tela pede outro e nao o le de novo.
        self.assertEqual((fe.overlay, fe.ov['msg'], fe.ov['bad']), ('medianone', 'UNKNOWN DISC', True))
        fe.media_tick(time.monotonic() + 5)
        self.assertEqual(fe.overlay, 'medianone')
        drive['state'] = 'empty'
        fe.media_tick(time.monotonic())
        self.assertEqual((fe.ov['msg'], fe.ov['bad']), ('NO DISC', False))
        # O 2 sai para a lista.
        fe.act('b2')
        self.assertEqual((fe.overlay, fe.boot), (None, None))
        frontend = (ROOT / 'fliperos-setup/gui/fliperos-frontend').read_text()
        self.assertIn('if self.picking and self.strip is None and now - self.pick_at >= PICK_WAIT:', frontend)

    def fake_oscr(self, carts, files, firmware=True, bad_crc=False):
        """Um OSCR de mentira num pseudo-terminal, que responde como o firmware
        com o patch do FliperOS (patches/oscr, FLIPEROS.ino): devolve o
        caminho da porta e a lista dos comandos que recebeu."""
        import zlib
        master, slave = os.openpty()
        seen = []

        def serve():
            buf = b''
            while True:
                try:
                    chunk = os.read(master, 4096)
                except OSError:
                    return
                if not chunk:
                    return
                buf += chunk
                while b'\n' in buf:
                    raw, _, buf = buf.partition(b'\n')
                    cmd = raw.decode().strip()
                    seen.append(cmd)
                    out = b''
                    if not firmware:
                        out = b'OSCR: Unknown Command\n'
                    elif cmd == 'FLIPEROS':
                        out = b'FLIPEROS 1 SNES MD N64 GB GBA\n'
                    elif cmd == 'SCAN':
                        out = b''.join(('CART %s|%s|%d|%d\n' % c).encode() for c in carts) + b'END\n'
                    elif cmd.startswith('INFO '):
                        got = [c for c in carts if c[0] == cmd[5:]]
                        out = ('CART %s|%s|%d|%d\n' % got[0]).encode() if got else b'NONE\n'
                    elif cmd.startswith('DUMP '):
                        out = b''.join(b'FILE %s\n' % p.encode() for p in files) + b'END\n'
                    elif cmd.startswith('BAUD '):
                        out = b'OK\n'
                    elif cmd.startswith('GET '):
                        data = files[cmd[4:]]
                        crc = zlib.crc32(data) ^ (1 if bad_crc else 0)
                        out = b'SIZE %d\n' % len(data) + data + b'CRC %X\n' % crc
                    os.write(master, out)
        threading.Thread(target=serve, daemon=True).start()
        self.addCleanup(os.close, slave)
        return os.ttyname(slave), seen

    def test_oscr_ports_scan_and_dump_over_usb(self):
        fm = self.fm
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            # A porta do CH340 (1a86:7523) e outra de outro aparelho.
            for name, ids in (('ttyUSB0', ('1a86', '7523')), ('ttyUSB1', ('0403', '6001'))):
                usb = tmp / 'usb' / name / '1-1'
                (usb / '1-1:1.0' / name).mkdir(parents=True)
                (usb / 'idVendor').write_text(ids[0] + '\n')
                (usb / 'idProduct').write_text(ids[1] + '\n')
                (tmp / 'tty' / name).mkdir(parents=True)
                os.symlink(usb / '1-1:1.0' / name, tmp / 'tty' / name / 'device')
            (tmp / 'tty' / 'ttyS0').mkdir()
            saved = (fm.SYS_TTY, fm.DEV_DIR)
            fm.SYS_TTY, fm.DEV_DIR = str(tmp / 'tty'), '/dev'
            try:
                self.assertEqual([(d['key'], d['name'], d['dev'], d['label']) for d in fm.oscr_ports()],
                                 [('oscr', 'OSCR', '/dev/ttyUSB0', 'READY')])
            finally:
                fm.SYS_TTY, fm.DEV_DIR = saved
            rom, srm = bytes(range(256)) * 2048, b'\x5a' * 2048
            files = {'/SNES/ROM/SUPER MARIO WORLD/3/SUPER MARIO WORLD.sfc': rom,
                     '/SNES/SAVE/SUPER MARIO WORLD/4/SUPER MARIO WORLD.srm': srm}
            carts = [('SNES', 'SUPER MARIO WORLD', 524288, 2048), ('MD', 'SONIC THE HEDGEHOG 2', 1048576, 0)]
            port, seen = self.fake_oscr(carts, files)
            got = fm.oscr_call(port, 'scan')
            self.assertEqual(got['systems'], ['SNES', 'MD', 'N64', 'GB', 'GBA'])
            self.assertEqual([(c['system'], c['console'], c['title'], c['rom']) for c in got['carts']],
                             [('SNES', 'snes', 'SUPER MARIO WORLD', 524288), ('MD', 'md', 'SONIC THE HEDGEHOG 2', 1048576)])
            self.assertEqual(fm.oscr_call(port, 'info', 'N64'), {'carts': [], 'systems': got['systems']})
            # O dump: a ROM com o nome do jogo e o save ao lado (.srm), a 1 Mbaud.
            out = io.StringIO()
            saved_stdout, sys.stdout = sys.stdout, out
            try:
                self.assertEqual(fm.oscr_rip(port, 'SNES', str(tmp / 'snes9x'), 'Super Mario World'), 0)
            finally:
                sys.stdout = saved_stdout
                signal.signal(signal.SIGTERM, signal.SIG_DFL)
            self.assertEqual((tmp / 'snes9x' / 'Super Mario World.sfc').read_bytes(), rom)
            self.assertEqual((tmp / 'snes9x' / 'Super Mario World.srm').read_bytes(), srm)
            self.assertEqual(out.getvalue().splitlines()[-1], '@done %s' % (tmp / 'snes9x' / 'Super Mario World.sfc'))
            self.assertIn('BAUD 1000000', seen)
            self.assertIn('DUMP SNES', seen)
            # O arquivo estragado no caminho nao fica; o OSCR sem o firmware do FliperOS e dito.
            port, _ = self.fake_oscr(carts, files, bad_crc=True)
            out = io.StringIO()
            saved_stdout, sys.stdout = sys.stdout, out
            try:
                self.assertEqual(fm.oscr_rip(port, 'SNES', str(tmp / 'bad'), 'Super Mario World'), 1)
            finally:
                sys.stdout = saved_stdout
                signal.signal(signal.SIGTERM, signal.SIG_DFL)
            self.assertEqual(out.getvalue().splitlines()[-1], '@fail crc')
            self.assertEqual(list((tmp / 'bad').iterdir()), [])
            port, _ = self.fake_oscr(carts, files, firmware=False)
            self.assertEqual(fm.oscr_call(port, 'scan'), {'error': 'firmware'})
            # A conferencia do Setup depois de gravar (lib/oscr.sh, oscr_check).
            out = io.StringIO()
            saved_stdout, sys.stdout = sys.stdout, out
            try:
                self.assertEqual(fm.main(['oscr-hello', port]), 1)
                self.assertEqual(fm.main(['oscr-hello', self.fake_oscr(carts, files)[0]]), 0)
            finally:
                sys.stdout = saved_stdout
            self.assertEqual(out.getvalue().splitlines(),
                             ['the OSCR did not answer as FliperOS firmware: firmware', 'FLIPEROS 1 SNES MD N64 GB GBA'])

    def test_oscr_carts_systems_play_and_boot(self):
        import types
        loader = SourceFileLoader('fliperos_frontend_oscr', str(ROOT / 'fliperos-setup/gui/fliperos-frontend'))
        fmod = types.ModuleType(loader.name)
        fmod.__file__ = loader.path
        loader.exec_module(fmod)
        real = self.fm
        answers = []
        fake = types.SimpleNamespace(
            CONSOLES=real.CONSOLES, CARTS=real.CARTS, file_name=real.file_name, command=real.command,
            oscr_call=lambda dev, what, system=None: answers.pop(0),
            emulators=lambda c: [{'id': 'retroarch:snes9x', 'label': 'SNES9X', 'icon': 'retroarch',
                                  'folder': 'retroarch/snes9x', 'core': 'snes9x', 'missing': False}],
            pick=lambda c, saved=None: {'id': 'retroarch:snes9x', 'label': 'SNES9X', 'icon': 'retroarch',
                                        'folder': 'retroarch/snes9x', 'core': 'snes9x', 'missing': False})
        oscr = {'key': 'oscr', 'kind': 'oscr', 'name': 'OSCR', 'model': 'CART READER', 'dev': '/dev/ttyUSB0',
                'state': 'ready', 'label': 'READY'}
        fe = types.SimpleNamespace(fm=fake, devices=[oscr], strip=0, picking=True, overlay=None, ov={},
                                   commercial=False, boot=None, media_emus={}, said=[], launched=[], ripped=[],
                                   view=types.SimpleNamespace(INSERT_TIME=0.8), letter_mode=None)
        fe.say = lambda text, *a: fe.said.append(text)
        fe.remember = lambda: None
        fe.cancel_pick = lambda: None
        fe.launch = lambda argv, media=False: fe.launched.append(argv)
        fe.media_rip = lambda play=False: fe.ripped.append(play)
        for name in ('act', 'overlay_act', 'strip_act', 'device', 'media_open', 'media_card', 'media_labels',
                     'cart_info', 'oscr_result', 'media_act', 'media_play', 'media_tick', 'none_ov', 'boot_leave'):
            setattr(fe, name, types.MethodType(getattr(fmod.Frontend, name), fe))

        def settle():
            deadline = time.monotonic() + 5
            while fe.ov.get('result') is None and time.monotonic() < deadline:
                time.sleep(0.02)
            fe.media_tick(time.monotonic() + 1)

        systems = ['SNES', 'MD', 'N64', 'GB', 'GBA']
        smw = {'system': 'SNES', 'console': 'snes', 'title': 'SUPER MARIO WORLD', 'rom': 524288, 'save': 2048}
        sonic = {'system': 'MD', 'console': 'md', 'title': 'SONIC THE HEDGEHOG 2', 'rom': 1048576, 'save': 0}
        # Dois cartuchos: a escolha, e o cartao do escolhido.
        answers.append({'carts': [smw, sonic], 'systems': systems})
        fe.act('b1')
        self.assertEqual((fe.overlay, fe.ov['step']), ('mediaload', 'LOOKING AT EACH SLOT'))
        settle()
        self.assertEqual((fe.overlay, len(fe.ov['carts'])), ('mediacarts', 2))
        fe.act('b1')
        self.assertEqual((fe.overlay, fe.ov['title'], fe.ov['sub'], fe.ov['dest'], fe.ov['oscr']),
                         ('mediacard', 'SUPER MARIO WORLD', 'Super Nintendo - 4 MBIT - OSCR', 'ROMS/RETROARCH/SNES9X',
                          True))
        # PLAY le o cartucho antes; a copia lida abre no core.
        fe.act('b1')
        self.assertEqual(fe.ripped, [True])
        fe.overlay, fe.ov = 'mediarip', {'card': fe.ov, 'result': 'ok', 'play': True, 'path': '/c/smw.sfc'}
        fe.media_tick(time.monotonic())
        self.assertEqual((fe.overlay, fe.launched[-1][-1]), ('mediacard', '/c/smw.sfc'))
        self.assertEqual(fe.launched[-1][1:3], ['retroarch', '-L'])
        fe.act('b2')
        # Nenhum respondeu a 3,3 V: a lista dos sistemas, e o INFO do escolhido.
        answers.extend([{'carts': [], 'systems': systems}, {'carts': [sonic], 'systems': systems}])
        fe.act('b1')
        settle()
        self.assertEqual((fe.overlay, fe.ov['level'], [r['system'] for r in fe.ov['rows']]),
                         ('medialist', 'system', systems))
        fe.act('down')
        fe.act('b1')
        self.assertEqual(fe.ov['step'], 'READING THE MEGA DRIVE CART')
        settle()
        self.assertEqual((fe.overlay, fe.ov['title']), ('mediacard', 'SONIC THE HEDGEHOG 2'))
        fe.act('b2')
        # O OSCR sem o firmware do FliperOS.
        answers.append({'error': 'firmware'})
        fe.act('b1')
        settle()
        self.assertEqual((fe.overlay, fe.said[-1]), (None, 'THE OSCR NEEDS THE FliperOS FIRMWARE'))
        # O boot pelo OSCR: a tela pede o cartucho; o botao 1 o poe e ele e lido.
        fe.boot = 'oscr'
        fe.overlay, fe.ov = 'medianone', fe.none_ov()
        self.assertEqual((fe.ov['msg'], fe.ov['cart']), ('NO CARTRIDGE', True))
        t = time.monotonic()
        fe.media_tick(t)
        self.assertEqual(fe.ov['sub'], 'PUT A CARTRIDGE IN THE OSCR AND PRESS 1')
        fe.act('b1')
        answers.append({'carts': [smw], 'systems': systems})
        fe.media_tick(fe.ov['inserted'] + 1.2)
        self.assertEqual(fe.overlay, 'mediaload')
        settle()
        self.assertEqual((fe.overlay, fe.ov['title']), ('mediacard', 'SUPER MARIO WORLD'))
        fe.devices = []
        fe.overlay, fe.ov = 'medianone', fe.none_ov()
        fe.media_tick(time.monotonic())
        self.assertEqual(fe.ov['sub'], 'THE OSCR IS NOT CONNECTED')

    def test_media_screens_draw(self):
        import types
        try:
            import pygame
        except ImportError:
            self.skipTest('pygame')
        os.environ.setdefault('SDL_VIDEODRIVER', 'dummy')
        pygame.init()
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        try:
            import background
            import feview
        finally:
            sys.path.remove(str(ROOT / 'fliperos-setup/gui'))
        devices = [{'key': 'sr0', 'kind': 'cd', 'name': 'DRIVE 1', 'state': 'disc', 'label': 'DISC'},
                   {'key': 'sr1', 'kind': 'cd', 'name': 'DRIVE 2', 'state': 'empty', 'label': 'EMPTY'}]
        fe = types.SimpleNamespace(devices=devices, strip=1, start=0.0, bg=background.pick('stars', seed=1))
        ui = pygame.Surface((feview.WW, feview.HH), pygame.SRCALPHA)
        feview.draw_media_strip(fe, ui, 0.5)
        fe.ov = {'where': 'DRIVE 1 - ASUS (sr0)'}
        feview.draw_media_load(fe, ui, 0.5)
        for sel in range(3):
            fe.ov = {'title': 'A VERY LONG GAME TITLE THAT DOES NOT FIT', 'sub': 'SONY PLAYSTATION', 'sel': sel,
                     'icon': 'retroarch', 'emu': 'RETROARCH - BEETLE PSX', 'dest': 'ROMS/PS1'}
            feview.draw_media_card(fe, ui, 0.5)
        fe.ov = {'head': 'RETROARCH CORE', 'title': 'x', 'sel': 7, 'note': 'ONLY CORES THAT READ A REAL DISC',
                 'rows': [{'label': 'CORE %d' % i, 'icon': 'retroarch', 'tag': 'DOWNLOAD'} for i in range(9)]}
        feview.draw_media_list(fe, ui, 0.5)
        fe.ov = {'title': 'x', 'progress': (40, 100, 'READING 10 OF 600 MB'), 'dest': 'ROMS/PS1/X.CHD'}
        feview.draw_media_rip(fe, ui, 0.5)
        back = pygame.Surface((feview.WW, feview.HH))
        for inserted in (None, 0.2, 0.0):
            for cart in (False, True):
                fe.ov = {'since': 0.0, 'inserted': inserted, 'msg': 'NO DISC', 'sub': 'PUT A DISC IN DRIVE 1',
                         'cart': cart}
                feview.draw_media_none(fe, back, 0.5)
        fe.ov = {'sel': 1, 'carts': [{'system': 'SNES', 'console': 'snes', 'title': 'SUPER MARIO WORLD'},
                                     {'system': 'MD', 'console': 'md', 'title': 'SONIC THE HEDGEHOG 2'}]}
        feview.draw_media_carts(fe, ui, 0.5)


class JoypadMappingTests(unittest.TestCase):
    """config/fliperos-buttons com o painel de 8 botoes e o joypad (o mapeador do
    Batocera): o tipo de cada jogador, os analogicos, L3/R3, o hotkey e os gatilhos."""

    # O Steam Virtual Gamepad do banco do SDL (o layout de um Xbox 360).
    XBOX = ('03000000de280000ff11000001000000,Steam Virtual Gamepad,a:b0,b:b1,back:b6,dpdown:h0.4,dpleft:h0.8,'
            'dpright:h0.2,dpup:h0.1,guide:b8,leftshoulder:b4,leftstick:b9,lefttrigger:a2,leftx:a0,lefty:a1,'
            'rightshoulder:b5,rightstick:b10,righttrigger:a5,rightx:a3,righty:a4~,start:b7,x:b2,y:b3,'
            'platform:Linux,')
    RESTS = (0, 0, -32768, 0, 0, -32768)

    def setUp(self):
        self.rc = load_script('buttons', 'config/fliperos-buttons')

    def pad(self):
        return {c: (0, e) for c, e in self.rc.mapping_binds(self.XBOX).items()}

    def test_the_known_layout_comes_from_the_sdl_mapping(self):
        binds = self.rc.mapping_binds(self.XBOX)
        # Pela posicao: o de sul e o 4, o de leste o 5, o de oeste o 1, o de norte o 2.
        self.assertEqual((binds['b4'], binds['b5'], binds['b1'], binds['b2']), ('b0', 'b1', 'b2', 'b3'))
        self.assertEqual((binds['b3'], binds['b6'], binds['b7'], binds['b8']), ('b4', 'b5', '+a2', '+a5'))
        self.assertEqual((binds['coin'], binds['start'], binds['hotkey']), ('b6', 'b7', 'b8'))
        self.assertEqual((binds['l3'], binds['r3'], binds['up']), ('b9', 'b10', 'h0.1'))
        # O analogico pelo sentido de cima e da esquerda; "~" e ao contrario.
        self.assertEqual((binds['lsup'], binds['lsleft'], binds['rsleft'], binds['rsup']),
                         ('-a1', '-a0', '-a3', '+a4'))

    def test_the_pad_goes_to_sdl_as_it_is(self):
        line = self.rc.sdl_mapping_line('guid', 'Pad', self.pad(), self.rc.SDL_PAD_SLOTS, self.RESTS)
        fields = set(line.split(',')[2:-1])
        for field in ('a:b0', 'b:b1', 'x:b2', 'y:b3', 'leftshoulder:b4', 'rightshoulder:b5', 'lefttrigger:a2',
                      'righttrigger:a5', 'back:b6', 'start:b7', 'guide:b8', 'leftstick:b9', 'rightstick:b10',
                      'leftx:a0', 'lefty:a1', 'rightx:a3', 'righty:a4~', 'dpup:h0.1', 'platform:Linux'):
            self.assertIn(field, fields)
        # O painel continua como fight stick, com o 7 e o 8 no LB e no LT.
        panel = {'b1': (0, 'b0'), 'b3': (0, 'b2'), 'b7': (0, 'b6'), 'b8': (0, 'b7')}
        self.assertEqual(self.rc.sdl_mapping_line('g', 'Panel', panel).split(',')[2:-1],
                         ['leftshoulder:b6', 'lefttrigger:b7', 'rightshoulder:b2', 'x:b0', 'platform:Linux'])
        # O hotkey no proprio Select (o que o Batocera sugere) fica so no Back.
        binds = dict(self.pad(), hotkey=(0, 'b6'))
        line = self.rc.sdl_mapping_line('guid', 'Pad', binds, self.rc.SDL_PAD_SLOTS, self.RESTS)
        self.assertIn('back:b6', line)
        self.assertNotIn('guide:', line)
        # Os jogadores do mapa: o tipo diz qual dos dois.
        devices = {0: ('g0', 'Pad', 11, 6, self.RESTS), 1: ('g1', 'Panel', 10, 2, (0, 0))}
        db = self.rc.sdl_user_db({1: self.pad(), 2: {k: (1, e) for k, (_, e) in panel.items()}}, devices, {1: 'pad'})
        self.assertIn('lefttrigger:a2', db['g0'])
        self.assertIn('x:b0', db['g1'])
        self.assertIn('rightshoulder:b2', db['g1'])

    def test_retroarch_gets_the_sticks_l3_r3_and_the_triggers(self):
        cfg = self.rc.retroarch_cfg({1: self.pad()}, {0: 'Pad'}).split('\n')
        for line in ('input_player1_l_x_minus_axis = "-0"', 'input_player1_l_x_plus_axis = "+0"',
                     'input_player1_l_y_minus_axis = "-1"', 'input_player1_l_y_plus_axis = "+1"',
                     'input_player1_r_y_minus_axis = "+4"', 'input_player1_r_y_plus_axis = "-4"',
                     'input_player1_l3_btn = "9"', 'input_player1_r3_btn = "10"',
                     'input_player1_l2_axis = "+2"', 'input_player1_r2_axis = "+5"',
                     'input_player1_l_btn = "4"', 'input_player1_b_btn = "0"', 'input_player1_select_btn = "6"'):
            self.assertIn(line, cfg)
        # Os gatilhos sao comandos (o 7 e o 8): nao sao apagados como os de um painel.
        self.assertNotIn('input_player1_l2_axis = "+99"', cfg)
        self.assertFalse(any('hotkey' in line for line in cfg))
        # MAME: os botoes 7 e 8 do painel, com as teclas padrao do jogador 1.
        mame = self.rc.mame_cfg({1: {'b7': (0, 'b6'), 'b8': (0, 'b7')}}, {0: 'Panel'})
        self.assertIn('<port type="P1_BUTTON7">', mame)
        self.assertIn('JOYCODE_1_BUTTON8 OR KEYCODE_V', mame)

    def test_flycast_dreamcast_and_dolphin_gamecube_from_the_pad(self):
        cfg = self.rc.flycast_cfg('Pad', self.pad(), self.rc.FLYCAST_PAD, self.RESTS)
        for bind in ('0-:btn_analog_left', '0+:btn_analog_right', '1-:btn_analog_up', '1+:btn_analog_down',
                     '4+:axis2_up', '4-:axis2_down', '2+:btn_trigger_left', '5+:btn_trigger_right',
                     '0:btn_a', '1:btn_b', '2:btn_x', '3:btn_y', '7:btn_start', '6:btn_menu'):
            self.assertIn(' = ' + bind + '\n', cfg)
        self.assertIn('triggers = 2,5', cfg)
        self.assertNotIn('None', cfg)
        # O painel no Flycast nao ganha analogico nem comando sem nome.
        self.assertNotIn('None', self.rc.flycast_cfg('Pad', self.pad(), self.rc.FLYCAST_DC))
        with tempfile.TemporaryDirectory() as tmp:
            self.rc.DOLPHIN_DIR = tmp
            devices = {0: ('g0', 'Pad', 11, 6, self.RESTS)}
            self.rc.dolphin_save({1: self.pad()}, devices, {1: 'pad'})
            ini = (Path(tmp) / 'GCPadNew.ini').read_text()
            self.assertIn('Main Stick/Up = `Left Y+`', ini)
            self.assertIn('C-Stick/Left = `Right X-`', ini)
            self.assertIn('Triggers/L = `Trigger L`', ini)
            self.rc.dolphin_save({1: self.pad()}, devices)
            self.assertIn('Main Stick/Up = `Pad N`', (Path(tmp) / 'GCPadNew.ini').read_text())

    def test_the_kind_lines_survive_the_map(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'map'
            text = self.rc.map_text({1: self.pad(), 2: {'up': (1, 'h0.1'), 'b8': (1, 'b7')}},
                                    {0: 'Pad', 1: 'Panel'}, {1: 'pad', 2: 'arcade'})
            path.write_text(text)
            self.assertTrue(text.startswith('1 kind 0 pad Pad\n'))
            self.assertIn('2 kind 1 arcade Panel\n2 up 1 h0.1 Panel\n2 b8 1 b7 Panel\n', text)
            self.assertEqual(self.rc.read_kinds(str(path)), {1: 'pad', 2: 'arcade'})
            players, _ = self.rc.read_map(str(path))
            self.assertEqual(players[1], self.pad())
            # A linha nova nao atrapalha quem so le os comandos de painel.
            self.assertEqual(self.rc.watch_state(players, {}, set()), {'1': [], '2': []})
        self.assertEqual(self.rc.read_kinds('/nao/existe'), {})
        self.assertEqual(self.rc.player_kind({}, 3), 'arcade')
        # O hotkey vale num atalho (fliperos-buttons hotkey --combo hotkey+start).
        self.assertIn('hotkey', self.rc.ALL_CONTROLS)
        self.assertEqual(self.rc.fbneo_preset({1: {'b8': (0, 'b7')}}, 0x029744).count('Fire 8'), 1)

    def test_the_pad_type_and_element_names(self):
        self.assertEqual(self.rc.pad_type(1, ''), 'xbox')
        self.assertEqual(self.rc.pad_type(4, ''), 'playstation')
        self.assertEqual(self.rc.pad_type(5, ''), 'nintendo')
        self.assertEqual(self.rc.pad_type(0, 'Sony Interactive Entertainment Wireless Controller'), 'playstation')
        self.assertEqual(self.rc.pad_type(0, '8BitDo SN30 Pro'), 'generic')
        self.assertEqual(self.rc.stick_axis('+a4'), (4, True))
        self.assertIsNone(self.rc.stick_axis('b3'))

    def test_bluetooth_controllers_take_the_free_players_by_connection_order(self):
        rc = self.rc
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            # Os nos do evdev: o event9 (8BitDo) foi ligado antes do event5 (Xbox).
            for name, at in (('event9', 100), ('event5', 200)):
                (tmp / name).write_text('')
                os.utime(tmp / name, (at, at))
            (tmp / 'bt.map').write_text('0500aaaa000000000000000000000000 kind pad 8BitDo\n'
                                        '0500aaaa000000000000000000000000 b4 b0 8BitDo\n'
                                        '0500bbbb000000000000000000000000 b4 b1 Xbox Wireless Controller\n'
                                        '0500bbbb000000000000000000000000 lsup -a1 Xbox Wireless Controller\n')
            profiles = rc.read_bt_profiles(str(tmp / 'bt.map'))
            self.assertEqual(profiles['0500aaaa000000000000000000000000'], ('pad', {'b4': 'b0'}, '8BitDo'))
            devices = {0: ('03000000panel', 'Panel'), 1: ('0500bbbb000000000000000000000000', 'Xbox Wireless Controller',
                                                       11, 6, (), None, None, str(tmp / 'event5')),
                       2: ('0500aaaa000000000000000000000000', '8BitDo', 11, 6, (), None, None, str(tmp / 'event9')),
                       3: ('0500cccc000000000000000000000000', 'Sem perfil', 11, 6, (), None, None, '')}
            players = {1: {'up': (0, 'h0.1')}, 2: {'b4': (9, 'b0')}}
            names, kinds, autos = {0: 'Panel'}, {1: 'arcade', 2: 'pad'}, {2: '0500dead000000000000000000000000'}
            self.assertTrue(rc.resolve_bluetooth(players, names, kinds, autos, devices, profiles))
            # O jogador 2 era um Bluetooth de antes: sai, e os ligados entram pela
            # ordem de conexao (o 8BitDo antes do Xbox, embora o SDL o conte depois).
            self.assertEqual(players, {1: {'up': (0, 'h0.1')}, 2: {'b4': (2, 'b0')},
                                       3: {'b4': (1, 'b1'), 'lsup': (1, '-a1')}})
            self.assertEqual(autos, {2: '0500aaaa000000000000000000000000', 3: '0500bbbb000000000000000000000000'})
            self.assertEqual(kinds[2], 'pad')
            self.assertFalse(rc.resolve_bluetooth(players, names, kinds, autos, devices, profiles))
            text = rc.map_text(players, names, kinds, autos)
            self.assertIn('2 bt 2 0500aaaa000000000000000000000000 8BitDo\n2 kind 2 pad 8BitDo\n2 b4 2 b0 8BitDo\n', text)
            (tmp / 'map').write_text(text)
            self.assertEqual(rc.read_autos(str(tmp / 'map')), autos)
            self.assertEqual(rc.read_map(str(tmp / 'map'))[0], players)
        self.assertTrue(rc.is_bluetooth('05009b4e5e0400000b0b000000000000'))
        self.assertFalse(rc.is_bluetooth('030000005e0400008e02000014010000'))

    def test_wired_controllers_keep_their_players_by_port(self):
        # O gabinete em 2026-11-09: um GameCube Nyxi pareado pegou um eventN
        # livre e virou o controle 0 do SDL, a frente dos dois Xbox 360 com
        # fio. Os com fio seguem pela porta, e o Bluetooth fica com o que sobra.
        rc = self.rc
        xbox = '030081b85e0400008e02000014010000'
        nyxi = '0500d71f7e0500000920000001800000'
        ports = {'event7': '', 'event8': 'usb2/2-2/2-2.2/2-2.2:1.0', 'event9': 'usb2/2-2/2-2.3/2-2.3:1.0'}
        rc.port_of = lambda device: ports.get(os.path.basename(device[7]), '') if len(device) > 7 else ''
        devices = {0: (nyxi, 'Pro Controller', 14, 4, (), None, None, '/dev/input/event7'),
                   1: (xbox, 'Xbox 360 Controller', 11, 6, (), None, None, '/dev/input/event8'),
                   2: (xbox, 'Xbox 360 Controller', 11, 6, (), None, None, '/dev/input/event9')}
        players = {1: {'up': (0, 'h0.1'), 'b1': (0, 'b0')}, 2: {'up': (1, 'h0.1')}}
        names = {0: 'Xbox 360 Controller', 1: 'Xbox 360 Controller'}
        saved = {1: 'usb2/2-2/2-2.2/2-2.2:1.0', 2: 'usb2/2-2/2-2.3/2-2.3:1.0'}
        kinds, autos = {}, {}
        self.assertTrue(rc.resolve_wired(players, names, saved, autos, devices))
        self.assertEqual(players, {1: {'up': (1, 'h0.1'), 'b1': (1, 'b0')}, 2: {'up': (2, 'h0.1')}})
        profiles = {nyxi: ('pad', {'b4': 'b1'}, 'Pro Controller')}
        rc.resolve_bluetooth(players, names, kinds, autos, devices, profiles)
        self.assertEqual(players[3], {'b4': (0, 'b1')})
        self.assertEqual(autos, {3: nyxi})
        self.assertFalse(rc.resolve_wired(players, names, saved, autos, devices))
        # O mapa guarda a porta de cada com fio.
        text = rc.map_text(players, names, kinds, autos, saved)
        self.assertIn('1 usb 1 usb2/2-2/2-2.2/2-2.2:1.0 Xbox 360 Controller\n', text)
        with tempfile.TemporaryDirectory() as tmp:
            (Path(tmp) / 'map').write_text(text)
            self.assertEqual(rc.read_ports(str(Path(tmp) / 'map')), saved)
        # Desligado o do jogador 2: um indice que nao existe, e nada pega o lugar.
        del devices[2]
        rc.resolve_wired(players, names, saved, autos, devices)
        self.assertEqual(players[2], {'up': (rc.UNPLUGGED + 2, 'h0.1')})
        # Dois jogadores na mesma porta: o de numero maior e um resto e sai.
        twice = {1: {'up': (1, 'h0.1')}, 3: {'up': (93, 'h0.1')}}
        same = {1: 'usb2/2-2/2-2.2/2-2.2:1.0', 3: 'usb2/2-2/2-2.2/2-2.2:1.0'}
        self.assertTrue(rc.resolve_wired(twice, {1: 'Xbox 360 Controller'}, same, {}, devices))
        self.assertEqual((list(twice), list(same)), ([1], [1]))
        # Sem porta guardada (o mapa de antes): a do controle do indice de agora.
        fresh = {}
        players = {1: {'up': (1, 'h0.1')}}
        rc.resolve_wired(players, {1: 'Xbox 360 Controller'}, fresh, {}, devices)
        self.assertEqual(fresh, {1: 'usb2/2-2/2-2.2/2-2.2:1.0'})

    def test_retroarch_follows_the_sdl_order_of_the_event_devices(self):
        # Um Bluetooth religado no event7 (js3) fica antes dos Xbox (event8 js1,
        # event9 js2) no SDL; a pistola no js0. O indice do SDL vira o jsN certo.
        with tempfile.TemporaryDirectory() as tmp:
            tmp = Path(tmp)
            prog = tmp / 'retroarch'
            prog.write_text('#!/bin/sh\nprintf "%s\\n" "$@"\n')
            prog.chmod(0o755)
            buttons = tmp / 'buttons.cfg'
            buttons.write_text('input_player1_joypad_index = "1"\ninput_player2_joypad_index = "2"\n'
                               'input_player3_joypad_index = "0"\n')
            (tmp / 'debug').write_text('')
            dev = 'N: Name="%s"\nH: Handlers=%s \n\n'
            (tmp / 'devices').write_text(dev % ('Namco GunCon 2', 'mouse1 event6 js0') + dev % ('Xbox', 'event8 js1')
                                         + dev % ('Xbox', 'event9 js2') + dev % ('Nyxi', 'event7 js3'))
            env = dict(os.environ, FLIPEROS_RA_BUTTONS=str(buttons), FLIPEROS_DEBUG_FLAG=str(tmp / 'debug'),
                       PATH='%s:%s' % (tmp, os.environ['PATH']), FLIPEROS_INPUT_DEVICES=str(tmp / 'devices'),
                       XDG_RUNTIME_DIR=str(tmp))
            env.pop('DISPLAY', None)
            out = subprocess.run(['bash', str(ROOT / 'config/fliperos-kms-run'), 'retroarch', '-L', 'x'],
                                 capture_output=True, text=True, env=env).stdout.split('\n')
            lines = Path(out[1].split('|')[-1]).read_text()
            for player, js in ((1, 1), (2, 2), (3, 3)):
                self.assertIn('input_player%d_joypad_index = "%d"\n' % (player, js), lines)

    def test_menus_confirm_with_south_and_go_back_with_east_on_a_joypad(self):
        # O SNES30 do gabinete (HID generico): o BTN_SOUTH do kernel e o A, de
        # leste. Pelo Button mapping, o de sul (b1 do SDL) confirma e o de
        # leste (b0) volta; no painel, o botao 1 confirma e o 2 volta.
        pk = load_script('padkeys_map', 'config/fliperos-padkeys')
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'map'
            path.write_text('1 usb 0 usb2/2-2/2-2.2/2-2.2:1.0 Xbox 360 Controller\n1 kind 0 arcade Xbox\n'
                            '1 b1 0 b0 Xbox\n1 b2 0 b1 Xbox\n1 up 0 h0.1 Xbox\n'
                            '3 bt 2 05004c6ac82d00004028000000010000 8Bitdo SNES30 GamePad\n3 kind 2 pad SNES30\n'
                            '3 b4 2 b1 SNES30\n3 b5 2 b0 SNES30\n3 b1 2 b4 SNES30\n3 coin 2 b10 SNES30\n')
            players = pk.read_players(str(path))
        self.assertEqual(pk.guid_ids('05004c6ac82d00004028000000010000'), (5, 0x2dc8, 0x2840))
        # Os botoes do SNES30: BTN_SOUTH (0x130) em diante, na ordem do SDL.
        keys = {0x130, 0x131, 0x132, 0x133, 0x134, 0x135, 0x136, 0x137, 0x138, 0x139, 0x13a, 0x13b}
        self.assertEqual(pk.sdl_buttons(keys)[:2], [0x130, 0x131])
        pad = pk.mapped_buttons(keys, '', (5, 0x2dc8, 0x2840), players)
        self.assertEqual((pad[0x131], pad[0x130]), (pk.KEY_ENTER, pk.KEY_ESC))
        self.assertEqual(pad[0x134], pk.KEY_SPACE)
        self.assertEqual(pad[0x13a], pk.KEY_ESC)   # o Select (b10)
        mapper = pk.Mapper({}, pad)
        self.assertEqual(mapper.event(pk.EV_KEY, 0x131, 1), [(pk.KEY_ENTER, 1)])
        self.assertEqual(mapper.event(pk.EV_KEY, 0x130, 1), [(pk.KEY_ESC, 1)])
        panel = pk.mapped_buttons({0x130, 0x131, 0x132}, 'usb2/2-2/2-2.2/2-2.2:1.0', (3, 0x45e, 0x28e), players)
        self.assertEqual((panel[0x130], panel[0x131]), (pk.KEY_ENTER, pk.KEY_ESC))
        # Fora do mapa: os codigos do kernel, como antes.
        self.assertIsNone(pk.mapped_buttons(keys, 'outra', (3, 1, 2), players))
        self.assertIs(pk.Mapper({}).buttons, pk.BUTTONS)
        # O Attract-Mode: o joypad com o sul no papel do botao 1 e o leste no do 2.
        roles = self.rc.menu_roles({1: {'b1': (0, 'b0')}, 3: {'b4': (2, 'b1'), 'b5': (2, 'b0'), 'b1': (2, 'b4')}},
                                   {3: 'pad'})
        self.assertEqual(roles[1], {'b1': (0, 'b0')})
        self.assertEqual(roles[3], {'b1': (2, 'b1'), 'b2': (2, 'b0'), 'b4': (2, 'b4')})
        # Os botoes da interface escolhidos (accept, cancel) valem mais.
        roles = self.rc.menu_roles({3: {'b4': (2, 'b1'), 'b5': (2, 'b0'), 'b1': (2, 'b4'),
                                        'accept': (2, 'b4'), 'cancel': (2, 'b1')}}, {3: 'pad'})
        self.assertEqual(roles[3], {'b1': (2, 'b4'), 'b2': (2, 'b1')})
        self.assertIn('accept', self.rc.ALL_CONTROLS)
        self.assertEqual(self.rc.retroarch_lines(1, 'accept', 'b4'), [])
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'map'
            path.write_text('3 bt 2 05004c6ac82d00004028000000010000 SNES30\n3 kind 2 pad SNES30\n'
                            '3 b4 2 b1 SNES30\n3 b5 2 b0 SNES30\n3 start 2 b11 SNES30\n'
                            '3 accept 2 b4 SNES30\n3 cancel 2 b3 SNES30\n')
            chosen = pk.mapped_buttons(keys, '', (5, 0x2dc8, 0x2840), pk.read_players(str(path)))
        self.assertEqual(chosen[0x134], pk.KEY_ENTER)
        self.assertEqual(chosen[0x133], pk.KEY_ESC)
        self.assertNotIn(0x131, chosen)           # o sul nao e mais o Enter
        self.assertEqual(chosen[0x13b], pk.KEY_ENTER)  # o Start continua
        # O frontend do FliperOS (gui/feinput.py), o mesmo.
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        try:
            import feinput
        finally:
            sys.path.remove(str(ROOT / 'fliperos-setup/gui'))
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'map'
            path.write_text('1 kind 0 arcade P\n1 b1 0 b0 P\n2 kind 1 pad Pad\n2 b4 1 b1 Pad\n2 b5 1 b0 Pad\n'
                            '2 b1 1 b3 Pad\n')
            # O joypad vira os papeis dele ("j:"), o aceitar e o voltar
            # primeiro (sem escolha, o de sul e o de leste).
            self.assertEqual(feinput.read_map(str(path)),
                             [('j:accept', 1, 'b1'), ('j:cancel', 1, 'b0'), ('b1', 0, 'b0'),
                              ('j:south', 1, 'b1'), ('j:east', 1, 'b0'), ('j:west', 1, 'b3')])
            path.write_text('2 kind 1 pad Pad\n2 b4 1 b1 Pad\n2 b5 1 b0 Pad\n2 b1 1 b3 Pad\n'
                            '2 accept 1 b3 Pad\n2 cancel 1 b1 Pad\n')
            self.assertEqual(feinput.read_map(str(path))[:2], [('j:accept', 1, 'b3'), ('j:cancel', 1, 'b1')])
            # O guia desenha o aceitar e o voltar no botao escolhido.
            self.assertEqual(feinput.interface_roles(str(path)), {'accept': 'west', 'cancel': 'south'})

    def test_a_controller_connected_or_removed_reassigns_the_bluetooth_players(self):
        rules = (ROOT / 'config/99-fliperos-input.rules').read_text()
        self.assertIn('ACTION=="remove", ENV{ID_INPUT_JOYSTICK}=="1", \\\n'
                      '  RUN+="/bin/systemctl --no-block restart fliperos-controllers.service"', rules)
        controllers = (ROOT / 'config/fliperos-controllers').read_text()
        self.assertIn("if os.environ.get('FLIPEROS_CONTROLLERS_ONLY') or not os.path.isfile(BT_MAP)", controllers)
        self.assertIn("FLIPEROS_BUTTONS_FROM_CONTROLLERS='1'", controllers)
        buttons = (ROOT / 'config/fliperos-buttons').read_text()
        self.assertIn("os.system('FLIPEROS_CONTROLLERS_ONLY=1 \"%s\" > /dev/null 2>&1' % CONTROLLERS)", buttons)
        # Como root o HIDAPI do SDL via o Nyxi com outro GUID, no comeco da
        # lista; os emuladores (o usuario) o veem pelo evdev. Os dois sem ele.
        self.assertIn("os.environ['SDL_JOYSTICK_HIDAPI'] = '0'", buttons)
        self.assertIn("os.environ['SDL_JOYSTICK_HIDAPI'] = '0'", controllers)
        self.assertEqual(self.rc.os.environ.get('SDL_JOYSTICK_HIDAPI'), '0')

    def test_capture_has_hold_to_skip_and_identify(self):
        source = (ROOT / 'config/fliperos-buttons').read_text()
        self.assertIn("p.add_argument('--hold', type=float, default=0)", source)
        self.assertIn("p.add_argument('--device', type=int, default=-1)", source)
        self.assertIn("os.environ['SDL_GAMECONTROLLER_USE_BUTTON_LABELS'] = '0'", source)
        self.assertIn("known = 'platform:' in mapping", source)


class DeskpadTests(unittest.TestCase):
    """config/fliperos-deskpad: o controle como mouse no desktop; o teclado na
    tela e o Onboard, que ele abre, fecha e esconde pelo D-Bus."""

    def setUp(self):
        loader = importlib.machinery.SourceFileLoader('fliperos_deskpad', str(ROOT / 'config/fliperos-deskpad'))
        spec = importlib.util.spec_from_loader('fliperos_deskpad', loader)
        self.dp = importlib.util.module_from_spec(spec)
        loader.exec_module(self.dp)
        self.calls = []
        self.osk_rect, self.where = None, (100, 100)
        test = self

        class FakeX:
            def width(self):
                return 640

            def move(self, dx, dy):
                if dx or dy:
                    test.calls.append(('move', dx, dy))

            def button(self, number, down):
                test.calls.append(('button', number, down))

            def scroll(self, lines):
                test.calls.append(('scroll', lines))

            def osk_rect(self):
                return test.osk_rect

            def pointer(self):
                return test.where

        class FakeOnboard:
            def toggle(self):
                test.calls.append(('osk', 'toggle'))

            def hide(self):
                test.calls.append(('osk', 'hide'))

        self.desk = self.dp.Desk(FakeX(), FakeOnboard())

    def test_accept_is_the_left_click_and_back_the_right(self):
        dp, desk = self.dp, self.desk
        desk.key(dp.KEY_ENTER, 1, 0.0)
        desk.key(dp.KEY_ENTER, 0, 0.1)
        desk.key(dp.KEY_ESC, 1, 0.2)
        desk.key(dp.KEY_ESC, 0, 0.3)
        self.assertEqual(self.calls, [('button', 1, True), ('button', 1, False),
                                      ('button', 3, True), ('button', 3, False)])
        self.calls.clear()
        desk.key(dp.KEY_PAGEDOWN, 1, 0.4)
        self.assertEqual(self.calls, [('scroll', 3)])

    def test_stick_and_dpad_move_the_pointer(self):
        dp, desk = self.dp, self.desk
        self.assertEqual(dp.stick(0, -32768, 32767), 0.0)
        self.assertAlmostEqual(dp.stick(32767, -32768, 32767), 1.0, places=3)
        self.assertLess(dp.stick(-32768, -32768, 32767), -0.99)
        # O analogico no fim: MAX_SPEED larguras de tela por segundo.
        desk.analog(dp.ABS_X, 1.0)
        desk.tick(0.5, 1.0)
        self.assertEqual(self.calls, [('move', round(dp.MAX_SPEED * 640 * 0.5), 0)])
        desk.analog(dp.ABS_X, 0.0)
        # A seta que veio do analogico nao anda de novo; a do direcional anda.
        self.calls.clear()
        desk.key(dp.KEY_DOWN, 1, 1.0, analog=True)
        desk.tick(0.1, 1.1)
        self.assertEqual(self.calls, [])
        desk.key(dp.KEY_DOWN, 1, 1.0)
        desk.tick(0.1, 1.1)
        self.assertEqual(self.calls[0][:2], ('move', 0))
        self.assertGreater(self.calls[0][2], 0)
        # Segurando, acelera.
        first = self.calls[0][2]
        self.calls.clear()
        desk.tick(0.1, 3.0)
        self.assertGreater(self.calls[0][2], first)

    def test_button_3_toggles_the_onboard_keyboard(self):
        dp, desk = self.dp, self.desk
        desk.key(dp.KEY_SPACE, 1, 0.0)
        desk.key(dp.KEY_SPACE, 0, 0.1)
        self.assertEqual(self.calls, [('osk', 'toggle')])
        # O ponteiro segue andando com o teclado aberto: tecla-se clicando.
        desk.analog(dp.ABS_X, 1.0)
        desk.tick(0.1, 0.2)
        self.assertEqual(self.calls[-1][0], 'move')

    def test_accept_outside_the_keyboard_closes_it(self):
        dp, desk = self.dp, self.desk
        # Teclado fechado: so o clique.
        desk.key(dp.KEY_ENTER, 1, 0.0)
        desk.key(dp.KEY_ENTER, 0, 0.1)
        self.assertEqual(self.calls, [('button', 1, True), ('button', 1, False)])
        # Aberto embaixo, o ponteiro numa tecla: o clique digita, nada fecha.
        self.osk_rect, self.where = (0, 288, 640, 192), (85, 347)
        self.calls.clear()
        desk.key(dp.KEY_ENTER, 1, 1.0)
        desk.key(dp.KEY_ENTER, 0, 1.1)
        self.assertEqual(self.calls, [('button', 1, True), ('button', 1, False)])
        # O ponteiro fora: o teclado sai e o clique segue para a janela.
        self.where = (320, 100)
        self.calls.clear()
        desk.key(dp.KEY_ENTER, 1, 2.0)
        self.assertEqual(self.calls, [('osk', 'hide'), ('button', 1, True)])
        desk.key(dp.KEY_ENTER, 0, 2.1)
        # Voltar (o clique direito) fora dele nao o fecha.
        self.calls.clear()
        desk.key(dp.KEY_ESC, 1, 3.0)
        self.assertEqual(self.calls, [('button', 3, True)])

    def test_the_keyboard_only_opens_by_itself_for_the_controller(self):
        # O Onboard abre sozinho num campo de texto (auto-show); com teclado ou mouse de verdade isso
        # atrapalha. Desligado, o deskpad o liga enquanto chegam comandos do controle (um botao, o
        # analogico fora da zona morta) e o desliga ACTIVE segundos depois do ultimo.
        dp = self.dp
        with tempfile.TemporaryDirectory() as tmp:
            fake = Path(tmp) / 'gsettings'
            fake.write_text('#!/bin/sh\necho "$*" >> %s/log\n' % tmp)
            fake.chmod(0o755)
            dp.AutoShow.GSETTINGS = str(fake)
            auto = dp.AutoShow()
            written = lambda: (Path(tmp) / 'log').read_text().splitlines() if (Path(tmp) / 'log').exists() else []
            wait = lambda n: [time.sleep(0.05) for _ in range(40) if len(written()) < n]
            desk = self.dp.Desk(self.desk.x, self.desk.osk, auto)
            auto.set(False)                                  # ao abrir: desligado, uma vez so
            auto.set(False)
            wait(1)
            self.assertEqual(written(), ['set org.onboard.auto-show enabled false'])
            desk.tick(0.1, 1.0)                              # sem comando: continua desligado
            desk.analog(dp.ABS_X, 0.0, 1.0)                  # o analogico na zona morta nao conta
            time.sleep(0.2)
            self.assertEqual(len(written()), 1)
            desk.key(dp.KEY_ENTER, 1, 2.0)                   # um botao liga
            wait(2)
            self.assertEqual(written()[1], 'set org.onboard.auto-show enabled true')
            desk.key(dp.KEY_ENTER, 0, 2.1)
            desk.analog(dp.ABS_X, 0.8, 5.0)                  # o analogico fora da zona morta mantem ligado
            desk.tick(0.1, 10.0)
            time.sleep(0.2)
            self.assertEqual(len(written()), 2)
            desk.tick(0.1, 5.0 + dp.AutoShow.ACTIVE + 0.1)   # ACTIVE segundos sem comando: desliga
            wait(3)
            self.assertEqual(written()[2], 'set org.onboard.auto-show enabled false')
            desk.analog(dp.ABS_X, 0.0, 30.0)
            desk.tick(0.1, 31.0)
            time.sleep(0.2)
            self.assertEqual(len(written()), 3)
        # Aberto pelo main com o auto-show desligado de saida.
        source = (ROOT / 'config/fliperos-deskpad').read_text()
        self.assertIn('autoshow = AutoShow()\n    autoshow.set(False)\n    desk = Desk(x, osk, autoshow)', source)
        self.assertIn('desk.analog(code, stick(value, low, high), now)', source)

    def test_onboard_settings_and_dbus(self):
        from unittest import mock
        override = (ROOT / 'config/fliperos-onboard.gschema.override').read_text()
        # O auto-show nasce desligado: o deskpad o liga so enquanto chegam comandos do controle.
        for line in ("[org.onboard.auto-show]\nenabled=false", "docking-enabled=true", "keep-aspect-ratio=true",
                     "docking-aspect-change-range=[1.0, 1.0]", "input-event-source='GTK'", "key-synth='XTest'",
                     "start-minimized=true", "use-system-defaults=false"):
            self.assertIn(line, override)
        self.assertIn('install -Dm644 "$src/config/fliperos-onboard.gschema.override" \\\n'
                      '  "$root/usr/share/glib-2.0/schemas/90_fliperos-onboard.gschema.override"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())
        osk = self.dp.Onboard()
        with mock.patch.object(self.dp.subprocess, 'Popen') as popen:
            osk.toggle()
            osk.hide()
        self.assertEqual([c.args[0][-1] for c in popen.call_args_list],
                         ['org.onboard.Onboard.Keyboard.ToggleVisible', 'org.onboard.Onboard.Keyboard.Hide'])
        self.assertIn('--dest=org.onboard.Onboard', popen.call_args_list[0].args[0])
        with mock.patch.object(self.dp.subprocess, 'Popen', side_effect=OSError):
            osk.hide()   # sem dbus-send: calado

    def test_one_per_display_and_it_leaves_on_kill(self):
        # Duas copias leriam os mesmos controles: cada botao valeria duas vezes.
        with tempfile.TemporaryDirectory() as tmp:
            old = os.environ.get('XDG_RUNTIME_DIR')
            os.environ['XDG_RUNTIME_DIR'] = tmp
            try:
                first = self.dp.single(':0')
                self.assertIsNotNone(first)
                self.assertIsNone(self.dp.single(':0'))
                other = self.dp.single(':1')
                self.assertIsNotNone(other)
                os.close(first)
                os.close(other)
            finally:
                if old is None:
                    os.environ.pop('XDG_RUNTIME_DIR', None)
                else:
                    os.environ['XDG_RUNTIME_DIR'] = old
        source = (ROOT / 'config/fliperos-deskpad').read_text()
        self.assertIn("signal.signal(sig, lambda *_: os._exit(0))", source)
        self.assertIn("if 'ConnectionClosed' in type(e).__name__:", source)

    def test_started_by_the_desktop_and_installed(self):
        lxde = (ROOT / 'config/fliperos-lxde').read_text()
        self.assertIn('/opt/fliperos/bin/fliperos-deskpad < /dev/null >> "$deskpad_log" 2>&1 &', lxde)
        self.assertLess(lxde.index('fliperos-deskpad'), lxde.index('exec startlxde'))
        # O Onboard antes do startlxde, com o encaixe na altura da tela.
        self.assertIn('  onboard < /dev/null > /dev/null 2>&1 &\n', lxde)
        self.assertLess(lxde.index('onboard < /dev/null'), lxde.index('exec startlxde'))
        self.assertIn('dock-height "$((screen_h * 2 / 5))"', lxde)
        self.assertIn('install -Dm755 "$src/config/fliperos-deskpad" "$root/opt/fliperos/bin/fliperos-deskpad"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())
        for pkg in ('python3-xlib', 'gir1.2-atspi-2.0', 'xdotool', 'onboard'):
            self.assertIn(pkg, MKISO)
            self.assertIn(pkg, (ROOT / 'tools/cabinet-update.sh').read_text())


class PadColorTests(unittest.TestCase):
    """config/fliperos-padcolor: a luz RGB dos controles no roxo do Dracula."""

    def run_tool(self, leds, *args, color=None):
        env = dict(os.environ, FLIPEROS_LEDS=str(leds), FLIPEROS_CONF='/nao/existe')
        if color:
            env['FLIPEROS_PADCOLOR'] = color
        return subprocess.run(['bash', str(ROOT / 'config/fliperos-padcolor')] + list(args),
                              env=env, capture_output=True, text=True)

    def led(self, root, name, multi=True, pad=True, max_=255):
        dev = root / 'hid' / name.replace(':', '_')
        (dev / 'input/input5/js0' if pad else dev / 'input/input5/mouse0').mkdir(parents=True)
        led = root / 'leds' / name
        led.mkdir(parents=True)
        (led / 'device').symlink_to(dev)
        (led / 'max_brightness').write_text('%d\n' % max_)
        (led / 'brightness').write_text('0\n')
        if multi:
            (led / 'multi_index').write_text('red green blue\n')
            (led / 'multi_intensity').write_text('0 0 0\n')
        return led

    def test_fliperos_purple_on_a_pad_light(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            pad = self.led(root, 'input5:rgb:indicator')
            mouse = self.led(root, 'input9:rgb:indicator', pad=False)
            # O padrao (fliperos) num LED so: o roxo saturado, #7a00ff.
            r = self.run_tool(root / 'leds', 'all')
            self.assertEqual(r.returncode, 0, r.stderr)
            self.assertEqual((pad / 'multi_intensity').read_text(), '122 0 255\n')
            r = self.run_tool(root / 'leds', 'all', color='bd93f9')
            self.assertEqual((pad / 'multi_intensity').read_text(), '189 147 249\n')
            self.assertEqual((pad / 'brightness').read_text(), '255\n')
            # Um LED que nao e de controle fica.
            self.assertEqual((mouse / 'multi_intensity').read_text(), '0 0 0\n')
            # O DualShock 4 (hid-sony): um LED por cor.
            red = self.led(root, '0005:054C:05C4.0001:red', multi=False)
            blue = self.led(root, '0005:054C:05C4.0001:blue', multi=False)
            self.run_tool(root / 'leds', 'apply', str(red))
            self.run_tool(root / 'leds', 'apply', '0005:054C:05C4.0001:blue')
            self.assertEqual((red / 'brightness').read_text(), '122\n')
            self.assertEqual((blue / 'brightness').read_text(), '255\n')
            # padcolor=off: a luz fica como o controle a acende.
            (pad / 'multi_intensity').write_text('1 2 3\n')
            self.run_tool(root / 'leds', 'all', color='off')
            self.assertEqual((pad / 'multi_intensity').read_text(), '1 2 3\n')

    def test_installed_with_its_udev_rule(self):
        rules = (ROOT / 'config/99-fliperos-input.rules').read_text()
        self.assertIn('SUBSYSTEM=="leds", ACTION=="add", RUN+="/opt/fliperos/bin/fliperos-padcolor apply %S%p"',
                      rules)
        self.assertIn('install -Dm755 "$src/config/fliperos-padcolor" "$root/opt/fliperos/bin/fliperos-padcolor"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())
        self.assertIn('SUBSYSTEM=="hidraw", ACTION=="add", ATTRS{idVendor}=="2dc8", '
                      'RUN+="/opt/fliperos/bin/fliperos-padcolor hidraw %k"', rules)
        self.assertIn('install -Dm755 "$src/config/fliperos-padcolor-8bitdo" '
                      '"$root/opt/fliperos/bin/fliperos-padcolor-8bitdo"', (ROOT / 'fliperos-rootfs.sh').read_text())

    def test_launch_switches_the_8bitdo_to_game_colours_until_the_game_closes(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            log = root / 'calls'
            tool = root / 'u2'
            tool.write_text('#!/bin/sh\necho "$*" >> "%s"\n' % log)
            tool.chmod(0o755)
            rom = root / 'sf2.zip'
            rom.write_text('')
            game = subprocess.Popen(['sleep', '0.5'])
            env = dict(os.environ, FLIPEROS_LEDS=str(root), FLIPEROS_CONF='/nao/existe',
                       FLIPEROS_PADCOLOR_8BITDO=str(tool), PADCOLOR_GAME_PID=str(game.pid))
            tool_path = str(ROOT / 'config/fliperos-padcolor')
            # O jogo fecha (e e recolhido: zumbi, o tail --pid esperaria) com o launch esperando.
            r = subprocess.Popen(['bash', tool_path, 'launch', 'retroarch', '-L', 'core.so', str(rom)], env=env)
            game.wait()
            self.assertEqual(r.wait(timeout=10), 0)
            self.assertEqual(log.read_text(), 'game on\ngame off\n')
            # Um frontend (sem jogo), o GroovyMAME sem set, ou uma cor so: nada.
            log.write_text('')
            for args, colour in ((['es-de'], None), (['groovymame', '-listxml'], None),
                                 (['retroarch', str(rom)], '7a00ff')):
                e = dict(env, FLIPEROS_PADCOLOR=colour) if colour else env
                subprocess.run(['bash', tool_path, 'launch'] + args, env=e, timeout=10)
            self.assertEqual(log.read_text(), '')
        for runner in ('config/fliperos-kms-run', 'config/fliperos-x11-run'):
            self.assertIn('[[ -x $padcolor ]] && after_game "$padcolor" launch "$@"', (ROOT / runner).read_text())

    def test_game_watchers_live_outside_the_game_tree(self):
        # O atalho de sair do frontend mata a arvore do jogo (tree() no
        # fliperos-frontend): a roleta do 8BitDo, o "end" do Pixelcade, o fim
        # do LEDSpicer e a nuvem morriam antes de agir. after_game os poe fora
        # dela, com o PID do jogo (o do script, que o exec mantem) explicito.
        for runner in ('config/fliperos-kms-run', 'config/fliperos-x11-run'):
            text = (ROOT / runner).read_text()
            self.assertIn('[[ -x $cloud ]] && after_game "$cloud" watch $$', text, runner)
            self.assertNotRegex(text, r'\{ "\$(padcolor|pixelcade|outputs|cloud)"', runner)
            helper = re.search(r'(?ms)^after_game\(\) \{.*?^\}\n', text).group(0)
            with tempfile.TemporaryDirectory() as tmp:
                out = Path(tmp) / 'seen'
                tool = Path(tmp) / 'tool'
                tool.write_text('#!/bin/sh\necho "$PPID $PADCOLOR_GAME_PID $PIXELCADE_GAME_PID $FLIPEROS_GAME_PID $1"'
                                ' > "%s.tmp" && mv "%s.tmp" "%s"\n' % (out, out, out))
                tool.chmod(0o755)
                shell = subprocess.run(['bash', '-c', helper + 'after_game "$1" arg; echo $$; sleep 0.3', 'x', str(tool)],
                                       capture_output=True, text=True, timeout=10)
                for _ in range(50):
                    if out.exists():
                        break
                    time.sleep(0.05)
                ppid, *pids, arg = out.read_text().split()
                game = shell.stdout.strip()
                self.assertEqual((pids, arg), ([game] * 3, 'arg'), runner)
                self.assertNotEqual(ppid, game, runner)
        self.assertIn('SUBSYSTEM=="hidraw", ATTRS{idVendor}=="2dc8", MODE="0660", GROUP="input"',
                      (ROOT / 'config/99-fliperos-input.rules').read_text())

    def test_list_names_the_pads_and_the_8bitdo_on_bluetooth(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            pad = self.led(root, 'input5:rgb:indicator')
            (pad / 'device/uevent').write_text('HID_NAME=DualSense Wireless Controller\n')
            self.led(root, '0005:054C:05C4.0001:red', multi=False)
            self.led(root, '0005:054C:05C4.0001:green', multi=False)
            tool = root / 'u2'
            tool.write_text('#!/bin/sh\n[ "$1" = list ] && echo "/dev/hidraw4 8BitDo Ultimate 2 Wireless"\n'
                            '[ "$1" = bluetooth ] && echo "8BitDo Ultimate 2 Wireless"\nexit 0\n')
            tool.chmod(0o755)
            env = dict(os.environ, FLIPEROS_LEDS=str(root / 'leds'), FLIPEROS_CONF='/nao/existe',
                       FLIPEROS_PADCOLOR='off', FLIPEROS_PADCOLOR_8BITDO=str(tool))
            r = subprocess.run(['bash', str(ROOT / 'config/fliperos-padcolor'), 'list'], env=env,
                               capture_output=True, text=True)
            self.assertEqual(r.returncode, 0, r.stderr)
            # O DualShock 4 conta uma vez (pelo :red); off nao esconde a lista.
            self.assertIn('led DualSense Wireless Controller', r.stdout.splitlines())
            self.assertIn('8bitdo 8BitDo Ultimate 2 Wireless', r.stdout.splitlines())
            self.assertIn('bluetooth 8BitDo Ultimate 2 Wireless', r.stdout.splitlines())
            self.assertEqual(sum(l.startswith('led 0005:054C') for l in r.stdout.splitlines()), 1)


class PadColor8BitDoTests(unittest.TestCase):
    """config/fliperos-padcolor-8bitdo: a cor do anel do Ultimate 2 gravada na
    configuracao dele, contra um controle de mentira com o protocolo."""

    def setUp(self):
        self.u2 = load_script('fliperos_padcolor_8bitdo', 'config/fliperos-padcolor-8bitdo')
        u2 = self.u2

        class FakePad(u2.Pad):
            def __init__(pad, record, theme=2, ack_commit=True):
                pad.ram = bytearray(record)
                pad.flash = bytes(record)
                pad.theme = theme
                pad.ack_commit = ack_commit
                pad.log = []
                pad.answer = None
                pad.reports_on = True

            def close(pad):
                pass

            def send(pad, cmd, sub=0, data=b"", total=0, offset=0, length=None, with_crc=True):
                raw = u2.build_request(cmd, sub, data, total, offset, length, with_crc)
                self.assertEqual(len(raw), 64)
                self.assertEqual(raw[:2], b"\x81\x04")
                length = struct.unpack_from("<H", raw, 6)[0]
                body = raw[18:18 + length]
                if with_crc:
                    self.assertEqual(struct.unpack_from("<H", raw, 8)[0], u2.crc16(body))
                pad.log.append((cmd, sub, offset, length))
                reply = b""
                if cmd == u2.CMD_READ:
                    reply = bytes(pad.ram[offset:offset + length])
                elif cmd == u2.CMD_WRITE:
                    self.assertFalse(pad.reports_on, "writes go between 7/0 and 7/1")
                    self.assertEqual(total, u2.CFG_SIZE)
                    # Nunca 0x0C-0x13: crc, modo e perfil ativo sao do firmware.
                    self.assertTrue(offset + length <= 12 or offset >= 20, (offset, length))
                    pad.ram[offset:offset + length] = body
                    reply = b"\0" * length
                elif cmd == u2.CMD_GET_THEME:
                    reply = bytes([pad.theme])
                    length = 1
                elif cmd == u2.CMD_SET_THEME:
                    pad.theme = sub
                elif cmd == u2.CMD_REPORT:
                    pad.reports_on = sub == 1
                elif cmd == u2.CMD_COMMIT:
                    self.assertEqual(sub, u2.COMMIT_KEY)
                    if not pad.ack_commit:
                        pad.answer = None
                        return
                    pad.flash = bytes(pad.ram)
                pad.answer = (length, reply)

            def recv(pad, cmd, timeout=0.5, offset=None):
                answer, pad.answer = pad.answer, None
                return answer

        self.FakePad = FakePad
        # Um controle com os perfis 1 e 3 (o 2 apagado), modo XInput (3).
        record = bytearray(i % 251 for i in range(u2.CFG_SIZE))
        for s, flag in ((0, 0x20200911), (1, 0xFFFFFFFF), (2, 0x20200911)):
            struct.pack_into('<I', record, 4 * s, flag)
        struct.pack_into('<HH', record, 16, 3, 0)
        self.record = bytes(record)
        # Um controle de fabrica: flash apagada, sem perfil (cur_slot 3).
        blank = bytearray(b'\xff' * u2.CFG_SIZE)
        struct.pack_into('<HH', blank, 16, 3, 3)
        self.blank = bytes(blank)

    def test_saves_the_colour_in_the_profiles_and_keeps_the_rest(self):
        u2 = self.u2
        pad = self.FakePad(self.record)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            self.assertEqual(u2.apply(pad, 0xbd93f9, 'ultimate2-6012-test'), 'saved')
            self.assertEqual(Path(tmp, 'ultimate2-6012-test.bin').read_bytes(), self.record)
            self.assertEqual(Path(tmp, 'ultimate2-6012-test.theme').read_text(), '2\n')
        want = struct.pack('<I', 0x20200911) + bytes.fromhex('f993bd00') * 24
        for s in (0, 2):
            off = 1292 + 100 * s
            self.assertEqual(pad.flash[off:off + 100], want)
        # Todo o resto do registro ficou igual, o perfil apagado tambem.
        rest = bytearray(pad.flash)
        orig = bytearray(self.record)
        for s in (2, 0):
            off = 1292 + 100 * s
            del rest[off:off + 100], orig[off:off + 100]
        self.assertEqual(rest, orig)
        self.assertEqual(pad.theme, 4)
        self.assertTrue(pad.reports_on)
        # Cada pedaco no maximo 45 bytes.
        self.assertTrue(all(length <= 45 for cmd, _, _, length in pad.log if cmd in (1, 2)))

    def test_a_pad_with_no_profile_gets_profile_1_like_the_8bitdo_app(self):
        u2 = self.u2
        pad = self.FakePad(self.blank)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            self.assertEqual(u2.apply(pad, 0x50fa7b), 'profile')
        f = pad.flash
        self.assertEqual(f[12:20], self.blank[12:20])
        self.assertEqual(struct.unpack_from('<I', f, 0)[0], 0x20200911)
        self.assertEqual(f[4:12], b'\xff' * 8)
        self.assertEqual(f[20:52].decode('utf-16-be').rstrip('\0'), 'FliperOS')
        # Cada botao faz o que diz (XInput): A B X Y LB RB LT RT L3 R3 Select Start Star=Menu Home + d-pad.
        keys = struct.unpack_from('<I22I', f, 224)
        self.assertEqual(keys[0], 0x20200911)
        self.assertEqual(keys[1:], (0x2000, 0x1000, 0x10, 0x20, 0x400, 0x800, 0x4000, 0x8000, 0x2, 0x4, 0x8, 0x1,
                                    0x10000, 0x20000, 0x200, 0x100, 0x80, 0x40, 0, 0, 0, 0))
        self.assertEqual(struct.unpack_from('<IBBBB', f, 152), (0x20200911, 17, 128, 17, 128))
        self.assertEqual(struct.unpack_from('<IBBBB', f, 176), (0x20200911, 0, 255, 0, 255))
        self.assertEqual(struct.unpack_from('<Iff', f, 116), (0x20200911, 1.0, 1.0))
        self.assertEqual(struct.unpack_from('<I', f, 1172)[0], 0x20190000)
        self.assertEqual(f[1292:1392], struct.pack('<I', 0x20200911) + bytes.fromhex('7bfa5000') * 24)
        # Os perfis 2 e 3 continuam apagados.
        for s in (1, 2):
            self.assertEqual(f[1292 + 100 * s:1392 + 100 * s], b'\xff' * 100)
            self.assertEqual(f[224 + 92 * s:316 + 92 * s], b'\xff' * 92)
        self.assertEqual(pad.theme, 4)
        # Feito o perfil, a cor nova muda so a luz dele.
        pad.log.clear()
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            self.assertEqual(u2.apply(pad, 0xff5555), 'saved')
        writes = [(o, n) for c, _, o, n in pad.log if c == u2.CMD_WRITE]
        self.assertTrue(writes and all(1292 <= o and o + n <= 1392 for o, n in writes), writes)

    def test_the_fliperos_style_roulette_and_game_rings(self):
        u2 = self.u2
        pad = self.FakePad(self.record)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            self.assertEqual(u2.parse_color('FliperOS'), 'fliperos')
            self.assertEqual(u2.apply(pad, 'fliperos'), 'saved')
            self.assertEqual(u2.apply(pad, 'fliperos'), 'same')
        for s in (0, 2):
            # A roleta: o roxo girando sobre o rosa, velocidade 7.
            self.assertEqual(struct.unpack_from('<IIIB', pad.flash, 1244 + 16 * s),
                             (0x20200911, 0x7a00ff, 0xff0080, 7))
            # Em jogo: LEDs 0-11 (anel esquerdo) roxos, 12-23 (direito) rosa.
            colours = struct.unpack_from('<I24I', pad.flash, 1292 + 100 * s)
            self.assertEqual(colours, (0x20200911,) + (0x7a00ff,) * 12 + (0xff0080,) * 12)
        self.assertEqual(pad.flash[1244 + 16:1244 + 32], self.record[1244 + 16:1244 + 32])
        self.assertEqual(pad.theme, 3)
        # Um controle sem perfil ganha o perfil 1 ja no estilo.
        blank = self.FakePad(self.blank)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            self.assertEqual(u2.apply(blank, 'fliperos'), 'profile')
        self.assertEqual(struct.unpack_from('<IIIB', blank.flash, 1244), (0x20200911, 0x7a00ff, 0xff0080, 7))
        self.assertEqual(blank.theme, 3)

    def test_game_on_and_off_only_switch_the_theme(self):
        u2 = self.u2
        pad = self.FakePad(self.record, theme=3)
        u2.find_devices = lambda: iter([('/dev/hidraw9', '8BitDo', '/x')])
        u2.find_input_node = lambda usb_dir: None
        u2.Pad = lambda dev, node: pad
        self.assertEqual(u2.main(['game', 'on']), 0)
        self.assertEqual(pad.theme, 4)
        u2.find_devices = lambda: iter([('/dev/hidraw9', '8BitDo', '/x')])
        self.assertEqual(u2.main(['game', 'off']), 0)
        self.assertEqual(pad.theme, 3)
        self.assertFalse([c for c, *_ in pad.log if c in (u2.CMD_WRITE, u2.CMD_COMMIT)])

    def test_runs_skip_the_firmware_bytes(self):
        u2 = self.u2
        old = bytes(40)
        new = bytes([1]) * 40
        self.assertEqual(u2.runs(old, new), [(0, 12), (20, 40)])
        self.assertEqual(u2.runs(bytes(100), bytes(30) + b'\1' + bytes(10) + b'\1' + bytes(58)), [(30, 42)])

    def test_nothing_written_when_the_colour_is_already_there(self):
        u2 = self.u2
        pad = self.FakePad(self.record)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            u2.apply(pad, 0x50fa7b)
            pad.log.clear()
            self.assertEqual(u2.apply(pad, 0x50fa7b), 'same')
        self.assertFalse([c for c, *_ in pad.log if c in (u2.CMD_WRITE, u2.CMD_COMMIT, u2.CMD_SET_THEME)])

    def test_a_save_not_confirmed_fails_and_turns_reports_back_on(self):
        u2 = self.u2
        pad = self.FakePad(self.record, ack_commit=False)
        with tempfile.TemporaryDirectory() as tmp:
            u2.BACKUP_DIR = tmp
            with self.assertRaises(IOError):
                u2.apply(pad, 0xff5555)
        self.assertEqual(pad.flash, self.record)
        self.assertTrue(pad.reports_on)

    def test_finds_only_the_config_channel(self):
        u2 = self.u2
        with tempfile.TemporaryDirectory() as tmp:
            sysfs = Path(tmp)
            usb = sysfs / 'devices/usb1/1-1'
            for n, hid_id, desc, name in (
                    (0, '0003:00002DC8:00006012', b'\x05\x01\x09\x05', '8BitDo Ultimate 2 Wireless'),
                    (1, '0003:00002DC8:00006012', b'\x06\x7a\xff\x09\x01', '8BitDo Ultimate 2 Wireless'),
                    (2, '0005:00002DC8:00006012', b'\x05\x01\x09\x05', '8BitDo Ultimate 2 Wireless'),
                    (3, '0003:0000054C:00000CE6', b'\x06\x7a\xff', 'DualSense')):
                dev = usb / ('1-1:1.%d' % n) / ('0003:2DC8:6012.%04d' % n)
                dev.mkdir(parents=True)
                (dev / 'uevent').write_text('HID_ID=%s\nHID_NAME=%s\nHID_UNIQ=e4:17:d8\n' % (hid_id, name))
                (dev / 'report_descriptor').write_bytes(desc)
                hr = sysfs / 'class/hidraw' / ('hidraw%d' % n)
                hr.mkdir(parents=True)
                (hr / 'device').symlink_to(dev)
            u2.SYS = str(sysfs)
            found = list(u2.find_devices())
            self.assertEqual([(d, n) for d, n, _ in found], [('/dev/hidraw1', '8BitDo Ultimate 2 Wireless')])
            self.assertEqual(u2.bluetooth_pads(), ['8BitDo Ultimate 2 Wireless'])
            self.assertEqual(u2._key('/dev/hidraw1'), 'ultimate2-6012-e417d8')
            # O udev chama a cada hidraw do 8BitDo: o do gamepad/teclado fica quieto.
            self.assertIsNone(u2.apply_device('/dev/hidraw0', 0x50fa7b))
        self.assertEqual(u2.parse_color('#BD93F9'), 0xbd93f9)
        with self.assertRaises(ValueError):
            u2.parse_color('zzz')


class BluetoothToolTests(unittest.TestCase):
    """config/fliperos-bluetooth: o texto do bluetoothctl, os controles primeiro e o
    /etc/bluetooth como os controles pedem."""

    INFO = ('Device E4:17:D8:00:11:22 (public)\n\tName: 8BitDo Pro 2\n\tAlias: 8BitDo Pro 2\n'
            '\tClass: 0x00002508\n\tIcon: input-gaming\n\tPaired: yes\n\tTrusted: yes\n\tConnected: no\n'
            '\tUUID: Human Interface Device... (00001124-0000-1000-8000-00805f9b34fb)\n')

    def setUp(self):
        self.bt = load_script('fliperos_bluetooth', 'config/fliperos-bluetooth')

    def test_info_devices_and_prompts(self):
        info = self.bt.parse_info(self.INFO)
        self.assertEqual((info['Name'], info['Icon'], info['Paired'], info['Connected']),
                         ('8BitDo Pro 2', 'input-gaming', 'yes', 'no'))
        self.assertEqual(self.bt.parse_info('Device E4:17:D8:00:11:22 not available\n'), {})
        out = '\x1b[0;94m[bluetooth]\x1b[0m# Device E4:17:D8:00:11:22 8BitDo Pro 2\r\nDevice 11:22:33:44:55:66 JBL\n'
        self.assertEqual(self.bt.parse_devices(out), [('E4:17:D8:00:11:22', '8BitDo Pro 2'),
                                                      ('11:22:33:44:55:66', 'JBL')])
        self.assertEqual(self.bt.clean('[Xbox Wireless Controller]# [CHG] Device AA:BB:CC:DD:EE:FF Connected: yes'),
                         '[CHG] Device AA:BB:CC:DD:EE:FF Connected: yes')
        self.assertEqual(self.bt.device_line('E4:17:D8:00:11:22', info), 'E4:17:D8:00:11:22|8BitDo Pro 2|input-gaming|yes|no')

    def test_controllers_come_first(self):
        self.assertTrue(self.bt.is_gamepad({'Icon': 'input-gaming'}))
        # Sem icone, pela classe: periferico (0x05) com gamepad (0x08 na classe menor).
        self.assertTrue(self.bt.is_gamepad({'Class': '0x002508'}))
        self.assertFalse(self.bt.is_gamepad({'Class': '0x240404', 'Icon': 'audio-headset'}))
        rows = [('11:22:33:44:55:66', {'Name': 'JBL Flip', 'Icon': 'audio-card'}, ''),
                ('AA:AA:AA:AA:AA:AA', {}, ''),
                ('E4:17:D8:00:11:22', {'Name': 'Pro Controller', 'Icon': 'input-gaming'}, '')]
        self.assertEqual([r[0] for r in self.bt.sort_devices(rows)],
                         ['E4:17:D8:00:11:22', '11:22:33:44:55:66', 'AA:AA:AA:AA:AA:AA'])

    def test_the_config_for_controllers(self):
        main = ('[General]\n#Name = BlueZ\n#JustWorksRepairing = never\n\n[Policy]\n#AutoEnable=true\n')
        out = self.bt.set_ini(main, 'General', 'JustWorksRepairing', 'always')
        self.assertIn('JustWorksRepairing = always\n', out)
        self.assertNotIn('#JustWorksRepairing', out)
        out = self.bt.set_ini(out, 'General', 'FastConnectable', 'true')
        self.assertRegex(out, r'\[General\]\n#Name = BlueZ\nJustWorksRepairing = always\nFastConnectable = true\n\n\[Policy\]')
        self.assertEqual(self.bt.set_ini('', 'General', 'ClassicBondedOnly', 'false'),
                         '[General]\nClassicBondedOnly = false\n')
        with tempfile.TemporaryDirectory() as tmp:
            self.bt.BLUETOOTH_ETC = tmp
            (Path(tmp) / 'main.conf').write_text(main)
            self.assertTrue(self.bt.ensure_config())
            self.assertFalse(self.bt.ensure_config())
            self.assertIn('ClassicBondedOnly = false', (Path(tmp) / 'input.conf').read_text())
            self.assertIn('AutoEnable = true', (Path(tmp) / 'main.conf').read_text())

    def test_pairing_tries_twice(self):
        """O primeiro pareamento de muitos controles falha e o segundo vai: na
        falha o aparelho e esquecido e o pair vem de novo."""
        class FakeSession:
            def __init__(self, answers):
                self.sent, self.answers = [], list(answers)

            def send(self, command):
                self.sent.append(command)

            def wait(self, patterns, seconds):
                if self.sent[-1].startswith(('pair ', 'trust ', 'connect ')):
                    return self.answers.pop(0)
                return None

        mac = 'E4:17:D8:00:11:22'
        s = FakeSession(['Failed to pair: org.bluez.Error.AuthenticationFailed', 'Pairing successful',
                         'trust succeeded', 'Connection successful'])
        self.assertEqual(self.bt.pair_in(s, mac), (True, 'connected'))
        self.assertEqual([c for c in s.sent if c.startswith(('pair', 'remove'))],
                         ['pair ' + mac, 'remove ' + mac, 'pair ' + mac])
        s = FakeSession(['Failed to pair: x', 'Failed to pair: y'])
        self.assertEqual(self.bt.pair_in(s, mac), (False, 'Failed to pair: y'))
        self.assertEqual(sum(c.startswith('pair ') for c in s.sent), 2)
        s = FakeSession(['Pairing successful', 'trust succeeded', 'Connection successful'])
        self.assertTrue(self.bt.pair_in(s, mac)[0])
        self.assertNotIn('remove ' + mac, s.sent)

    def test_installed_in_the_image_and_by_the_update(self):
        rootfs = (ROOT / 'fliperos-rootfs.sh').read_text()
        self.assertIn('install -Dm755 "$src/config/fliperos-bluetooth" "$root/opt/fliperos/bin/fliperos-bluetooth"',
                      rootfs)
        self.assertRegex((ROOT / 'fliperos-mkiso.sh').read_text(), r'\n  bluez espeak-ng triggerhappy zsh picom\n')
        self.assertIn('packages+=(bluez)', (ROOT / 'tools/cabinet-update.sh').read_text())


class ButtonMappingGuiTests(unittest.TestCase):
    """O painel de arcade de 1 a 8 botoes, o icone de cada numero e o mapeador de
    joypad do Batocera na interface grafica."""
    GUI = ROOT / "fliperos-setup/gui"

    @unittest.skipUnless(importlib.util.find_spec("pygame"), "sem o pygame")
    def test_the_screens_draw(self):
        os.environ["SDL_VIDEODRIVER"] = "dummy"
        os.environ["PYGAME_HIDE_SUPPORT_PROMPT"] = "1"
        sys.path.insert(0, str(self.GUI))
        try:
            import pygame
            import widgets
        finally:
            sys.path.remove(str(self.GUI))
        pygame.font.init()
        surf = pygame.Surface((320, 240), pygame.SRCALPHA)
        ctx = {"status": "", "version": ""}
        for buttons in range(1, 9):
            widgets.Capture("Button mapping", 1, "b%d" % buttons, ["up"], 5, 12, 8, 8, buttons).draw(surf, ctx)
            widgets.panel_tile(buttons)(surf, 0, 0, 4)
        pad = widgets.PadCapture("Button mapping", 2, "lsup", 13, "playstation", "Wireless Controller",
                                 {"b4": "b0", "b5": "-", "up": "h0.1", "b7": "+a2"})
        pad.draw(surf, ctx)
        self.assertEqual([r[0] for r in widgets.PAD_ROWS],
                         ["b4", "b5", "b2", "b1", "start", "coin", "up", "down", "left", "right", "b3", "b6",
                          "lsup", "lsleft", "rsup", "rsleft", "b7", "b8", "l3", "r3", "hotkey"])
        self.assertEqual([widgets.element_name(e) for e in ("b3", "h0.4", "h1.8", "-a1", "-", "")],
                         ["BUTTON 3", "HAT DOWN", "HAT 1 LEFT", "AXIS 1-", "-NOT DEFINED-", "-NOT DEFINED-"])
        # Os desenhos do Batocera estao todos la.
        for _, _, icon in widgets.PAD_ROWS:
            self.assertTrue((self.GUI / "icons/pad" / (icon + ".png")).is_file(), icon)
            self.assertTrue((self.GUI / "icons/pad" / (icon + ".svg")).is_file(), icon)
        self.assertIsNotNone(widgets.pad_icon("buttons_south", 11, (255, 0, 0)))
        self.assertIn("Alec Lofquist", (self.GUI / "icons/README.md").read_text())
        source = (self.GUI / "serve.py").read_text()
        self.assertIn('if cmd == "padcapture":', source)
        self.assertIn('elif style == "panel":', source)
        # A lista de controles: o icone de com fio ou sem fio antes do nome.
        self.assertIn('elif style == "controllers":', source)
        menu = widgets.Menu("Button mapping", [("0", "P1 Xbox 360 Controller"), ("1", "-- Pro Controller"),
                                               ("return", "Return")], "1", "", vertical=True,
                            row_icons={"0": "wired", "1": "wireless"})
        menu.draw(surf, ctx)
        # Ao vivo: um controle ligado com a lista na tela a faz se refazer.
        with tempfile.TemporaryDirectory() as tmp:
            devices = Path(tmp) / "devices"
            dev = 'N: Name="%s"\nH: Handlers=%s \n\n'
            devices.write_text(dev % ("Namco GunCon 2", "mouse1 event6 js0") + dev % ("Xbox", "event8 js1")
                               + dev % ("Keyboard", "sysrq kbd event3"))
            self.assertEqual(widgets.joystick_signature(str(devices)),
                             (("Namco GunCon 2", "mouse1 event6 js0"), ("Xbox", "event8 js1")))
            menu.watch = lambda: widgets.joystick_signature(str(devices))
            menu.tick()
            menu._watched = (menu._watched[0] - 2, menu._watched[1])
            self.assertNotEqual(menu.tick(), ("refresh", "1"))
            devices.write_text(devices.read_text() + dev % ("Pro Controller", "event19 js4"))
            menu._watched = (menu._watched[0] - 2, menu._watched[1])
            self.assertEqual(menu.tick(), ("refresh", "1"))
        self.assertIn('if action == "refresh":\n                return 124, value', source)
        # Os botoes da interface: o verde e o vermelho.
        for which in ("accept", "cancel"):
            widgets.ConfirmCapture("Button mapping", 3, which, 10).draw(surf, ctx)
        self.assertIn('if cmd == "confirmcapture":', source)
        # O Esc na captura: as telas de captura sao canceladas pelo arquivo.
        self.assertTrue(widgets.Capture.cancelable and widgets.PadCapture.cancelable
                        and widgets.ConfirmCapture.cancelable)
        self.assertIn('open(os.path.join(self.dir, "cancel"), "w").close()', source)
        self.assertIn("if args.cancel and os.path.exists(args.cancel):\n                return 3",
                      (ROOT / "config/fliperos-buttons").read_text())
        # A ordem dos comandos do joypad e a mesma no Setup (lib/buttons.sh).
        lib = (ROOT / "fliperos-setup/lib/buttons.sh").read_text()
        self.assertIn("PAD_CONTROLS=(%s)" % " ".join(r[0] for r in widgets.PAD_ROWS), lib)


class GoogleOAuthSecretsTests(unittest.TestCase):
    """O cliente OAuth do Google fica nos secrets do GitHub Actions, fora do
    git (o push protection o recusa): tools/google-oauth-conf.sh o escreve no
    build da ISO e no workflow que o publica no release "packages"."""

    SCRIPT = ROOT / 'tools/google-oauth-conf.sh'

    def run_script(self, path, **env):
        return subprocess.run(['bash', str(self.SCRIPT), str(path)], capture_output=True, text=True,
                              env=dict(os.environ, **env), timeout=30)

    def test_the_client_comes_from_the_secrets_and_never_from_git(self):
        # No git o arquivo fica sem o par.
        conf = (ROOT / 'config/google-oauth.conf').read_text()
        self.assertRegex(conf, r'(?m)^client_id=$')
        self.assertRegex(conf, r'(?m)^client_secret=$')
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / 'google-oauth.conf'
            path.write_text(conf)
            # Sem os secrets (um fork), o arquivo fica como esta.
            r = self.run_script(path, CLIENT_ID='', CLIENT_SECRET='')
            self.assertEqual((r.returncode, path.read_text()), (0, conf), r.stderr)
            # Com eles, as duas linhas; os comentarios ficam.
            r = self.run_script(path, CLIENT_ID='123-abc.apps.googleusercontent.com', CLIENT_SECRET='GOCSPX-x_y')
            self.assertEqual(r.returncode, 0, r.stderr)
            text = path.read_text()
            self.assertIn('client_id=123-abc.apps.googleusercontent.com\nclient_secret=GOCSPX-x_y\n', text)
            self.assertEqual([l for l in text.splitlines() if l.startswith('#')],
                             [l for l in conf.splitlines() if l.startswith('#')])
            # Um par fora do formato do Google nao entra.
            r = self.run_script(path, CLIENT_ID='x; rm -rf /', CLIENT_SECRET='y')
            self.assertEqual(r.returncode, 1)
            self.assertIn('client_secret=GOCSPX-x_y', path.read_text())
        # O build da ISO o escreve antes de tudo, e o workflow Google OAuth o
        # publica no release "packages" (de onde o fliperos-cloud o baixa).
        release = (ROOT / '.github/workflows/release.yml').read_text()
        self.assertLess(release.index('bash tools/google-oauth-conf.sh config/google-oauth.conf'),
                        release.index('name: Versao, tag e changelog'))
        self.assertIn('secrets.GOOGLE_OAUTH_CLIENT_SECRET', release)
        publish = (ROOT / '.github/workflows/google-oauth.yml').read_text()
        self.assertIn('workflow_dispatch', publish)
        self.assertIn('gh release upload packages google-oauth.conf', publish)
        self.assertIn('releases/download/packages/google-oauth.conf', (ROOT / 'config/fliperos-cloud').read_text())


class HapticTests(unittest.TestCase):
    """gui/fehaptic.py e config/fliperos-haptic: a vibracao dos controles
    modernos ao navegar, abrir e fechar frontend e jogo."""

    def setUp(self):
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        self.addCleanup(sys.path.remove, str(ROOT / 'fliperos-setup/gui'))
        import fehaptic
        self.fh = fehaptic
        self.tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, self.tmp, True)

    def test_every_pattern_fits_the_kernel_effect_slots(self):
        # O kernel guarda 16 efeitos por controle; um padrao tem poucos passos,
        # e cada um de duracao valida (replay.length e 16 bits).
        for name, plan in self.fh.PATTERNS.items():
            self.assertLessEqual(len(plan), 4, name)
            for delay, ms, strong, weak in plan:
                self.assertTrue(0 <= delay < 1000 and 0 < ms < 500, name)
                self.assertTrue(0 <= strong <= 0xffff and 0 <= weak <= 0xffff, name)
        # Os eventos que o pedido cita.
        for name in ('open', 'close', 'start', 'end', 'error', 'tick', 'select', 'back'):
            self.assertIn(name, self.fh.PATTERNS)

    def test_presets_are_valid_and_playable_by_name(self):
        self.assertGreaterEqual(len(self.fh.PRESETS), 20)
        for name, plan in self.fh.PRESETS.items():
            self.assertLessEqual(len(plan), 12, name)        # o kernel guarda 16 efeitos
            for delay, ms, strong, weak in plan:
                self.assertTrue(0 <= delay < 1500 and 0 < ms < 1000, name)
                self.assertTrue(0 <= strong <= 0xffff and 0 <= weak <= 0xffff, name)
            self.assertIn(name, self.fh.ALL)
        self.assertGreater(self.fh.duration('heartbeat'), 0.8)
        tool = (ROOT / 'config/fliperos-haptic').read_text()
        self.assertIn('argv[0] == "demo"', tool)

    def test_events_use_the_preset_chosen_in_the_setup(self):
        conf = self.tmp / 'fliperos.conf'
        conf.write_text('haptic_move=heartbeat\nhaptic_enter=off\nhaptic_back=nope\n')
        self.fh.CONF = str(conf)
        self.fh._CONF_CACHE.clear()
        self.addCleanup(setattr, self.fh, 'CONF', '/etc/fliperos/fliperos.conf')
        self.addCleanup(self.fh._CONF_CACHE.clear)
        self.assertEqual(self.fh.chosen('tick'), 'heartbeat')       # move
        self.assertEqual(self.fh.chosen('select'), 'off')           # enter
        self.assertEqual(self.fh.chosen('back'), 'back')            # preset que nao existe: o padrao
        self.assertEqual(self.fh.chosen('step'), 'step')            # sem escolha: o padrao
        self.assertEqual(self.fh.chosen('start'), 'start')          # fora da lista: nao muda
        self.assertEqual(self.fh.steps('select'), [])               # off: sem passos
        self.assertEqual(self.fh.steps('tick'), self.fh.steps('heartbeat', raw=True))
        # A previa toca o preset com o nome, sem a escolha.
        self.assertEqual(self.fh.steps('tick', raw=True), self.fh.steps('tick', 1.0, True))
        self.assertNotEqual(self.fh.steps('tick', raw=True), self.fh.steps('tick'))

    def test_every_event_default_and_preset_is_in_the_setup(self):
        shell = (ROOT / 'fliperos-setup/lib/buttons.sh').read_text()
        theme = (ROOT / 'fliperos-setup/gui/theme.py').read_text()
        for event, (key, _label, default, _help) in self.fh.EVENT_KEYS.items():
            self.assertIn('"%s|' % key, shell)
            self.assertIn('|%s|' % default, shell)
            self.assertIn(default, self.fh.ALL)
        # Cada preset tem o icone do menu (haptic-NOME no theme.py) e uma dica.
        for name in self.fh.ALL:
            self.assertIn('"%s"' % name, theme, name)
        for name in list(self.fh.PRESETS) + list(self.fh.PATTERNS):
            self.assertIn(name, self.fh.HINTS)

    def test_open_rises_and_close_falls(self):
        power = lambda e: [s + w for _d, _m, s, w in self.fh.PATTERNS[e]]
        self.assertEqual(power('open'), sorted(power('open')))
        self.assertEqual(power('close'), sorted(power('close'), reverse=True))
        # O fim se desfaz em ecos cada vez mais leves.
        self.assertEqual(power('end'), sorted(power('end'), reverse=True))

    def test_level_from_env_and_conf(self):
        self.assertEqual(self.fh.level('off'), 0.0)
        self.assertEqual(self.fh.level('low'), 0.5)
        self.assertEqual(self.fh.level('on'), 1.0)
        self.assertEqual(self.fh.level('high'), 1.5)
        conf = self.tmp / 'fliperos.conf'
        conf.write_text('screens=1\nhaptic=off\n')
        self.fh.CONF = str(conf)
        try:
            saved = os.environ.pop('FLIPEROS_HAPTIC', None)
            self.assertEqual(self.fh.level(), 0.0)
        finally:
            self.fh.CONF = '/etc/fliperos/fliperos.conf'
            if saved is not None:
                os.environ['FLIPEROS_HAPTIC'] = saved
        # A forca nunca passa do maximo do motor.
        self.assertTrue(all(s <= 0xffff and w <= 0xffff for _d, _m, s, w in self.fh.steps('error', 3.0)))
        self.assertEqual(self.fh.steps('nao-existe'), [])

    def test_classify_frontends_games_and_tools(self):
        rom = self.tmp / 'sf2.zip'
        rom.write_text('')
        c = self.fh.classify
        self.assertEqual(c('/usr/local/lib/fliperos-setup/gui/fliperos-frontend', '--media'), 'frontend')
        self.assertEqual(c('es-de', '--no-splash'), 'frontend')
        self.assertEqual(c('attractplus', '--loglevel'), 'frontend')
        self.assertEqual(c('retroarch', str(rom)), 'game')
        self.assertEqual(c('groovymame', 'sf2'), 'game')
        # O menu de um emulador, o GroovyMAME sem set, ferramentas: sem aviso.
        self.assertEqual(c('groovymame', '-listxml'), '')
        self.assertEqual(c('retroarch', '--menu'), '')

    def test_effect_struct_matches_the_kernel(self):
        # ff_effect: type, id, direction, trigger(2), replay(length, delay), e a
        # uniao a partir do byte 16 (rumble: strong, weak). 48 bytes no x86_64.
        buf = self.fh._effect(30, 70, 0x1234, 0x4321)
        self.assertEqual(len(buf), 48)
        import struct
        self.assertEqual(struct.unpack_from('<HhHHHHH', buf), (0x50, -1, 0, 0, 0, 30, 70))
        self.assertEqual(struct.unpack_from('<HH', buf, 16), (0x1234, 0x4321))

    def test_only_rumble_gamepads_buzz(self):
        # Sem /dev/input legivel (aqui), ninguem vibra e nada quebra.
        empty = self.tmp / 'input'
        empty.mkdir()
        self.assertEqual(self.fh.pads(str(empty)), [])

    def test_buzzer_goes_to_the_pad_in_use_and_throttles(self):
        class Joy:
            def __init__(self):
                self.calls = []

            def rumble(self, low, high, ms):
                self.calls.append((low, high, ms))

        a, b = Joy(), Joy()
        buzzer = self.fh.Buzzer()
        buzzer.scale = 1.0
        buzzer.feel('select', a)
        buzzer.feel('tick', a)            # logo depois: engolido pelo intervalo minimo
        self.assertEqual(len(a.calls), 1)
        self.assertEqual(b.calls, [])
        buzzer.use(b)
        buzzer.feel('tick')               # o controle em uso
        self.assertEqual(len(b.calls), 1)
        # Um padrao de varios passos anda pela fila (pump).
        c = Joy()
        buzzer.feel('back', c)
        self.assertEqual(len(c.calls), 1)
        buzzer.queue = [(0, c, 0.1, 0.2, 16)]
        buzzer.pump()
        self.assertEqual(len(c.calls), 2)
        # Teclado (sem controle) e haptic=off: nada.
        buzzer.pad = None
        buzzer.feel('select')
        off = self.fh.Buzzer()
        off.scale = 0
        d = Joy()
        off.feel('select', d)
        self.assertEqual(d.calls, [])

    def test_actions_map_to_events(self):
        e = self.fh.action_event
        self.assertEqual((e('up'), e('b1'), e('b2'), e('left')), ('tick', 'select', 'back', 'step'))
        self.assertEqual(e('esc'), '')
        self.assertEqual(e('char:a'), '')

    def test_launch_hook_waits_for_the_game_and_tells_crash_from_end(self):
        # fliperos-haptic launch: "start" ao abrir e "end" ao fechar; fechou em
        # menos de CRASH_SECONDS, "error". Os controles ficam por conta de
        # play_all, aqui trocado por um registro.
        tool = (ROOT / 'config/fliperos-haptic').read_text()
        self.assertIn('fehaptic.play_all("open" if kind == "frontend" else "start")', tool)
        self.assertIn('fehaptic.play_all("error" if crashed else "end")', tool)
        self.assertIn('fehaptic.play_all("close")', tool)
        rom = self.tmp / 'sf2.zip'
        rom.write_text('')
        log = self.tmp / 'calls'
        shim = self.tmp / 'fehaptic.py'
        real = (ROOT / 'fliperos-setup/gui/fehaptic.py').read_text()
        shim.write_text(real + '\n\ndef play_all(event, wait=True):\n    open(%r, "a").write(event + "\\n")\n'
                         '    return 1\n\n\nlevel = lambda env=None: 1.0\n' % str(log))
        game = subprocess.Popen(['sleep', '0.5'])
        env = dict(os.environ, FLIPEROS_GUI_DIR=str(self.tmp), HAPTIC_GAME_PID=str(game.pid))
        r = subprocess.Popen([sys.executable, str(ROOT / 'config/fliperos-haptic'), 'launch', 'retroarch',
                              '-L', 'core.so', str(rom)], env=env)
        game.wait()
        self.assertEqual(r.wait(timeout=10), 0)
        # Fechou em meio segundo: caiu logo ao abrir.
        self.assertEqual(log.read_text(), 'start\nerror\n')
        # Sem jogo na linha (o menu de um emulador): nada.
        log.write_text('')
        subprocess.run([sys.executable, str(ROOT / 'config/fliperos-haptic'), 'launch', 'retroarch', '--menu'],
                       env=env, timeout=10)
        self.assertEqual(log.read_text(), '')

    def test_wiring(self):
        for runner in ('config/fliperos-kms-run', 'config/fliperos-x11-run'):
            text = (ROOT / runner).read_text()
            self.assertIn('[[ -x $haptic ]] && after_game "$haptic" launch "$@"', text, runner)
            self.assertIn('HAPTIC_GAME_PID=$$', text, runner)
        self.assertIn('install -Dm755 "$src/config/fliperos-haptic" "$root/opt/fliperos/bin/fliperos-haptic"',
                      (ROOT / 'fliperos-rootfs.sh').read_text())
        # O menu do Setup (padkeys) e o frontend usam o mesmo modulo.
        self.assertIn('HAPTIC_KEYS', (ROOT / 'config/fliperos-padkeys').read_text())
        # Segurar o botao nao vibra: o menu so vibra no toque, e o frontend so quando a lista andou.
        self.assertIn('if value == 1 and current[0]:', (ROOT / 'config/fliperos-padkeys').read_text())
        frontend = (ROOT / 'fliperos-setup/gui/fliperos-frontend').read_text()
        self.assertIn('if self.cursor != before:\n                        self.input.feel(["up"]', frontend)
        self.assertIn('fehaptic.Buzzer()', (ROOT / 'fliperos-setup/gui/feinput.py').read_text())


class BrandSpellingTests(unittest.TestCase):
    """O nome se escreve FliperOS, nunca FLIPEROS, e onde ele e desenhado o OS tem outra cor.
    Nao sao o nome: as variaveis FLIPEROS_*, os comandos fliperos-* e o token FLIPEROS do
    protocolo serial do OSCR (o firmware ja gravado responde por ele)."""

    SHOUT = re.compile(r'(?<![A-Za-z0-9_])FLIPEROS(?![A-Za-z0-9_])')
    SKIP = {'.git', 'node_modules', '__pycache__', 'third-party'}

    def test_no_source_file_shouts_the_name(self):
        found = []
        files = [p for p in ROOT.iterdir() if p.is_file() and p.suffix in ('.md', '.sh', '.py', '.html', '.yml')]
        for base in ('config', 'fliperos-setup', 'tools', 'docs', 'website/src', 'packaging', 'updates'):
            files += [p for p in (ROOT / base).rglob('*') if p.is_file()]
        for path in files:
            rel = path.relative_to(ROOT)
            if self.SKIP & set(rel.parts) or rel.as_posix() == 'fliperos-setup/gui/femedia.py':   # o protocolo do OSCR
                continue
            data = path.read_bytes()
            if b'\0' in data[:4096]:
                continue
            for n, line in enumerate(data.decode('utf-8', 'ignore').splitlines(), 1):
                if self.SHOUT.search(line):
                    found.append('%s:%d' % (rel.as_posix(), n))
        self.assertEqual(found, [], 'escreva FliperOS (o OS em outra cor onde for desenhado), nunca FLIPEROS')

    def test_the_small_font_spells_the_name_and_paints_the_os(self):
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        import tiny
        self.assertEqual(tiny.upper('the fliperos menu'), 'THE FliperOS MENU')
        self.assertEqual(tiny.upper('FliperOS ok'), 'FliperOS OK')
        # Variavel, nome de maquina e pasta nao sao o nome.
        self.assertEqual(tiny.upper('FLIPEROS_HOME fliperos.local \\\\fliperos\\roms'),
                         'FLIPEROS_HOME FLIPEROS.LOCAL \\\\FLIPEROS\\ROMS')
        self.assertTrue(all(ch in tiny.GLYPHS for ch in 'liper'))
        self.assertEqual(tiny.width('FliperOS'), tiny.width('FLIPEROS'))

        class Surface:
            def __init__(self):
                self.fills = []

            def fill(self, color, rect):
                self.fills.append((tuple(color), rect))

        surf = Surface()
        tiny.text(surf, 'fliperos', (1, 2, 3), 0, 0)
        self.assertEqual({c for c, r in surf.fills if r[0] < 6 * 4}, {(1, 2, 3)})
        self.assertEqual({c for c, r in surf.fills if r[0] >= 6 * 4}, {tiny.BRAND_OS})

    def test_pygame_text_spells_the_name_and_paints_the_os(self):
        try:
            import pygame
        except ImportError:
            self.skipTest('pygame')
        os.environ.setdefault('SDL_VIDEODRIVER', 'dummy')
        pygame.init()
        sys.path.insert(0, str(ROOT / 'fliperos-setup/gui'))
        import theme as T
        import widgets as W
        self.assertEqual(T.brand('BACK TO THE FLIPEROS MENU?'), 'BACK TO THE FliperOS MENU?')
        self.assertEqual(T.brand('FLIPEROS_HOME fliperos.local'), 'FLIPEROS_HOME fliperos.local')
        self.assertEqual(T.font().size('FLIPEROS'), T.font().size('FliperOS'))
        split = T.font().size('Fliper')[0]

        def colors(img, x0, x1):
            return {tuple(img.get_at((x, y)))[:3] for x in range(x0, x1) for y in range(img.get_height())
                    if img.get_at((x, y))[3]}

        # Texto de uma cor: o OS sai em outra.
        img = T.font().render('FLIPEROS', False, T.FG)
        self.assertEqual((colors(img, 0, split), colors(img, split, img.get_width())), ({T.FG}, {T.BRAND_OS}))
        # O titulo em degrade (o letreiro do Setup): o nome tem varias cores e o OS uma so; a sombra, nenhuma extra.
        title = W.big('FLIPEROS', 1, W.MARQUEE)
        self.assertGreater(len(colors(title, 0, split)), 1)
        self.assertEqual(colors(title, split, title.get_width()), {T.BRAND_OS})
        shadow = W.big('FLIPEROS', 1, (0x40, 0x20, 0x70))
        self.assertEqual(colors(shadow, 0, shadow.get_width()), {(0x40, 0x20, 0x70)})

    def test_the_dmd_animations_spell_the_name(self):
        # tools/zedmd-vector-anim.py e tools/marquee-logo-anim.py desenham o nome com as
        # minusculas (liper) no mesmo traco, e o OS em outra cor.
        vector = (ROOT / 'tools/zedmd-vector-anim.py').read_text()
        marquee = (ROOT / 'tools/marquee-logo-anim.py').read_text()
        self.assertIn("WORD = 'FliperOS'", vector)
        self.assertIn('OS_FROM = 6', vector)
        self.assertIn("BRAND = 'FliperOS'", marquee)
        self.assertIn('"marquee-fliperos": (BRAND, palm, None)', marquee)
        self.assertIn('chrome(y, st, os_x is not None and x >= os_x)', marquee)
        for ch in 'liper':
            self.assertIn("    '%s': [[" % ch, vector)
            self.assertIn("    '%s': [[" % ch, marquee)
            self.assertRegex(vector, r"WIDTH = \{[^}]*'%s': \d" % ch)
            self.assertRegex(marquee, r"WIDTH = \{[^}]*'%s': \d" % ch)
        self.assertNotIn('FLIPEROS', vector + marquee)

    def test_the_web_panel_spells_the_name(self):
        web = ROOT / 'config/web'
        index, ui = (web / 'index.html').read_text(), (web / 'ui.js').read_text()
        # O login, o letreiro do gabinete e o rodape do tubo: o nome com o OS em outra cor.
        self.assertEqual(index.count('<bdi class="fo">Fliper<b>OS</b></bdi>'), 3)
        self.assertIn('.fo b { color: var(--pink);', (web / 'style.css').read_text())
        # A caixa alta dos letreiros nao pode virar FLIPEROS, e o texto leva o OS em outra cor.
        self.assertIn('const upperName = ', ui)
        self.assertIn('function brandNodes(s)', ui)
        self.assertNotIn('(?<', ui)        # sem lookbehind: o Safari antigo do tablet nao le o script
        cabinet, view = (web / 'cabinet.js').read_text(), (web / 'marqueeview.js').read_text()
        self.assertIn('upperName(title.replace(', cabinet)
        self.assertIn('brandNodes(text)', cabinet)
        self.assertIn('upperName(frontName(cabFront.program))', cabinet)
        self.assertIn('upperName(title.replace(', view)
        self.assertIn('el("b", {}, ...brandNodes(title))', view)
        self.assertIn('el("h3", {}, ...brandNodes(title))', (web / 'system.js').read_text())


if __name__ == '__main__':
    unittest.main()
